(window.__COUR = window.__COUR || {})["data/cas.json"] = [{"id":"atlas","matiere":"affaires","title":"TechMaroc c/ Atlas Fret","court":"Tribunal de commerce — chambre commerciale","object":"Rupture abusive d'une relation commerciale établie. Demande de 500 000 DH de dommages et intérêts.","you":"Avocat de la défense (Atlas Fret)","adverseName":"Avocat de TechMaroc","facts":"Atlas Fret (logistique) a rompu un contrat de 3 ans avec son prestataire informatique TechMaroc par un simple e-mail, avec un préavis de 48 heures, en invoquant des dysfonctionnements techniques. TechMaroc saisit la justice.","rounds":[{"name":"Plaidoirie de la demande","adverse":"Monsieur le Président, Honorables Juges. La société Atlas Fret a rompu unilatéralement et brutalement une relation commerciale établie depuis trois ans, avec un préavis réduit à quarante-huit heures, notifié par un simple courriel. Cette rupture, sans mise en demeure ni délai de régularisation, constitue un abus de droit et une violation de l'obligation de bonne foi du Dahir des Obligations et Contrats. Nous demandons 500 000 Dirhams de dommages et intérêts.","prompt":"Présentez la réplique de la défense.","options":[{"label":"Contester sur le fond","detail":"Invoquer l'inexécution grave de TechMaroc et l'article 259 du DOC.","pts":15,"speech":"Monsieur le Président, cher Confrère. Atlas Fret conteste le caractère abusif de la rupture. En vertu de l'article 259 du DOC, l'inexécution répétée et grave de TechMaroc, dont la plateforme a paralysé notre chaîne logistique, rendait impossible la poursuite du contrat.","ok":["Fondement juridique pertinent (art. 259 DOC)","Met en avant la gravité de l'inexécution"],"ko":["Ne traite pas encore l'absence de mise en demeure"]},{"label":"Attaquer sur la forme","detail":"Soulever l'incompétence du tribunal de commerce.","pts":6,"speech":"Monsieur le Président, la défense soulève à titre liminaire l'incompétence de cette juridiction pour connaître du présent litige.","ok":["Réflexe procédural"],"ko":["Exception mal fondée : litige entre commerçants pour un acte de commerce","Laisse le fond sans réponse"]}],"concepts":[{"label":"Invoque l'inexécution / les dysfonctionnements de TechMaroc","re":"inexecution|dysfonction|panne|defaillan|manquement","pts":6,"key":true},{"label":"Souligne la gravité de la faute","re":"grav|faute grave|paralys|bloqu","pts":4},{"label":"Évoque des preuves des incidents","re":"preuve|rapport|ticket|incident|constat|pieces?","pts":3},{"label":"Répond sur la bonne foi","re":"bonne foi|loyaut","pts":3}],"articles":[{"code":"DOC","article":"259","label":"Art. 259 DOC (exécution forcée ou résolution)","pts":4}],"faille":"La défense invoque des dysfonctionnements, mais où sont les pièces ? Aucun constat, aucun rapport d'incident n'est versé aux débats.","concede":"La défense invoque l'inexécution. Soit. Encore faut-il qu'elle ait respecté la procédure qui l'encadre."},{"name":"Contre-attaque : la mise en demeure","adverse":"Si l'article 259 du DOC autorise la résolution en cas d'inexécution, encore faut-il que le débiteur soit en demeure. Or Atlas Fret ne produit aucune interpellation écrite lui laissant un délai pour corriger, seulement cet e-mail de 48 heures.","prompt":"Répondez à l'argument de l'absence de mise en demeure.","options":[{"label":"Produire les échanges écrits","detail":"Tickets et e-mails de réclamation ; liberté de la preuve en matière commerciale.","pts":17,"speech":"La défense verse aux débats quatorze tickets d'incident et six e-mails de réclamation adressés à TechMaroc sur quatre mois. En matière commerciale, la preuve est libre : ces écrits démontrent que le prestataire connaissait ses manquements et disposait de délais pour y remédier.","ok":["Neutralise l'argument de l'absence de mise en demeure","Utilise la liberté de la preuve commerciale"],"ko":["Les réclamations ne fixaient pas de délai formel"]},{"label":"Invoquer la gravité seule","detail":"Soutenir que la gravité de la faute dispense de toute mise en demeure.","pts":8,"speech":"La gravité exceptionnelle des manquements dispensait Atlas Fret de toute mise en demeure préalable.","ok":["Argument recevable en théorie"],"ko":["Aucune pièce pour prouver la gravité alléguée","Laisse ouverte la faille de forme"]}],"concepts":[{"label":"Répond sur la mise en demeure","re":"mise en demeure|interpell|mettre en demeure|notifi","pts":5,"key":true},{"label":"Produit des écrits (e-mails, tickets, réclamations)","re":"e-?mail|courriel|ticket|reclamation|ecrit|lettre","pts":6},{"label":"Invoque la liberté de la preuve commerciale","re":"liberte de la preuve|preuve (est )?libre|tous moyens","pts":4}],"articles":[{"code":"CCOM","article":"334","label":"Art. 334 Code de commerce (liberté de la preuve)","pts":3},{"code":"DOC","article":"255","label":"Art. 255 DOC (demeure du débiteur)","pts":2}],"faille":"La défense n'a toujours rien produit qui ressemble à une mise en demeure. La rupture reste fautive dans sa forme.","concede":"Les pièces montrent des échanges. Mais elles ne fixaient aucun délai : le préavis de 48 heures reste brutal."},{"name":"Le montant réclamé","adverse":"Le préjudice de TechMaroc est considérable : perte du client principal, licenciement de deux ingénieurs, atteinte à sa réputation. Les 500 000 Dirhams réclamés sont la juste réparation de cette rupture brutale.","prompt":"Plaidez sur le montant des dommages et intérêts.","options":[{"label":"Contester le montant","detail":"Disproportion avec le chiffre d'affaires réel ; préjudice non justifié ; subsidiairement, réduction.","pts":18,"speech":"À titre subsidiaire, 500 000 Dirhams sont sans rapport avec le chiffre d'affaires réalisé avec Atlas Fret sur douze mois, soit 210 000 Dirhams. Aucun justificatif des licenciements ni de l'atteinte à la réputation n'est produit. Le préjudice, s'il existe, se limite au défaut de préavis.","ok":["Chiffre la disproportion","Exige la preuve du préjudice","Plaide à titre subsidiaire"],"ko":[]},{"label":"Demande reconventionnelle","detail":"Réclamer à TechMaroc une indemnisation pour le préjudice logistique.","pts":10,"speech":"Atlas Fret forme une demande reconventionnelle : c'est elle qui a subi un préjudice logistique du fait des pannes répétées.","ok":["Démarche offensive"],"ko":["Demande non chiffrée et sans pièces","Ne conteste pas directement les 500 000 DH"]}],"concepts":[{"label":"Conteste le montant / la disproportion","re":"disproportion|excessi|exager|montant|chiffre d.affaires","pts":5,"key":true},{"label":"Exige la preuve du préjudice","re":"prejudice.*(prouv|justifi|demontr)|(prouv|justifi|demontr).*prejudice|aucun justificatif","pts":5},{"label":"Plaide à titre subsidiaire / réduction","re":"subsidiair|reduir|reduction|limit","pts":4},{"label":"Lie le préjudice au seul défaut de préavis","re":"preavis","pts":3}],"articles":[{"code":"DOC","article":"264","label":"Art. 264 DOC (évaluation des dommages)","pts":3}],"faille":"La défense ne conteste même pas sérieusement le chiffrage. Le tribunal retiendra le montant demandé.","concede":"Le chiffrage peut être discuté, mais le principe de la réparation demeure."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu qu'Atlas Fret justifie de réclamations écrites répétées, mais que le préavis de quarante-huit heures demeure insuffisant au regard de la durée de la relation ; constate que le préjudice allégué n'est que partiellement justifié ; Par ces motifs : condamne Atlas Fret à verser 25 000 Dirhams au titre du seul défaut de préavis."},{"min":45,"text":"Le Tribunal, attendu que la rupture d'un partenariat de longue durée exige un préavis raisonnable et une mise en demeure préalable, dont la preuve n'est pas rapportée ; retient toutefois que la somme de 500 000 Dirhams est disproportionnée ; Par ces motifs : condamne Atlas Fret à verser 50 000 Dirhams de dommages et intérêts."},{"min":0,"text":"Le Tribunal, attendu qu'Atlas Fret ne justifie ni des manquements allégués ni d'aucune mise en demeure, et n'a pas utilement contesté le préjudice ; Par ces motifs : qualifie la rupture d'abusive et condamne Atlas Fret à verser 180 000 Dirhams, outre les dépens."}]},{"id":"sahara","matiere":"affaires","title":"Sahara Textiles c/ Boutique Anfa","court":"Tribunal de commerce de Casablanca","object":"Recouvrement de factures impayées : 240 000 DH de marchandises livrées.","you":"Avocat de la demande (Sahara Textiles)","adverseName":"Avocat de Boutique Anfa","facts":"Sahara Textiles SARL a livré à Boutique Anfa trois lots de tissus entre janvier et mars. Les factures, d'un total de 240 000 DH, restent impayées malgré une lettre de mise en demeure. Boutique Anfa a versé un acompte de 30 000 DH en février, puis plus rien.","rounds":[{"name":"Exception de la défense : la preuve","adverse":"Monsieur le Président, la demanderesse ne produit aucun bon de commande signé par ma cliente. Des factures établies unilatéralement ne prouvent rien. La demande doit être rejetée faute de preuve de l'obligation.","prompt":"Établissez l'existence de la créance.","options":[{"label":"Liberté de la preuve","detail":"Bons de livraison signés, acompte versé, preuve libre entre commerçants.","pts":18,"speech":"Entre commerçants, la preuve est libre. Nous produisons les trois bons de livraison signés et tamponnés par Boutique Anfa, ainsi que son virement de 30 000 Dirhams en février, qui vaut reconnaissance de la relation et de la dette.","ok":["Mobilise la liberté de la preuve commerciale","Produit des pièces signées par l'adversaire","L'acompte vaut reconnaissance"],"ko":[]},{"label":"S'en tenir aux factures","detail":"Rappeler que les factures ont été envoyées et jamais contestées.","pts":8,"speech":"Les factures ont été adressées à la défenderesse, qui ne les a jamais contestées.","ok":["L'absence de contestation est un indice"],"ko":["Aucune pièce émanant du débiteur","N'utilise pas les bons de livraison"]}],"concepts":[{"label":"Produit des bons de livraison / pièces signées","re":"bons? de livraison|signe|tampon|cachet|accuse de reception","pts":6,"key":true},{"label":"Invoque la liberté de la preuve commerciale","re":"liberte de la preuve|preuve (est )?libre|tous moyens|entre commercants","pts":5},{"label":"Utilise l'acompte ou une reconnaissance","re":"paiement partiel|acompte|virement|reconnaiss","pts":4}],"articles":[{"code":"CCOM","article":"334","label":"Art. 334 Code de commerce (liberté de la preuve)","pts":5}],"faille":"La demande ne produit rien qui émane de ma cliente. Une facture ne se prouve pas par elle-même.","concede":"Admettons que les livraisons aient eu lieu. Encore faut-il que la marchandise ait été conforme."},{"name":"Exception d'inexécution : marchandise défectueuse","adverse":"Subsidiairement, les tissus du troisième lot présentaient des défauts de teinture. Ma cliente était donc fondée à suspendre son paiement en application de l'exception d'inexécution.","prompt":"Répondez à l'allégation de marchandise défectueuse.","options":[{"label":"Réception sans réserve","detail":"Marchandise acceptée sans réserves, réclamation inexistante, revente déjà effectuée.","pts":17,"speech":"Les bons de livraison ont été signés sans aucune réserve. Aucune réclamation n'a été formulée dans les jours suivant la réception, et la défenderesse a revendu l'essentiel des tissus. On ne peut à la fois vendre une marchandise et la dire inutilisable.","ok":["Réception sans réserve","Réclamation tardive","Contradiction de l'adversaire (revente)"],"ko":["Ne propose pas d'expertise pour clore le débat"]},{"label":"Demander une expertise","detail":"Solliciter une expertise judiciaire sur la qualité des tissus.","pts":10,"speech":"La demanderesse sollicite une expertise judiciaire afin d'établir la conformité des tissus livrés.","ok":["Démarche prudente"],"ko":["Retarde la procédure","Reprend à son compte une preuve qui pèse sur l'adversaire"]}],"concepts":[{"label":"Réception sans réserve","re":"sans (aucune )?reserve|accept","pts":6,"key":true},{"label":"Réclamation tardive ou inexistante","re":"tardi|delai|aucune reclamation|jamais (conteste|reclame)","pts":5},{"label":"Relève la revente / la contradiction","re":"revend|revente|contradi","pts":4}],"articles":[{"code":"DOC","article":"235","label":"Art. 235 DOC (exception d'inexécution)","pts":5}],"faille":"La demande ne répond pas sur les défauts. L'exception d'inexécution reste entière.","concede":"Les tissus ont été réceptionnés sans réserve, c'est exact. Mais le montant réclamé reste discutable."},{"name":"Les intérêts et le montant","adverse":"Enfin, la demanderesse réclame des intérêts et des dommages sans fondement. Ma cliente traverse des difficultés de trésorerie ; nous demandons des délais de paiement.","prompt":"Fixez vos demandes chiffrées.","options":[{"label":"Principal + intérêts","detail":"210 000 DH restant dus, dommages pour retard depuis la mise en demeure, rejet des délais.","pts":17,"speech":"Nous demandons le solde de 210 000 Dirhams, déduction faite de l'acompte, avec des dommages pour retard à compter de la mise en demeure. Des difficultés de trésorerie ne justifient pas de nouveaux délais à un débiteur qui a déjà revendu la marchandise.","ok":["Chiffrage exact (déduction de l'acompte)","Point de départ de la demeure","Répond à la demande de délais"],"ko":[]},{"label":"Dommages forfaitaires","detail":"Réclamer 500 000 DH pour le préjudice global subi.","pts":6,"speech":"Nous demandons 500 000 Dirhams pour l'ensemble du préjudice subi par notre cliente.","ok":[],"ko":["Montant sans rapport avec la créance","Aucun justificatif","Décrédibilise la demande principale"]}],"concepts":[{"label":"Chiffre le principal (déduction de l'acompte)","re":"210|solde|deduction|deduit|principal","pts":5,"key":true},{"label":"Demande les intérêts / dommages pour retard","re":"interets?|retard","pts":4},{"label":"Fixe le point de départ (mise en demeure)","re":"mise en demeure","pts":3},{"label":"S'oppose aux délais de paiement","re":"delai|tresorerie","pts":3}],"articles":[{"code":"DOC","article":"263","label":"Art. 263 DOC (dommages pour inexécution ou retard)","pts":5}],"faille":"La demande ne chiffre rien de précis. Le tribunal ne peut accorder ce qu'on ne lui demande pas clairement.","concede":"Nous prenons acte du chiffrage et nous en remettons à la sagesse du tribunal."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la livraison est établie par des bons signés sans réserve et que l'acompte vaut reconnaissance de la dette ; que l'exception d'inexécution n'est pas justifiée ; Par ces motifs : condamne Boutique Anfa à payer 210 000 Dirhams, avec dommages pour retard à compter de la mise en demeure, et rejette la demande de délais."},{"min":45,"text":"Le Tribunal, attendu que la livraison est établie, mais que la demanderesse n'a pas répondu sur l'ensemble des contestations ; Par ces motifs : condamne Boutique Anfa à payer 210 000 Dirhams, accorde un délai de six mois et rejette le surplus."},{"min":0,"text":"Le Tribunal, attendu que la demanderesse ne rapporte pas une preuve suffisante de sa créance ni de la conformité de la marchandise ; Par ces motifs : ordonne avant dire droit une expertise et réserve les dépens."}]},{"id":"cheque-impaye","matiere":"affaires","title":"Optique Médina c/ Ben Saïd","court":"Tribunal de commerce de Fès","object":"Recouvrement d'un chèque de 85 000 DH rejeté pour défaut de provision.","you":"Avocat du porteur (Optique Médina)","adverseName":"Avocat de M. Ben Saïd","facts":"M. Ben Saïd, commerçant, a remis à Optique Médina un chèque de 85 000 DH en paiement d'un lot de montures. Présenté dans les délais, le chèque a été rejeté pour défaut de provision et un protêt a été dressé. Optique Médina a prévenu le tireur par lettre recommandée cinq jours plus tard, puis l'a assigné sept mois après l'expiration du délai de présentation.","rounds":[{"name":"L'action cambiaire est-elle recevable ?","adverse":"Monsieur le Président, le porteur a laissé passer plus de six mois après l'expiration du délai de présentation avant d'agir. L'action en recours fondée sur le chèque est prescrite. La demande doit être déclarée irrecevable.","prompt":"Répondez à l'exception de prescription.","options":[{"label":"Basculer sur l'action de droit commun","detail":"Admettre la prescription cambiaire mais agir sur la vente (créance fondamentale).","pts":17,"speech":"Nous ne contestons pas que l'action cambiaire contre le tireur se prescrit par six mois. Mais la créance de prix née de la vente des montures subsiste : le chèque n'a pas éteint la dette tant qu'il n'a pas été payé. Nous agissons donc sur le fondement du contrat de vente, dont la livraison est prouvée par le bon signé.","ok":["Distingue rapport cambiaire et créance fondamentale","Reconnaît loyalement la prescription","S'appuie sur la preuve de la livraison"],"ko":[]},{"label":"Nier la prescription","detail":"Soutenir que le délai de six mois n'est pas écoulé.","pts":5,"speech":"Le délai de prescription n'est pas expiré, l'action est parfaitement recevable.","ok":[],"ko":["Contredit les dates du dossier","Perd en crédibilité devant le tribunal"]}],"concepts":[{"label":"Distingue l'action cambiaire et la créance de la vente","re":"vente|contrat|creance (fondamentale|initiale|de prix)|rapport fondamental|droit commun","pts":6,"key":true},{"label":"Reconnaît la prescription de six mois","re":"six mois|6 mois|prescri","pts":4},{"label":"Prouve la livraison / la dette","re":"livraison|bon|facture","pts":4}],"articles":[{"code":"CCOM","article":"295","label":"Art. 295 Code de commerce (prescription des recours : six mois)","pts":4}],"faille":"Le porteur ne propose aucun autre fondement : sa demande tombe avec la prescription du chèque.","concede":"Soit, la créance de prix demeure. Mais encore faut-il qu'elle soit exigible."},{"name":"Le préavis au tireur","adverse":"Subsidiairement, le porteur n'a pas averti le tireur du défaut de paiement dans le délai légal. Cette négligence a privé mon client de la possibilité de régulariser.","prompt":"Répondez sur l'avis du défaut de paiement.","options":[{"label":"Avis donné dans le délai","detail":"Lettre recommandée envoyée cinq jours après le protêt, dans le délai de huit jours ouvrables.","pts":16,"speech":"L'avis du défaut de paiement a été adressé au tireur par lettre recommandée cinq jours après le protêt, soit dans le délai de huit jours ouvrables. Au surplus, l'omission de l'avis n'entraîne pas la déchéance du porteur : elle l'expose seulement à réparer le préjudice causé par sa négligence, que l'adversaire ne démontre pas.","ok":["Produit l'accusé de réception","Respect du délai de huit jours","Rappelle que l'omission n'entraîne pas la déchéance"],"ko":[]},{"label":"Ignorer l'argument","detail":"Plaider directement sur le montant.","pts":6,"speech":"Nous maintenons notre demande de 85 000 Dirhams.","ok":[],"ko":["Laisse l'argument adverse sans réponse"]}],"concepts":[{"label":"Avis envoyé dans les huit jours","re":"huit jours|8 jours|cinq jours|recommande|avis","pts":6,"key":true},{"label":"Pas de déchéance, seulement des dommages","re":"decheance|negligence|prejudice","pts":4},{"label":"Produit une preuve d'envoi","re":"accuse|recommande|preuve","pts":3}],"articles":[{"code":"CCOM","article":"285","label":"Art. 285 Code de commerce (avis du défaut de paiement)","pts":4}],"faille":"Le porteur ne justifie d'aucun avis : la négligence est établie.","concede":"L'avis a été donné à temps. Reste la question des intérêts."},{"name":"Les demandes chiffrées","adverse":"Mon client reconnaît devoir une partie de la somme, mais les montures livrées étaient en partie d'une autre référence. Il propose 60 000 Dirhams.","prompt":"Fixez vos demandes.","options":[{"label":"Principal et dommages pour retard","detail":"85 000 DH, dommages pour retard depuis la présentation, rejet de la réfaction non prouvée.","pts":17,"speech":"Le bon de livraison, signé sans réserve, mentionne les références commandées. La réfaction proposée n'est étayée par aucune réclamation. Nous demandons 85 000 Dirhams, avec des dommages pour retard à compter de la présentation du chèque.","ok":["S'appuie sur la réception sans réserve","Rejette une réfaction non prouvée","Point de départ cohérent"],"ko":[]},{"label":"Accepter 60 000 DH","detail":"Transiger immédiatement.","pts":9,"speech":"Notre cliente accepte la somme de 60 000 Dirhams.","ok":["Solution rapide"],"ko":["Abandonne 25 000 DH sans contrepartie","Aucune vérification de la réclamation"]}],"concepts":[{"label":"Maintient le principal de 85 000 DH","re":"85|principal|totalite","pts":5,"key":true},{"label":"Rejette la réfaction non prouvée","re":"sans reserve|aucune reclamation|non prouv|pas prouv","pts":4},{"label":"Demande des dommages pour retard","re":"retard|interets?","pts":4}],"articles":[{"code":"DOC","article":"263","label":"Art. 263 DOC (dommages pour retard)","pts":3}],"faille":"Le porteur ne justifie pas pourquoi la proposition serait insuffisante.","concede":"Nous prenons acte, le tribunal appréciera."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'action cambiaire est prescrite mais que la créance de prix née de la vente est établie par un bon de livraison signé sans réserve ; Par ces motifs : condamne M. Ben Saïd à payer 85 000 Dirhams, avec dommages pour retard à compter de la présentation du chèque."},{"min":45,"text":"Le Tribunal, attendu que la créance de prix est établie mais que le porteur n'a pas répondu à toutes les contestations ; Par ces motifs : condamne M. Ben Saïd à payer 85 000 Dirhams sans dommages pour retard."},{"min":0,"text":"Le Tribunal, attendu que l'action fondée sur le chèque est prescrite et qu'aucun autre fondement n'est utilement invoqué ; Par ces motifs : déclare la demande irrecevable."}]},{"id":"lettre-change","matiere":"affaires","title":"Banque Atlantique c/ Société Rif Bois","court":"Tribunal de commerce de Tanger","object":"Recours du porteur d'une lettre de change de 120 000 DH contre un endosseur.","you":"Avocat de l'endosseur (Rif Bois)","adverseName":"Avocat de Banque Atlantique","facts":"Rif Bois a endossé au profit de Banque Atlantique une lettre de change tirée sur un client. À l'échéance, le tiré n'a pas payé. La banque n'a fait dresser le protêt que trois semaines après l'échéance, sans invoquer de force majeure, puis s'est retournée contre Rif Bois.","rounds":[{"name":"Le recours contre l'endosseur","adverse":"Monsieur le Président, tous ceux qui ont endossé une lettre de change sont tenus solidairement envers le porteur. Rif Bois doit payer les 120 000 Dirhams.","prompt":"Présentez la défense de l'endosseur.","options":[{"label":"Protêt tardif","detail":"Le refus de paiement devait être constaté par un protêt dans les délais : le porteur négligent perd ses recours contre les endosseurs.","pts":17,"speech":"Le refus de paiement doit être constaté par un protêt dressé dans les délais légaux. La banque l'a fait établir trois semaines après l'échéance, sans aucune force majeure. Porteur négligent, elle a perdu ses recours contre les endosseurs, dont Rif Bois.","ok":["Identifie la tardiveté du protêt","Écarte la force majeure","Tire la conséquence : perte du recours contre l'endosseur"],"ko":[]},{"label":"Contester la solidarité","detail":"Soutenir que l'endosseur n'est jamais tenu.","pts":5,"speech":"Un endosseur n'a pas à garantir le paiement d'une dette qui n'est pas la sienne.","ok":[],"ko":["Contraire au principe de solidarité cambiaire","Ignore le vrai moyen de défense"]}],"concepts":[{"label":"Invoque le protêt tardif","re":"protet.*(tardi|delai|hors)|(tardi|delai|hors).*protet","pts":6,"key":true},{"label":"Écarte la force majeure","re":"force majeure","pts":4},{"label":"Conclut à la perte du recours (porteur négligent)","re":"negligent|perte|perd|decheance","pts":4}],"articles":[{"code":"CCOM","article":"197","label":"Art. 197 Code de commerce (protêt faute de paiement)","pts":2},{"code":"CCOM","article":"206","label":"Art. 206 Code de commerce (déchéance du porteur négligent)","pts":3},{"code":"CCOM","article":"207","label":"Art. 207 Code de commerce (force majeure)","pts":1}],"faille":"L'endosseur ne conteste rien de sérieux : la solidarité joue pleinement.","concede":"Le protêt est tardif, c'est vrai. Mais la banque garde d'autres droits."},{"name":"Les autres droits de la banque","adverse":"Même sans recours cambiaire, la banque a escompté cet effet et crédité le compte de Rif Bois : elle peut lui réclamer le remboursement au titre du compte.","prompt":"Répondez à ce nouveau fondement.","options":[{"label":"Exiger la preuve de l'escompte et du compte","detail":"Ce fondement relève du contrat bancaire : la banque doit le prouver et le chiffrer.","pts":15,"speech":"La banque change de fondement en cours d'audience. Si elle invoque une convention d'escompte, qu'elle la produise, ainsi que le relevé de compte montrant le crédit et sa contre-passation. À défaut, la demande n'est pas prouvée : la preuve de l'obligation incombe à celui qui s'en prévaut.","ok":["Relève le changement de fondement","Exige la convention et les relevés","Rappelle la charge de la preuve"],"ko":[]},{"label":"Reconnaître la dette","detail":"Admettre devoir le montant au titre du compte.","pts":6,"speech":"Notre cliente ne conteste pas avoir été créditée.","ok":[],"ko":["Abandonne la défense gagnée au premier round"]}],"concepts":[{"label":"Rappelle la charge de la preuve","re":"preuve|prouv","pts":5,"key":true},{"label":"Exige la convention / les relevés","re":"convention|releve|escompte|contrat","pts":5},{"label":"Relève le changement de fondement","re":"fondement|nouveau|change","pts":3}],"articles":[{"code":"DOC","article":"399","label":"Art. 399 DOC (charge de la preuve)","pts":4}],"faille":"L'endosseur ne conteste pas avoir été crédité : la créance est reconnue.","concede":"La banque produira ses relevés. Le tribunal appréciera."},{"name":"Conclusions finales","adverse":"La banque demande, à titre subsidiaire, des délais pour produire les relevés de compte.","prompt":"Concluez.","options":[{"label":"Rejet et, au plus, renvoi encadré","detail":"Rejet du recours cambiaire ; sur le compte, rejet faute de preuve ou délai strict.","pts":16,"speech":"Nous concluons au rejet du recours cambiaire, le protêt étant tardif. Sur le fondement du compte, la banque n'a rien produit : nous demandons le rejet, ou à tout le moins un délai strict avec avertissement que la demande sera écartée faute de pièces.","ok":["Conclusions claires et hiérarchisées","Encadre la demande de délai"],"ko":[]},{"label":"Ne rien conclure","detail":"Laisser le tribunal décider.","pts":7,"speech":"Nous nous en remettons à la sagesse du tribunal.","ok":[],"ko":["Aucune conclusion précise"]}],"concepts":[{"label":"Conclut au rejet du recours cambiaire","re":"rejet|irrecevab","pts":5,"key":true},{"label":"Encadre le délai demandé","re":"delai strict|bref delai|ecart|a defaut","pts":4}],"articles":[],"faille":"Faute de conclusions précises, le tribunal accordera les délais demandés.","concede":"Les conclusions sont claires."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le protêt faute de paiement a été dressé hors délai sans force majeure et que la banque, porteur négligent, a perdu son recours contre l'endosseur ; qu'elle ne prouve pas la créance invoquée au titre du compte ; Par ces motifs : rejette la demande."},{"min":45,"text":"Le Tribunal, attendu que le recours cambiaire est perdu mais que la banque peut justifier d'une créance de compte ; Par ces motifs : rejette le recours cambiaire et renvoie l'affaire pour production des relevés."},{"min":0,"text":"Le Tribunal, attendu que les endosseurs sont tenus solidairement et que la défense n'établit aucune cause de déchéance ; Par ces motifs : condamne Rif Bois à payer 120 000 Dirhams."}]},{"id":"bail-commercial","matiere":"affaires","title":"Café Les Palmiers c/ Mme El Fassi","court":"Tribunal de commerce de Marrakech","object":"Éviction d'un locataire commercial et indemnité de résiliation.","you":"Avocat du locataire (Café Les Palmiers)","adverseName":"Avocat de la bailleresse","facts":"Le Café Les Palmiers exploite depuis neuf ans un local appartenant à Mme El Fassi. Celle-ci a délivré congé pour « reprise », sans autre précision, avec un délai de quinze jours, puis a saisi le tribunal pour obtenir l'expulsion sans indemnité.","rounds":[{"name":"La validité du congé","adverse":"Monsieur le Président, ma cliente est propriétaire et souhaite reprendre son bien. Le congé a été délivré ; le locataire doit partir.","prompt":"Contestez le congé.","options":[{"label":"Congé irrégulier","detail":"Le congé doit exposer obligatoirement son motif et respecter le délai légal correspondant.","pts":17,"speech":"La loi impose au bailleur d'adresser un congé exposant obligatoirement le motif, avec le délai d'éviction prévu pour ce motif. Le congé se borne à évoquer une « reprise » sans dire pour quoi faire. Surtout, une reprise ouvre un délai de trois mois ; le délai de quinze jours est réservé au défaut de paiement des loyers ou au local menaçant ruine. Le congé est irrégulier.","ok":["Exige un motif précis","Vérifie le délai correspondant au motif"],"ko":[]},{"label":"Plaider l'ancienneté seule","detail":"Neuf ans d'exploitation empêchent l'éviction.","pts":8,"speech":"Après neuf ans, le locataire ne peut pas être évincé.","ok":["Valorise l'ancienneté"],"ko":["L'ancienneté n'interdit pas l'éviction","Ne critique pas le congé"]}],"concepts":[{"label":"Exige un motif exposé dans le congé","re":"motif","pts":6,"key":true},{"label":"Conteste le délai : trois mois pour une reprise, pas quinze jours","re":"trois mois|3 mois|quinze|15 jours|delai","pts":5},{"label":"Conclut à l'irrégularité / nullité du congé","re":"irregul|nul|invalide","pts":3}],"articles":[{"code":"L49-16","article":"26","label":"Art. 26 loi 49-16 (congé motivé et délais)","pts":4}],"faille":"Le locataire ne critique pas sérieusement le congé : il est valable.","concede":"Le congé est imparfait. Mais la bailleresse peut le régulariser."},{"name":"Le droit à indemnité","adverse":"Quand bien même, la reprise par la propriétaire est un droit : aucune indemnité n'est due.","prompt":"Défendez le droit à indemnité.","options":[{"label":"Indemnité de résiliation","detail":"Le locataire évincé a droit à une indemnité égale au préjudice, incluant la valeur du fonds.","pts":18,"speech":"La loi pose le principe : le locataire a droit à une indemnité de résiliation, qui correspond au préjudice subi du fait de l'éviction et comprend la valeur du fonds de commerce. La bailleresse n'invoque aucune des exceptions légales. Nous demandons une expertise pour évaluer le fonds.","ok":["Pose le principe légal","Relève l'absence d'exception","Demande une expertise d'évaluation"],"ko":[]},{"label":"Demander un montant forfaitaire","detail":"Réclamer 2 millions de DH sans justification.","pts":7,"speech":"Nous réclamons deux millions de Dirhams.","ok":[],"ko":["Aucun fondement ni évaluation","Montant arbitraire"]}],"concepts":[{"label":"Invoque le droit à indemnité","re":"indemnite","pts":6,"key":true},{"label":"Inclut la valeur du fonds de commerce","re":"valeur du fonds|fonds de commerce|clientele","pts":4},{"label":"Demande une expertise","re":"expert","pts":4}],"articles":[{"code":"L49-16","article":"7","label":"Art. 7 loi 49-16 (indemnité de résiliation)","pts":4}],"faille":"Sans évaluation, la demande d'indemnité est inopérante.","concede":"Le principe de l'indemnité est acquis. Reste à la chiffrer."},{"name":"Le montant et le maintien dans les lieux","adverse":"À titre subsidiaire, la bailleresse propose six mois de loyer.","prompt":"Concluez.","options":[{"label":"Maintien jusqu'au paiement + expertise","detail":"Rejet de l'expulsion ; à défaut, indemnité évaluée par expert avant tout départ.","pts":16,"speech":"Nous concluons à la nullité du congé. À titre subsidiaire, l'indemnité doit être fixée par expertise et versée avant toute libération des lieux. Six mois de loyer ne couvrent ni la valeur du fonds ni les frais de déménagement.","ok":["Conclusions hiérarchisées","Lie le départ au paiement"],"ko":[]},{"label":"Accepter six mois de loyer","detail":"Transiger.","pts":8,"speech":"Le locataire accepte la proposition.","ok":[],"ko":["Bien inférieur à la valeur d'un fonds exploité depuis neuf ans"]}],"concepts":[{"label":"Nullité du congé à titre principal","re":"nul|irregul|principal","pts":4,"key":true},{"label":"Indemnité fixée par expert","re":"expert","pts":4},{"label":"Pas de départ avant paiement","re":"avant|paiement|maintien","pts":3}],"articles":[],"faille":"Le locataire accepte au fond le principe du départ.","concede":"Les conclusions sont claires."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le congé n'expose pas de motif précis et ne respecte pas le délai légal ; Par ces motifs : déclare le congé nul et déboute la bailleresse de sa demande d'expulsion."},{"min":45,"text":"Le Tribunal, attendu que le congé est valable en son principe mais que le locataire a droit à une indemnité de résiliation ; Par ces motifs : ordonne une expertise pour évaluer le fonds et subordonne l'éviction au paiement de l'indemnité."},{"min":0,"text":"Le Tribunal, attendu que le locataire ne critique utilement ni le congé ni son motif ; Par ces motifs : valide le congé et alloue une indemnité de six mois de loyer."}]},{"id":"concurrence","matiere":"affaires","title":"Douceurs d'Agadir c/ Sucré Salé SARL","court":"Tribunal de commerce d'Agadir","object":"Concurrence déloyale : imitation d'emballage et dénigrement. Demande de 300 000 DH.","you":"Avocat de la demande (Douceurs d'Agadir)","adverseName":"Avocat de Sucré Salé","facts":"Douceurs d'Agadir vend depuis dix ans des biscuits dans une boîte orange à motifs d'arganier. Sucré Salé a lancé une boîte orange très proche, puis ses commerciaux ont affirmé aux revendeurs que les biscuits de Douceurs d'Agadir « contenaient des huiles de mauvaise qualité ». Les ventes de Douceurs d'Agadir ont baissé de 35 % en six mois.","rounds":[{"name":"Les faits de concurrence déloyale","adverse":"Monsieur le Président, la couleur orange n'appartient à personne. Le commerce est libre et la concurrence aussi.","prompt":"Caractérisez la concurrence déloyale.","options":[{"label":"Confusion + dénigrement","detail":"Imitation créant la confusion et propos dénigrants : deux faits de concurrence déloyale.","pts":18,"speech":"Ce n'est pas la couleur que nous reprochons, mais l'ensemble : même couleur, même motif d'arganier, même format, créant une confusion dans l'esprit de la clientèle. S'y ajoutent des propos dénigrants tenus aux revendeurs, attestés par trois d'entre eux. Ces faits constituent une concurrence déloyale ouvrant droit à dommages-intérêts.","ok":["Raisonne sur l'impression d'ensemble","Ajoute le dénigrement","Produit des attestations"],"ko":[]},{"label":"Revendiquer la couleur","detail":"Soutenir que l'orange est réservé à la demanderesse.","pts":6,"speech":"Notre cliente a l'exclusivité de la couleur orange pour ses biscuits.","ok":[],"ko":["Aucun droit exclusif sur une couleur","Oublie le dénigrement"]}],"concepts":[{"label":"Invoque la confusion / l'imitation","re":"confusion|imitation|ressembl|copi","pts":6,"key":true},{"label":"Invoque le dénigrement","re":"denigr|propos|mauvaise qualite","pts":5},{"label":"Produit des preuves (attestations, photos)","re":"attestation|temoign|photo|constat|preuve","pts":3}],"articles":[{"code":"DOC","article":"84","label":"Art. 84 DOC (concurrence déloyale)","pts":4}],"faille":"La demande ne démontre aucun acte déloyal : seulement une concurrence normale.","concede":"Il y a des ressemblances, nous l'admettons. Mais le préjudice reste à prouver."},{"name":"Le préjudice","adverse":"La baisse des ventes s'explique par la hausse des prix de la demanderesse, pas par ma cliente.","prompt":"Établissez le préjudice et le lien de causalité.","options":[{"label":"Chiffres et chronologie","detail":"Baisse de 35 % coïncidant avec le lancement adverse ; prix inchangés ; expertise comptable.","pts":16,"speech":"Nos prix sont inchangés depuis dix-huit mois, comme le montrent les factures. La baisse de 35 % commence le mois du lancement de la boîte concurrente et se concentre chez les revendeurs démarchés. Nous demandons une expertise comptable pour chiffrer le manque à gagner.","ok":["Neutralise l'explication adverse","Établit la chronologie","Demande une expertise"],"ko":[]},{"label":"Affirmer le préjudice","detail":"Dire que le préjudice est évident.","pts":7,"speech":"Le préjudice est évident.","ok":[],"ko":["Aucune preuve du lien de causalité"]}],"concepts":[{"label":"Prouve la baisse et sa chronologie","re":"35|baisse|chronolog|lancement","pts":5,"key":true},{"label":"Écarte l'explication par les prix","re":"prix (inchanges|stables)|pas augmente","pts":4},{"label":"Demande une expertise comptable","re":"expert","pts":4}],"articles":[{"code":"DOC","article":"98","label":"Art. 98 DOC (étendue des dommages)","pts":3}],"faille":"Faute de lien de causalité, aucune réparation n'est due.","concede":"Le lien est plausible. Le montant reste discutable."},{"name":"Les mesures demandées","adverse":"Ma cliente est prête à modifier sa boîte. Toute condamnation pécuniaire serait excessive.","prompt":"Fixez vos demandes.","options":[{"label":"Cessation + dommages + publication","detail":"Interdiction sous astreinte, dommages évalués par expert, publication du jugement.","pts":16,"speech":"Nous demandons l'interdiction de l'emballage litigieux sous astreinte, des dommages-intérêts fixés après expertise, et la publication du jugement auprès des revendeurs, seul moyen de réparer le dénigrement.","ok":["Mesure de cessation","Réparation du dénigrement par publication"],"ko":[]},{"label":"Accepter la modification seule","detail":"Se contenter de l'engagement adverse.","pts":8,"speech":"Nous prenons acte de l'engagement.","ok":[],"ko":["Aucune réparation du préjudice passé"]}],"concepts":[{"label":"Demande la cessation (astreinte, interdiction)","re":"astreinte|interdi|cessation|retrait","pts":5,"key":true},{"label":"Demande des dommages-intérêts","re":"dommages","pts":3},{"label":"Demande la publication","re":"publicat","pts":3}],"articles":[],"faille":"La demande se contente d'un engagement : le préjudice passé reste sans réparation.","concede":"Les demandes sont précises."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'imitation de l'emballage crée un risque de confusion et que le dénigrement est établi par attestations ; Par ces motifs : interdit l'emballage sous astreinte, ordonne une expertise sur le préjudice et la publication du jugement."},{"min":45,"text":"Le Tribunal, attendu que la confusion est établie mais que le préjudice n'est que partiellement démontré ; Par ces motifs : interdit l'emballage et alloue 60 000 Dirhams de dommages-intérêts."},{"min":0,"text":"Le Tribunal, attendu que la demanderesse ne démontre ni confusion ni lien de causalité ; Par ces motifs : rejette la demande."}]},{"id":"gerant-sarl","matiere":"affaires","title":"M. Alaoui c/ M. Bennani, gérant de Logistix SARL","court":"Tribunal de commerce de Casablanca","object":"Action en responsabilité d'un associé contre le gérant pour fautes de gestion.","you":"Avocat de l'associé demandeur (M. Alaoui)","adverseName":"Avocat du gérant","facts":"M. Alaoui détient 40 % de Logistix SARL. Le gérant, M. Bennani, a fait louer par la société, à un prix double du marché, un entrepôt appartenant à son beau-frère, sans autorisation de l'assemblée, et a distribué des dividendes alors que l'exercice était déficitaire.","rounds":[{"name":"La faute du gérant","adverse":"Monsieur le Président, le gérant gère. Ses choix relèvent de son pouvoir de gestion ; le juge n'a pas à contrôler l'opportunité.","prompt":"Caractérisez la responsabilité du gérant.","options":[{"label":"Violations de la loi et fautes de gestion","detail":"Conflit d'intérêts non autorisé, loyer excessif, dividendes fictifs.","pts":18,"speech":"Il ne s'agit pas d'opportunité mais de violations caractérisées : une convention passée avec un proche sans autorisation des associés, à un loyer double du marché, et une distribution de dividendes sans bénéfice distribuable. Les gérants répondent envers la société et les tiers des infractions à la loi, des violations des statuts et de leurs fautes de gestion.","ok":["Distingue faute et opportunité","Identifie trois manquements","Cite le régime de responsabilité"],"ko":[]},{"label":"Reprocher la mauvaise gestion en général","detail":"Critiquer les résultats de la société.","pts":7,"speech":"La société perd de l'argent : le gérant est responsable.","ok":[],"ko":["Des pertes ne suffisent pas à prouver une faute"]}],"concepts":[{"label":"Invoque le conflit d'intérêts / convention non autorisée","re":"beau-frere|conflit|convention|autoris","pts":5,"key":true},{"label":"Invoque le loyer excessif","re":"loyer|double|prix","pts":4},{"label":"Invoque les dividendes fictifs","re":"dividende","pts":5}],"articles":[{"code":"L5-96","article":"67","label":"Art. 67 loi 5-96 (responsabilité des gérants de SARL)","pts":4}],"faille":"L'associé ne démontre aucune faute précise.","concede":"Les faits sont établis. Reste le préjudice."},{"name":"La dimension pénale","adverse":"Les dividendes ont été votés par l'assemblée : le gérant n'a fait qu'exécuter.","prompt":"Répondez.","options":[{"label":"Délit de répartition de dividendes fictifs","detail":"La loi sanctionne pénalement le gérant qui distribue sciemment des dividendes fictifs.","pts":15,"speech":"Le vote de l'assemblée ne couvre pas le gérant : c'est lui qui a présenté des comptes laissant croire à un bénéfice. La loi punit les gérants qui opèrent sciemment entre associés la répartition de dividendes fictifs. Nous nous réservons de saisir le parquet.","ok":["Écarte l'excuse du vote","Mentionne la sanction pénale"],"ko":[]},{"label":"Admettre le vote","detail":"Concéder que l'assemblée a validé.","pts":6,"speech":"Il est exact que l'assemblée a voté.","ok":[],"ko":["Laisse tomber le grief le plus grave"]}],"concepts":[{"label":"Le vote ne couvre pas le gérant","re":"vote|assemblee","pts":4,"key":true},{"label":"Mentionne le délit / la sanction pénale","re":"penal|delit|emprisonnement|parquet|fictif","pts":5}],"articles":[{"code":"L5-96","article":"107","label":"Art. 107 loi 5-96 (dividendes fictifs)","pts":4}],"faille":"Le vote de l'assemblée couvre le gérant.","concede":"La question pénale relève d'une autre juridiction."},{"name":"Les réparations","adverse":"Le gérant propose de baisser le loyer pour l'avenir.","prompt":"Fixez vos demandes.","options":[{"label":"Réparation à la société + révocation","detail":"Restitution du surcoût de loyer, des dividendes, et révocation pour juste motif.","pts":16,"speech":"Nous demandons la condamnation du gérant à verser à la société le surcoût de loyer depuis le début du bail et le montant des dividendes indûment distribués, et sa révocation pour juste motif.","ok":["Réparation au profit de la société","Demande la révocation"],"ko":[]},{"label":"Demander des dommages pour soi","detail":"Réclamer une indemnité personnelle de 40 % des pertes.","pts":9,"speech":"M. Alaoui réclame 40 % des pertes.","ok":[],"ko":["Le préjudice est d'abord celui de la société"]}],"concepts":[{"label":"Réparation au profit de la société","re":"societe","pts":4,"key":true},{"label":"Chiffre le surcoût / les dividendes","re":"surcout|dividende|loyer","pts":4},{"label":"Demande la révocation","re":"revoc","pts":3}],"articles":[],"faille":"La demande vise un préjudice personnel non démontré.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le gérant a conclu sans autorisation une convention défavorable avec un proche et distribué des dividendes fictifs ; Par ces motifs : le condamne à verser à la société le surcoût de loyer et les dividendes indûment distribués, et prononce sa révocation."},{"min":45,"text":"Le Tribunal, attendu que la convention litigieuse constitue une faute de gestion ; Par ces motifs : condamne le gérant à rembourser le surcoût de loyer et rejette le surplus."},{"min":0,"text":"Le Tribunal, attendu qu'aucune faute précise n'est démontrée ; Par ces motifs : rejette la demande."}]},{"id":"retard-paiement","matiere":"affaires","title":"Imprimerie Tétouan c/ Groupe Média Nord","court":"Tribunal de commerce de Tétouan","object":"Indemnité de retard sur des factures payées avec quatre mois de retard.","you":"Avocat du fournisseur (Imprimerie Tétouan)","adverseName":"Avocat de Média Nord","facts":"L'imprimerie a livré des magazines avec paiement convenu à 60 jours. Média Nord a payé les 400 000 DH de factures avec quatre mois de retard. L'imprimerie réclame l'indemnité de retard prévue par le Code de commerce ; Média Nord refuse, aucune pénalité n'étant écrite au contrat.","rounds":[{"name":"L'indemnité est-elle due ?","adverse":"Monsieur le Président, le contrat ne prévoit aucune pénalité de retard. Le principal a été payé : la demande est sans objet.","prompt":"Défendez le principe de l'indemnité de retard.","options":[{"label":"Indemnité légale","detail":"Les conditions de paiement doivent prévoir une indemnité exigible dès le lendemain de l'échéance, à un taux minimal réglementaire.","pts":17,"speech":"Le Code de commerce impose que les conditions de paiement précisent une indemnité de retard exigible le jour suivant la date convenue, à un taux qui ne peut être inférieur au taux réglementaire. L'absence de clause ne prive pas le créancier de ce minimum légal.","ok":["Invoque le régime légal des délais de paiement","Écarte l'argument de l'absence de clause"],"ko":[]},{"label":"Réclamer des dommages généraux","detail":"Demander une indemnisation sans fondement précis.","pts":8,"speech":"Notre cliente a subi un préjudice de trésorerie.","ok":[],"ko":["Ne mobilise pas le régime spécial plus favorable"]}],"concepts":[{"label":"Invoque l'indemnité légale de retard","re":"indemnite de retard|taux|reglementaire","pts":6,"key":true},{"label":"Exigible dès le lendemain de l'échéance","re":"lendemain|jour suivant|echeance","pts":4},{"label":"L'absence de clause est indifférente","re":"clause|contrat","pts":3}],"articles":[{"code":"CCOM","article":"78-3","label":"Art. 78-3 Code de commerce (indemnité de retard)","pts":5}],"faille":"Sans clause ni fondement légal invoqué, aucune pénalité n'est due.","concede":"Le régime légal s'applique, soit. Mais le montant se discute."},{"name":"Le calcul","adverse":"Le retard s'explique par une réorganisation interne ; et le fournisseur a accepté les paiements sans réserve.","prompt":"Répondez sur le calcul et l'acceptation des paiements.","options":[{"label":"Calcul précis, pas de renonciation","detail":"Taux légal appliqué par facture et par jour ; un paiement accepté n'emporte pas renonciation.","pts":16,"speech":"Nous produisons un tableau : pour chaque facture, l'échéance, la date de paiement et l'indemnité au taux réglementaire. Accepter un paiement tardif n'est pas renoncer à l'indemnité, et des difficultés internes ne sont pas une force majeure.","ok":["Produit un calcul par facture","Écarte la renonciation","Écarte la réorganisation interne"],"ko":[]},{"label":"Réclamer un forfait","detail":"Demander 20 % des factures.","pts":6,"speech":"Nous demandons 80 000 Dirhams.","ok":[],"ko":["Aucun calcul","Montant arbitraire"]}],"concepts":[{"label":"Calcul facture par facture","re":"tableau|calcul|facture par facture|par jour","pts":5,"key":true},{"label":"Pas de renonciation","re":"renonc|sans reserve","pts":4},{"label":"La réorganisation n'est pas une force majeure","re":"force majeure|reorganis|interne","pts":3}],"articles":[],"faille":"La demande n'est pas chiffrée sérieusement.","concede":"Le calcul est clair."},{"name":"Conclusions","adverse":"Média Nord propose de régler la moitié pour clore le litige.","prompt":"Concluez.","options":[{"label":"Totalité de l'indemnité légale","detail":"Maintenir le montant calculé, avec dommages pour retard sur l'indemnité.","pts":15,"speech":"Nous maintenons l'indemnité légale telle que calculée. Le minimum fixé par la loi n'a pas vocation à être divisé par deux.","ok":["Cohérent avec le régime légal"],"ko":[]},{"label":"Accepter la moitié","detail":"Transiger.","pts":9,"speech":"Nous acceptons la proposition.","ok":["Rapidité"],"ko":["Renonce à la moitié d'un minimum légal"]}],"concepts":[{"label":"Maintient le calcul légal","re":"maintien|totalite|calcul","pts":4,"key":true}],"articles":[],"faille":"Le fournisseur se contente d'une transaction.","concede":"Nous prenons acte."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'indemnité de retard est due de plein droit au taux minimal réglementaire, nonobstant le silence du contrat ; Par ces motifs : condamne Média Nord au paiement de l'indemnité calculée facture par facture."},{"min":45,"text":"Le Tribunal, attendu que l'indemnité légale est due mais que son calcul doit être vérifié ; Par ces motifs : en fixe le principe et ordonne une expertise comptable."},{"min":0,"text":"Le Tribunal, attendu que le fournisseur n'invoque aucun fondement précis ; Par ces motifs : rejette la demande."}]},{"id":"redressement","matiere":"affaires","title":"Matériaux du Sud c/ syndic de Batiplus SA","court":"Tribunal de commerce d'Agadir","object":"Déclaration de créance tardive dans une procédure de redressement judiciaire.","you":"Avocat du créancier (Matériaux du Sud)","adverseName":"Avocat du syndic","facts":"Batiplus SA a été placée en redressement judiciaire. Matériaux du Sud, à qui elle doit 650 000 DH, figurait sur la liste des créanciers remise par la débitrice, mais n'a jamais reçu l'avis du syndic. Elle a déclaré sa créance trois mois après la publication du jugement d'ouverture. Le syndic la dit forclose.","rounds":[{"name":"La forclusion","adverse":"Monsieur le Président, la déclaration doit intervenir dans les deux mois. Matériaux du Sud a déclaré après trois mois : elle est forclose.","prompt":"Contestez la forclusion.","options":[{"label":"Le délai n'a pas couru","detail":"Pour un créancier inscrit sur la liste, le délai court à compter de l'avis du syndic, jamais reçu.","pts":18,"speech":"Le délai de deux mois ne court pas pour tous à partir de la publication. Pour les créanciers inscrits sur la liste fournie par le débiteur ou connus du syndic, il court à compter de l'avis que le syndic doit leur adresser. Matériaux du Sud figurait sur la liste et n'a jamais reçu cet avis : le délai n'a donc pas commencé à courir.","ok":["Distingue créanciers connus et inconnus","Identifie le point de départ du délai","S'appuie sur l'absence d'avis"],"ko":[]},{"label":"Invoquer l'équité","detail":"Demander la bienveillance du tribunal.","pts":6,"speech":"Il serait injuste de priver ma cliente de sa créance.","ok":[],"ko":["Aucun argument juridique"]}],"concepts":[{"label":"Le délai court à partir de l'avis du syndic","re":"avis","pts":6,"key":true},{"label":"Créancier inscrit sur la liste / connu","re":"liste|connu|inscrit","pts":5},{"label":"Délai de deux mois","re":"deux mois|2 mois","pts":3}],"articles":[{"code":"CCOM","article":"719","label":"Art. 719 Code de commerce (déclaration au syndic)","pts":3},{"code":"CCOM","article":"720","label":"Art. 720 Code de commerce (délai de deux mois)","pts":3}],"faille":"Le créancier ne démontre pas qu'il était connu du syndic.","concede":"L'avis n'a pas été envoyé, c'est exact. Le montant reste à vérifier."},{"name":"La preuve de la créance","adverse":"Subsidiairement, le syndic conteste le montant : certaines factures ne sont pas signées par Batiplus.","prompt":"Justifiez la créance.","options":[{"label":"Pièces commerciales","detail":"Bons de livraison signés, relevés de compte, preuve libre entre commerçants.","pts":16,"speech":"Les livraisons sont attestées par des bons signés par les chefs de chantier de Batiplus et par le relevé de compte que Batiplus elle-même a reconnu en fin d'exercice. Entre commerçants, la preuve est libre.","ok":["Pièces émanant de la débitrice","Liberté de la preuve"],"ko":[]},{"label":"Affirmer le montant","detail":"Maintenir sans pièces.","pts":6,"speech":"Le montant est exact.","ok":[],"ko":["Aucune pièce"]}],"concepts":[{"label":"Bons signés / relevé reconnu","re":"bons?|signe|releve|reconnu","pts":5,"key":true},{"label":"Liberté de la preuve commerciale","re":"liberte de la preuve|preuve (est )?libre","pts":4}],"articles":[{"code":"CCOM","article":"334","label":"Art. 334 Code de commerce (preuve libre)","pts":3}],"faille":"La créance n'est pas justifiée.","concede":"Les pièces sont probantes."},{"name":"Conclusions","adverse":"Le syndic demande que la créance soit au moins réduite de 20 %.","prompt":"Concluez.","options":[{"label":"Admission intégrale","detail":"Déclaration recevable, créance admise pour 650 000 DH.","pts":15,"speech":"Nous demandons que la déclaration soit jugée recevable et la créance admise au passif pour 650 000 Dirhams.","ok":["Conclusion nette"],"ko":[]},{"label":"Accepter la réduction","detail":"Transiger à 520 000 DH.","pts":8,"speech":"Nous acceptons.","ok":[],"ko":["Abandonne 130 000 DH sans motif"]}],"concepts":[{"label":"Recevabilité et admission","re":"recevab|admi","pts":4,"key":true}],"articles":[],"faille":"Le créancier n'a pas de conclusion claire.","concede":"Les conclusions sont nettes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le créancier figurait sur la liste fournie par la débitrice et n'a pas reçu l'avis du syndic, de sorte que le délai de déclaration n'a pas couru ; Par ces motifs : déclare la déclaration recevable et admet la créance pour 650 000 Dirhams."},{"min":45,"text":"Le Tribunal, attendu que la déclaration est recevable mais que certaines factures ne sont pas justifiées ; Par ces motifs : admet la créance pour 540 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu que la déclaration est intervenue hors délai sans justification ; Par ces motifs : constate la forclusion."}]},{"id":"clause-abusive","matiere":"affaires","title":"Mme Tazi c/ Fitness Club Royal","court":"Tribunal de première instance de Rabat","object":"Clause abusive dans un abonnement de salle de sport.","you":"Avocat de la consommatrice (Mme Tazi)","adverseName":"Avocat du club","facts":"Mme Tazi a souscrit un abonnement de 24 mois. Le contrat prévoit qu'en cas de résiliation, même pour raison médicale, la totalité des mensualités restantes est due, alors que le club peut modifier ses horaires et fermer des activités sans préavis. Après une opération, Mme Tazi veut résilier.","rounds":[{"name":"Le caractère abusif","adverse":"Monsieur le Président, Mme Tazi a signé en connaissance de cause. Le contrat fait la loi des parties.","prompt":"Démontrez le caractère abusif de la clause.","options":[{"label":"Déséquilibre significatif","detail":"Clause qui crée un déséquilibre significatif entre les droits et obligations des parties, au détriment de la consommatrice.","pts":18,"speech":"La force obligatoire du contrat cède devant la protection du consommateur : est abusive toute clause qui crée, à son détriment, un déséquilibre significatif entre les droits et obligations des parties. Ici, la cliente doit tout payer même si elle ne peut plus venir pour raison médicale, tandis que le club peut réduire unilatéralement ses prestations sans préavis.","ok":["Invoque le régime spécial des clauses abusives","Démontre le déséquilibre par comparaison"],"ko":[]},{"label":"Invoquer la maladie seule","detail":"Demander une exception compassionnelle.","pts":8,"speech":"Mme Tazi est malade, elle ne peut pas payer.","ok":[],"ko":["Ne qualifie pas la clause"]}],"concepts":[{"label":"Déséquilibre significatif","re":"desequilibre","pts":6,"key":true},{"label":"Compare les droits du club et de la cliente","re":"club peut|modifier|horaires|unilateral","pts":4},{"label":"Relève la raison médicale","re":"medical|operation|sante","pts":3}],"articles":[{"code":"L31-08","article":"15","label":"Art. 15 loi 31-08 (définition de la clause abusive)","pts":5}],"faille":"La consommatrice ne démontre aucun déséquilibre.","concede":"Le déséquilibre est réel. Mais le contrat doit-il tomber entier ?"},{"name":"La sanction","adverse":"Si la clause tombe, tout le contrat tombe : Mme Tazi devra rembourser les séances utilisées à plein tarif.","prompt":"Précisez la sanction.","options":[{"label":"Nullité de la clause seule","detail":"La clause abusive est nulle ; le contrat subsiste dans ses autres dispositions.","pts":17,"speech":"La loi est précise : la clause abusive est nulle et de nul effet, mais le contrat reste applicable dans ses autres dispositions s'il peut subsister sans elle. La cliente a payé les mois écoulés ; seule la clause de pénalité disparaît.","ok":["Distingue nullité de la clause et du contrat"],"ko":[]},{"label":"Demander l'annulation totale","detail":"Faire annuler tout le contrat.","pts":7,"speech":"Nous demandons l'annulation du contrat entier.","ok":[],"ko":["Expose la cliente à des restitutions"]}],"concepts":[{"label":"Nullité de la seule clause","re":"clause.*nul|nul.*clause|nulle et de nul effet","pts":6,"key":true},{"label":"Le contrat subsiste","re":"subsist|reste applicable|autres dispositions","pts":4}],"articles":[{"code":"L31-08","article":"19","label":"Art. 19 loi 31-08 (nullité des clauses abusives)","pts":4}],"faille":"La demande d'annulation totale se retourne contre la consommatrice.","concede":"La nullité partielle s'impose."},{"name":"Conclusions","adverse":"Le club propose de suspendre l'abonnement trois mois au lieu de le résilier.","prompt":"Concluez.","options":[{"label":"Résiliation sans pénalité","detail":"Nullité de la clause, résiliation au jour de la demande, remboursement des prélèvements postérieurs.","pts":16,"speech":"Nous demandons la nullité de la clause, la résiliation à la date de la demande et le remboursement des prélèvements effectués depuis.","ok":["Demandes précises"],"ko":[]},{"label":"Accepter la suspension","detail":"Accepter trois mois de suspension.","pts":8,"speech":"Mme Tazi accepte.","ok":[],"ko":["La clause abusive reste en place"]}],"concepts":[{"label":"Résiliation et remboursement","re":"resili|rembours","pts":4,"key":true}],"articles":[],"faille":"La consommatrice ne précise pas ce qu'elle demande.","concede":"Les demandes sont claires."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la clause imposant le paiement de toutes les mensualités restantes, même pour motif médical, crée un déséquilibre significatif au détriment de la consommatrice ; Par ces motifs : la déclare nulle, constate la résiliation et ordonne le remboursement des prélèvements postérieurs."},{"min":45,"text":"Le Tribunal, attendu que la clause est abusive ; Par ces motifs : la déclare nulle et réduit les sommes dues à deux mensualités."},{"min":0,"text":"Le Tribunal, attendu que la consommatrice ne démontre pas le caractère abusif ; Par ces motifs : rejette la demande."}]},{"id":"degat-eaux","matiere":"civil","title":"M. Kettani c/ M. Rami","court":"Tribunal de première instance de Meknès","object":"Dégât des eaux provenant de l'appartement du dessus : 45 000 DH de dommages.","you":"Avocat de la victime (M. Kettani)","adverseName":"Avocat de M. Rami","facts":"Une conduite du chauffe-eau de M. Rami, au troisième étage, a cédé pendant son absence. L'eau a endommagé le plafond, le parquet et un ordinateur de M. Kettani, au deuxième étage. Un constat d'huissier et un devis de 45 000 DH ont été établis.","rounds":[{"name":"Le fondement de la responsabilité","adverse":"Monsieur le Président, mon client était absent et n'a commis aucune faute. Une fuite est un accident.","prompt":"Fondez la responsabilité.","options":[{"label":"Responsabilité du fait des choses","detail":"Le gardien répond du dommage causé par la chose qu'il a sous sa garde, sans qu'il faille prouver sa faute.","pts":18,"speech":"Nous n'avons pas à prouver une faute. Chacun répond du dommage causé par les choses qu'il a sous sa garde ; le chauffe-eau et ses conduites sont sous la garde de M. Rami, et ils sont la cause directe du dommage. Pour s'exonérer, c'est à lui de démontrer qu'il a tout fait pour empêcher le dommage et que celui-ci vient d'un cas fortuit ou de la faute de la victime.","ok":["Choisit le bon fondement","Renverse la charge de la preuve"],"ko":[]},{"label":"Chercher une faute","detail":"Soutenir que M. Rami a mal entretenu son chauffe-eau, sans preuve.","pts":9,"speech":"M. Rami n'entretenait pas son chauffe-eau.","ok":["Piste possible"],"ko":["Faute à prouver, alors qu'un fondement plus simple existe"]}],"concepts":[{"label":"Invoque la garde de la chose","re":"garde|chose","pts":6,"key":true},{"label":"Pas besoin de prouver une faute","re":"sans faute|pas (a|besoin de) prouver|presum","pts":4},{"label":"Lien de causalité (cause directe)","re":"cause directe|causalite|constat","pts":3}],"articles":[{"code":"DOC","article":"88","label":"Art. 88 DOC (responsabilité du fait des choses)","pts":5}],"faille":"La victime ne prouve aucune faute : la demande doit être rejetée.","concede":"Le fondement est le bon. Reste l'exonération."},{"name":"L'exonération","adverse":"Le chauffe-eau avait été révisé six mois plus tôt par un professionnel : mon client a fait tout ce qui était nécessaire.","prompt":"Répondez à la tentative d'exonération.","options":[{"label":"Les deux conditions sont cumulatives","detail":"Il faut avoir tout fait pour empêcher le dommage ET que le dommage dépende d'un cas fortuit ou de la faute de la victime.","pts":16,"speech":"L'exonération exige deux conditions cumulatives : avoir fait tout le nécessaire, et que le dommage dépende d'un cas fortuit, d'une force majeure ou de la faute de la victime. Une révision six mois plus tôt ne prouve aucun cas fortuit : une conduite qui cède est un défaut de la chose elle-même.","ok":["Rappelle le caractère cumulatif","Le défaut de la chose n'est pas un cas fortuit"],"ko":[]},{"label":"Contester la révision","detail":"Douter de la facture de révision.","pts":7,"speech":"La facture de révision est peut-être fausse.","ok":[],"ko":["Accusation sans preuve"]}],"concepts":[{"label":"Conditions cumulatives","re":"cumulat|deux conditions|et que","pts":5,"key":true},{"label":"Pas de cas fortuit / force majeure","re":"cas fortuit|force majeure","pts":5}],"articles":[],"faille":"La révision prouve la diligence du gardien : il est exonéré.","concede":"La révision ne suffit pas. Le montant reste à discuter."},{"name":"Le montant","adverse":"Le devis est surévalué : le parquet était ancien et l'ordinateur avait cinq ans.","prompt":"Défendez l'évaluation du préjudice.","options":[{"label":"Perte effective et dépenses de remise en état","detail":"Constat, devis, facture de l'ordinateur ; demande d'expertise en cas de contestation.","pts":15,"speech":"La réparation couvre la perte effective et les dépenses nécessaires pour réparer les suites du fait dommageable. Le constat et le devis sont détaillés. Si la défense conteste la vétusté, qu'une expertise la chiffre ; elle ne peut pas l'affirmer sans preuve.","ok":["Notion de perte effective","Propose une expertise"],"ko":[]},{"label":"Ajouter un préjudice moral élevé","detail":"Réclamer 100 000 DH de préjudice moral.","pts":7,"speech":"Nous ajoutons 100 000 Dirhams de préjudice moral.","ok":[],"ko":["Demande disproportionnée"]}],"concepts":[{"label":"Perte effective / dépenses de remise en état","re":"perte|depenses|remise en etat|devis","pts":5,"key":true},{"label":"Demande une expertise","re":"expert","pts":4}],"articles":[{"code":"DOC","article":"98","label":"Art. 98 DOC (étendue des dommages)","pts":3}],"faille":"Le préjudice est surévalué.","concede":"Le montant sera ajusté pour vétusté."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le dommage a pour cause directe une chose sous la garde du défendeur, qui ne prouve ni cas fortuit ni faute de la victime ; Par ces motifs : le condamne à payer 45 000 Dirhams."},{"min":45,"text":"Le Tribunal, attendu que la responsabilité du gardien est engagée, mais qu'il convient de tenir compte de la vétusté ; Par ces motifs : le condamne à payer 32 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu que la victime ne précise pas le fondement de sa demande ni n'établit de faute ; Par ces motifs : rejette la demande."}]},{"id":"mur-effondre","matiere":"civil","title":"Mme Berrada c/ M. Lahlou","court":"Tribunal de première instance de Fès","object":"Effondrement du mur d'une maison ancienne sur une voiture garée.","you":"Avocat du propriétaire (M. Lahlou)","adverseName":"Avocat de Mme Berrada","facts":"Le mur de clôture de la maison de M. Lahlou, à la médina, s'est effondré pendant un orage exceptionnel, écrasant la voiture de Mme Berrada. La météo nationale avait émis une alerte rouge ; plusieurs constructions récentes du quartier ont aussi été endommagées. Un rapport d'entretien de l'an dernier décrit le mur comme sain.","rounds":[{"name":"Le régime applicable","adverse":"Monsieur le Président, le propriétaire d'un édifice répond de son écroulement. M. Lahlou doit payer.","prompt":"Présentez la défense.","options":[{"label":"Ruine due à un événement extérieur","detail":"Le propriétaire répond de la ruine due à la vétusté, au défaut d'entretien ou au vice de construction ; ce n'est pas le cas.","pts":17,"speech":"La responsabilité du propriétaire d'un édifice suppose que l'écroulement soit arrivé par vétusté, défaut d'entretien ou vice de construction. Or le rapport d'entretien de l'an dernier décrit un mur sain, et l'effondrement est survenu lors d'un orage sous alerte rouge qui a aussi endommagé des constructions récentes.","ok":["Rappelle les causes légales de la responsabilité","Produit le rapport d'entretien","Met en avant l'événement exceptionnel"],"ko":[]},{"label":"Nier être propriétaire","detail":"Soutenir que le mur est mitoyen.","pts":5,"speech":"Ce mur n'est pas à mon client.","ok":[],"ko":["Contredit le dossier"]}],"concepts":[{"label":"Pas de vétusté, défaut d'entretien ni vice","re":"vetuste|entretien|vice","pts":6,"key":true},{"label":"Événement exceptionnel / orage / alerte","re":"orage|alerte|exceptionnel|force majeure","pts":5},{"label":"Produit le rapport d'entretien","re":"rapport|sain","pts":3}],"articles":[{"code":"DOC","article":"89","label":"Art. 89 DOC (responsabilité du propriétaire d'un édifice)","pts":4}],"faille":"Le propriétaire ne démontre pas l'origine extérieure de l'effondrement.","concede":"L'orage était exceptionnel. Mais il reste la garde de la chose."},{"name":"La garde de la chose","adverse":"À défaut, le propriétaire est gardien du mur et répond du fait des choses.","prompt":"Répondez.","options":[{"label":"Exonération : diligence + force majeure","detail":"Le gardien s'exonère s'il a fait le nécessaire et si le dommage dépend d'une force majeure.","pts":16,"speech":"Même sur ce terrain, M. Lahlou s'exonère : il a fait tout le nécessaire, comme le prouve l'entretien régulier, et le dommage dépend d'une force majeure, un orage sous alerte rouge qui a frappé tout le quartier.","ok":["Réunit les deux conditions d'exonération"],"ko":[]},{"label":"Ignorer","detail":"Ne pas répondre à ce fondement.","pts":5,"speech":"Nous maintenons notre position.","ok":[],"ko":["Laisse le second fondement sans réponse"]}],"concepts":[{"label":"A fait le nécessaire (entretien)","re":"necessaire|entretien|diligen","pts":5,"key":true},{"label":"Force majeure","re":"force majeure|orage|alerte","pts":5}],"articles":[{"code":"DOC","article":"88","label":"Art. 88 DOC (fait des choses et exonération)","pts":3}],"faille":"Le gardien ne s'exonère pas.","concede":"Les conditions d'exonération sont plausibles."},{"name":"Conclusions","adverse":"Mme Berrada demande au moins la moitié des réparations, soit 30 000 DH.","prompt":"Concluez.","options":[{"label":"Rejet, subsidiairement expertise","detail":"Rejet total ; à titre subsidiaire, expertise sur la cause de l'effondrement.","pts":15,"speech":"Nous concluons au rejet. À titre subsidiaire, une expertise sur la cause de l'effondrement permettra de vérifier qu'aucun défaut d'entretien n'est en cause.","ok":["Hiérarchise les demandes"],"ko":[]},{"label":"Accepter 30 000 DH","detail":"Transiger.","pts":8,"speech":"Nous acceptons.","ok":[],"ko":["Reconnaît une responsabilité contestable"]}],"concepts":[{"label":"Rejet / expertise","re":"rejet|expert","pts":4,"key":true}],"articles":[],"faille":"Le propriétaire n'a pas de conclusion claire.","concede":"Les conclusions sont nettes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'écroulement n'est dû ni à la vétusté ni à un défaut d'entretien, mais à un orage exceptionnel constitutif de force majeure ; Par ces motifs : rejette la demande."},{"min":45,"text":"Le Tribunal, attendu que la cause de l'effondrement doit être précisée ; Par ces motifs : ordonne une expertise."},{"min":0,"text":"Le Tribunal, attendu que le propriétaire ne démontre pas l'origine extérieure de l'effondrement ; Par ces motifs : le condamne à réparer l'intégralité du dommage."}]},{"id":"vice-cache","matiere":"civil","title":"M. Ouazzani c/ M. Chraibi","court":"Tribunal de première instance de Kénitra","object":"Voiture d'occasion : boîte de vitesses défaillante découverte après la vente.","you":"Avocat de l'acheteur (M. Ouazzani)","adverseName":"Avocat du vendeur","facts":"M. Ouazzani a acheté à un particulier une voiture d'occasion 95 000 DH. Douze jours après la livraison, la boîte de vitesses a lâché ; le garagiste a constaté une fuite ancienne colmatée avec un produit masquant. M. Ouazzani a adressé une réclamation écrite le jour même et assigné vingt jours après la livraison.","rounds":[{"name":"Le vice","adverse":"Monsieur le Président, une voiture d'occasion s'achète en l'état. L'acheteur aurait dû la faire inspecter.","prompt":"Caractérisez le vice.","options":[{"label":"Vice caché qui rend la chose impropre","detail":"Le vendeur garantit les vices qui rendent la chose impropre à son usage ; ici le défaut était masqué.","pts":17,"speech":"Le vendeur garantit les vices qui diminuent sensiblement la valeur de la chose ou la rendent impropre à l'usage auquel elle est destinée. Une boîte de vitesses hors d'usage rend la voiture impropre à rouler, et la fuite avait été colmatée avec un produit masquant : le vice n'était pas décelable par un acheteur non professionnel.","ok":["Qualifie le vice","Démontre son caractère caché","Met en évidence la dissimulation"],"ko":[]},{"label":"Invoquer la déception","detail":"Dire que la voiture ne plaît plus.","pts":4,"speech":"Mon client est déçu de son achat.","ok":[],"ko":["Aucun vice juridiquement caractérisé"]}],"concepts":[{"label":"Rend la chose impropre à l'usage / diminue sa valeur","re":"impropre|usage|valeur","pts":5,"key":true},{"label":"Vice caché / non décelable","re":"cache|masqu|decelable|colmat","pts":5},{"label":"Rapport du garagiste","re":"garag|rapport|constat","pts":3}],"articles":[{"code":"DOC","article":"549","label":"Art. 549 DOC (garantie des vices)","pts":5}],"faille":"L'acheteur ne démontre pas un vice antérieur à la vente.","concede":"Le vice est établi. Mais l'action est-elle dans les délais ?"},{"name":"Le délai d'action","adverse":"L'action est tardive : pour un meuble, le délai est très court.","prompt":"Répondez sur le délai.","options":[{"label":"Action dans les trente jours","detail":"Pour une chose mobilière, l'action doit être intentée dans les trente jours après la délivrance : c'est le cas.","pts":17,"speech":"Pour les choses mobilières, l'action doit être intentée dans les trente jours après la délivrance. Le vice est apparu au douzième jour, la réclamation a été faite le jour même et l'assignation au vingtième jour : le délai est respecté.","ok":["Identifie le bon délai","Démontre le respect par les dates"],"ko":[]},{"label":"Dire que le délai ne s'applique pas","detail":"Soutenir qu'aucun délai n'existe.","pts":5,"speech":"Il n'y a aucun délai en la matière.","ok":[],"ko":["Faux : un délai de déchéance existe"]}],"concepts":[{"label":"Trente jours pour un meuble","re":"trente|30 jours","pts":6,"key":true},{"label":"Démontre par les dates","re":"douze|vingt|20 jours|12 jours|delivrance","pts":4}],"articles":[{"code":"DOC","article":"573","label":"Art. 573 DOC (délai de l'action rédhibitoire)","pts":5}],"faille":"L'action est tardive.","concede":"Le délai est respecté. Reste la sanction."},{"name":"La sanction","adverse":"Le vendeur propose de payer la réparation de la boîte, 18 000 DH.","prompt":"Concluez.","options":[{"label":"Résolution et restitution, ou réduction","detail":"Résolution de la vente et restitution du prix ; dommages en raison de la dissimulation.","pts":15,"speech":"Nous demandons la résolution de la vente et la restitution des 95 000 Dirhams contre retour du véhicule, ainsi que des dommages-intérêts : le vendeur, qui a masqué le défaut, ne pouvait l'ignorer. À titre subsidiaire, la prise en charge de la réparation et des frais.","ok":["Demande principale et subsidiaire","Exploite la mauvaise foi du vendeur"],"ko":[]},{"label":"Accepter 18 000 DH","detail":"Transiger.","pts":9,"speech":"Nous acceptons la réparation.","ok":["Rapide"],"ko":["Renonce aux dommages liés à la dissimulation"]}],"concepts":[{"label":"Résolution / restitution du prix","re":"resolution|restitution|95","pts":4,"key":true},{"label":"Mauvaise foi / dissimulation","re":"mauvaise foi|dissimul|masqu","pts":3}],"articles":[],"faille":"L'acheteur ne précise pas sa demande.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la voiture était affectée d'un vice caché la rendant impropre à l'usage, dissimulé par le vendeur, et que l'action a été intentée dans les trente jours ; Par ces motifs : prononce la résolution, ordonne la restitution de 95 000 Dirhams et alloue 10 000 Dirhams de dommages-intérêts."},{"min":45,"text":"Le Tribunal, attendu que le vice est établi ; Par ces motifs : condamne le vendeur à prendre en charge la réparation, soit 18 000 Dirhams, et les frais d'immobilisation."},{"min":0,"text":"Le Tribunal, attendu que l'acheteur ne démontre pas un vice antérieur à la vente ; Par ces motifs : rejette la demande."}]},{"id":"pret-oral","matiere":"civil","title":"M. Hajji c/ M. Sefrioui","court":"Tribunal de première instance de Oujda","object":"Remboursement d'un prêt de 60 000 DH prétendument consenti sans écrit.","you":"Avocat du défendeur (M. Sefrioui)","adverseName":"Avocat de M. Hajji","facts":"M. Hajji affirme avoir prêté 60 000 DH en espèces à son ancien associé, M. Sefrioui, et produit deux témoins qui disent avoir assisté à la remise de l'argent. Aucun écrit n'a été signé. M. Sefrioui conteste tout prêt.","rounds":[{"name":"La preuve du prêt","adverse":"Monsieur le Président, deux témoins honorables ont vu la remise des fonds. Le prêt est prouvé.","prompt":"Contestez le mode de preuve.","options":[{"label":"Écrit obligatoire au-delà de 10 000 DH","detail":"Les conventions excédant dix mille dirhams ne peuvent être prouvées par témoins.","pts":18,"speech":"La loi exige un écrit : les conventions excédant la valeur de dix mille dirhams ne peuvent être prouvées par témoins. Le prêt allégué est de soixante mille dirhams ; les témoignages sont donc irrecevables pour en établir l'existence.","ok":["Identifie la règle de preuve","Applique le seuil au montant"],"ko":[]},{"label":"Attaquer les témoins","detail":"Mettre en cause l'honnêteté des témoins.","pts":8,"speech":"Ces témoins sont des amis du demandeur.","ok":["Peut affaiblir les témoignages"],"ko":["Passe à côté de l'irrecevabilité"]}],"concepts":[{"label":"Seuil de dix mille dirhams / écrit exigé","re":"dix mille|10 000|10000|ecrit","pts":6,"key":true},{"label":"Témoins irrecevables","re":"temoin","pts":4}],"articles":[{"code":"DOC","article":"443","label":"Art. 443 DOC (preuve par écrit au-delà de 10 000 DH)","pts":5}],"faille":"La défense ne conteste pas sérieusement les témoignages.","concede":"La preuve testimoniale est discutable. Mais il existe d'autres indices."},{"name":"Les autres indices","adverse":"Le demandeur produit aussi un SMS où M. Sefrioui écrit « je te rendrai tout dès que possible ».","prompt":"Répondez à cette nouvelle pièce.","options":[{"label":"Message ambigu, charge de la preuve","detail":"Le SMS ne mentionne ni prêt ni montant ; la preuve incombe au demandeur.","pts":15,"speech":"Ce message ne mentionne ni prêt, ni somme, ni date ; il peut se rapporter au règlement des comptes entre anciens associés. La preuve de l'obligation incombe à celui qui s'en prévaut, et ce message ne suffit pas à l'établir pour soixante mille dirhams.","ok":["Souligne l'ambiguïté","Rappelle la charge de la preuve"],"ko":[]},{"label":"Nier le message","detail":"Dire que le téléphone a été piraté.","pts":5,"speech":"Ce message n'est pas de mon client.","ok":[],"ko":["Affirmation invraisemblable sans preuve"]}],"concepts":[{"label":"Message ambigu (ni prêt ni montant)","re":"ambigu|ni pret|ni montant|ni somme","pts":5,"key":true},{"label":"Charge de la preuve sur le demandeur","re":"preuve|incombe","pts":4}],"articles":[{"code":"DOC","article":"399","label":"Art. 399 DOC (charge de la preuve)","pts":4}],"faille":"Le message vaut reconnaissance de dette.","concede":"Le message est un indice, rien de plus."},{"name":"Conclusions","adverse":"Le demandeur propose un serment décisoire.","prompt":"Concluez.","options":[{"label":"Rejet faute de preuve écrite","detail":"Rejet de la demande ; prudence sur le serment.","pts":14,"speech":"Nous concluons au rejet de la demande, faute de preuve écrite d'un prêt supérieur à dix mille dirhams.","ok":["Conclusion conforme à la règle"],"ko":[]},{"label":"Reconnaître une partie","detail":"Proposer 20 000 DH.","pts":7,"speech":"Mon client propose 20 000 Dirhams.","ok":[],"ko":["Reconnaissance implicite d'un prêt contesté"]}],"concepts":[{"label":"Rejet faute d'écrit","re":"rejet|ecrit","pts":4,"key":true}],"articles":[],"faille":"La défense n'a pas de conclusion claire.","concede":"Les conclusions sont nettes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le prêt allégué excède dix mille dirhams et ne peut être prouvé par témoins, et que le message produit ne mentionne ni prêt ni montant ; Par ces motifs : rejette la demande."},{"min":45,"text":"Le Tribunal, attendu que le message constitue un commencement de preuve insuffisant ; Par ces motifs : rejette la demande en l'état."},{"min":0,"text":"Le Tribunal, attendu que le prêt est établi par les témoignages et le message de reconnaissance ; Par ces motifs : condamne le défendeur à payer 60 000 Dirhams."}]},{"id":"loyers-impayes","matiere":"civil","title":"Mme Sqalli c/ M. Daoudi","court":"Tribunal de première instance de Rabat","object":"Loyers d'habitation impayés depuis sept ans et demi.","you":"Avocat de la bailleresse (Mme Sqalli)","adverseName":"Avocat du locataire","facts":"M. Daoudi loue un appartement à Mme Sqalli. Il a cessé de payer régulièrement il y a sept ans et demi, réglant parfois quelques mois. Mme Sqalli réclame 270 000 DH d'arriérés et la résiliation du bail.","rounds":[{"name":"La prescription des loyers","adverse":"Monsieur le Président, les loyers se prescrivent : une grande partie de la demande est irrecevable.","prompt":"Répondez sur la prescription.","options":[{"label":"Limiter loyalement aux cinq dernières années","detail":"Les loyers se prescrivent par cinq ans à compter de chaque échéance : réclamer les loyers non prescrits.","pts":17,"speech":"Il est exact que les loyers se prescrivent par cinq années à partir de l'échéance de chaque terme. Nous limitons donc notre demande aux loyers échus depuis moins de cinq ans, soit 180 000 Dirhams, en produisant le décompte terme par terme.","ok":["Reconnaît la règle de prescription","Recalcule la demande","Produit un décompte"],"ko":[]},{"label":"Invoquer la prescription de quinze ans","detail":"Soutenir que toutes les actions se prescrivent par quinze ans.","pts":6,"speech":"La prescription de droit commun est de quinze ans.","ok":[],"ko":["Ignore la règle spéciale des loyers"]}],"concepts":[{"label":"Cinq ans pour les loyers","re":"cinq ans|5 ans|cinq annees","pts":6,"key":true},{"label":"À partir de chaque échéance / décompte","re":"echeance|terme|decompte","pts":4}],"articles":[{"code":"DOC","article":"391","label":"Art. 391 DOC (prescription quinquennale des loyers)","pts":5}],"faille":"La bailleresse maintient une demande en partie prescrite.","concede":"La demande est recalculée correctement."},{"name":"Les manquements du locataire","adverse":"Le locataire a payé quelques mois chaque année ; il n'a jamais été mis en demeure.","prompt":"Démontrez le manquement.","options":[{"label":"Obligation principale de payer le prix","detail":"Payer le loyer est l'obligation principale du preneur ; les paiements partiels ne la remplissent pas.","pts":15,"speech":"Le preneur est tenu de deux obligations principales, dont celle de payer le prix du louage. Des paiements sporadiques ne la remplissent pas. Au surplus, nous produisons deux lettres recommandées réclamant les arriérés.","ok":["Cite l'obligation principale du preneur","Produit les réclamations écrites"],"ko":[]},{"label":"Insister sur la mauvaise foi","detail":"Accuser le locataire sans pièces.","pts":7,"speech":"Le locataire est de mauvaise foi.","ok":[],"ko":["Aucune pièce"]}],"concepts":[{"label":"Obligation de payer le loyer","re":"payer|prix du louage|obligation","pts":5,"key":true},{"label":"Réclamations / mise en demeure","re":"recommande|reclam|mise en demeure","pts":4}],"articles":[{"code":"DOC","article":"663","label":"Art. 663 DOC (obligations du preneur)","pts":4}],"faille":"La bailleresse ne prouve aucune réclamation.","concede":"Le manquement est établi."},{"name":"Conclusions","adverse":"Le locataire demande un échéancier de cinq ans.","prompt":"Concluez.","options":[{"label":"Paiement + résiliation, échéancier court","detail":"Condamnation aux loyers non prescrits, résiliation, échéancier limité si nécessaire.","pts":15,"speech":"Nous demandons la condamnation au paiement de 180 000 Dirhams, la résiliation du bail et l'expulsion ; un échéancier ne saurait excéder quelques mois après sept ans d'impayés.","ok":["Demandes complètes"],"ko":[]},{"label":"Accepter cinq ans","detail":"Accepter l'échéancier.","pts":8,"speech":"Nous acceptons.","ok":[],"ko":["Laisse le locataire dans les lieux sans garantie"]}],"concepts":[{"label":"Paiement et résiliation","re":"resili|expuls|paiement","pts":4,"key":true}],"articles":[],"faille":"La bailleresse n'a pas de conclusion claire.","concede":"Les conclusions sont claires."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que les loyers se prescrivent par cinq ans et que le manquement du preneur à son obligation principale est établi ; Par ces motifs : le condamne à payer 180 000 Dirhams, prononce la résiliation du bail et ordonne l'expulsion."},{"min":45,"text":"Le Tribunal, attendu que les loyers non prescrits sont dus ; Par ces motifs : condamne le locataire à payer 180 000 Dirhams avec un échéancier de douze mois."},{"min":0,"text":"Le Tribunal, attendu qu'une partie de la demande est prescrite et que la bailleresse ne distingue pas ; Par ces motifs : renvoie l'affaire pour production d'un décompte."}]},{"id":"prescription-facture","matiere":"civil","title":"Électro Plus c/ M. Naciri","court":"Tribunal de première instance de Settat","object":"Facture de fournitures impayée depuis six ans.","you":"Avocat du client (M. Naciri)","adverseName":"Avocat d'Électro Plus","facts":"Électro Plus réclame à M. Naciri, particulier, le paiement d'une facture de 38 000 DH pour l'équipement électroménager de sa maison, livré il y a six ans. Aucune relance écrite n'a été envoyée depuis la livraison. M. Naciri affirme avoir payé en espèces mais a perdu le reçu.","rounds":[{"name":"La prescription","adverse":"Monsieur le Président, toutes les actions naissant d'une obligation se prescrivent par quinze ans. La demande est recevable.","prompt":"Opposez la prescription.","options":[{"label":"Prescription de deux ans (fournitures domestiques)","detail":"L'action des marchands pour les fournitures faites aux particuliers pour leurs usages domestiques se prescrit par deux ans.","pts":18,"speech":"Le délai de quinze ans est le droit commun, mais la loi prévoit des exceptions. L'action des marchands et fournisseurs à raison des fournitures faites aux particuliers pour leurs usages domestiques se prescrit par deux ans, à partir du jour de la fourniture. L'électroménager de la maison a été livré il y a six ans, sans aucun acte interruptif : l'action est prescrite depuis longtemps.","ok":["Distingue droit commun et exception","Choisit le délai des fournitures domestiques (deux ans)","Relève l'absence d'acte interruptif"],"ko":[]},{"label":"Prescription de cinq ans","detail":"Invoquer la prescription de cinq ans des fournisseurs.","pts":11,"speech":"L'action des fournisseurs se prescrit par cinq ans ; la livraison date de six ans : l'action est prescrite.","ok":["Le résultat est le même ici"],"ko":["Le délai de cinq ans vise les fournitures entre commerçants, pas celles faites aux particuliers"]}],"concepts":[{"label":"Prescription de deux ans (usages domestiques)","re":"deux ans|2 ans|domestique|particulier","pts":6,"key":true},{"label":"Le droit commun de quinze ans ne s'applique pas","re":"quinze|15 ans|exception","pts":4},{"label":"Aucun acte interruptif","re":"interrupt|relance|aucune","pts":4}],"articles":[{"code":"DOC","article":"388","label":"Art. 388 DOC (prescriptions de cinq ans, deux ans et un an)","pts":4},{"code":"DOC","article":"387","label":"Art. 387 DOC (prescription de droit commun)","pts":2}],"faille":"Le client n'oppose pas utilement la prescription.","concede":"Le délai de deux ans est largement dépassé. Le fournisseur invoque une reconnaissance."},{"name":"La reconnaissance de dette","adverse":"M. Naciri aurait reconnu la dette au téléphone il y a deux ans, ce qui a interrompu la prescription.","prompt":"Répondez.","options":[{"label":"Exiger la preuve de l'interruption","detail":"La preuve de l'interruption incombe à celui qui s'en prévaut ; un appel non prouvé ne suffit pas.","pts":15,"speech":"C'est à Électro Plus de prouver l'acte interruptif qu'elle invoque. Elle ne produit ni écrit, ni enregistrement, ni témoin. Une conversation alléguée ne suffit pas à interrompre la prescription.","ok":["Rappelle la charge de la preuve","Relève l'absence de pièce"],"ko":[]},{"label":"Reconnaître l'appel","detail":"Admettre la conversation.","pts":5,"speech":"Mon client a pu évoquer la facture.","ok":[],"ko":["Fournit à l'adversaire l'interruption"]}],"concepts":[{"label":"Preuve de l'interruption à la charge du fournisseur","re":"preuve|incombe|prouv","pts":5,"key":true},{"label":"Aucune pièce","re":"aucun|ni ecrit|enregistrement","pts":3}],"articles":[{"code":"DOC","article":"399","label":"Art. 399 DOC (charge de la preuve)","pts":3}],"faille":"La reconnaissance téléphonique est vraisemblable.","concede":"L'interruption n'est pas prouvée."},{"name":"Conclusions","adverse":"Le fournisseur demande, à défaut, la moitié de la facture.","prompt":"Concluez.","options":[{"label":"Irrecevabilité pour prescription","detail":"Action prescrite, rejet intégral.","pts":14,"speech":"Nous concluons à l'irrecevabilité de l'action, prescrite.","ok":["Conclusion nette"],"ko":[]},{"label":"Accepter la moitié","detail":"Transiger.","pts":7,"speech":"Mon client accepte.","ok":[],"ko":["Paie une dette prescrite"]}],"concepts":[{"label":"Prescription / irrecevabilité","re":"prescri|irrecevab","pts":4,"key":true}],"articles":[],"faille":"Le client n'a pas de conclusion claire.","concede":"Les conclusions sont nettes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'action du fournisseur pour des fournitures faites à un particulier pour ses usages domestiques se prescrit par deux ans et qu'aucun acte interruptif n'est prouvé ; Par ces motifs : déclare l'action prescrite."},{"min":45,"text":"Le Tribunal, attendu que la prescription semble acquise mais que le fournisseur offre de prouver une reconnaissance ; Par ces motifs : ordonne une enquête."},{"min":0,"text":"Le Tribunal, attendu que le client n'oppose pas utilement la prescription et ne prouve pas le paiement ; Par ces motifs : le condamne à payer 38 000 Dirhams."}]},{"id":"escroquerie","matiere":"penal","title":"Ministère public c/ Youssef A.","court":"Tribunal de première instance de Casablanca — chambre correctionnelle","object":"Poursuite pour escroquerie : vente en ligne d'un téléphone jamais livré.","you":"Avocat de la défense (Youssef A.)","adverseName":"Ministère public","facts":"Youssef A. a vendu sur internet un téléphone 6 500 DH. L'acheteur a payé par virement ; le téléphone n'est jamais arrivé. Youssef A. explique que son fournisseur ne l'a pas livré et il a remboursé l'acheteur deux mois plus tard, après le dépôt de la plainte. C'est sa seule vente en ligne.","rounds":[{"name":"L'élément matériel","adverse":"Monsieur le Président, le prévenu a encaissé 6 500 Dirhams pour un objet qu'il n'a jamais livré. L'escroquerie est constituée.","prompt":"Contestez la qualification.","options":[{"label":"Absence de manœuvres","detail":"L'escroquerie suppose d'induire astucieusement en erreur par des affirmations fallacieuses ; une simple inexécution ne suffit pas.","pts":17,"speech":"L'escroquerie exige que l'auteur ait induit astucieusement la victime en erreur, par des affirmations fallacieuses ou la dissimulation de faits vrais, en vue d'un profit illégitime. Une vente non livrée est d'abord une inexécution contractuelle. Le prévenu a utilisé son vrai nom et son vrai compte, n'a pas de faux profil, et a remboursé.","ok":["Rappelle les éléments constitutifs","Distingue inexécution et escroquerie","Relève l'identité réelle utilisée"],"ko":[]},{"label":"Plaider la clémence","detail":"Demander l'indulgence sans contester les faits.","pts":7,"speech":"Mon client regrette, il est jeune.","ok":[],"ko":["Ne conteste pas la qualification"]}],"concepts":[{"label":"Pas de manœuvres frauduleuses / affirmations fallacieuses","re":"manoeuvre|astuc|fallaci|tromp","pts":6,"key":true},{"label":"Simple inexécution contractuelle","re":"inexecution|civil|contractuel","pts":5},{"label":"Identité réelle / remboursement","re":"vrai nom|identite|rembours","pts":3}],"articles":[{"code":"CP","article":"540","label":"Art. 540 Code pénal (escroquerie)","pts":4}],"faille":"La défense ne conteste pas les faits : l'escroquerie est caractérisée.","concede":"Il n'y a pas de faux profil, c'est vrai. Mais l'intention reste à examiner."},{"name":"L'intention","adverse":"Le remboursement est intervenu après la plainte : il ne fait pas disparaître l'infraction.","prompt":"Plaidez sur l'élément intentionnel.","options":[{"label":"Bonne foi démontrée","detail":"Preuves de la commande au fournisseur ; l'intention s'apprécie au jour de la vente.","pts":15,"speech":"L'intention s'apprécie au moment de la vente. Nous produisons la commande passée au fournisseur et les messages relançant celui-ci : au jour de la vente, le prévenu croyait pouvoir livrer. Le remboursement confirme cette bonne foi.","ok":["Situe l'intention au jour de la vente","Produit des preuves"],"ko":[]},{"label":"Admettre l'intention","detail":"Concéder qu'il savait ne pas pouvoir livrer.","pts":3,"speech":"Il savait que ce serait difficile.","ok":[],"ko":["Aveu de l'élément moral"]}],"concepts":[{"label":"Intention appréciée au jour de la vente","re":"jour de la vente|moment|au moment","pts":5,"key":true},{"label":"Preuves de la commande au fournisseur","re":"commande|fournisseur|messages","pts":4}],"articles":[],"faille":"L'élément intentionnel est établi.","concede":"Le doute profite au prévenu."},{"name":"Réquisitions et peine","adverse":"Le ministère public requiert six mois d'emprisonnement avec sursis et une amende.","prompt":"Concluez.","options":[{"label":"Relaxe, subsidiairement peine minimale","detail":"Relaxe au bénéfice du doute ; subsidiairement, amende avec sursis.","pts":15,"speech":"Nous sollicitons la relaxe. À titre subsidiaire, compte tenu du remboursement intégral et d'un casier vierge, une simple amende avec sursis.","ok":["Conclusions hiérarchisées"],"ko":[]},{"label":"Accepter les réquisitions","detail":"Ne rien contester.","pts":6,"speech":"Nous nous en remettons.","ok":[],"ko":["Aucune défense de la peine"]}],"concepts":[{"label":"Relaxe","re":"relaxe|acquitt|doute","pts":4,"key":true},{"label":"Subsidiairement, peine réduite","re":"subsidiair|sursis|amende","pts":3}],"articles":[],"faille":"La défense ne discute pas la peine.","concede":"Les conclusions sont claires."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'existence d'affirmations fallacieuses et de l'intention frauduleuse au jour de la vente n'est pas établie, le litige relevant d'une inexécution contractuelle réparée ; Par ces motifs : relaxe le prévenu."},{"min":45,"text":"Le Tribunal, attendu que l'escroquerie est établie mais que le remboursement intégral justifie une peine modérée ; Par ces motifs : condamne le prévenu à une amende avec sursis."},{"min":0,"text":"Le Tribunal, attendu que le prévenu a encaissé le prix sans pouvoir livrer, sachant ne pas le pouvoir ; Par ces motifs : le condamne à six mois d'emprisonnement avec sursis."}]},{"id":"abus-confiance","matiere":"penal","title":"Société Atlas Électro c/ Hicham K.","court":"Tribunal de première instance de Rabat — chambre correctionnelle","object":"Abus de confiance : un commercial a gardé les encaissements clients.","you":"Avocat de la partie civile (Atlas Électro)","adverseName":"Avocat de Hicham K.","facts":"Hicham K., commercial, encaissait les paiements en espèces des clients et devait les reverser chaque semaine. Un audit montre que 142 000 DH encaissés sur huit mois n'ont jamais été reversés ; les reçus signés par Hicham K. sont au dossier. Il affirme que la société lui devait des commissions.","rounds":[{"name":"Les éléments de l'infraction","adverse":"Monsieur le Président, mon client n'a rien volé : la société lui devait des commissions, il s'est simplement payé.","prompt":"Caractérisez l'abus de confiance.","options":[{"label":"Détournement de fonds remis à titre précaire","detail":"Les fonds étaient remis à charge de les reverser ; les garder constitue un détournement.","pts":17,"speech":"Les fonds n'appartenaient pas au prévenu : il les recevait pour le compte de la société, à charge de les reverser chaque semaine. Les garder, c'est les détourner de mauvaise foi au préjudice de leur propriétaire. Les reçus qu'il a signés établissent chaque encaissement.","ok":["Identifie la remise précaire","Caractérise le détournement","S'appuie sur les reçus signés"],"ko":[]},{"label":"Parler de vol","detail":"Qualifier les faits de vol.","pts":7,"speech":"Le prévenu a volé l'argent de la société.","ok":[],"ko":["Mauvaise qualification : les fonds lui avaient été remis"]}],"concepts":[{"label":"Fonds remis à charge de les reverser","re":"remis|reverser|pour le compte|precaire","pts":5,"key":true},{"label":"Détournement de mauvaise foi","re":"detourn|mauvaise foi","pts":5},{"label":"Reçus signés / audit","re":"recu|audit","pts":3}],"articles":[{"code":"CP","article":"547","label":"Art. 547 Code pénal (abus de confiance)","pts":5}],"faille":"La partie civile qualifie mal les faits.","concede":"Les éléments matériels sont là. Reste la compensation."},{"name":"La compensation invoquée","adverse":"La société devait 40 000 Dirhams de commissions : il y a compensation.","prompt":"Répondez.","options":[{"label":"On ne se fait pas justice soi-même","detail":"Une créance contestée ne justifie pas de retenir les fonds d'autrui ; et elle couvrirait au mieux 40 000 DH.","pts":15,"speech":"Une créance de commissions, à la supposer fondée, se réclame devant le juge ; elle n'autorise pas à retenir les fonds confiés. De plus, 40 000 Dirhams ne justifient pas la rétention de 142 000 Dirhams. Les fiches de paie montrent d'ailleurs que les commissions ont été réglées.","ok":["Refuse la justice privée","Disproportion des montants","Produit les fiches de paie"],"ko":[]},{"label":"Ignorer l'argument","detail":"Ne pas répondre.","pts":5,"speech":"La partie civile maintient sa demande.","ok":[],"ko":["Laisse la compensation sans réponse"]}],"concepts":[{"label":"Pas de justice privée / créance à réclamer en justice","re":"justice|reclam|retenir","pts":5,"key":true},{"label":"Disproportion 40 000 / 142 000","re":"142|disproportion","pts":4},{"label":"Fiches de paie","re":"fiche|paie|commission","pts":3}],"articles":[],"faille":"La compensation est plausible.","concede":"La compensation ne tient pas."},{"name":"Demandes civiles","adverse":"La défense propose un remboursement échelonné sur dix ans.","prompt":"Formulez les demandes de la partie civile.","options":[{"label":"Restitution intégrale + dommages","detail":"142 000 DH de restitution et des dommages pour le préjudice d'audit.","pts":15,"speech":"La partie civile demande la restitution des 142 000 Dirhams et 15 000 Dirhams de dommages-intérêts pour les frais d'audit, ainsi que la condamnation pénale du prévenu.","ok":["Demandes complètes et chiffrées"],"ko":[]},{"label":"Accepter dix ans","detail":"Accepter l'échéancier.","pts":7,"speech":"Nous acceptons.","ok":[],"ko":["Aucune garantie de paiement"]}],"concepts":[{"label":"Restitution intégrale","re":"142|restitution","pts":4,"key":true},{"label":"Dommages pour les frais d'audit","re":"audit|dommages","pts":3}],"articles":[],"faille":"La partie civile ne chiffre pas ses demandes.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le prévenu a détourné de mauvaise foi des fonds remis à charge de les reverser, sans que la compensation invoquée soit justifiée ; Par ces motifs : le déclare coupable d'abus de confiance et le condamne à restituer 142 000 Dirhams et à verser 15 000 Dirhams de dommages-intérêts."},{"min":45,"text":"Le Tribunal, attendu que l'abus de confiance est établi ; Par ces motifs : condamne le prévenu à restituer 102 000 Dirhams, déduction faite des commissions alléguées."},{"min":0,"text":"Le Tribunal, attendu que la partie civile qualifie mal les faits et que la créance invoquée rend la situation équivoque ; Par ces motifs : renvoie la partie civile à mieux se pourvoir."}]},{"id":"garde-a-vue","matiere":"penal","title":"Ministère public c/ Karim B.","court":"Tribunal de première instance de Tanger — chambre correctionnelle","object":"Vol d'un scooter : nullité de la garde à vue et du procès-verbal.","you":"Avocat de la défense (Karim B.)","adverseName":"Ministère public","facts":"Karim B. a été arrêté pour le vol d'un scooter. Il a été gardé à vue 70 heures sans prolongation écrite du parquet. Le procès-verbal ne mentionne ni l'heure du début de la garde à vue ni les heures d'audition, et ne porte pas sa signature. Ses aveux ne figurent que dans ce procès-verbal ; aucun témoin ne l'a vu prendre le scooter.","rounds":[{"name":"La durée de la garde à vue","adverse":"Monsieur le Président, les aveux du prévenu sont clairs : il a reconnu le vol.","prompt":"Soulevez l'irrégularité de la garde à vue.","options":[{"label":"Dépassement de la durée légale","detail":"La garde à vue ne peut excéder 48 heures sans prolongation autorisée par le parquet.","pts":17,"speech":"Le Code de procédure pénale limite la garde à vue à quarante-huit heures à compter de l'arrestation, sauf prolongation autorisée par le ministère public. Karim B. a été retenu soixante-dix heures sans aucune autorisation écrite. La mesure est irrégulière et les déclarations recueillies pendant ce temps doivent être écartées.","ok":["Cite la durée légale de 48 heures","Relève l'absence de prolongation","Demande d'écarter les déclarations"],"ko":[]},{"label":"Contester les aveux sur le fond","detail":"Dire que les aveux sont faux.","pts":8,"speech":"Mon client n'a jamais avoué.","ok":[],"ko":["Ne soulève pas la nullité, pourtant décisive"]}],"concepts":[{"label":"Durée de 48 heures","re":"48|quarante-huit","pts":6,"key":true},{"label":"Absence de prolongation du parquet","re":"prolongation|parquet|ministere public|autoris","pts":5},{"label":"Nullité / écarter les déclarations","re":"nul|ecart|irregul","pts":3}],"articles":[{"code":"CPP","article":"66","label":"Art. 66 CPP (durée de la garde à vue)","pts":5}],"faille":"La défense ne soulève aucune nullité : les aveux sont réguliers.","concede":"La durée est dépassée. Reste le procès-verbal."},{"name":"Le procès-verbal","adverse":"Les irrégularités du procès-verbal sont de simples oublis matériels.","prompt":"Répondez sur le procès-verbal.","options":[{"label":"Mentions obligatoires manquantes","detail":"Le PV doit mentionner les heures de garde à vue et d'audition et être signé par l'intéressé.","pts":16,"speech":"La loi impose que le procès-verbal mentionne le jour et l'heure du début et de la fin de la garde à vue et des auditions, et qu'il soit signé par la personne entendue ou porte la mention de son refus. Aucune de ces garanties n'est respectée. Un acte qui ne prouve pas l'accomplissement régulier des formalités est réputé non accompli.","ok":["Énumère les mentions obligatoires","Tire la conséquence sur la valeur du PV"],"ko":[]},{"label":"Accepter le PV","detail":"Ne pas discuter.","pts":4,"speech":"Nous ne contestons pas le procès-verbal.","ok":[],"ko":["Renonce à une nullité sérieuse"]}],"concepts":[{"label":"Heures de garde à vue et d'audition","re":"heure|horaire","pts":5,"key":true},{"label":"Signature du prévenu","re":"signature|signe","pts":4},{"label":"Acte réputé non accompli / nullité","re":"nul|non accompli|ecart","pts":3}],"articles":[{"code":"CPP","article":"67","label":"Art. 67 CPP (mentions du procès-verbal)","pts":4},{"code":"CPP","article":"751","label":"Art. 751 CPP (acte irrégulier réputé non accompli)","pts":2}],"faille":"Les irrégularités sont mineures.","concede":"Le procès-verbal est fragile."},{"name":"Le fond et la peine","adverse":"Même sans aveux, le scooter a été retrouvé près du domicile du prévenu.","prompt":"Concluez.","options":[{"label":"Relaxe faute de preuve régulière","detail":"Sans aveux réguliers, la proximité ne prouve pas la soustraction.","pts":15,"speech":"Une fois les déclarations écartées, il reste un scooter retrouvé dans une rue fréquentée, près de plusieurs immeubles. Cela ne prouve pas la soustraction frauduleuse par Karim B. Nous sollicitons la relaxe.","ok":["Raisonne sans les preuves annulées","Relève l'insuffisance de l'indice"],"ko":[]},{"label":"Demander une peine légère","detail":"Admettre la culpabilité.","pts":6,"speech":"Nous demandons une peine avec sursis.","ok":[],"ko":["Abandonne les nullités"]}],"concepts":[{"label":"Relaxe / insuffisance de preuves","re":"relaxe|preuve|doute","pts":4,"key":true},{"label":"Soustraction non prouvée","re":"soustraction|proximite","pts":3}],"articles":[{"code":"CP","article":"505","label":"Art. 505 Code pénal (vol)","pts":2}],"faille":"La défense admet la culpabilité.","concede":"Le doute est réel."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la garde à vue a excédé la durée légale sans prolongation et que le procès-verbal ne comporte pas les mentions obligatoires ; que les déclarations doivent être écartées et que les autres éléments sont insuffisants ; Par ces motifs : relaxe le prévenu."},{"min":45,"text":"Le Tribunal, attendu que les déclarations recueillies irrégulièrement sont écartées, mais qu'il subsiste un doute ; Par ces motifs : relaxe le prévenu au bénéfice du doute."},{"min":0,"text":"Le Tribunal, attendu qu'aucune nullité n'est utilement soulevée et que les aveux sont circonstanciés ; Par ces motifs : condamne le prévenu à un an d'emprisonnement pour vol."}]},{"id":"violences","matiere":"penal","title":"Ministère public c/ Saïd M.","court":"Tribunal de première instance de Marrakech — chambre correctionnelle","object":"Violences volontaires lors d'une dispute de voisinage : qualification et certificat médical.","you":"Avocat de la défense (Saïd M.)","adverseName":"Ministère public","facts":"Au cours d'une dispute de stationnement, Saïd M. a poussé son voisin, qui est tombé. Le premier certificat médical mentionne une incapacité de 12 jours ; un second certificat, établi trois semaines plus tard par un autre médecin à la demande de la victime, mentionne 25 jours. Le parquet poursuit sur la base du second certificat.","rounds":[{"name":"La qualification","adverse":"Monsieur le Président, le certificat fait état de 25 jours d'incapacité : la peine aggravée s'applique.","prompt":"Contestez la qualification aggravée.","options":[{"label":"Seuil des 20 jours contesté","detail":"La qualification aggravée suppose une incapacité de plus de 20 jours ; le premier certificat, contemporain des faits, retient 12 jours.","pts":17,"speech":"La qualification aggravée suppose une incapacité supérieure à vingt jours. Le seul certificat contemporain des faits retient douze jours ; le second, établi trois semaines plus tard par un autre médecin, à la demande de la victime, ne précise pas pourquoi l'incapacité aurait doublé. Les faits relèvent au plus des violences simples.","ok":["Identifie le seuil des 20 jours","Compare les deux certificats","Demande la requalification"],"ko":[]},{"label":"Nier les faits","detail":"Dire qu'il n'y a jamais eu de contact.","pts":5,"speech":"Mon client n'a jamais touché la victime.","ok":[],"ko":["Contredit les témoins et le dossier"]}],"concepts":[{"label":"Seuil de vingt jours","re":"vingt jours|20 jours|plus de 20|superieure","pts":6,"key":true},{"label":"Compare les certificats / le premier est contemporain","re":"certificat|12 jours|douze|contemporain","pts":5},{"label":"Requalification en violences simples","re":"requalif|simple","pts":3}],"articles":[{"code":"CP","article":"401","label":"Art. 401 Code pénal (incapacité supérieure à 20 jours)","pts":3},{"code":"CP","article":"400","label":"Art. 400 Code pénal (violences volontaires)","pts":3}],"faille":"La défense ne conteste pas le certificat : la qualification aggravée est retenue.","concede":"Le second certificat est discutable. Le tribunal peut ordonner une expertise."},{"name":"Les circonstances","adverse":"Le prévenu a agi avec violence, sans provocation.","prompt":"Plaidez les circonstances.","options":[{"label":"Geste unique dans une altercation réciproque","detail":"Une poussée unique, sans arme, dans une dispute où la victime a aussi été agressive (témoin).","pts":14,"speech":"Il s'agit d'une poussée unique, sans arme ni préméditation, au cours d'une altercation où la victime elle-même avait saisi le prévenu par le col, comme l'atteste un voisin. Ces circonstances doivent être prises en compte dans la peine.","ok":["Geste unique, sans arme","Altercation réciproque attestée"],"ko":[]},{"label":"Accuser la victime","detail":"Dire que la victime a simulé.","pts":5,"speech":"La victime exagère tout.","ok":[],"ko":["Attitude contre-productive"]}],"concepts":[{"label":"Geste unique / sans arme ni préméditation","re":"unique|sans arme|premedit","pts":4,"key":true},{"label":"Comportement de la victime attesté","re":"victime.*(col|saisi|agress)|temoin|atteste","pts":4}],"articles":[],"faille":"Le prévenu ne manifeste aucun regret.","concede":"Les circonstances sont atténuantes."},{"name":"Peine et réparation","adverse":"La victime réclame 50 000 DH de dommages-intérêts.","prompt":"Concluez.","options":[{"label":"Requalification, amende, réparation mesurée","detail":"Violences simples, amende ou sursis, dommages limités au préjudice prouvé.","pts":15,"speech":"Nous demandons la requalification en violences simples, une peine d'amende ou d'emprisonnement avec sursis, et une réparation limitée au préjudice justifié, au besoin après expertise médicale.","ok":["Conclusions complètes"],"ko":[]},{"label":"Accepter tout","detail":"Ne pas discuter.","pts":6,"speech":"Nous nous en remettons.","ok":[],"ko":["Aucune défense"]}],"concepts":[{"label":"Requalification et peine modérée","re":"requalif|sursis|amende","pts":4,"key":true},{"label":"Expertise médicale","re":"expert","pts":3}],"articles":[],"faille":"La défense ne discute pas la peine.","concede":"Les conclusions sont mesurées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que seul le certificat contemporain des faits est probant et retient une incapacité de douze jours ; Par ces motifs : requalifie en violences simples et condamne le prévenu à une amende, ainsi qu'à 8 000 Dirhams de dommages-intérêts."},{"min":45,"text":"Le Tribunal, attendu que la durée de l'incapacité est incertaine ; Par ces motifs : ordonne une expertise médicale avant dire droit."},{"min":0,"text":"Le Tribunal, attendu que l'incapacité est supérieure à vingt jours ; Par ces motifs : condamne le prévenu à un an d'emprisonnement et à 30 000 Dirhams de dommages-intérêts."}]},{"id":"cheque-penal","matiere":"penal","title":"Ministère public c/ Nadia R.","court":"Tribunal de première instance d'Agadir — chambre correctionnelle","object":"Émission de chèque sans provision : 48 000 DH.","you":"Avocat de la défense (Nadia R.)","adverseName":"Ministère public","facts":"Nadia R., gérante d'un salon de coiffure, a remis un chèque de 48 000 DH à un fournisseur. Le chèque a été rejeté pour insuffisance de provision. Elle a régularisé en déposant la somme sur le compte et en payant le fournisseur douze jours après le rejet, avant toute citation. Le fournisseur s'est désisté de sa plainte.","rounds":[{"name":"L'infraction","adverse":"Monsieur le Président, le chèque a été émis sans provision suffisante : l'infraction est constituée au jour de l'émission.","prompt":"Présentez la défense.","options":[{"label":"Régularisation et absence d'intention","detail":"Provision constituée et créancier payé rapidement ; démontrer la bonne foi.","pts":16,"speech":"Nadia R. a régularisé la situation douze jours après le rejet, avant toute poursuite : la provision a été constituée et le fournisseur intégralement payé, puis s'est désisté. L'insuffisance résultait d'un virement client attendu et retardé, dont nous produisons la preuve. Ces éléments écartent la mauvaise foi.","ok":["Met en avant la régularisation rapide","Produit la preuve du virement attendu","Mentionne le désistement"],"ko":[]},{"label":"Nier l'émission","detail":"Dire que le chèque a été volé.","pts":4,"speech":"Ce chèque a été volé.","ok":[],"ko":["Version incompatible avec le paiement effectué"]}],"concepts":[{"label":"Régularisation / provision constituée","re":"regularis|provision|depos|paye","pts":6,"key":true},{"label":"Bonne foi / virement attendu","re":"bonne foi|virement|attendu|retard","pts":4},{"label":"Désistement du fournisseur","re":"desist","pts":3}],"articles":[{"code":"CCOM","article":"316","label":"Art. 316 Code de commerce (chèque sans provision)","pts":4}],"faille":"La défense n'apporte aucun élément de bonne foi.","concede":"La régularisation est établie. Elle pèsera sur la peine."},{"name":"La portée du désistement","adverse":"Le désistement de la victime n'éteint pas l'action publique.","prompt":"Répondez.","options":[{"label":"Admettre et plaider la peine","detail":"Reconnaître que l'action publique subsiste, mais demander une peine minimale.","pts":14,"speech":"Il est exact que le désistement n'éteint pas l'action publique. Mais il témoigne de la réparation intégrale du préjudice, que le tribunal doit prendre en compte pour individualiser la peine.","ok":["Position juridiquement exacte","Oriente vers la peine"],"ko":[]},{"label":"Soutenir l'extinction","detail":"Affirmer que le désistement met fin aux poursuites.","pts":6,"speech":"Le désistement met fin à l'affaire.","ok":[],"ko":["Erreur de droit"]}],"concepts":[{"label":"Le désistement n'éteint pas l'action publique","re":"action publique|n.eteint pas|subsist","pts":5,"key":true},{"label":"Réparation intégrale","re":"repar|integral","pts":3}],"articles":[],"faille":"La défense se trompe sur le droit.","concede":"La position est exacte."},{"name":"La peine","adverse":"Le ministère public requiert un an d'emprisonnement avec sursis et l'amende légale.","prompt":"Concluez.","options":[{"label":"Peine minimale, sursis","detail":"Amende au minimum, sursis, compte tenu de la régularisation.","pts":14,"speech":"Compte tenu de la régularisation avant poursuites, d'un casier vierge et du désistement, nous sollicitons l'application la plus clémente : amende au minimum légal et, le cas échéant, sursis.","ok":["Individualisation argumentée"],"ko":[]},{"label":"Se taire","detail":"Ne rien demander.","pts":6,"speech":"Nous nous en remettons.","ok":[],"ko":["Aucune défense de la peine"]}],"concepts":[{"label":"Peine minimale / sursis","re":"minimum|sursis|clemen","pts":4,"key":true}],"articles":[],"faille":"La défense ne discute pas la peine.","concede":"La demande est argumentée."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'infraction est constituée mais que la prévenue a régularisé avant toute poursuite et désintéressé intégralement le créancier ; Par ces motifs : la condamne à l'amende minimale avec sursis."},{"min":45,"text":"Le Tribunal, attendu que l'infraction est établie et que la régularisation justifie une peine modérée ; Par ces motifs : la condamne à six mois d'emprisonnement avec sursis et à l'amende légale."},{"min":0,"text":"Le Tribunal, attendu que la prévenue ne justifie d'aucune circonstance favorable ; Par ces motifs : la condamne à un an d'emprisonnement et à l'amende légale."}]},{"id":"faux-commerce","matiere":"penal","title":"Banque du Nord c/ Mehdi T.","court":"Tribunal de première instance de Casablanca — chambre correctionnelle","object":"Faux en écriture de commerce : bilans falsifiés pour obtenir un crédit.","you":"Avocat de la partie civile (Banque du Nord)","adverseName":"Avocat de Mehdi T.","facts":"Pour obtenir un crédit de 1,5 million de DH, Mehdi T., gérant d'une société de négoce, a remis à la banque des bilans montrant un bénéfice de 900 000 DH. Les bilans déposés au greffe et à l'administration fiscale font apparaître une perte de 300 000 DH. Le crédit n'est plus remboursé.","rounds":[{"name":"Le faux","adverse":"Monsieur le Président, mon client n'a fait qu'une présentation optimiste. La banque devait vérifier.","prompt":"Caractérisez le faux.","options":[{"label":"Altération frauduleuse de la vérité dans un écrit de commerce","detail":"Le faux est l'altération frauduleuse de la vérité dans un écrit, de nature à causer un préjudice ; les bilans sont des écritures de commerce.","pts":17,"speech":"Le faux en écritures est l'altération frauduleuse de la vérité, de nature à causer un préjudice, accomplie dans un écrit. Présenter un bénéfice de 900 000 Dirhams quand les comptes officiels montrent une perte de 300 000 Dirhams n'est pas de l'optimisme : c'est une altération. Les bilans d'une société sont des écritures de commerce, ce qui fonde une qualification spécifique.","ok":["Définit le faux","Compare les bilans","Qualifie d'écriture de commerce"],"ko":[]},{"label":"Parler d'escroquerie seulement","detail":"Qualifier uniquement d'escroquerie.","pts":9,"speech":"Le prévenu a escroqué la banque.","ok":["Qualification envisageable"],"ko":["Omet le faux, plus précis"]}],"concepts":[{"label":"Altération frauduleuse de la vérité","re":"alter|fausse|falsif","pts":6,"key":true},{"label":"Comparaison avec les bilans officiels","re":"greffe|fiscal|officiel|perte","pts":4},{"label":"Écriture de commerce","re":"ecriture de commerce|commerce","pts":3}],"articles":[{"code":"CP","article":"351","label":"Art. 351 Code pénal (définition du faux)","pts":3},{"code":"CP","article":"357","label":"Art. 357 Code pénal (faux en écriture de commerce)","pts":3}],"faille":"La partie civile ne démontre pas l'altération.","concede":"L'écart des bilans est troublant. Mais la banque a-t-elle été négligente ?"},{"name":"La négligence de la banque","adverse":"La banque aurait dû consulter les comptes déposés au greffe : sa négligence exclut son préjudice.","prompt":"Répondez.","options":[{"label":"La négligence n'efface pas l'infraction","detail":"Le faux est punissable dès qu'il est de nature à causer un préjudice ; la victime n'a pas à soupçonner les documents remis.","pts":15,"speech":"Le faux est constitué dès lors que l'écrit est de nature à causer un préjudice, et il en a causé un : 1,5 million de Dirhams de crédit. Une banque peut se fier à des bilans signés par le gérant ; l'éventuel défaut de vérification ne fait pas disparaître la fraude.","ok":["Préjudice potentiel et réel","Écarte la négligence comme excuse"],"ko":[]},{"label":"Admettre la négligence","detail":"Concéder la faute de la banque.","pts":5,"speech":"La banque aurait pu mieux vérifier.","ok":[],"ko":["Fragilise la demande civile"]}],"concepts":[{"label":"De nature à causer un préjudice","re":"nature a causer|prejudice","pts":5,"key":true},{"label":"La négligence n'excuse pas la fraude","re":"neglig|fier|confiance","pts":4}],"articles":[],"faille":"La négligence de la banque est établie.","concede":"La fraude subsiste malgré la négligence alléguée."},{"name":"Demandes civiles","adverse":"Le prévenu propose de rembourser sur quinze ans.","prompt":"Formulez les demandes.","options":[{"label":"Condamnation et réparation","detail":"Condamnation pénale, remboursement du capital restant dû et dommages.","pts":15,"speech":"La partie civile demande la condamnation du prévenu, le paiement du capital restant dû et des dommages-intérêts pour le préjudice né de la fraude.","ok":["Demandes complètes"],"ko":[]},{"label":"Accepter quinze ans","detail":"Accepter l'échéancier.","pts":7,"speech":"La banque accepte.","ok":[],"ko":["Aucune garantie"]}],"concepts":[{"label":"Condamnation et capital restant dû","re":"capital|rembours|condamn","pts":4,"key":true}],"articles":[],"faille":"La partie civile ne chiffre pas ses demandes.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le prévenu a remis des bilans altérés frauduleusement, écritures de commerce de nature à causer un préjudice ; Par ces motifs : le déclare coupable de faux en écriture de commerce, le condamne à deux ans d'emprisonnement et au paiement du capital restant dû."},{"min":45,"text":"Le Tribunal, attendu que le faux est établi mais que la banque a contribué au dommage ; Par ces motifs : condamne le prévenu et réduit les dommages-intérêts."},{"min":0,"text":"Le Tribunal, attendu que l'altération n'est pas démontrée avec certitude ; Par ces motifs : relaxe le prévenu."}]},{"id":"faute-grave","matiere":"travail","title":"Mme Bennis c/ Société Textiles du Nord","court":"Tribunal de première instance de Tanger — chambre sociale","object":"Licenciement pour faute grave sans audition préalable.","you":"Avocat de la salariée (Mme Bennis)","adverseName":"Avocat de l'employeur","facts":"Mme Bennis, chef d'équipe depuis huit ans, a été licenciée pour « faute grave » après une altercation verbale avec un superviseur. Elle n'a jamais été convoquée à un entretien ; la lettre de licenciement lui a été remise neuf jours après les faits.","rounds":[{"name":"La procédure","adverse":"Monsieur le Président, la salariée a insulté son supérieur : c'est une faute grave, le licenciement est justifié.","prompt":"Contestez la procédure.","options":[{"label":"Défaut d'audition et délai","detail":"Avant le licenciement, le salarié doit être entendu en présence d'un délégué ; la décision est notifiée dans les 48 heures.","pts":18,"speech":"Avant tout licenciement, le salarié doit pouvoir se défendre et être entendu par l'employeur, en présence d'un délégué des salariés ou d'un représentant syndical de son choix. Mme Bennis n'a jamais été entendue. De plus, la décision doit être remise dans les 48 heures suivant la décision : elle l'a été neuf jours après les faits, sans entretien.","ok":["Identifie l'obligation d'audition","Mentionne la présence du délégué","Relève le délai de notification"],"ko":[]},{"label":"Contester l'insulte","detail":"Dire qu'elle n'a pas insulté.","pts":9,"speech":"Mme Bennis n'a jamais insulté personne.","ok":["Défense sur le fond"],"ko":["Oublie la procédure, décisive"]}],"concepts":[{"label":"Audition préalable obligatoire","re":"audition|entendu|se defendre|entretien","pts":6,"key":true},{"label":"Présence du délégué / représentant","re":"delegue|syndical|representant","pts":4},{"label":"Délai de notification de 48 heures","re":"48|quarante-huit","pts":4}],"articles":[{"code":"CT","article":"62","label":"Art. 62 Code du travail (audition préalable)","pts":4},{"code":"CT","article":"63","label":"Art. 63 Code du travail (notification de la décision)","pts":2}],"faille":"La salariée ne critique pas la procédure.","concede":"La procédure n'a pas été respectée. Reste la gravité des faits."},{"name":"La gravité de la faute","adverse":"L'insulte envers un supérieur figure parmi les fautes graves légales.","prompt":"Discutez la qualification.","options":[{"label":"Faute grave contestée","detail":"Les fautes graves sont limitativement décrites ; une altercation verbale isolée, provoquée, n'en relève pas forcément.","pts":15,"speech":"Le Code du travail énumère les fautes graves. Une altercation verbale isolée, en huit ans d'ancienneté sans aucune sanction, et provoquée selon deux témoins par les propos du superviseur, n'a pas la gravité requise. Au plus, une sanction disciplinaire graduée était envisageable.","ok":["Renvoie à la liste légale","Ancienneté sans sanction","Témoignages de provocation"],"ko":[]},{"label":"Admettre la faute","detail":"Reconnaître la faute grave.","pts":4,"speech":"Il est vrai que c'était grave.","ok":[],"ko":["Abandonne la contestation au fond"]}],"concepts":[{"label":"Liste légale des fautes graves","re":"faute grave|liste|enumer","pts":5,"key":true},{"label":"Ancienneté sans sanction / sanction graduée","re":"anciennete|sans sanction|gradu|avertissement","pts":4},{"label":"Provocation attestée","re":"provoc|temoin","pts":3}],"articles":[{"code":"CT","article":"39","label":"Art. 39 Code du travail (fautes graves)","pts":4}],"faille":"La faute grave est reconnue.","concede":"La gravité est discutable."},{"name":"Les indemnités","adverse":"L'employeur propose deux mois de salaire pour solde de tout compte.","prompt":"Chiffrez les demandes.","options":[{"label":"Licenciement abusif : indemnités complètes","detail":"Dommages pour licenciement abusif, indemnité de licenciement, préavis.","pts":15,"speech":"Le licenciement étant abusif, nous demandons des dommages-intérêts, l'indemnité légale de licenciement calculée sur huit ans d'ancienneté et l'indemnité compensatrice de préavis.","ok":["Demandes complètes"],"ko":[]},{"label":"Accepter deux mois","detail":"Transiger.","pts":7,"speech":"Mme Bennis accepte.","ok":[],"ko":["Bien en deçà de ses droits"]}],"concepts":[{"label":"Dommages pour licenciement abusif","re":"abusif|dommages","pts":4,"key":true},{"label":"Indemnité de licenciement et préavis","re":"indemnite|preavis","pts":3}],"articles":[{"code":"CT","article":"41","label":"Art. 41 Code du travail (rupture abusive)","pts":3}],"faille":"La salariée ne chiffre pas ses demandes.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la salariée n'a pas été entendue avant son licenciement et que l'altercation isolée ne constitue pas une faute grave ; Par ces motifs : déclare le licenciement abusif et condamne l'employeur aux dommages-intérêts, à l'indemnité de licenciement et au préavis."},{"min":45,"text":"Le Tribunal, attendu que la procédure d'audition n'a pas été respectée ; Par ces motifs : déclare le licenciement abusif et alloue les indemnités légales."},{"min":0,"text":"Le Tribunal, attendu que la faute grave est établie et que la procédure n'est pas utilement critiquée ; Par ces motifs : rejette la demande."}]},{"id":"licenciement-abusif","matiere":"travail","title":"M. El Amrani c/ Agence Voyages Plus","court":"Tribunal de première instance de Rabat — chambre sociale","object":"Licenciement verbal d'un salarié de 12 ans d'ancienneté : calcul des indemnités.","you":"Avocat du salarié (M. El Amrani)","adverseName":"Avocat de l'employeur","facts":"M. El Amrani, agent de réservation depuis 12 ans, a été renvoyé oralement par le directeur après une baisse d'activité, sans lettre ni procédure. L'employeur soutient qu'il a démissionné.","rounds":[{"name":"La rupture","adverse":"Monsieur le Président, le salarié a quitté son poste de lui-même : c'est une démission.","prompt":"Établissez le licenciement.","options":[{"label":"Licenciement verbal prouvé","detail":"Attestations de collègues, SMS du directeur ; une démission ne se présume pas.","pts":16,"speech":"Une démission suppose une volonté claire et non équivoque du salarié, qui n'existe pas ici. Deux collègues attestent avoir entendu le directeur lui dire de « ne plus revenir », et un SMS du directeur le confirme. Il s'agit d'un licenciement sans procédure, donc abusif, ouvrant droit à dommages-intérêts.","ok":["La démission ne se présume pas","Preuves du renvoi","Qualifie de licenciement abusif"],"ko":[]},{"label":"Plaider l'injustice","detail":"Dire que le salarié a été maltraité.","pts":7,"speech":"Mon client a été traité injustement.","ok":[],"ko":["Aucune preuve ni qualification"]}],"concepts":[{"label":"Pas de démission (volonté claire)","re":"demission|volonte|equivoque","pts":4,"key":true},{"label":"Preuves du renvoi (attestations, SMS)","re":"attest|sms|message|temoin","pts":5},{"label":"Licenciement abusif","re":"abusif","pts":4}],"articles":[{"code":"CT","article":"41","label":"Art. 41 Code du travail (rupture abusive)","pts":4}],"faille":"Le salarié ne prouve pas son licenciement.","concede":"Le renvoi est établi. Reste le calcul."},{"name":"L'indemnité de licenciement","adverse":"À supposer un licenciement, l'indemnité ne serait que d'un mois de salaire.","prompt":"Calculez l'indemnité légale.","options":[{"label":"Barème légal par tranches d'ancienneté","detail":"96 heures par an pour les 5 premières années, 144 heures de la 6e à la 10e, puis davantage au-delà.","pts":16,"speech":"L'indemnité de licenciement est due après six mois d'ancienneté. Elle se calcule par tranches : 96 heures de salaire pour chacune des cinq premières années, 144 heures pour la sixième à la dixième, puis le taux supérieur prévu par la loi pour les années suivantes. Sur douze ans, elle dépasse très largement un mois de salaire.","ok":["Applique le barème par tranches","Droit dès six mois d'ancienneté"],"ko":[]},{"label":"Demander un an de salaire","detail":"Réclamer un montant forfaitaire.","pts":7,"speech":"Nous demandons un an de salaire.","ok":[],"ko":["Aucun calcul légal"]}],"concepts":[{"label":"Barème par tranches (96 h / 144 h)","re":"96|144|tranche|heures","pts":6,"key":true},{"label":"Droit dès six mois","re":"six mois|6 mois","pts":3}],"articles":[{"code":"CT","article":"53","label":"Art. 53 Code du travail (barème de l'indemnité)","pts":4},{"code":"CT","article":"52","label":"Art. 52 Code du travail (droit à indemnité)","pts":2}],"faille":"Le calcul n'est pas fait.","concede":"Le barème est correctement appliqué."},{"name":"Les autres sommes","adverse":"L'employeur reconnaît devoir le dernier salaire.","prompt":"Concluez.","options":[{"label":"Demandes complètes","detail":"Dommages pour licenciement abusif, indemnité légale, préavis, salaire dû.","pts":15,"speech":"Nous demandons les dommages-intérêts pour licenciement abusif, l'indemnité légale de licenciement, l'indemnité compensatrice de préavis et le dernier salaire.","ok":["Complet"],"ko":[]},{"label":"Se limiter au salaire","detail":"Demander seulement le dernier salaire.","pts":6,"speech":"Nous demandons le dernier salaire.","ok":[],"ko":["Oublie l'essentiel"]}],"concepts":[{"label":"Dommages + indemnité + préavis","re":"dommages|indemnite|preavis","pts":4,"key":true}],"articles":[],"faille":"Le salarié oublie ses principales demandes.","concede":"Les demandes sont complètes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le salarié a été renvoyé verbalement sans procédure et qu'aucune démission n'est établie ; Par ces motifs : déclare le licenciement abusif et condamne l'employeur aux dommages-intérêts, à l'indemnité légale calculée selon le barème, au préavis et au salaire dû."},{"min":45,"text":"Le Tribunal, attendu que le licenciement est établi ; Par ces motifs : alloue l'indemnité légale et le préavis, et des dommages-intérêts modérés."},{"min":0,"text":"Le Tribunal, attendu que le salarié ne prouve pas la rupture à l'initiative de l'employeur ; Par ces motifs : rejette la demande, sauf le dernier salaire."}]},{"id":"heures-sup","matiere":"travail","title":"M. Fikri c/ Société Sécurité Atlas","court":"Tribunal de première instance de Casablanca — chambre sociale","object":"Rappel d'heures supplémentaires d'un agent de sécurité.","you":"Avocat du salarié (M. Fikri)","adverseName":"Avocat de l'employeur","facts":"M. Fikri, agent de sécurité, a travaillé pendant deux ans des postes de 12 heures, six jours sur sept, selon les plannings affichés. Ses bulletins de paie ne mentionnent aucune heure supplémentaire. L'employeur affirme que la rémunération est forfaitaire.","rounds":[{"name":"L'existence des heures","adverse":"Monsieur le Président, le salaire est un forfait qui couvre toutes les heures.","prompt":"Prouvez les heures supplémentaires.","options":[{"label":"Plannings et durée légale","detail":"Les plannings montrent des semaines bien au-delà de la durée normale ; les heures au-delà sont des heures supplémentaires.","pts":16,"speech":"Les plannings affichés par l'employeur lui-même montrent soixante-douze heures par semaine, bien au-delà de la durée normale de travail. Les heures supplémentaires se calculent au-delà de cette durée hebdomadaire. Aucun forfait écrit ne prévoit leur inclusion dans le salaire.","ok":["Preuve par les plannings de l'employeur","Calcul au-delà de la durée normale","Écarte le forfait non écrit"],"ko":[]},{"label":"Affirmer la fatigue","detail":"Dire que le travail était épuisant.","pts":6,"speech":"Mon client était épuisé.","ok":[],"ko":["Aucune preuve des heures"]}],"concepts":[{"label":"Plannings / preuve des horaires","re":"planning|horaire|72|douze heures|12 heures","pts":6,"key":true},{"label":"Au-delà de la durée normale","re":"duree normale|hebdomadaire|au-dela","pts":4},{"label":"Pas de forfait écrit","re":"forfait","pts":3}],"articles":[{"code":"CT","article":"196","label":"Art. 196 Code du travail (heures supplémentaires)","pts":3},{"code":"CT","article":"197","label":"Art. 197 Code du travail (calcul hebdomadaire)","pts":3}],"faille":"Le salarié ne prouve pas ses horaires.","concede":"Les plannings sont probants. Reste le calcul."},{"name":"Le calcul et la majoration","adverse":"À supposer des heures supplémentaires, elles ont été compensées par des jours de repos.","prompt":"Répondez.","options":[{"label":"Exiger la preuve des repos","detail":"L'employeur doit prouver les repos compensateurs ; les plannings ne les montrent pas.","pts":15,"speech":"Les plannings montrent six jours travaillés sur sept pendant deux ans, sans repos supplémentaire. Si l'employeur prétend avoir compensé, qu'il le prouve. Nous produisons un décompte semaine par semaine, avec la majoration légale.","ok":["Renverse l'argument des repos","Décompte détaillé avec majoration"],"ko":[]},{"label":"Demander un forfait","detail":"Réclamer 100 000 DH sans calcul.","pts":6,"speech":"Nous demandons 100 000 Dirhams.","ok":[],"ko":["Aucun calcul"]}],"concepts":[{"label":"Décompte semaine par semaine","re":"decompte|semaine|calcul","pts":5,"key":true},{"label":"Majoration","re":"majoration|majore","pts":4}],"articles":[],"faille":"Le salarié ne chiffre pas sa demande.","concede":"Le décompte est clair."},{"name":"Conclusions","adverse":"L'employeur propose un mois de salaire.","prompt":"Concluez.","options":[{"label":"Rappel intégral","detail":"Rappel des heures supplémentaires majorées et dommages pour défaut de paiement.","pts":14,"speech":"Nous demandons le rappel intégral des heures supplémentaires majorées selon le décompte, et la régularisation des bulletins de paie.","ok":["Demandes précises"],"ko":[]},{"label":"Accepter un mois","detail":"Transiger.","pts":7,"speech":"Nous acceptons.","ok":[],"ko":["Très inférieur au dû"]}],"concepts":[{"label":"Rappel intégral","re":"rappel|integral|decompte","pts":4,"key":true}],"articles":[],"faille":"Le salarié ne précise pas sa demande.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que les plannings établis par l'employeur démontrent des heures au-delà de la durée normale sans compensation prouvée ; Par ces motifs : condamne l'employeur au rappel des heures supplémentaires majorées selon le décompte produit."},{"min":45,"text":"Le Tribunal, attendu que des heures supplémentaires sont établies mais que le décompte doit être vérifié ; Par ces motifs : ordonne une expertise."},{"min":0,"text":"Le Tribunal, attendu que le salarié ne prouve pas ses horaires ; Par ces motifs : rejette la demande."}]},{"id":"periode-essai","matiere":"travail","title":"Mme Lamrani c/ Clinique Al Amal","court":"Tribunal de première instance de Fès — chambre sociale","object":"Rupture de la période d'essai d'une employée administrative.","you":"Avocat de l'employeur (Clinique Al Amal)","adverseName":"Avocat de Mme Lamrani","facts":"Mme Lamrani, employée administrative en CDI, payée au mois, a vu sa période d'essai rompue au bout de cinq semaines, par écrit, avec deux jours de préavis. Elle réclame six mois de salaire pour licenciement abusif.","rounds":[{"name":"La nature de la rupture","adverse":"Monsieur le Président, Mme Lamrani a été licenciée sans motif ni procédure : c'est un licenciement abusif.","prompt":"Présentez la défense de l'employeur.","options":[{"label":"Rupture de la période d'essai","detail":"Pendant l'essai, chaque partie peut rompre sans indemnité ; pour une employée, l'essai dure un mois et demi.","pts":17,"speech":"Il ne s'agit pas d'un licenciement : pendant la période d'essai, chacune des parties peut rompre le contrat sans indemnité. Pour les employés en CDI, la période d'essai est d'un mois et demi ; la rupture est intervenue au bout de cinq semaines, donc pendant l'essai.","ok":["Qualifie de rupture d'essai","Vérifie la durée légale de l'essai pour une employée"],"ko":[]},{"label":"Invoquer une faute","detail":"Accuser la salariée d'incompétence grave.","pts":7,"speech":"Mme Lamrani était incompétente.","ok":[],"ko":["Inutile et risqué : l'essai n'exige pas de motif"]}],"concepts":[{"label":"Rupture pendant la période d'essai","re":"periode d.essai|essai","pts":6,"key":true},{"label":"Un mois et demi pour une employée","re":"mois et demi|6 semaines|employe","pts":5},{"label":"Sans indemnité","re":"sans indemnite|sans preavis","pts":3}],"articles":[{"code":"CT","article":"13","label":"Art. 13 Code du travail (période d'essai)","pts":3},{"code":"CT","article":"14","label":"Art. 14 Code du travail (durée de l'essai)","pts":3}],"faille":"L'employeur ne démontre pas que la rupture est intervenue pendant l'essai.","concede":"La rupture est bien intervenue pendant l'essai. Mais le préavis ?"},{"name":"Le préavis minimal","adverse":"Après au moins une semaine de travail, la rupture de l'essai non motivée par une faute grave exige un délai de préavis.","prompt":"Répondez.","options":[{"label":"Reconnaître le préavis insuffisant, limiter la conséquence","detail":"Payée au mois, la salariée avait droit à huit jours : seuls les six jours manquants sont dus, pas un licenciement abusif.","pts":16,"speech":"Nous reconnaissons loyalement que, la salariée étant payée au mois, le préavis de rupture de l'essai devait être de huit jours, et non de deux. Mais cette irrégularité ne transforme pas la rupture de l'essai en licenciement abusif : elle ouvre droit seulement à la rémunération des six jours de préavis manquants.","ok":["Applique le bon délai (huit jours, paiement au mois)","Limite la sanction au préavis manquant"],"ko":[]},{"label":"Soutenir que deux jours suffisent","detail":"Affirmer que le préavis de deux jours est le délai légal.","pts":6,"speech":"Deux jours de préavis suffisent toujours.","ok":[],"ko":["Inexact : deux jours ne valent que pour les salariés payés à la journée, à la semaine ou à la quinzaine"]}],"concepts":[{"label":"Huit jours pour un salarié payé au mois","re":"huit jours|8 jours|paye au mois|au mois","pts":6,"key":true},{"label":"Seuls les jours manquants sont dus","re":"manquant|six jours|6 jours|remuneration du preavis","pts":4}],"articles":[{"code":"CT","article":"13","label":"Art. 13 Code du travail (préavis de rupture de l'essai)","pts":3}],"faille":"L'employeur prétend que deux jours suffisaient : c'est faux pour une salariée payée au mois.","concede":"Le préavis était insuffisant, l'employeur le reconnaît : la conséquence reste limitée."},{"name":"Conclusions","adverse":"La salariée réclame six mois de salaire.","prompt":"Concluez.","options":[{"label":"Rejet de l'abus, paiement du préavis manquant","detail":"Pas de licenciement abusif ; seuls six jours de préavis sont dus.","pts":15,"speech":"Nous concluons au rejet de la demande de dommages pour licenciement abusif, la rupture étant intervenue pendant l'essai, et offrons la rémunération des six jours de préavis manquants.","ok":["Conclusion exacte et loyale"],"ko":[]},{"label":"Proposer trois mois","detail":"Transiger.","pts":7,"speech":"La clinique propose trois mois.","ok":[],"ko":["Paie bien au-delà de l'obligation"]}],"concepts":[{"label":"Rejet de l'abus","re":"rejet|pas abusi","pts":4,"key":true},{"label":"Offre du préavis manquant","re":"six jours|6 jours|preavis manquant|manquant","pts":3}],"articles":[],"faille":"L'employeur n'a pas de conclusion claire.","concede":"Les conclusions sont nettes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la rupture est intervenue pendant la période d'essai d'un mois et demi applicable aux employés, mais que la salariée, payée au mois, avait droit à un préavis de huit jours ; Par ces motifs : rejette la demande pour licenciement abusif et condamne l'employeur à la rémunération de six jours de préavis."},{"min":45,"text":"Le Tribunal, attendu que la rupture est intervenue pendant l'essai avec un préavis insuffisant ; Par ces motifs : alloue une indemnité de préavis et des dommages modérés."},{"min":0,"text":"Le Tribunal, attendu que l'employeur n'a pas respecté le préavis légal et ne démontre pas une rupture régulière de l'essai ; Par ces motifs : déclare la rupture abusive."}]},{"id":"preavis","matiere":"travail","title":"Société Infotech c/ M. Zouhair","court":"Tribunal de première instance de Rabat — chambre sociale","object":"Démission sans préavis d'un ingénieur parti chez un concurrent.","you":"Avocat de l'employeur (Infotech)","adverseName":"Avocat de M. Zouhair","facts":"M. Zouhair, ingénieur en CDI depuis quatre ans, a démissionné par e-mail un vendredi et n'est plus revenu dès le lundi, rejoignant un concurrent. Infotech a dû recruter un prestataire en urgence pour finir un projet.","rounds":[{"name":"L'obligation de préavis","adverse":"Monsieur le Président, un salarié est libre de démissionner. Mon client n'a commis aucune faute.","prompt":"Fondez la demande de l'employeur.","options":[{"label":"Préavis obligatoire pour les deux parties","detail":"La rupture unilatérale d'un CDI, hors faute grave de l'autre partie, est subordonnée au respect du préavis ; à défaut, indemnité compensatrice.","pts":17,"speech":"La liberté de démissionner n'est pas en cause. Mais la rupture unilatérale d'un contrat à durée indéterminée est subordonnée, en l'absence de faute grave de l'autre partie, au respect du délai de préavis. Toute rupture sans préavis oblige la partie responsable à verser une indemnité égale à la rémunération de la période de préavis non observée.","ok":["Le préavis s'impose aussi au salarié","Identifie l'indemnité compensatrice"],"ko":[]},{"label":"Accuser de trahison","detail":"Reprocher le départ chez un concurrent.","pts":7,"speech":"Il est parti chez un concurrent, c'est une trahison.","ok":[],"ko":["Aucune règle invoquée"]}],"concepts":[{"label":"Préavis obligatoire en CDI","re":"preavis","pts":6,"key":true},{"label":"Indemnité compensatrice de préavis","re":"indemnite compensatrice|remuneration|periode de preavis","pts":5},{"label":"Absence de faute grave de l'employeur","re":"faute grave","pts":3}],"articles":[{"code":"CT","article":"43","label":"Art. 43 Code du travail (préavis)","pts":3},{"code":"CT","article":"51","label":"Art. 51 Code du travail (indemnité pour défaut de préavis)","pts":3}],"faille":"L'employeur ne fonde pas sa demande.","concede":"Le préavis était dû. Reste le préjudice supplémentaire."},{"name":"Le préjudice supplémentaire","adverse":"L'employeur ne peut réclamer plus que l'indemnité de préavis.","prompt":"Défendez les dommages complémentaires.","options":[{"label":"Rupture abusive par le salarié","detail":"La partie lésée par une rupture abusive peut demander des dommages-intérêts ; coût du prestataire justifié.","pts":14,"speech":"La loi permet à la partie lésée par une rupture abusive, quelle qu'elle soit, de demander des dommages-intérêts. Le départ du jour au lendemain, en plein projet, a obligé Infotech à payer un prestataire 60 000 Dirhams, factures à l'appui.","ok":["La rupture abusive peut venir du salarié","Préjudice justifié par factures"],"ko":[]},{"label":"Réclamer la perte du client","detail":"Demander 500 000 DH pour perte de marché.","pts":6,"speech":"Nous réclamons 500 000 Dirhams.","ok":[],"ko":["Préjudice non prouvé"]}],"concepts":[{"label":"La partie lésée peut demander des dommages","re":"partie lesee|dommages|abusi","pts":5,"key":true},{"label":"Coût du prestataire justifié","re":"prestataire|facture|60","pts":4}],"articles":[{"code":"CT","article":"41","label":"Art. 41 Code du travail (rupture abusive)","pts":3}],"faille":"Le préjudice supplémentaire n'est pas prouvé.","concede":"Le surcoût est justifié."},{"name":"Conclusions","adverse":"Le salarié propose d'effectuer une semaine de transition à distance.","prompt":"Concluez.","options":[{"label":"Indemnité de préavis + dommages justifiés","detail":"Indemnité compensatrice et coût du prestataire.","pts":14,"speech":"Nous demandons l'indemnité compensatrice de préavis et 60 000 Dirhams de dommages-intérêts justifiés par les factures du prestataire.","ok":["Demandes chiffrées"],"ko":[]},{"label":"Accepter la semaine","detail":"Transiger.","pts":7,"speech":"Nous acceptons.","ok":[],"ko":["Ne couvre pas le préjudice"]}],"concepts":[{"label":"Indemnité et dommages chiffrés","re":"indemnite|dommages|60","pts":4,"key":true}],"articles":[],"faille":"L'employeur ne chiffre pas sa demande.","concede":"Les demandes sont fondées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le salarié a rompu son contrat à durée indéterminée sans observer le préavis et que le surcoût subi par l'employeur est justifié ; Par ces motifs : le condamne à l'indemnité compensatrice de préavis et à 60 000 Dirhams de dommages-intérêts."},{"min":45,"text":"Le Tribunal, attendu que le préavis n'a pas été respecté ; Par ces motifs : condamne le salarié à l'indemnité compensatrice de préavis et rejette le surplus."},{"min":0,"text":"Le Tribunal, attendu que l'employeur ne fonde pas sa demande ; Par ces motifs : la rejette."}]},{"id":"chiqaq","matiere":"famille","title":"Mme Idrissi c/ M. Idrissi","court":"Tribunal de première instance de Meknès — section de la famille","object":"Divorce pour discorde (chiqaq) et droits de l'épouse.","you":"Avocat de l'épouse (Mme Idrissi)","adverseName":"Avocat de l'époux","facts":"Mariés depuis quatorze ans, trois enfants. Mme Idrissi demande le divorce pour discorde : le mari a quitté le domicile depuis un an et ne contribue plus aux charges. Le mari refuse le divorce et conteste toute somme.","rounds":[{"name":"La procédure de conciliation","adverse":"Monsieur le Président, mon client veut sauver son mariage ; le divorce ne peut être prononcé.","prompt":"Expliquez la procédure de discorde.","options":[{"label":"Tentative de conciliation puis divorce","detail":"Le tribunal doit tenter la conciliation ; en cas d'échec et de discorde persistante, il prononce le divorce.","pts":17,"speech":"En cas de discorde, le tribunal doit d'abord entreprendre toutes les tentatives de conciliation. Mais si la conciliation est impossible et que la discorde persiste, il en dresse procès-verbal et prononce le divorce. Le refus de l'époux n'y fait pas obstacle : un an d'abandon du domicile témoigne d'une discorde durable.","ok":["Décrit la procédure de conciliation","Le refus d'un époux n'empêche pas le divorce","Établit la discorde durable"],"ko":[]},{"label":"Accuser le mari","detail":"Énumérer ses torts sans procédure.","pts":8,"speech":"Le mari est seul responsable de tout.","ok":[],"ko":["N'explique pas la procédure applicable"]}],"concepts":[{"label":"Tentative de conciliation","re":"concilia","pts":5,"key":true},{"label":"Discorde persistante → divorce","re":"discorde|persist|chiqaq","pts":5},{"label":"Le refus de l'époux n'empêche pas","re":"refus|n.empeche pas|obstacle","pts":3}],"articles":[{"code":"CF","article":"94","label":"Art. 94 Code de la famille (conciliation)","pts":3},{"code":"CF","article":"97","label":"Art. 97 Code de la famille (prononcé du divorce)","pts":3}],"faille":"L'épouse ne démontre pas la discorde.","concede":"La discorde est établie. Reste la question des droits."},{"name":"Les droits de l'épouse","adverse":"Aucune somme n'est due : c'est l'épouse qui demande le divorce.","prompt":"Défendez les droits de l'épouse.","options":[{"label":"Droits légaux de l'épouse","detail":"Reliquat du sadaq, pension de viduité, don de consolation selon la durée du mariage.","pts":16,"speech":"Les droits dus à l'épouse comprennent le reliquat du sadaq, la pension de la période de viduité et le don de consolation, évalué notamment en fonction de la durée du mariage et de la situation financière de l'époux. Quatorze ans de mariage justifient une mout'â significative ; le tribunal tient compte de la responsabilité de chacun dans la discorde.","ok":["Énumère les droits légaux","Lie la mout'â à la durée du mariage","Responsabilité du mari dans la discorde"],"ko":[]},{"label":"Réclamer la maison","detail":"Demander la propriété du domicile.","pts":6,"speech":"Mme Idrissi veut la maison.","ok":[],"ko":["Sans fondement juridique"]}],"concepts":[{"label":"Sadaq / viduité / don de consolation","re":"sadaq|viduite|idda|consolation|mout","pts":6,"key":true},{"label":"Durée du mariage et ressources de l'époux","re":"duree|quatorze|ressources|situation financiere","pts":4}],"articles":[{"code":"CF","article":"84","label":"Art. 84 Code de la famille (droits de l'épouse)","pts":4}],"faille":"L'épouse ne justifie pas ses droits.","concede":"Les droits sont fondés."},{"name":"Les enfants","adverse":"Le mari propose 1 000 DH par mois pour les trois enfants.","prompt":"Concluez sur les enfants.","options":[{"label":"Pension, logement et garde","detail":"Pension selon les besoins et le niveau de vie, logement distinct, garde à la mère.","pts":15,"speech":"Nous demandons la garde des trois enfants, une pension alimentaire fixée selon leurs besoins et leur scolarité antérieure au divorce, et les frais de logement, distincts de la pension.","ok":["Couvre pension, logement et garde"],"ko":[]},{"label":"Accepter 1 000 DH","detail":"Transiger.","pts":7,"speech":"Nous acceptons.","ok":[],"ko":["Manifestement insuffisant pour trois enfants"]}],"concepts":[{"label":"Pension selon besoins / scolarité","re":"pension|besoin|scolar","pts":4,"key":true},{"label":"Logement distinct / garde","re":"logement|garde","pts":3}],"articles":[{"code":"CF","article":"85","label":"Art. 85 Code de la famille (pension des enfants)","pts":3}],"faille":"L'épouse ne précise pas ses demandes pour les enfants.","concede":"Les demandes sont complètes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la conciliation a échoué et que la discorde persiste, imputable pour l'essentiel à l'époux ; Par ces motifs : prononce le divorce pour discorde, alloue à l'épouse le reliquat du sadaq, la pension de viduité et une mout'â de 60 000 Dirhams, lui confie la garde et fixe la pension et le logement des enfants."},{"min":45,"text":"Le Tribunal, attendu que la discorde est établie ; Par ces motifs : prononce le divorce, alloue les droits légaux avec une mout'â de 25 000 Dirhams et fixe la pension des enfants."},{"min":0,"text":"Le Tribunal, attendu que la discorde n'est pas suffisamment établie ; Par ces motifs : renvoie les parties à une nouvelle tentative de conciliation."}]},{"id":"pension","matiere":"famille","title":"Mme Kabbaj c/ M. Squalli","court":"Tribunal de première instance de Casablanca — section de la famille","object":"Fixation de la pension alimentaire et des frais de logement de deux enfants.","you":"Avocat de la mère (Mme Kabbaj)","adverseName":"Avocat du père","facts":"Divorcés depuis un an, Mme Kabbaj a la garde de deux enfants scolarisés en école privée. M. Squalli, cadre bancaire, déclare un salaire de 9 000 DH mais possède deux appartements loués. Il verse 1 500 DH par mois et refuse de payer le loyer de l'appartement où vivent les enfants.","rounds":[{"name":"Le contenu de la pension","adverse":"Monsieur le Président, 1 500 Dirhams suffisent : c'est ce que mon client peut payer.","prompt":"Définissez ce que couvre la pension.","options":[{"label":"Entretien complet et niveau de vie","detail":"La pension couvre alimentation, habillement, soins, instruction ; elle tient compte de la situation antérieure.","pts":16,"speech":"L'entretien comprend l'alimentation, l'habillement, les soins médicaux, l'instruction des enfants et tout ce qui est habituellement indispensable. Les enfants étaient scolarisés en école privée avant le divorce : leur situation scolaire doit être maintenue. 1 500 Dirhams ne couvrent même pas les frais de scolarité.","ok":["Contenu légal de l'entretien","Maintien du niveau de vie et de la scolarité"],"ko":[]},{"label":"Demander un montant élevé sans justification","detail":"Réclamer 20 000 DH.","pts":7,"speech":"Nous demandons 20 000 Dirhams.","ok":[],"ko":["Aucune justification des besoins"]}],"concepts":[{"label":"Contenu de l'entretien (alimentation, soins, instruction)","re":"aliment|habill|soins|instruction|scolar","pts":6,"key":true},{"label":"Maintien de la situation antérieure","re":"anterieur|avant le divorce|niveau de vie|ecole privee","pts":4}],"articles":[{"code":"CF","article":"189","label":"Art. 189 Code de la famille (contenu de l'entretien)","pts":4}],"faille":"La mère ne justifie pas les besoins.","concede":"Les besoins sont établis. Reste à évaluer les ressources."},{"name":"Les ressources du père","adverse":"Le père ne gagne que 9 000 Dirhams par mois.","prompt":"Démontrez les ressources réelles.","options":[{"label":"Preuves des revenus locatifs, expertise","detail":"Le tribunal se fonde sur les preuves produites et peut recourir à des experts.","pts":15,"speech":"Le tribunal se fonde sur les déclarations et les preuves des parties, et peut faire appel à des experts. Nous produisons les annonces de location et les certificats de propriété des deux appartements : les revenus réels du père dépassent largement son salaire déclaré.","ok":["Preuves des revenus cachés","Demande d'expertise"],"ko":[]},{"label":"Supposer des revenus","detail":"Affirmer qu'il gagne plus sans preuve.","pts":6,"speech":"Il gagne certainement plus.","ok":[],"ko":["Aucune preuve"]}],"concepts":[{"label":"Preuves des revenus locatifs","re":"appartement|loyer|location|propriet","pts":5,"key":true},{"label":"Recours à l'expertise","re":"expert","pts":4}],"articles":[{"code":"CF","article":"190","label":"Art. 190 Code de la famille (estimation de la pension)","pts":4}],"faille":"Les revenus supplémentaires ne sont pas prouvés.","concede":"Les revenus locatifs sont établis."},{"name":"Le logement","adverse":"Le père refuse de payer le loyer : la pension suffit.","prompt":"Défendez les frais de logement.","options":[{"label":"Logement distinct de la pension","detail":"Les frais de logement sont distincts de la pension ; le père doit assurer un logement ou payer le loyer.","pts":15,"speech":"Les frais de logement de l'enfant gardé sont distincts de la pension alimentaire et de la rémunération de garde. Le père doit assurer un logement à ses enfants ou s'acquitter du montant du loyer. Nous demandons la prise en charge du loyer de 4 500 Dirhams.","ok":["Le logement s'ajoute à la pension","Chiffre le loyer"],"ko":[]},{"label":"Renoncer au logement","detail":"Abandonner cette demande.","pts":5,"speech":"Nous renonçons au loyer.","ok":[],"ko":["Renonce à un droit distinct"]}],"concepts":[{"label":"Logement distinct de la pension","re":"logement|loyer|distinct","pts":5,"key":true}],"articles":[{"code":"CF","article":"168","label":"Art. 168 Code de la famille (frais de logement)","pts":4}],"faille":"La mère renonce au logement.","concede":"Le logement est dû."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que les besoins des enfants, scolarisés en école privée, et les revenus réels du père, incluant des loyers, sont établis ; Par ces motifs : fixe la pension à 6 000 Dirhams par mois et met à sa charge le loyer de 4 500 Dirhams."},{"min":45,"text":"Le Tribunal, attendu que les besoins sont établis mais les ressources partiellement ; Par ces motifs : fixe la pension à 3 500 Dirhams et le logement à 3 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu que la mère ne justifie ni les besoins ni les ressources alléguées ; Par ces motifs : fixe la pension à 2 000 Dirhams."}]},{"id":"rectification","matiere":"fiscal","title":"Société Négoce Sud c/ Administration fiscale","court":"Tribunal administratif de Marrakech","object":"Contestation d'un redressement d'impôt sur les sociétés de 780 000 DH.","you":"Avocat de la société (Négoce Sud)","adverseName":"Représentant de l'administration fiscale","facts":"Après un contrôle, l'administration a rehaussé le résultat de Négoce Sud. La société n'a reçu qu'une seule notification, puis directement l'avis d'imposition, sans réponse motivée à ses observations envoyées dans les 30 jours. L'administration applique en outre une majoration de 20 %.","rounds":[{"name":"La procédure de rectification","adverse":"Monsieur le Président, la société a été contrôlée et ses écritures sont insuffisantes. L'imposition est fondée.","prompt":"Soulevez le vice de procédure.","options":[{"label":"Procédure normale non respectée","detail":"La procédure normale de rectification impose une réponse de l'administration aux observations du contribuable avant l'imposition.","pts":17,"speech":"Le Code général des impôts organise une procédure normale de rectification contradictoire : notification des motifs et du montant, observations du contribuable dans les trente jours, puis seconde notification motivée de l'administration, avec possibilité de saisir la commission. Ici, la société a répondu dans les délais mais n'a reçu aucune réponse : l'imposition a été émise directement. La procédure est irrégulière.","ok":["Décrit la procédure contradictoire","Relève l'absence de seconde notification","Respect du délai de 30 jours par la société"],"ko":[]},{"label":"Contester les chiffres seulement","detail":"Discuter le montant sans la procédure.","pts":8,"speech":"Le montant est exagéré.","ok":[],"ko":["Néglige le vice de procédure, décisif"]}],"concepts":[{"label":"Procédure contradictoire / seconde notification","re":"seconde notification|reponse|contradictoire|procedure","pts":6,"key":true},{"label":"Observations dans les trente jours","re":"trente|30 jours|observation","pts":4},{"label":"Commission / recours","re":"commission","pts":3}],"articles":[{"code":"CGI","article":"220","label":"Art. 220 CGI (procédure normale de rectification)","pts":5}],"faille":"La société ne soulève aucune irrégularité.","concede":"La procédure est discutable. Reste le fond."},{"name":"La majoration","adverse":"La majoration de 20 % s'applique de plein droit en cas de rectification.","prompt":"Répondez sur la majoration.","options":[{"label":"La majoration suit le sort du redressement","detail":"Si la rectification est irrégulière, la majoration tombe ; à défaut, discuter son taux.","pts":14,"speech":"La majoration prévue en cas de rectification de la base imposable est l'accessoire du redressement : si la procédure de rectification est irrégulière, la majoration tombe avec lui. À titre subsidiaire, nous contestons son application aux chefs de redressement purement d'interprétation.","ok":["Lien accessoire entre majoration et redressement","Argument subsidiaire"],"ko":[]},{"label":"Accepter la majoration","detail":"Ne pas discuter.","pts":5,"speech":"Nous ne contestons pas la majoration.","ok":[],"ko":["Abandon inutile"]}],"concepts":[{"label":"La majoration suit le redressement","re":"accessoire|suit|tombe|majoration","pts":5,"key":true},{"label":"Argument subsidiaire","re":"subsidiair","pts":3}],"articles":[{"code":"CGI","article":"186","label":"Art. 186 CGI (sanctions en cas de rectification)","pts":4}],"faille":"La majoration s'applique.","concede":"La majoration dépend du redressement."},{"name":"Conclusions","adverse":"L'administration propose un abattement de 30 % sur les droits.","prompt":"Concluez.","options":[{"label":"Annulation de l'imposition","detail":"Annulation pour vice de procédure ; subsidiairement, expertise sur le fond.","pts":15,"speech":"Nous concluons à l'annulation de l'imposition et de la majoration pour irrégularité de la procédure. À titre subsidiaire, une expertise comptable sur les chefs de redressement.","ok":["Conclusions hiérarchisées"],"ko":[]},{"label":"Accepter l'abattement","detail":"Transiger.","pts":8,"speech":"Nous acceptons.","ok":[],"ko":["Renonce à un vice de procédure décisif"]}],"concepts":[{"label":"Annulation pour vice de procédure","re":"annul|vice|irregul","pts":4,"key":true}],"articles":[],"faille":"La société n'a pas de conclusion claire.","concede":"Les conclusions sont nettes."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'administration n'a pas répondu aux observations du contribuable avant d'émettre l'imposition, en méconnaissance de la procédure normale de rectification ; Par ces motifs : annule l'imposition et la majoration."},{"min":45,"text":"Le Tribunal, attendu que la procédure présente une irrégularité partielle ; Par ces motifs : annule la majoration et ordonne une expertise sur les chefs de redressement."},{"min":0,"text":"Le Tribunal, attendu qu'aucune irrégularité n'est démontrée ; Par ces motifs : rejette la requête."}]},{"id":"khol","matiere":"famille","title":"Mme Bennani c/ M. Tahiri","court":"Tribunal de première instance de Rabat — section de la famille","object":"Divorce par Khol : l'époux accepte le principe mais exige une contrepartie de 300 000 DH.","you":"Avocat de l'épouse (Mme Bennani)","adverseName":"Avocat de M. Tahiri","facts":"Mariés depuis six ans, sans enfant, les époux vivent séparés depuis un an. Mme Bennani, enseignante (salaire 9 000 DH), demande le divorce par Khol et propose de renoncer au reliquat de sa dot (20 000 DH). M. Tahiri accepte le principe du divorce mais exige 300 000 DH, montant qu'il dit correspondre aux frais du mariage et aux cadeaux offerts. Des voisins ont attesté d'insultes répétées de l'époux.","rounds":[{"name":"La contrepartie exigée","adverse":"Monsieur le Président, le Khol est un divorce consensuel : c'est l'épouse qui veut partir, c'est donc à elle d'en payer le prix. Mon client est libre de fixer ses conditions. Sans accord sur les 300 000 Dirhams, il n'y a pas de Khol.","prompt":"Répondez sur le pouvoir du tribunal quant à la contrepartie.","options":[{"label":"Le tribunal fixe la contrepartie","detail":"Accord sur le principe : à défaut d'accord sur le montant, le tribunal l'évalue (art. 120) ; pas d'abus (art. 118).","pts":18,"speech":"Les deux époux sont d'accord sur le principe du Khol. Dans ce cas, l'article 120 du Code de la famille donne au tribunal le pouvoir d'évaluer lui-même la contrepartie, en tenant compte de la dot, de la durée du mariage, des causes de la demande et de la situation de l'épouse. L'article 118 interdit en outre à l'époux tout abus ou excès : 300 000 Dirhams, soit près de trois ans de salaire, en sont l'illustration.","ok":["Cite l'article 120 : le tribunal évalue","Invoque l'interdiction de l'abus (art. 118)","Rapporte le montant au salaire de l'épouse"],"ko":[]},{"label":"Négocier le montant","detail":"Proposer 100 000 DH pour trouver un terrain d'entente.","pts":7,"speech":"Ma cliente est prête à faire un effort et propose 100 000 Dirhams afin de mettre fin au litige.","ok":["Volonté de conciliation"],"ko":["Concède un montant sans base légale","Ignore que le tribunal peut fixer la contrepartie"]}],"concepts":[{"label":"Le tribunal évalue la contrepartie","re":"tribunal.*(fix|evalu|apprec)|(fix|evalu|apprec).*tribunal","pts":6,"key":true},{"label":"Accord sur le principe du Khol","re":"principe|accord","pts":3},{"label":"Abus ou excès de l'époux","re":"abus|exces|excessi|disproportion","pts":4},{"label":"Critères : dot, durée, situation de l'épouse","re":"dot|sadaq|duree|salaire|situation","pts":3}],"articles":[{"code":"CF","article":"120","label":"Art. 120 Code de la famille (évaluation par le tribunal)","pts":4},{"code":"CF","article":"118","label":"Art. 118 CF (pas d'abus ni d'excès)","pts":2}],"faille":"La demanderesse ne conteste pas sérieusement le montant. Le tribunal ne peut que constater l'absence d'accord.","concede":"Admettons que le tribunal fixe la contrepartie. Encore faut-il qu'elle soit équitable pour mon client."},{"name":"Les frais du mariage","adverse":"Mon client a dépensé plus de 150 000 Dirhams pour la cérémonie et a offert des bijoux. Il est juste qu'il récupère ces sommes : la contrepartie doit couvrir son préjudice.","prompt":"Répondez sur les critères d'évaluation.","options":[{"label":"Critères légaux, pas remboursement","detail":"La contrepartie n'est pas un remboursement des dépenses ; la dot et la durée comptent ; les cadeaux d'usage ne se restituent pas.","pts":16,"speech":"Le Khol n'est pas une action en remboursement. Les frais d'une fête et les cadeaux d'usage ne sont pas une dette de l'épouse. Les critères de l'article 120 sont la dot, la durée du mariage, les causes du divorce et la situation matérielle de l'épouse : six ans de vie commune et une dot modeste conduisent à une contrepartie limitée, que ma cliente offre déjà sous forme de renonciation au reliquat de sa dot.","ok":["Distingue contrepartie et remboursement","Applique les critères légaux","Valorise l'offre de l'épouse"],"ko":["Ne chiffre pas de proposition subsidiaire"]},{"label":"Contester les factures","detail":"Demander les justificatifs des 150 000 DH.","pts":9,"speech":"Où sont les factures de ces prétendues dépenses ? Nous en contestons la réalité.","ok":["Exige la preuve"],"ko":["Accepte implicitement que ces frais puissent être remboursés"]}],"concepts":[{"label":"La contrepartie n'est pas un remboursement","re":"rembours|pas une (dette|creance)|cadeau|frais","pts":5,"key":true},{"label":"Durée du mariage et dot","re":"dot|sadaq|duree|six ans","pts":4},{"label":"Renonciation au reliquat de dot","re":"renonc|reliquat","pts":3}],"articles":[{"code":"CF","article":"120","label":"Art. 120 CF (critères d'évaluation)","pts":4}],"faille":"La demande ne dit rien des critères légaux : le tribunal retiendra le préjudice de mon client.","concede":"Les frais de mariage ne sont pas tout, soit. Mais le divorce reste voulu par l'épouse seule."},{"name":"Le préjudice subi par l'épouse","adverse":"Enfin, c'est l'épouse qui a quitté le domicile conjugal. Elle ne peut se plaindre de rien et doit assumer seule la rupture.","prompt":"Plaidez sur le comportement de l'époux et ses effets.","options":[{"label":"Préjudice et restitution","detail":"Insultes attestées : l'épouse a droit à restitution de la contrepartie si elle prouve un préjudice (art. 117).","pts":18,"speech":"Ma cliente a quitté le domicile après des insultes répétées, attestées par deux voisins. L'article 117 du Code de la famille prévoit que l'épouse a droit à la restitution de la contrepartie si elle établit avoir subi un préjudice de la part de son époux, le divorce restant acquis. À tout le moins, ce comportement justifie une contrepartie symbolique.","ok":["Cite l'article 117","S'appuie sur les attestations","Conclusion subsidiaire chiffrée"],"ko":[]},{"label":"Changer de procédure","detail":"Abandonner le Khol et demander le divorce pour discorde.","pts":8,"speech":"Ma cliente se réserve d'introduire une demande de divorce pour discorde.","ok":["Option procédurale réelle"],"ko":["Abandonne la demande en cours","N'exploite pas les attestations"]}],"concepts":[{"label":"Préjudice causé par l'époux","re":"prejudice|insult|violence|maltrait","pts":5,"key":true},{"label":"Restitution de la contrepartie","re":"restitu|rembours","pts":5},{"label":"Preuve par attestations / témoins","re":"attest|temoin|voisin","pts":3}],"articles":[{"code":"CF","article":"117","label":"Art. 117 CF (restitution en cas de préjudice)","pts":4}],"faille":"Aucune preuve du prétendu préjudice : le départ de l'épouse reste injustifié.","concede":"Les attestations existent, je l'admets ; leur portée reste discutable."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que les époux s'accordent sur le principe du Khol et que la contrepartie réclamée revêt un caractère excessif au sens de l'article 118 ; évaluant la contrepartie au regard de la dot, de la durée du mariage et des insultes attestées ; Par ces motifs : prononce le divorce par Khol moyennant la renonciation de l'épouse au reliquat de sa dot."},{"min":45,"text":"Le Tribunal, attendu l'accord des époux sur le principe et le défaut d'accord sur la contrepartie ; Par ces motifs : prononce le divorce par Khol et fixe la contrepartie à 40 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu que l'épouse n'a pas utilement contesté le montant ni justifié d'un préjudice ; Par ces motifs : fixe la contrepartie à 120 000 Dirhams et prononce le divorce par Khol."}]},{"id":"garde-remariage","matiere":"famille","title":"M. Alami c/ Mme Fassi","court":"Tribunal de première instance de Fès — section de la famille","object":"Demande de déchéance de la garde de la mère, remariée, sur une fillette de cinq ans.","you":"Avocat de la mère (Mme Fassi)","adverseName":"Avocat de M. Alami","facts":"Divorcés en 2021, les parents ont une fille, Rim, cinq ans, confiée à sa mère. Mme Fassi s'est remariée en mars 2023 ; M. Alami en a été informé le jour même par sa famille. En mai 2024, il demande la déchéance de la garde, estimant que la présence d'un beau-père étranger à l'enfant nuit à sa fille. L'enfant est scolarisée et suivie par un pédiatre.","rounds":[{"name":"Le remariage de la mère","adverse":"Monsieur le Président, la mère s'est remariée avec un homme étranger à l'enfant. Ce remariage fait perdre le droit de garde : l'intérêt de Rim commande qu'elle vive auprès de son père.","prompt":"Répondez sur l'effet du remariage.","options":[{"label":"Exception légale : enfant de moins de sept ans","detail":"Le remariage de la mère n'entraîne pas la déchéance si l'enfant n'a pas sept ans (art. 175).","pts":18,"speech":"L'article 175 du Code de la famille est clair : le mariage de la mère gardienne n'entraîne pas la déchéance de son droit de garde si l'enfant n'a pas dépassé l'âge de sept ans. Rim a cinq ans. La règle que plaide la partie adverse vise, à l'article 174, la gardienne autre que la mère.","ok":["Cite l'article 175 (moins de sept ans)","Distingue l'article 174 (gardienne autre que la mère)"],"ko":[]},{"label":"Plaider l'attachement","detail":"Insister sur le lien affectif entre la mère et l'enfant.","pts":9,"speech":"Rim a toujours vécu avec sa mère, qui l'élève avec amour. L'arracher à ce foyer serait cruel.","ok":["Argument humain"],"ko":["Aucun fondement textuel","Ne répond pas à l'argument du remariage"]}],"concepts":[{"label":"Enfant de moins de sept ans","re":"sept ans|7 ans|moins de sept|cinq ans|5 ans","pts":6,"key":true},{"label":"Le remariage n'entraîne pas la déchéance","re":"pas (la )?decheance|n.entraine pas|maintien","pts":4},{"label":"Distingue la gardienne autre que la mère","re":"autre que la mere|174","pts":3}],"articles":[{"code":"CF","article":"175","label":"Art. 175 CF (remariage de la mère)","pts":5}],"faille":"La défense ne répond pas sur le remariage : la déchéance s'impose.","concede":"L'enfant a moins de sept ans, c'est vrai. Mais le père n'a pas renoncé pour autant à agir."},{"name":"Le silence du père","adverse":"Mon client a toujours entendu protéger sa fille. Il agit aujourd'hui car il a constaté que l'enfant était perturbée.","prompt":"Répondez sur le délai d'action du père.","options":[{"label":"Déchéance du père par son silence","detail":"Informé en mars 2023, il agit en mai 2024 : plus d'un an de silence (art. 176).","pts":17,"speech":"Le père a été informé du remariage le jour même, en mars 2023, et n'a agi qu'en mai 2024. Or l'article 176 du Code de la famille déchoit du droit de réclamer la garde celui qui a gardé le silence pendant une année après avoir eu connaissance de la consommation du mariage de la gardienne, sauf motif impérieux. Aucun motif de ce type n'est allégué.","ok":["Calcule le délai d'un an","Cite l'article 176","Relève l'absence de motif impérieux"],"ko":["Devra prouver la date à laquelle le père a su"]},{"label":"Contester la perturbation","detail":"Produire le carnet scolaire et l'avis du pédiatre.","pts":11,"speech":"Le carnet scolaire et l'avis du pédiatre montrent une enfant épanouie.","ok":["Preuves concrètes de l'intérêt de l'enfant"],"ko":["Laisse de côté l'argument décisif du délai"]}],"concepts":[{"label":"Silence de plus d'un an","re":"un an|une annee|delai|silence|tardi","pts":6,"key":true},{"label":"Connaissance du remariage","re":"connaissance|informe|savait|mars 2023","pts":4},{"label":"Pas de motif impérieux","re":"motif imperieux|aucun motif","pts":3}],"articles":[{"code":"CF","article":"176","label":"Art. 176 CF (silence d'une année)","pts":5}],"faille":"La défense n'évoque même pas la date à laquelle mon client a été informé. L'action reste recevable.","concede":"Le délai est discuté, admettons. L'intérêt de l'enfant reste le critère suprême."},{"name":"L'intérêt de l'enfant","adverse":"En tout état de cause, le tribunal doit tenir compte de l'intérêt de l'enfant, qui est de vivre auprès de son père, dans un foyer stable.","prompt":"Plaidez sur l'intérêt de l'enfant et les conditions de la garde.","options":[{"label":"Intérêt de l'enfant et droit de visite","detail":"Stabilité, scolarité, suivi médical ; la mère remplit les conditions (art. 173) ; proposer un droit de visite élargi.","pts":18,"speech":"L'intérêt de Rim, que l'article 186 place au cœur de toute décision, est la stabilité : même école, même pédiatre, même foyer depuis sa naissance. La mère remplit toutes les conditions de l'article 173 : rectitude, capacité d'élever l'enfant et de la protéger. Ma cliente propose un droit de visite élargi au père, chaque week-end et la moitié des vacances.","ok":["Invoque l'intérêt de l'enfant (art. 186)","Vérifie les conditions de l'article 173","Proposition constructive"],"ko":[]},{"label":"Attaquer le père","detail":"Reprocher au père son manque d'implication passé.","pts":7,"speech":"Le père ne s'est jamais occupé de sa fille et ne paie la pension qu'avec retard.","ok":["Met en doute la sincérité du père"],"ko":["Aucune pièce","Ne démontre pas l'intérêt de l'enfant"]}],"concepts":[{"label":"Intérêt de l'enfant","re":"interet de l.enfant|interet superieur|stabilit","pts":5,"key":true},{"label":"Conditions de la garde remplies","re":"condition|capacit|rectitude|honnetet","pts":4},{"label":"Scolarité et suivi médical","re":"ecole|scolar|pediatre|medical","pts":3},{"label":"Droit de visite","re":"droit de visite|visite|week-end|vacances","pts":3}],"articles":[{"code":"CF","article":"186","label":"Art. 186 CF (intérêt de l'enfant)","pts":3},{"code":"CF","article":"173","label":"Art. 173 CF (conditions de la garde)","pts":2}],"faille":"La défense ne dit rien de concret sur l'intérêt de l'enfant.","concede":"La stabilité de l'enfant est réelle. Le père demande au moins à la voir davantage."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'enfant n'a pas atteint l'âge de sept ans (article 175) et que le père a gardé le silence plus d'une année après avoir connu le remariage (article 176) ; Par ces motifs : rejette la demande de déchéance et organise un droit de visite élargi au profit du père."},{"min":45,"text":"Le Tribunal, attendu que le remariage de la mère n'entraîne pas la déchéance lorsque l'enfant a moins de sept ans ; Par ces motifs : maintient la garde à la mère et fixe le droit de visite du père."},{"min":0,"text":"Le Tribunal, attendu que la mère n'a pas établi que le maintien de la garde serve l'intérêt de l'enfant ; Par ces motifs : ordonne une enquête sociale et confie provisoirement la garde au père."}]},{"id":"testament-heritier","matiere":"famille","title":"Consorts Berrada c/ M. Youssef Berrada","court":"Tribunal de première instance de Casablanca — section de la famille","object":"Nullité d'un testament léguant une villa à l'un des héritiers.","you":"Avocat des sœurs héritières (consorts Berrada)","adverseName":"Avocat de M. Youssef Berrada","facts":"M. Berrada père est décédé en 2024 en laissant trois enfants : Youssef, Salma et Hind. Un testament manuscrit, signé de sa main, lègue à Youssef la villa familiale (2,4 millions de DH sur une succession de 6 millions). Youssef soutient que ses sœurs avaient donné leur accord oral pendant la dernière maladie de leur père, ce qu'elles contestent.","rounds":[{"name":"La validité du testament","adverse":"Monsieur le Président, le testament est entièrement écrit et signé de la main du défunt, ce que l'article 296 du Code de la famille admet expressément. Il est donc valable et doit être exécuté.","prompt":"Répondez sur la validité du legs.","options":[{"label":"Forme valable, fond nul","detail":"La forme est régulière mais un legs à un héritier est interdit sans l'autorisation des autres (art. 280).","pts":18,"speech":"Nous ne contestons pas la forme : un écrit de la main du testateur est admis par l'article 296. Mais la forme n'est pas le fond. L'article 280 du Code de la famille dispose que le testament ne peut être fait en faveur d'un héritier, sauf permission des autres héritiers. Youssef est héritier ; ses sœurs n'ont rien autorisé. Le legs est sans effet.","ok":["Distingue forme (art. 296) et fond (art. 280)","Qualifie le légataire d'héritier"],"ko":[]},{"label":"Contester l'écriture","detail":"Demander une expertise graphologique.","pts":8,"speech":"Nous doutons que ce document soit de la main de notre père et demandons une expertise.","ok":["Démarche possible"],"ko":["Aucun indice de faux","Passe à côté de l'interdiction du legs à un héritier"]}],"concepts":[{"label":"Legs à un héritier interdit","re":"heritier.*(interdit|ne peut|nul|pas de)|(interdit|ne peut|nul).*heritier|pas de testament","pts":6,"key":true},{"label":"Sauf permission des autres héritiers","re":"permission|autoris|accord|consent","pts":4},{"label":"Distingue forme et fond","re":"forme|manuscrit|ecrit de (la|sa) main","pts":3}],"articles":[{"code":"CF","article":"280","label":"Art. 280 CF (pas de legs à un héritier)","pts":5},{"code":"CF","article":"296","label":"Art. 296 CF (forme du testament)","pts":1}],"faille":"Les demanderesses ne contestent pas la forme : le testament s'impose.","concede":"Le légataire est héritier, je le reconnais. Mais ses sœurs avaient donné leur accord."},{"name":"L'accord prétendu des sœurs","adverse":"Pendant la dernière maladie de leur père, Salma et Hind ont dit devant la famille qu'elles respecteraient sa volonté. Selon l'article 303, cet accord les engage.","prompt":"Répondez sur la ratification invoquée.","options":[{"label":"Exiger la preuve de la ratification","detail":"L'article 303 exige une ratification ou autorisation réelle d'héritiers capables : aucune preuve d'un accord sur ce legs précis.","pts":17,"speech":"L'article 303 n'engage que les héritiers qui ont réellement ratifié le testament ou donné leur autorisation, en pleine capacité. Il appartient à M. Youssef Berrada de prouver cet accord. Or il n'apporte ni écrit, ni témoin précis : une phrase de réconfort au chevet d'un père malade n'est pas l'autorisation d'un legs de 2,4 millions de Dirhams, dont mes clientes ignoraient d'ailleurs le contenu.","ok":["Charge de la preuve sur le légataire","Exige une autorisation portant sur ce legs","Ignorance du contenu"],"ko":["Ne demande pas d'enquête pour entendre les témoins"]},{"label":"Nier tout propos","detail":"Affirmer que les sœurs n'ont jamais rien dit.","pts":7,"speech":"Mes clientes n'ont jamais tenu de tels propos.","ok":["Contestation nette"],"ko":["Simple dénégation","N'analyse pas les conditions de l'article 303"]}],"concepts":[{"label":"Preuve de l'accord à la charge du légataire","re":"preuve|prouver|charge de la preuve|aucun (ecrit|temoin)","pts":5,"key":true},{"label":"Ratification réelle et éclairée","re":"ratifi|autoris|en connaissance|contenu|ignor","pts":5},{"label":"Pleine capacité des héritiers","re":"capacit","pts":2}],"articles":[{"code":"CF","article":"303","label":"Art. 303 CF (ratification par les héritiers)","pts":4}],"faille":"Les sœurs ne contestent pas la scène rapportée par la famille.","concede":"La preuve écrite manque, c'est vrai. Il reste au moins la quotité disponible."},{"name":"La quotité du tiers","adverse":"Subsidiairement, le défunt pouvait disposer du tiers de ses biens. Le legs doit au moins valoir dans la limite du tiers, soit deux millions de Dirhams.","prompt":"Répondez à la demande subsidiaire.","options":[{"label":"Le tiers ne sauve pas un legs à héritier","detail":"La limite du tiers (art. 277) concerne les legs aux non-héritiers ; au profit d'un héritier, le legs est nul même en deçà.","pts":18,"speech":"L'article 277 limite le testament au tiers des biens, mais cette limite est cumulative avec l'article 280 : un legs au profit d'un héritier est sans effet, qu'il soit inférieur ou supérieur au tiers, faute d'autorisation des autres héritiers. La villa doit donc revenir dans la masse successorale et être partagée selon les règles légales.","ok":["Articule les articles 277 et 280","Tire la conséquence : retour à la masse"],"ko":[]},{"label":"Accepter un tiers réduit","detail":"Proposer de valider le legs à hauteur d'un million.","pts":6,"speech":"Mes clientes accepteraient, à titre transactionnel, que le legs vaille pour un million de Dirhams.","ok":["Esprit de transaction"],"ko":["Abandonne un droit certain","Confond les deux règles"]}],"concepts":[{"label":"Legs à héritier nul même dans le tiers","re":"meme (dans|en deca|inferieur)|quel que soit|cumulati|tiers ne","pts":6,"key":true},{"label":"Limite du tiers","re":"tiers","pts":3},{"label":"Retour à la masse successorale","re":"masse|partage|succession","pts":3}],"articles":[{"code":"CF","article":"277","label":"Art. 277 CF (testament sur le tiers)","pts":3},{"code":"CF","article":"280","label":"Art. 280 CF","pts":2}],"faille":"Les demanderesses ne répondent pas : le legs vaudra au moins dans la limite du tiers.","concede":"Le tiers est une limite, admettons ; reste que la volonté du père était claire."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le legs est fait au profit d'un héritier et que la ratification des autres héritiers n'est pas établie (articles 280 et 303) ; Par ces motifs : déclare le testament sans effet et dit que la villa fait partie de la masse successorale."},{"min":45,"text":"Le Tribunal, attendu que le legs à un héritier requiert l'autorisation des autres héritiers ; ordonne avant dire droit une enquête sur l'accord allégué, en réservant les droits des parties."},{"min":0,"text":"Le Tribunal, attendu que les demanderesses n'ont pas utilement contesté l'accord rapporté ; Par ces motifs : valide le legs dans la limite du tiers de la succession."}]},{"id":"filiation","matiere":"famille","title":"Mme Ziani c/ M. Ouali","court":"Tribunal de première instance de Meknès — section de la famille","object":"Établissement de la filiation paternelle d'un enfant né sept mois après le mariage.","you":"Avocat de la mère (Mme Ziani)","adverseName":"Avocat de M. Ouali","facts":"Mme Ziani et M. Ouali se sont mariés par acte adoulaire le 2 janvier 2024 et ont vécu ensemble jusqu'en juin. Le petit Adam est né le 10 août 2024, sept mois et huit jours après le mariage. M. Ouali, parti du domicile, refuse de reconnaître l'enfant et soutient qu'il ne peut être de lui.","rounds":[{"name":"La présomption de paternité","adverse":"Monsieur le Président, mon client conteste être le père. Un enfant né à peine sept mois après le mariage n'a pu être conçu pendant celui-ci.","prompt":"Établissez la filiation de l'enfant.","options":[{"label":"Rapports conjugaux (Al Firach)","detail":"Né plus de six mois après le mariage, avec cohabitation : filiation établie par le firach (art. 154).","pts":18,"speech":"L'article 154 du Code de la famille établit la filiation par les rapports conjugaux lorsque l'enfant est né au moins six mois après la conclusion du mariage et que les rapports entre époux étaient possibles. Adam est né sept mois et huit jours après le mariage, alors que les époux vivaient ensemble. La filiation paternelle est donc établie de plein droit.","ok":["Cite l'article 154 (délai de six mois)","Calcule la durée","Relève la cohabitation"],"ko":[]},{"label":"Demander un test ADN","detail":"Solliciter immédiatement une expertise génétique.","pts":9,"speech":"Pour lever tout doute, ma cliente sollicite une expertise génétique.","ok":["Moyen de preuve admis"],"ko":["Renverse inutilement la charge : la présomption suffit"]}],"concepts":[{"label":"Naissance plus de six mois après le mariage","re":"six mois|6 mois|sept mois|7 mois","pts":6,"key":true},{"label":"Rapports conjugaux / Firach / cohabitation","re":"firach|rapports conjugaux|cohabit|vie commune|ensemble","pts":4},{"label":"Présomption de paternité","re":"presompt|de plein droit","pts":3}],"articles":[{"code":"CF","article":"154","label":"Art. 154 CF (filiation par le firach)","pts":5}],"faille":"La mère ne dit pas un mot du délai de gestation : la filiation reste douteuse.","concede":"Le délai de six mois est respecté, soit. Mon client demande néanmoins une expertise."},{"name":"La contestation par le père","adverse":"Mon client demande une expertise génétique, qui seule dira la vérité. Il a le droit de contester une paternité qu'il n'a jamais acceptée.","prompt":"Répondez sur les conditions de la contestation.","options":[{"label":"Contestation encadrée","detail":"Le firach est une preuve irréfutable, contestable seulement par le liâane ou une expertise formelle, à condition d'apporter des preuves sérieuses (art. 153).","pts":17,"speech":"L'article 153 du Code de la famille fait des rapports conjugaux une preuve irréfutable de la filiation, qui ne peut être contestée que par le mari, selon la procédure du liâane ou par une expertise formelle, à la condition qu'il produise des moyens de preuve sérieux à l'appui de sa contestation. M. Ouali n'apporte rien : ni absence, ni impossibilité, ni indice. Sa simple dénégation ne suffit pas à ouvrir l'expertise.","ok":["Cite l'article 153","Exige des preuves sérieuses avant l'expertise"],"ko":["Ne propose pas d'alternative si l'expertise est ordonnée"]},{"label":"Accepter l'expertise","detail":"Consentir à l'ADN, sûre du résultat.","pts":11,"speech":"Ma cliente ne craint rien et accepte l'expertise.","ok":["Confiance dans la vérité"],"ko":["Renonce à la protection légale de la présomption","Retarde la procédure"]}],"concepts":[{"label":"Preuve irréfutable, contestation limitée","re":"irrefutable|liaane|lian|serment d.anatheme","pts":5,"key":true},{"label":"Preuves sérieuses exigées du mari","re":"preuves? serieus|indice|simple denegation|rien","pts":5},{"label":"Expertise encadrée","re":"expertise","pts":2}],"articles":[{"code":"CF","article":"153","label":"Art. 153 CF (contestation de la filiation)","pts":5}],"faille":"La mère refuse l'expertise : c'est qu'elle craint son résultat.","concede":"La loi encadre l'expertise, je l'admets. Mais le doute de mon client est sincère."},{"name":"Les effets de la filiation","adverse":"Même si la filiation était retenue, mon client ne saurait être tenu à quoi que ce soit tant qu'un jugement n'a pas tranché.","prompt":"Plaidez sur la présomption et ses effets.","options":[{"label":"Présomption et décision judiciaire","detail":"La filiation s'établit par présomption et ne se désavoue que par jugement (art. 151) ; tous les moyens de preuve sont admis (art. 158).","pts":17,"speech":"L'article 151 dispose que la filiation paternelle s'établit par la présomption et ne peut être désavouée que par décision judiciaire. Tant qu'aucun jugement ne la désavoue, M. Ouali est le père d'Adam, avec toutes les obligations qui en découlent, notamment l'entretien de l'enfant. L'article 158 admet d'ailleurs tout moyen de preuve, y compris l'aveu et le témoignage des proches qui ont connu la vie commune.","ok":["Cite l'article 151","Rappelle les obligations du père","Ouvre les moyens de preuve (art. 158)"],"ko":[]},{"label":"Demander une pension immédiate","detail":"Réclamer 2 000 DH par mois sans autre argument.","pts":8,"speech":"Ma cliente demande une pension de 2 000 Dirhams par mois pour Adam.","ok":["Demande concrète"],"ko":["Ne fonde pas la filiation","Montant non justifié"]}],"concepts":[{"label":"Présomption, désaveu seulement par jugement","re":"presompt|desaveu|decision judiciaire|jugement","pts":5,"key":true},{"label":"Obligations du père / entretien","re":"entretien|pension|obligation","pts":4},{"label":"Tous moyens de preuve","re":"tout moyen|temoin|aveu|adoul","pts":3}],"articles":[{"code":"CF","article":"151","label":"Art. 151 CF (présomption)","pts":3},{"code":"CF","article":"158","label":"Art. 158 CF (moyens de preuve)","pts":2}],"faille":"Rien n'est dit des effets : le tribunal ne peut rien imposer à mon client.","concede":"La présomption joue, c'est exact. Encore faut-il fixer raisonnablement les obligations."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'enfant est né plus de six mois après la conclusion du mariage, pendant la vie commune, et que le père n'apporte aucun moyen sérieux au soutien de sa contestation (articles 153 et 154) ; Par ces motifs : dit que la filiation paternelle d'Adam à l'égard de M. Ouali est établie et le condamne à son entretien."},{"min":45,"text":"Le Tribunal, attendu que les conditions du firach paraissent réunies mais que le père conteste ; ordonne une expertise génétique aux frais avancés du défendeur."},{"min":0,"text":"Le Tribunal, attendu que la demanderesse n'a pas établi les conditions de la filiation par le firach ; Par ces motifs : ordonne une enquête et réserve les droits des parties."}]},{"id":"polygamie","matiere":"famille","title":"M. Karimi (demande d'autorisation de polygamie)","court":"Tribunal de première instance de Kénitra — section de la famille","object":"Opposition de la première épouse à une demande d'autorisation de polygamie.","you":"Avocat de la première épouse (Mme Karimi)","adverseName":"Avocat de M. Karimi","facts":"M. Karimi, employé de banque (salaire net 7 500 DH), marié depuis douze ans et père de trois enfants, demande l'autorisation d'épouser une seconde femme. Il invoque la maladie chronique de son épouse, qui l'empêcherait de « tenir le foyer ». Le couple loue un appartement de 3 500 DH par mois. Mme Karimi s'oppose à la demande.","rounds":[{"name":"Le motif invoqué","adverse":"Monsieur le Président, mon client est un époux loyal. La maladie de son épouse rend la vie conjugale difficile : c'est un motif objectif et exceptionnel qui justifie la polygamie.","prompt":"Contestez le motif invoqué.","options":[{"label":"Motif non exceptionnel","detail":"La polygamie exige une justification objective et exceptionnelle (art. 41 et 42) ; la maladie de l'épouse appelle soutien, non remplacement.","pts":17,"speech":"Le Code de la famille fait de la polygamie une exception : l'article 41 interdit au tribunal de l'autoriser si sa justification objective et son caractère exceptionnel ne sont pas établis, et l'article 42 impose au demandeur d'exposer ces motifs. Une maladie chronique, traitée, qui n'empêche pas ma cliente d'élever trois enfants, n'est pas une circonstance exceptionnelle. Le devoir de l'époux est l'assistance, non le remplacement.","ok":["Cite les articles 41 et 42","Conteste le caractère exceptionnel","Rappelle le devoir d'assistance"],"ko":["Ne produit pas de certificat médical"]},{"label":"Plaider l'émotion","detail":"Décrire la souffrance de l'épouse humiliée.","pts":7,"speech":"Ma cliente vit cette demande comme une humiliation après douze ans de mariage.","ok":["Touche le juge"],"ko":["Aucun argument juridique"]}],"concepts":[{"label":"Justification objective et exceptionnelle","re":"exceptionnel|objecti|justification","pts":6,"key":true},{"label":"Maladie traitée, non empêchement","re":"maladie|traite|certificat|soin","pts":3},{"label":"Devoir d'assistance","re":"assistance|soutien|devoir","pts":3}],"articles":[{"code":"CF","article":"41","label":"Art. 41 CF (refus d'autorisation)","pts":4},{"code":"CF","article":"42","label":"Art. 42 CF (motifs de la demande)","pts":2}],"faille":"La défense ne conteste pas la maladie : le motif est établi.","concede":"Le motif est discutable, je le concède ; mais mon client a les moyens d'entretenir deux foyers."},{"name":"Les ressources du mari","adverse":"Mon client perçoit un salaire régulier et s'engage à traiter ses deux épouses avec équité.","prompt":"Répondez sur les ressources.","options":[{"label":"Ressources insuffisantes","detail":"7 500 DH, un loyer de 3 500 DH, trois enfants : impossible d'assurer équitablement deux foyers (art. 41).","pts":18,"speech":"L'article 41 interdit encore la polygamie lorsque le demandeur ne dispose pas de ressources suffisantes pour pourvoir aux besoins des deux foyers et leur assurer équitablement l'entretien et le logement. Avec 7 500 Dirhams, dont 3 500 pour le loyer et trois enfants scolarisés, il reste 4 000 Dirhams : de quoi faire vivre un second foyer ? L'engagement d'équité est impossible à tenir.","ok":["Calcul concret des charges","Cite la condition de ressources (art. 41)"],"ko":[]},{"label":"Contester la sincérité","detail":"Soutenir que le mari a une liaison.","pts":6,"speech":"Mon client a une liaison ; la maladie n'est qu'un prétexte.","ok":["Hypothèse vraisemblable"],"ko":["Accusation sans preuve","N'aborde pas les ressources"]}],"concepts":[{"label":"Ressources insuffisantes pour deux foyers","re":"ressources?|insuffis|deux foyers|salaire","pts":6,"key":true},{"label":"Calcul des charges","re":"loyer|3 500|charge|enfants","pts":4},{"label":"Équité impossible","re":"equit|injustice","pts":3}],"articles":[{"code":"CF","article":"41","label":"Art. 41 CF (ressources suffisantes)","pts":4},{"code":"CF","article":"40","label":"Art. 40 CF (injustice à craindre)","pts":2}],"faille":"Rien n'est démontré sur les ressources : le salaire de mon client suffit.","concede":"Les ressources sont limitées, c'est vrai. Mon client pourra les compléter."},{"name":"Si l'autorisation était donnée","adverse":"Si le tribunal autorise la polygamie, l'épouse pourra toujours rester ; elle n'a aucun droit à imposer son refus.","prompt":"Plaidez sur les droits de l'épouse qui refuse.","options":[{"label":"Divorce et fixation des droits","detail":"Si l'épouse persiste à refuser, le tribunal fixe tous ses droits et ceux des enfants (art. 45).","pts":17,"speech":"Ma cliente le dit clairement : elle refuse la co-épouse. L'article 45 prévoit que, lorsque l'impossibilité de poursuivre la vie conjugale est établie et que l'épouse persiste à demander le divorce, le tribunal fixe un montant correspondant à tous ses droits et à ceux de leurs enfants. Le mari doit le consigner, faute de quoi sa demande d'autorisation est réputée abandonnée.","ok":["Cite l'article 45","Protège les droits des enfants"],"ko":[]},{"label":"Accepter sous conditions","detail":"Accepter la polygamie contre une pension majorée.","pts":5,"speech":"Ma cliente pourrait accepter si une pension plus élevée lui était garantie.","ok":["Pragmatique"],"ko":["Contredit la position de la cliente","Aucun fondement"]}],"concepts":[{"label":"Divorce et fixation de tous les droits","re":"tous (ses|les) droits|montant|divorce","pts":5,"key":true},{"label":"Refus persistant de l'épouse","re":"refus|persist|oppos","pts":4},{"label":"Droits des enfants","re":"enfants","pts":3}],"articles":[{"code":"CF","article":"45","label":"Art. 45 CF (droits de l'épouse qui refuse)","pts":4}],"faille":"L'épouse n'a rien demandé pour elle-même : le tribunal statuera sans elle.","concede":"L'épouse peut demander le divorce, soit ; cela ne prive pas le mari de sa demande."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la justification objective et exceptionnelle n'est pas établie et que les ressources du demandeur ne permettent pas d'assurer équitablement deux foyers (article 41) ; Par ces motifs : rejette la demande d'autorisation de polygamie."},{"min":45,"text":"Le Tribunal, attendu que les ressources du demandeur sont insuffisantes ; Par ces motifs : rejette la demande, en l'état."},{"min":0,"text":"Le Tribunal, attendu que l'épouse n'a pas utilement contesté le motif ni les ressources ; Par ces motifs : autorise la polygamie sous réserve de la consignation des droits de la première épouse."}]},{"id":"reconnaissance-mariage","matiere":"famille","title":"Mme Aït Brahim c/ héritiers Aït Lahcen","court":"Tribunal de première instance de Ouarzazate — section de la famille","object":"Reconnaissance d'un mariage non documenté après le décès de l'époux, et droits successoraux.","you":"Avocat de la veuve (Mme Aït Brahim)","adverseName":"Avocat des héritiers","facts":"Mme Aït Brahim a épousé M. Aït Lahcen en 2014 par la Fatiha, devant la famille, dans un douar enclavé, sans acte adoulaire. Le couple a eu deux enfants, inscrits à l'état civil. M. Aït Lahcen est décédé en 2025. Ses frères refusent à la veuve toute part de succession, faute d'acte de mariage.","rounds":[{"name":"L'absence d'acte","adverse":"Monsieur le Président, le mariage se prouve par l'acte de mariage. Il n'y en a pas : il n'y a donc pas de mariage, et pas d'épouse héritière.","prompt":"Répondez sur la preuve du mariage.","options":[{"label":"Action en reconnaissance de mariage","detail":"Raisons impérieuses : le tribunal admet tous moyens de preuve et l'expertise (art. 16).","pts":18,"speech":"L'acte est le moyen de preuve ordinaire, mais l'article 16 du Code de la famille prévoit que, lorsque des raisons impérieuses ont empêché de l'établir en temps voulu, le tribunal admet, dans l'action en reconnaissance de mariage, tous les moyens de preuve ainsi que l'expertise, en tenant compte notamment de l'existence d'enfants. Un douar enclavé, sans adoul, et deux enfants nés de l'union : toutes les conditions sont réunies.","ok":["Cite l'article 16","Caractérise les raisons impérieuses","Mentionne les enfants"],"ko":[]},{"label":"Invoquer la coutume","detail":"Soutenir que le mariage par la Fatiha suffit selon la coutume.","pts":7,"speech":"Dans notre région, la Fatiha devant la famille vaut mariage ; c'est la coutume.","ok":["Contexte réel"],"ko":["La coutume ne remplace pas la procédure de reconnaissance","Aucun article"]}],"concepts":[{"label":"Raisons impérieuses","re":"raisons? imperieu|enclav|pas d.adoul|empech","pts":5,"key":true},{"label":"Tous moyens de preuve / expertise","re":"tous (les )?moyens|expertise|temoin|lafif","pts":4},{"label":"Existence d'enfants","re":"enfants?","pts":3}],"articles":[{"code":"CF","article":"16","label":"Art. 16 CF (reconnaissance de mariage)","pts":5}],"faille":"La demanderesse n'explique pas pourquoi aucun acte n'a été dressé pendant onze ans.","concede":"Les raisons impérieuses peuvent exister, admettons. Encore faut-il prouver le mariage lui-même."},{"name":"La preuve du mariage","adverse":"Les héritiers contestent toute union : la demanderesse n'était qu'une proche qui aidait leur frère.","prompt":"Apportez la preuve du mariage.","options":[{"label":"Faisceau de preuves","detail":"Témoins de la Fatiha (lafif), vie commune, enfants inscrits sous le nom du père, photos.","pts":17,"speech":"Nous produisons un acte de lafif de douze témoins présents à la Fatiha de 2014, des photographies de la cérémonie, et surtout les actes de naissance des deux enfants, déclarés par le défunt lui-même sous son nom. On ne déclare pas comme siens les enfants d'une simple aide familiale. L'article 16 commande de tenir compte des enfants : leur filiation, reconnue par le défunt, confirme l'union.","ok":["Preuves variées et concordantes","Utilise la déclaration des enfants par le défunt"],"ko":["Ne demande pas l'audition des témoins à l'audience"]},{"label":"Se reposer sur la bonne foi","detail":"Affirmer la sincérité de la veuve.","pts":6,"speech":"Ma cliente est de bonne foi ; elle a partagé onze ans de la vie du défunt.","ok":["Contexte humain"],"ko":["Aucune pièce"]}],"concepts":[{"label":"Témoins / acte de lafif","re":"lafif|temoin|douze","pts":5,"key":true},{"label":"Enfants déclarés par le défunt","re":"acte de naissance|etat civil|declar|enfants","pts":5},{"label":"Vie commune / photos","re":"vie commune|photo|ceremonie","pts":3}],"articles":[{"code":"CF","article":"16","label":"Art. 16 CF (tous moyens de preuve)","pts":4}],"faille":"Aucune preuve sérieuse de l'union n'est versée.","concede":"Les témoignages sont nombreux, je l'admets ; leur sincérité reste à vérifier."},{"name":"Les droits successoraux","adverse":"Même reconnue, l'épouse ne saurait recevoir qu'une part symbolique, la maison relevant du patrimoine familial des frères.","prompt":"Plaidez sur la part de la veuve.","options":[{"label":"Le huitième de la succession","detail":"Avec une descendance, l'épouse reçoit le huitième (art. 344) ; les enfants héritent avant les frères.","pts":18,"speech":"Une fois le mariage reconnu, la loi fixe les parts. L'article 344 du Code de la famille attribue à l'épouse le huitième de la succession lorsque l'époux laisse une descendance ayant vocation successorale, ce qui est le cas. La maison appartenait au défunt : elle entre dans la succession, et les enfants, héritiers, priment d'ailleurs les frères.","ok":["Cite l'article 344 (huitième)","Relève la présence de descendants"],"ko":[]},{"label":"Demander la moitié","detail":"Réclamer la moitié des biens au titre de l'effort commun.","pts":8,"speech":"Ma cliente a contribué à l'enrichissement du foyer et réclame la moitié des biens.","ok":["Pense à la contribution (art. 49)"],"ko":["Aucune preuve de contribution","Confond partage des acquêts et succession"]}],"concepts":[{"label":"Le huitième pour l'épouse","re":"huitieme|1/8|un huitieme","pts":6,"key":true},{"label":"Présence de descendants","re":"descendan|enfants","pts":4},{"label":"La maison entre dans la succession","re":"succession|masse|appartenait","pts":3}],"articles":[{"code":"CF","article":"344","label":"Art. 344 CF (huitième de l'épouse)","pts":4}],"faille":"Rien n'est chiffré : le tribunal n'accordera qu'une part symbolique.","concede":"La part du huitième est légale, soit. Les frères contestent encore la consistance de la succession."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que des raisons impérieuses ont empêché l'établissement de l'acte et que le mariage est établi par le lafif, la vie commune et la déclaration des enfants par le défunt (article 16) ; Par ces motifs : reconnaît le mariage depuis 2014 et dit que la veuve a droit au huitième de la succession (article 344)."},{"min":45,"text":"Le Tribunal, attendu l'existence d'enfants et de témoignages concordants ; Par ces motifs : reconnaît le mariage et renvoie les parties au partage successoral."},{"min":0,"text":"Le Tribunal, attendu que la preuve du mariage n'est pas suffisamment rapportée ; Par ces motifs : ordonne une enquête par audition des témoins avant dire droit."}]},{"id":"taxation-office","matiere":"fiscal","title":"Société Kech Déco c/ Administration fiscale","court":"Tribunal administratif de Marrakech","object":"Contestation d'une taxation d'office à l'IS pour défaut de déclaration.","you":"Avocat de la société (Kech Déco SARL)","adverseName":"Représentant de l'administration fiscale","facts":"Kech Déco SARL n'a pas déposé sa déclaration de résultat fiscal 2022 dans le délai. L'administration affirme avoir adressé une lettre l'invitant à régulariser sous trente jours, puis l'a taxée d'office sur une base de 1,8 million de DH, avec la majoration maximale. La société a changé de siège en 2022 et l'avait déclaré au registre du commerce et à l'administration ; la lettre a été envoyée à l'ancienne adresse.","rounds":[{"name":"La régularité de la procédure","adverse":"Monsieur le Président, la société n'a pas déposé sa déclaration. La loi permet alors la taxation d'office ; l'administration a envoyé la lettre de régularisation, la procédure est régulière.","prompt":"Contestez la régularité de la procédure.","options":[{"label":"Notification irrégulière","detail":"La lettre préalable doit être notifiée à l'adresse déclarée (art. 219) ; sans notification valable, la taxation d'office (art. 228) est irrégulière.","pts":18,"speech":"La taxation d'office de l'article 228 du Code général des impôts suppose une lettre préalable invitant le contribuable à régulariser dans les trente jours. Cette lettre doit être notifiée, selon l'article 219, à l'adresse que le contribuable a indiquée dans ses déclarations et correspondances. La société avait déclaré son nouveau siège ; la lettre est partie à l'ancienne adresse. Faute de notification valable, le délai n'a jamais couru et la taxation d'office est irrégulière.","ok":["Cite les articles 219 et 228","Démontre la déclaration du nouveau siège","Tire la conséquence : délai jamais couru"],"ko":[]},{"label":"Plaider la bonne foi","detail":"Expliquer le retard par des difficultés internes.","pts":6,"speech":"La société a connu un changement de comptable ; le retard n'était pas volontaire.","ok":["Explique le contexte"],"ko":["La bonne foi n'efface pas le défaut de déclaration","Ignore le vice de notification"]}],"concepts":[{"label":"Notification à la mauvaise adresse","re":"notifi|ancienne adresse|adresse declar|siege","pts":6,"key":true},{"label":"Lettre préalable / délai de trente jours","re":"lettre|trente jours|30 jours|regularis","pts":4},{"label":"Taxation d'office irrégulière","re":"irreguli|nullit|vice de procedure","pts":3}],"articles":[{"code":"CGI","article":"228","label":"Art. 228 CGI (taxation d'office)","pts":3},{"code":"CGI","article":"219","label":"Art. 219 CGI (formes de notification)","pts":4}],"faille":"La société ne conteste pas le défaut de déclaration : la taxation d'office est fondée.","concede":"La notification est discutable, admettons. La société n'a pas davantage déclaré depuis."},{"name":"La base imposée","adverse":"En l'absence de déclaration, l'administration a reconstitué une base de 1,8 million de Dirhams à partir des données disponibles. C'est à la société de prouver le contraire.","prompt":"Contestez la base retenue.","options":[{"label":"Produire la comptabilité","detail":"Déposer la déclaration et la comptabilité : bénéfice réel de 240 000 DH ; la base ne peut être arbitraire.","pts":16,"speech":"La société produit aujourd'hui sa déclaration et sa comptabilité 2022, certifiées par son expert-comptable : le bénéfice réel s'élève à 240 000 Dirhams. L'administration ne dit pas d'où provient le chiffre de 1,8 million. Une base reconstituée doit reposer sur des éléments vérifiables, non sur une estimation arbitraire.","ok":["Apporte la preuve contraire","Exige la méthode de reconstitution"],"ko":["La production tardive peut être discutée"]},{"label":"Demander une expertise","detail":"Solliciter une expertise comptable judiciaire.","pts":10,"speech":"La société sollicite une expertise comptable pour déterminer la base réelle.","ok":["Démarche sérieuse"],"ko":["Ne produit pas ses propres chiffres"]}],"concepts":[{"label":"Base arbitraire ou non justifiée","re":"arbitraire|estim|methode|d.ou provient|justifi","pts":5,"key":true},{"label":"Production de la comptabilité","re":"comptabilit|bilan|declaration|expert-comptable","pts":5},{"label":"Bénéfice réel chiffré","re":"240 000|benefice reel","pts":3}],"articles":[{"code":"CGI","article":"228","label":"Art. 228 CGI","pts":2}],"faille":"La société n'apporte aucun chiffre : la base de l'administration demeure.","concede":"La comptabilité est produite, soit ; elle l'est bien tard."},{"name":"La majoration","adverse":"Enfin, la majoration maximale est appliquée de plein droit au contribuable défaillant.","prompt":"Plaidez sur les sanctions.","options":[{"label":"Proportionner la majoration","detail":"L'article 184 prévoit des taux de 5, 15 et 20 % selon la situation : le taux maximal ne s'applique pas automatiquement.","pts":15,"speech":"L'article 184 du Code général des impôts prévoit des majorations de 5 %, 15 % et 20 %, graduées selon la durée du retard et la situation du contribuable. Le taux maximal n'est pas automatique. La procédure de taxation d'office étant irrégulière, la majoration qui en découle tombe avec elle ; subsidiairement, seul le taux correspondant au retard réel peut s'appliquer.","ok":["Cite l'article 184","Lie la sanction à la procédure","Conclusion subsidiaire"],"ko":[]},{"label":"Demander une remise gracieuse","detail":"Solliciter l'indulgence du tribunal.","pts":6,"speech":"La société demande au tribunal de réduire les pénalités par équité.","ok":["Ton conciliant"],"ko":["Le juge ne statue pas en équité sur les pénalités","Aucun texte"]}],"concepts":[{"label":"Taux gradués","re":"5 ?%|15 ?%|20 ?%|gradu|taux","pts":5,"key":true},{"label":"Pas d'automatisme du maximum","re":"automati|maximal|maximum|plein droit","pts":4},{"label":"La sanction tombe avec la procédure","re":"tombe|consequence|irreguli|nullit","pts":3}],"articles":[{"code":"CGI","article":"184","label":"Art. 184 CGI (majorations)","pts":4}],"faille":"La société ne conteste pas le taux : il sera maintenu.","concede":"La gradation des taux existe, je le reconnais."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la lettre préalable n'a pas été notifiée à l'adresse déclarée par le contribuable (articles 219 et 228) ; Par ces motifs : annule la taxation d'office et les majorations y afférentes."},{"min":45,"text":"Le Tribunal, attendu que la base reconstituée n'est pas justifiée face à la comptabilité produite ; Par ces motifs : réduit l'imposition à la base déclarée et applique la majoration de 5 %."},{"min":0,"text":"Le Tribunal, attendu le défaut de déclaration non contesté ; Par ces motifs : rejette le recours et maintient l'imposition."}]},{"id":"prescription-fiscale","matiere":"fiscal","title":"M. Lazrak c/ Administration fiscale","court":"Tribunal administratif de Rabat","object":"Prescription d'un redressement à l'IR notifié pour l'exercice 2020.","you":"Avocat du contribuable (M. Lazrak)","adverseName":"Représentant de l'administration fiscale","facts":"M. Lazrak, médecin, a fait l'objet d'une vérification de comptabilité portant sur 2020. L'avis de vérification lui a été remis en novembre 2024. La première lettre de notification des redressements, portant sur 2020, ne lui a été notifiée que le 12 février 2025. L'administration réclame 310 000 DH de droits et pénalités.","rounds":[{"name":"Le délai de prescription","adverse":"Monsieur le Président, l'administration a engagé le contrôle en 2024, dans le délai. Le redressement est donc recevable.","prompt":"Soulevez la prescription.","options":[{"label":"Quatre ans à compter de l'exercice","detail":"Réparation possible jusqu'au 31 décembre de la quatrième année suivant l'exercice (art. 232) : 31/12/2024 pour 2020.","pts":18,"speech":"L'article 232 du Code général des impôts permet à l'administration de réparer les insuffisances jusqu'au 31 décembre de la quatrième année suivant celle de l'exercice concerné. Pour l'exercice 2020, ce délai a expiré le 31 décembre 2024. La notification des redressements du 12 février 2025 est intervenue après l'expiration du délai : le droit de reprise était éteint.","ok":["Cite l'article 232","Calcule l'échéance exacte","Compare avec la date de notification"],"ko":[]},{"label":"Contester le contrôle","detail":"Dénoncer la durée excessive de la vérification.","pts":7,"speech":"La vérification a duré bien plus que nécessaire et a désorganisé le cabinet.","ok":["Grief réel"],"ko":["Passe à côté de la prescription, moyen décisif"]}],"concepts":[{"label":"Échéance du 31 décembre de la 4e année","re":"31 decembre|quatrieme annee|4e annee|quatre ans|4 ans","pts":6,"key":true},{"label":"Exercice 2020 prescrit fin 2024","re":"2020|2024","pts":4},{"label":"Notification tardive (2025)","re":"2025|fevrier|tardi|apres","pts":3}],"articles":[{"code":"CGI","article":"232","label":"Art. 232 CGI (prescription)","pts":5}],"faille":"Le contribuable ne soulève pas la prescription : le redressement est recevable.","concede":"Le délai de quatre ans est exact. Mais l'avis de vérification l'a interrompu."},{"name":"L'interruption invoquée","adverse":"L'avis de vérification remis en novembre 2024 a interrompu la prescription : l'administration a manifesté sa volonté de contrôler avant l'échéance.","prompt":"Répondez sur l'interruption.","options":[{"label":"Seule la notification interrompt","detail":"C'est la notification des redressements, non l'avis de vérification, qui interrompt la prescription.","pts":16,"speech":"L'avis de vérification annonce un contrôle ; il ne notifie aucun redressement. La prescription est interrompue par la notification des redressements au contribuable, qui seule lui fait connaître les montants et motifs. Celle-ci date du 12 février 2025, après l'expiration du délai. Admettre l'inverse permettrait à l'administration de prolonger indéfiniment son droit de reprise par un simple avis.","ok":["Distingue avis de vérification et notification","Argument de sécurité juridique"],"ko":["Ne cite pas précisément le paragraphe de l'article 232"]},{"label":"Contester la remise de l'avis","detail":"Soutenir que l'avis n'a pas été reçu.","pts":8,"speech":"Mon client conteste avoir reçu l'avis de vérification en novembre.","ok":["Argument possible"],"ko":["Contredit les pièces","Même reçu, l'avis n'interrompt pas"]}],"concepts":[{"label":"La notification des redressements interrompt","re":"notification|notifi","pts":5,"key":true},{"label":"L'avis de vérification n'interrompt pas","re":"avis de verification|annonce|n.interrompt pas","pts":5},{"label":"Sécurité juridique","re":"securite|indefini|prolong","pts":3}],"articles":[{"code":"CGI","article":"232","label":"Art. 232 CGI","pts":3},{"code":"CGI","article":"220","label":"Art. 220 CGI (procédure de rectification)","pts":2}],"faille":"Le contribuable admet l'avis de 2024 : la prescription a été interrompue.","concede":"La distinction est juste, mais le contrôle était engagé."},{"name":"Les pénalités","adverse":"Subsidiairement, même si les droits étaient prescrits, les pénalités pour dissimulation restent dues.","prompt":"Plaidez sur le sort des pénalités.","options":[{"label":"L'accessoire suit le principal","detail":"Les pénalités sont l'accessoire des droits : la prescription des droits emporte celle des pénalités.","pts":15,"speech":"Les pénalités et majorations n'existent qu'en raison des droits qu'elles sanctionnent. Lorsque le droit de reprise est éteint par la prescription de l'article 232, les droits ne peuvent plus être établis et les pénalités, accessoires, tombent avec eux. L'administration ne justifie d'ailleurs d'aucune dissimulation établie.","ok":["Principe de l'accessoire","Conteste la dissimulation"],"ko":[]},{"label":"Négocier les pénalités","detail":"Proposer de payer la moitié des pénalités.","pts":5,"speech":"Mon client accepterait de payer la moitié des pénalités pour clore le dossier.","ok":["Pragmatique"],"ko":["Abandonne un moyen décisif"]}],"concepts":[{"label":"Accessoire du principal","re":"accessoire|suit le principal|tombent","pts":5,"key":true},{"label":"Droits prescrits","re":"prescri|eteint","pts":4},{"label":"Pas de dissimulation prouvée","re":"dissimul|aucune preuve","pts":3}],"articles":[{"code":"CGI","article":"232","label":"Art. 232 CGI","pts":3}],"faille":"Rien n'est dit des pénalités : elles restent dues.","concede":"Les pénalités suivent les droits, je l'admets."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le droit de reprise au titre de l'exercice 2020 expirait le 31 décembre 2024 et que la notification des redressements n'est intervenue qu'en février 2025 (article 232) ; Par ces motifs : constate la prescription et annule l'imposition, droits et pénalités."},{"min":45,"text":"Le Tribunal, attendu que la prescription paraît acquise pour une partie des chefs de redressement ; Par ces motifs : annule les droits et ordonne le dégrèvement partiel des pénalités."},{"min":0,"text":"Le Tribunal, attendu que le contribuable n'a pas établi l'expiration du délai de reprise ; Par ces motifs : rejette le recours."}]},{"id":"factures-tva","matiere":"fiscal","title":"Société Atlas BTP c/ Administration fiscale","court":"Tribunal administratif de Casablanca","object":"Rejet de la déduction de TVA sur des factures d'un fournisseur jugé fictif.","you":"Avocat de la société (Atlas BTP SA)","adverseName":"Représentant de l'administration fiscale","facts":"L'administration a rejeté la déduction de 420 000 DH de TVA figurant sur les factures d'un fournisseur de ciment, Sud Matériaux, au motif que celui-ci est introuvable à son adresse et ne dépose pas ses déclarations. Atlas BTP a payé toutes les factures par virement bancaire, détient les bons de livraison signés par ses chefs de chantier et les marchandises ont été utilisées sur deux chantiers publics.","rounds":[{"name":"Le fournisseur introuvable","adverse":"Monsieur le Président, Sud Matériaux est une société fantôme : pas de local, pas de déclarations. Ses factures sont fictives et la TVA qu'elles mentionnent n'est pas déductible.","prompt":"Défendez le droit à déduction.","options":[{"label":"Réalité des achats","detail":"Achats réellement réalisés et justifiés par facture régulière (art. 146) : virements, bons de livraison, utilisation sur chantier.","pts":18,"speech":"L'article 146 du Code général des impôts exige que l'achat soit réellement réalisé et justifié par une facture régulière et probante. Les deux conditions sont remplies : chaque facture a été payée par virement bancaire traçable, les livraisons sont attestées par des bons signés sur chantier, et le ciment a été incorporé dans deux ouvrages publics réceptionnés. Les défaillances déclaratives du fournisseur lui sont propres ; elles ne rendent pas fictif un achat réel.","ok":["Cite l'article 146","Faisceau de preuves de réalité","Distingue fautes du fournisseur et du client"],"ko":[]},{"label":"Rejeter la faute sur l'État","detail":"Reprocher à l'administration de ne pas contrôler les fournisseurs.","pts":6,"speech":"C'est à l'administration de surveiller les fournisseurs, pas à mon client.","ok":["Pointe une réalité"],"ko":["Ne prouve pas la réalité des achats"]}],"concepts":[{"label":"Achat réellement réalisé","re":"reellement|realite|effecti|reel","pts":6,"key":true},{"label":"Paiement traçable","re":"virement|banc|tracab|cheque","pts":4},{"label":"Livraisons et utilisation sur chantier","re":"bons? de livraison|chantier|incorpor|utilis","pts":4}],"articles":[{"code":"CGI","article":"146","label":"Art. 146 CGI (pièces justificatives)","pts":5}],"faille":"La société n'apporte rien sur la réalité des achats : la fictivité est présumée.","concede":"Les virements existent, je l'admets. Mais la facture d'une société sans existence n'est pas régulière."},{"name":"La régularité des factures","adverse":"Une facture émanant d'une société qui n'exerce pas à son adresse n'est pas une facture régulière et probante.","prompt":"Répondez sur la régularité formelle.","options":[{"label":"Mentions légales présentes","detail":"Les factures portent identifiant fiscal, ICE, mentions obligatoires ; au jour des achats, le fournisseur était immatriculé et actif.","pts":16,"speech":"Les factures comportent toutes les mentions exigées : identifiant fiscal, identifiant commun de l'entreprise, numéro de registre du commerce, détail des quantités et des prix, TVA distincte. Au moment des achats, Sud Matériaux était immatriculée et figurait comme active. La société a vérifié ce qui pouvait l'être ; la disparition ultérieure du fournisseur ne rend pas rétroactivement irrégulières des factures conformes.","ok":["Vérifie les mentions obligatoires","Situe l'appréciation au jour des achats"],"ko":["Ne produit pas l'attestation de régularité fiscale du fournisseur"]},{"label":"Admettre l'irrégularité","detail":"Reconnaître des factures imparfaites et demander l'indulgence.","pts":5,"speech":"Les factures sont peut-être imparfaites, mais la société était de bonne foi.","ok":["Franchise"],"ko":["Concède le cœur du litige"]}],"concepts":[{"label":"Mentions obligatoires présentes","re":"mention|identifiant|ice|registre","pts":5,"key":true},{"label":"Appréciation au jour de l'achat","re":"au (jour|moment)|a l.epoque|immatricul|actif","pts":4},{"label":"Diligence du client","re":"verifi|diligence|bonne foi","pts":3}],"articles":[{"code":"CGI","article":"146","label":"Art. 146 CGI","pts":2},{"code":"CGI","article":"101","label":"Art. 101 CGI (droit à déduction)","pts":3}],"faille":"La société ne démontre pas la régularité des factures.","concede":"Les mentions sont présentes, soit."},{"name":"Le pouvoir d'appréciation de l'administration","adverse":"L'administration a le pouvoir de rectifier lorsqu'elle constate des irrégularités : elle a usé de ce pouvoir.","prompt":"Plaidez sur les limites de ce pouvoir.","options":[{"label":"Irrégularités graves exigées","detail":"L'article 213 suppose des irrégularités graves mettant en cause la comptabilité ; ici, comptabilité probante.","pts":15,"speech":"Le pouvoir d'appréciation de l'article 213 suppose des irrégularités graves de nature à mettre en cause la valeur probante de la comptabilité. La comptabilité d'Atlas BTP, certifiée par son commissaire aux comptes, n'est pas remise en cause dans son ensemble ; seul un fournisseur est visé. Le rejet de la déduction doit donc être prouvé par l'administration, ce qu'elle ne fait pas.","ok":["Cite l'article 213","Comptabilité certifiée","Charge de la preuve sur l'administration"],"ko":[]},{"label":"Demander une transaction","detail":"Proposer de payer 50 % du rappel.","pts":6,"speech":"Atlas BTP propose de régler la moitié du rappel pour solder le litige.","ok":["Pragmatique"],"ko":["Abandon de droits sans contrepartie juridique"]}],"concepts":[{"label":"Irrégularités graves exigées","re":"irregularites? graves?|valeur probante","pts":5,"key":true},{"label":"Comptabilité certifiée","re":"certifi|commissaire aux comptes","pts":4},{"label":"Charge de la preuve sur l'administration","re":"charge de la preuve|a l.administration de prouver|prouver","pts":3}],"articles":[{"code":"CGI","article":"213","label":"Art. 213 CGI (pouvoir d'appréciation)","pts":4}],"faille":"La société n'a rien opposé : le rejet est fondé.","concede":"La comptabilité est certifiée, c'est un fait."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la réalité des achats est établie par les paiements bancaires, les bons de livraison et l'incorporation des matériaux dans les ouvrages, et que les factures comportent les mentions requises (articles 101 et 146) ; Par ces motifs : annule le rappel de TVA."},{"min":45,"text":"Le Tribunal, attendu que la réalité d'une partie des livraisons est établie ; Par ces motifs : réduit le rappel de moitié."},{"min":0,"text":"Le Tribunal, attendu que la société n'a pas établi la réalité des opérations facturées ; Par ces motifs : rejette le recours."}]},{"id":"copropriete","matiere":"civil","title":"Syndicat de la résidence Al Manar c/ M. Benkirane","court":"Tribunal de première instance de Casablanca","object":"Recouvrement de charges de copropriété impayées (38 000 DH).","you":"Avocat du syndicat des copropriétaires","adverseName":"Avocat de M. Benkirane","facts":"M. Benkirane, propriétaire d'un local au rez-de-chaussée de la résidence Al Manar, refuse depuis trois ans de payer sa quote-part des charges (ascenseur, gardiennage, nettoyage), soit 38 000 DH. Il soutient qu'il n'utilise pas l'ascenseur. Le règlement de copropriété répartit les charges selon les tantièmes, sans exception. Une mise en demeure lui a été adressée.","rounds":[{"name":"L'obligation de contribuer","adverse":"Monsieur le Président, mon client n'utilise ni l'ascenseur ni les étages. Il n'a pas à payer pour un service dont il ne profite pas.","prompt":"Établissez l'obligation de payer les charges.","options":[{"label":"Obligation légale de participation","detail":"Chaque copropriétaire participe aux charges des parties communes (art. 36 loi 18-00), selon le règlement.","pts":17,"speech":"L'article 36 de la loi 18-00 sur la copropriété impose à chaque copropriétaire de participer aux charges de conservation, d'entretien et de gestion des parties communes. Le règlement de copropriété, qui s'impose à tous, répartit ces charges selon les tantièmes, sans exception pour le rez-de-chaussée. M. Benkirane a acquis son local en connaissance de ce règlement.","ok":["Cite l'article 36","S'appuie sur le règlement de copropriété"],"ko":["Ne distingue pas les catégories de charges"]},{"label":"Menacer de couper les services","detail":"Annoncer la suspension de l'accès aux parties communes.","pts":4,"speech":"Si M. Benkirane ne paie pas, le syndicat lui interdira l'accès aux parties communes.","ok":["Pression"],"ko":["Voie de fait illégale","Aucun fondement"]}],"concepts":[{"label":"Obligation de participer aux charges","re":"particip|contribu|obligation|charges","pts":6,"key":true},{"label":"Parties communes","re":"parties communes","pts":3},{"label":"Règlement de copropriété / tantièmes","re":"reglement|tantiem|quote-part","pts":4}],"articles":[{"code":"d0459","article":"36","label":"Art. 36 loi 18-00 (participation aux charges)","pts":5}],"faille":"Le syndicat ne justifie pas que mon client profite des services facturés.","concede":"Le principe de participation est clair. Mais la répartition est inéquitable."},{"name":"La répartition contestée","adverse":"La répartition actuelle est injuste : un local en rez-de-chaussée ne devrait pas payer l'ascenseur. Mon client demande qu'elle soit revue.","prompt":"Répondez sur la modification de la répartition.","options":[{"label":"Seule l'AG ou le tribunal modifie","detail":"La répartition ne peut être changée que par l'assemblée générale ou, à défaut, par le tribunal (art. 37) ; en attendant, elle s'applique.","pts":16,"speech":"L'article 37 de la loi 18-00 dispose que la modification de la répartition des charges ne peut être décidée que par l'assemblée générale ou, à défaut, fixée par le tribunal à la demande d'un copropriétaire. M. Benkirane n'a jamais saisi l'assemblée ni introduit cette demande. Tant que la répartition n'est pas modifiée, elle s'applique : on ne se fait pas justice soi-même en cessant de payer.","ok":["Cite l'article 37","Pas d'auto-réduction des charges"],"ko":["N'envisage pas une concession sur l'ascenseur"]},{"label":"Reconnaître l'injustice","detail":"Admettre que l'ascenseur ne le concerne pas.","pts":7,"speech":"Le syndicat veut bien reconnaître que l'ascenseur ne profite pas au rez-de-chaussée.","ok":["Bonne foi"],"ko":["Fragilise la créance sans décision de l'AG"]}],"concepts":[{"label":"Modification par l'AG ou le tribunal","re":"assemblee|tribunal|modifi","pts":6,"key":true},{"label":"Pas d'auto-réduction","re":"justice (soi-meme|lui-meme)|cesser de payer|unilateral","pts":4},{"label":"Règlement en vigueur","re":"en vigueur|s.applique|tant que","pts":3}],"articles":[{"code":"d0459","article":"37","label":"Art. 37 loi 18-00 (modification de la répartition)","pts":5}],"faille":"Le syndicat ne répond pas sur l'iniquité de la répartition.","concede":"La procédure de modification existe, soit."},{"name":"Le montant et les intérêts","adverse":"Le syndicat réclame aussi des dommages pour retard, alors qu'il ne prouve aucun préjudice.","prompt":"Plaidez sur la créance et le retard.","options":[{"label":"Créance certaine et dommages pour retard","detail":"Relevés de charges, procès-verbaux d'AG, mise en demeure ; dommages dus pour retard (art. 263 DOC).","pts":16,"speech":"La créance est certaine : budgets votés en assemblée générale, appels de charges et relevés sur trois ans, mise en demeure restée sans effet. L'article 263 du DOC accorde des dommages-intérêts en raison du retard dans l'exécution. Le retard de trois ans a contraint le syndicat à différer l'entretien de l'immeuble.","ok":["Pièces de la créance","Cite l'article 263 DOC","Préjudice concret"],"ko":[]},{"label":"Renoncer aux dommages","detail":"Ne demander que le principal.","pts":9,"speech":"Le syndicat se limite aux 38 000 Dirhams de charges.","ok":["Simplicité"],"ko":["Renonce à un droit"]}],"concepts":[{"label":"Créance justifiée par pièces","re":"proces-verbal|budget|releve|appel de charges|mise en demeure","pts":5,"key":true},{"label":"Dommages pour retard","re":"retard|dommages","pts":4},{"label":"Préjudice du syndicat","re":"entretien|prejudice|differ","pts":3}],"articles":[{"code":"DOC","article":"263","label":"Art. 263 DOC (dommages pour retard)","pts":3}],"faille":"Les pièces ne sont pas produites : la créance n'est pas certaine.","concede":"La créance est justifiée, je l'admets."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que chaque copropriétaire participe aux charges des parties communes et que la répartition n'a pas été modifiée selon l'article 37 ; Par ces motifs : condamne M. Benkirane à payer 38 000 Dirhams et 3 000 Dirhams de dommages pour retard."},{"min":45,"text":"Le Tribunal, attendu l'obligation de participer aux charges ; Par ces motifs : condamne M. Benkirane à payer 38 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu que le syndicat ne justifie pas suffisamment du détail de sa créance ; Par ces motifs : ordonne une expertise comptable avant dire droit."}]},{"id":"morsure-chien","matiere":"civil","title":"M. Haddaoui c/ M. Sbai","court":"Tribunal de première instance d'Agadir","object":"Responsabilité du gardien d'un chien ayant mordu un livreur.","you":"Avocat de la victime (M. Haddaoui)","adverseName":"Avocat de M. Sbai","facts":"M. Haddaoui, livreur, a été mordu à la jambe par le chien de M. Sbai, sorti par le portail laissé entrouvert de la villa. Il a subi 25 jours d'incapacité de travail, perdu un mois de revenus (6 000 DH) et engagé 4 500 DH de frais médicaux. M. Sbai soutient que le livreur a provoqué l'animal en sonnant avec insistance.","rounds":[{"name":"Le fondement de la responsabilité","adverse":"Monsieur le Président, mon client n'a commis aucune faute : il était absent, et le chien n'a jamais mordu personne. Sans faute, pas de responsabilité.","prompt":"Fondez la responsabilité du propriétaire.","options":[{"label":"Responsabilité du gardien de l'animal","detail":"Le gardien répond du dommage causé par l'animal, même échappé, sauf preuve des précautions ou d'une cause étrangère (art. 86 DOC).","pts":18,"speech":"L'article 86 du DOC rend chacun responsable du dommage causé par l'animal qu'il a sous sa garde, même si celui-ci s'est échappé, à moins qu'il ne prouve avoir pris les précautions nécessaires ou que le dommage provient d'un cas fortuit, d'une force majeure ou de la faute de la victime. Ma cliente n'a pas à prouver une faute : c'est au gardien de s'exonérer. Or le portail était entrouvert.","ok":["Cite l'article 86 DOC","Renverse la charge de la preuve","Relève le portail ouvert"],"ko":[]},{"label":"Prouver la faute","detail":"Démontrer la négligence du propriétaire (art. 78).","pts":10,"speech":"Le propriétaire a commis une négligence en laissant le portail ouvert, faute au sens de l'article 78.","ok":["Raisonnement juste"],"ko":["S'impose une preuve inutile : l'article 86 est plus favorable"]}],"concepts":[{"label":"Responsabilité du gardien de l'animal","re":"gardien|garde|animal|chien","pts":6,"key":true},{"label":"Pas besoin de prouver une faute","re":"sans faute|pas (a|besoin de) prouver|presum","pts":4},{"label":"Animal échappé / portail ouvert","re":"echapp|portail|entrouvert|ouvert","pts":3}],"articles":[{"code":"DOC","article":"86","label":"Art. 86 DOC (fait des animaux)","pts":5}],"faille":"La victime ne prouve aucune faute de mon client.","concede":"La responsabilité du gardien est présumée, soit. Mais la victime a provoqué l'animal."},{"name":"La faute de la victime","adverse":"Le livreur a sonné de longues minutes et frappé sur le portail : il a excité le chien. Sa faute exonère mon client.","prompt":"Répondez à l'exonération invoquée.","options":[{"label":"Pas de faute de la victime","detail":"Sonner est le comportement normal d'un livreur ; aucune preuve de provocation ; le portail ouvert reste la cause.","pts":16,"speech":"Sonner à la porte est exactement ce qu'on attend d'un livreur. Aucun témoin, aucune pièce ne démontre une provocation. Pour exonérer le gardien, la faute de la victime doit être prouvée et être la cause du dommage : ici, la cause est le portail laissé ouvert, sans laquelle le chien n'aurait jamais atteint la rue.","ok":["Comportement normal de la victime","Exige la preuve de la faute","Causalité"],"ko":["Ne produit pas de témoin de la scène"]},{"label":"Admettre un partage","detail":"Accepter un partage de responsabilité de moitié.","pts":6,"speech":"La victime veut bien admettre un partage de responsabilité.","ok":["Esprit de conciliation"],"ko":["Divise l'indemnité sans raison"]}],"concepts":[{"label":"Comportement normal de la victime","re":"normal|sonner|livreur|metier","pts":5,"key":true},{"label":"Preuve de la provocation absente","re":"aucune preuve|aucun temoin|prouv","pts":4},{"label":"Causalité : le portail ouvert","re":"cause|causal|portail","pts":3}],"articles":[{"code":"DOC","article":"86","label":"Art. 86 DOC (exonération)","pts":3}],"faille":"La victime ne conteste pas avoir insisté : la faute est établie.","concede":"La provocation n'est pas prouvée, je le reconnais."},{"name":"L'évaluation du préjudice","adverse":"La victime réclame 60 000 Dirhams pour une simple morsure. C'est sans commune mesure.","prompt":"Chiffrez le préjudice.","options":[{"label":"Préjudice détaillé","detail":"Pertes effectives, frais, gains manqués et préjudice moral (art. 98 DOC).","pts":17,"speech":"L'article 98 du DOC répare la perte effective, les dépenses nécessaires et les gains manqués. Nous justifions 4 500 Dirhams de frais médicaux, 6 000 Dirhams de revenus perdus pendant 25 jours d'incapacité, auxquels s'ajoutent les souffrances endurées et la cicatrice, évaluées à 20 000 Dirhams. Total : 30 500 Dirhams, chaque poste étant justifié.","ok":["Cite l'article 98 DOC","Poste par poste","Justificatifs"],"ko":[]},{"label":"Maintenir 60 000 DH","detail":"Insister sur le traumatisme.","pts":7,"speech":"Le traumatisme justifie pleinement les 60 000 Dirhams.","ok":["Ferme"],"ko":["Montant non décomposé"]}],"concepts":[{"label":"Préjudice décomposé par postes","re":"frais|revenus?|gains?|perte","pts":5,"key":true},{"label":"Préjudice moral / souffrances","re":"moral|souffran|cicatrice|douleur","pts":4},{"label":"Justificatifs","re":"justifi|certificat|factur","pts":3}],"articles":[{"code":"DOC","article":"98","label":"Art. 98 DOC (évaluation du dommage)","pts":4}],"faille":"Le montant n'est pas justifié : il sera réduit.","concede":"Les frais sont justifiés ; le préjudice moral reste à apprécier."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le gardien de l'animal répond du dommage causé et ne justifie ni de précautions suffisantes ni d'une faute de la victime (article 86 DOC) ; Par ces motifs : condamne M. Sbai à verser 30 500 Dirhams à M. Haddaoui."},{"min":45,"text":"Le Tribunal, attendu la responsabilité du gardien ; Par ces motifs : condamne M. Sbai à verser 15 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu un partage de responsabilité ; Par ces motifs : condamne M. Sbai à verser 5 000 Dirhams."}]},{"id":"servitude-passage","matiere":"civil","title":"M. Ait Ouali c/ M. Rachidi","court":"Tribunal de première instance de Taroudant","object":"Demande de servitude de passage pour un terrain enclavé.","you":"Avocat du propriétaire enclavé (M. Ait Ouali)","adverseName":"Avocat de M. Rachidi","facts":"M. Ait Ouali possède une parcelle agricole de 3 hectares, sans accès à la route, sauf un sentier piéton de 80 cm à travers un oued. Il demande un passage de 4 mètres sur la bordure du terrain de M. Rachidi, le long d'une haie, pour faire entrer tracteurs et camions de récolte. La parcelle n'est pas issue d'un partage.","rounds":[{"name":"L'état d'enclave","adverse":"Monsieur le Président, le terrain n'est pas enclavé : un sentier y mène. Mon client n'a pas à subir de servitude.","prompt":"Démontrez l'enclave.","options":[{"label":"Issue insuffisante","detail":"Le texte vise aussi l'issue insuffisante pour l'exploitation (art. 64 CDR).","pts":18,"speech":"L'article 64 du Code des droits réels ne vise pas seulement le fonds sans aucune issue : il vise aussi celui qui n'a sur la voie publique qu'une issue insuffisante pour son exploitation. Un sentier piéton de 80 centimètres, coupé par un oued, ne permet pas l'exploitation agricole de trois hectares : aucun tracteur, aucun camion de récolte ne peut y passer.","ok":["Cite l'article 64 CDR","Issue insuffisante pour l'exploitation"],"ko":[]},{"label":"Invoquer l'usage ancien","detail":"Soutenir que les anciens passaient déjà par là.","pts":7,"speech":"De tout temps, les familles passaient par ce terrain.","ok":["Contexte local"],"ko":["Aucune preuve","Ignore la notion d'issue insuffisante"]}],"concepts":[{"label":"Issue insuffisante pour l'exploitation","re":"insuffisant|exploitation|tracteur|camion","pts":6,"key":true},{"label":"Enclave","re":"enclav","pts":4},{"label":"Sentier inadapté","re":"sentier|80 cm|oued","pts":3}],"articles":[{"code":"CDR","article":"64","label":"Art. 64 CDR (fonds enclavé)","pts":5}],"faille":"Le demandeur ne conteste pas l'existence d'un accès.","concede":"L'issue est insuffisante, soit. Mais pourquoi passer chez mon client ?"},{"name":"L'origine de l'enclave","adverse":"L'enclave résulte d'un partage familial : le demandeur doit réclamer le passage sur les lots de ses cohéritiers, pas sur le terrain de mon client.","prompt":"Répondez sur l'origine de l'enclave.","options":[{"label":"Pas de division à l'origine","detail":"L'article 65 vise l'enclave née d'une division ; la parcelle n'en est pas issue.","pts":16,"speech":"L'article 65 du Code des droits réels impose de réclamer le passage sur les lots issus de la division lorsque c'est la division du fonds qui a créé l'enclave. Ce n'est pas le cas : le titre foncier de M. Ait Ouali n'est issu d'aucun partage, comme le montre le certificat de la conservation foncière. C'est donc l'article 64 qui s'applique.","ok":["Cite l'article 65 et l'écarte","Preuve par le titre foncier"],"ko":[]},{"label":"Ne pas répondre","detail":"Revenir à l'état d'enclave.","pts":4,"speech":"Le terrain est enclavé, c'est tout ce qui compte.","ok":["Constance"],"ko":["Laisse l'argument adverse sans réponse"]}],"concepts":[{"label":"Enclave non issue d'une division","re":"pas (issu|issue) d.(un )?partage|aucun partage|division","pts":6,"key":true},{"label":"Preuve par le titre foncier","re":"titre foncier|conservation|certificat","pts":4}],"articles":[{"code":"CDR","article":"65","label":"Art. 65 CDR (enclave née d'une division)","pts":4}],"faille":"Le demandeur ne prouve pas que l'enclave est étrangère à un partage.","concede":"Le titre ne mentionne pas de partage, je l'admets."},{"name":"Le tracé et l'indemnité","adverse":"Si un passage est accordé, il ruinera la plantation d'oliviers de mon client. Il exige une indemnité de 200 000 Dirhams.","prompt":"Plaidez sur le tracé et l'indemnité.","options":[{"label":"Moindre préjudice et indemnité adéquate","detail":"Passage le long de la haie, sans toucher aux oliviers ; indemnité adéquate fixée par expert.","pts":17,"speech":"L'article 64 exige que le passage soit établi là où il cause le moindre préjudice, moyennant une indemnité adéquate. Le tracé proposé longe la haie en bordure, sans aucun olivier : il occupe 1 200 mètres carrés de terrain nu. Nous offrons une indemnité correspondant à la valeur de cette bande, et demandons subsidiairement une expertise pour la fixer.","ok":["Tracé de moindre préjudice","Indemnité adéquate","Expertise subsidiaire"],"ko":[]},{"label":"Refuser toute indemnité","detail":"Soutenir que le passage ne coûte rien au voisin.","pts":5,"speech":"Le passage ne cause aucun préjudice : aucune indemnité n'est due.","ok":["Ferme"],"ko":["Contraire à la loi"]}],"concepts":[{"label":"Moindre préjudice","re":"moindre prejudice|bordure|haie|sans (toucher|olivier)","pts":5,"key":true},{"label":"Indemnité adéquate","re":"indemnit","pts":4},{"label":"Expertise","re":"expert","pts":3}],"articles":[{"code":"CDR","article":"64","label":"Art. 64 CDR (indemnité, moindre préjudice)","pts":4}],"faille":"Rien n'est proposé : la demande doit être rejetée.","concede":"Le tracé est raisonnable ; l'indemnité reste à fixer."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le fonds ne dispose que d'une issue insuffisante pour son exploitation et que l'enclave n'est pas née d'une division (articles 64 et 65 CDR) ; Par ces motifs : accorde un passage de 4 mètres le long de la haie moyennant une indemnité fixée par expert."},{"min":45,"text":"Le Tribunal, attendu l'état d'enclave ; Par ces motifs : ordonne une expertise pour déterminer le tracé de moindre préjudice et l'indemnité."},{"min":0,"text":"Le Tribunal, attendu que l'insuffisance de l'issue n'est pas établie ; Par ces motifs : rejette la demande."}]},{"id":"chefaa","matiere":"civil","title":"Mme Chraïbi c/ M. Naji","court":"Tribunal de première instance de Marrakech","object":"Exercice du droit de préemption (chefaa) sur une part indivise vendue à un tiers.","you":"Avocat de la copropriétaire (Mme Chraïbi)","adverseName":"Avocat de l'acquéreur (M. Naji)","facts":"Mme Chraïbi et son cousin étaient copropriétaires indivis, à parts égales, d'un riad. Le cousin a vendu sa moitié à M. Naji pour 1,2 million de DH. M. Naji a fait signifier une copie de l'acte au domicile de Mme Chraïbi, où elle a été remise à sa domestique. Quarante jours plus tard, Mme Chraïbi a demandé au président du tribunal l'autorisation de faire une offre réelle et a consigné le prix.","rounds":[{"name":"Le délai de trente jours","adverse":"Monsieur le Président, mon client a notifié l'acte ; la préemptrice disposait de trente jours. Elle a agi au bout de quarante : elle est déchue.","prompt":"Contestez la déchéance.","options":[{"label":"Notification non personnelle","detail":"La notification n'est valable que si elle est reçue personnellement par le préempteur (art. 304).","pts":18,"speech":"L'article 304 du Code des droits réels est précis : la notification n'est valable que si elle est reçue personnellement par l'ayant droit à la préemption. L'acte a été remis à une employée de maison. Faute de notification personnelle, le délai de trente jours n'a jamais commencé à courir : la demande est recevable.","ok":["Cite l'article 304","Remise à un tiers","Délai non couru"],"ko":[]},{"label":"Invoquer l'ignorance","detail":"Affirmer qu'elle ignorait la vente.","pts":8,"speech":"Ma cliente ignorait tout de cette vente.","ok":["Vrai en fait"],"ko":["N'exploite pas la condition de réception personnelle"]}],"concepts":[{"label":"Réception personnelle exigée","re":"personnellement|personnelle|en mains propres|domestique|employee","pts":6,"key":true},{"label":"Délai de trente jours non couru","re":"trente jours|30 jours|n.a (jamais )?pas couru|point de depart","pts":4},{"label":"Notification irrégulière","re":"notification|nullit|irreguli","pts":3}],"articles":[{"code":"CDR","article":"304","label":"Art. 304 CDR (notification et délai)","pts":5}],"faille":"La demande ne conteste pas la notification : la déchéance est acquise.","concede":"La remise n'était pas personnelle, soit. Mais la procédure de préemption a-t-elle été suivie ?"},{"name":"La procédure d'offre réelle","adverse":"La préemptrice devait présenter une offre réelle du prix et des frais : elle n'a consigné que le prix, pas les frais.","prompt":"Répondez sur la procédure.","options":[{"label":"Procédure respectée","detail":"Demande au président, offre réelle, consignation du prix et des frais apparents (art. 306).","pts":16,"speech":"Ma cliente a suivi à la lettre l'article 306 : requête au président du tribunal, autorisation de présenter une offre réelle, puis consignation à la caisse du tribunal après le refus de l'acquéreur. Elle a consigné le prix et les frais apparents de l'acte, soit 1 284 000 Dirhams, comme l'atteste le récépissé.","ok":["Cite l'article 306","Récépissé de consignation","Prix et frais apparents"],"ko":["Les frais non apparents restent discutables"]},{"label":"Proposer de compléter","detail":"Offrir de payer les frais plus tard.","pts":7,"speech":"Ma cliente paiera les frais dès qu'ils seront justifiés.","ok":["Bonne volonté"],"ko":["Admet une consignation incomplète"]}],"concepts":[{"label":"Offre réelle et consignation","re":"offre reelle|consign|caisse du tribunal","pts":6,"key":true},{"label":"Prix et frais apparents","re":"frais|prix","pts":4},{"label":"Requête au président","re":"president","pts":2}],"articles":[{"code":"CDR","article":"306","label":"Art. 306 CDR (demande et consignation)","pts":5}],"faille":"La consignation n'est pas justifiée.","concede":"La consignation est faite, admettons. Reste le montant dû à mon client."},{"name":"Ce que doit le préempteur","adverse":"Mon client a réalisé des travaux de 150 000 Dirhams dans le riad depuis son achat ; il doit en être remboursé.","prompt":"Plaidez sur le montant à rembourser.","options":[{"label":"Prix, frais et dépenses utiles","detail":"Le préempteur paie le prix, les frais du contrat et les dépenses nécessaires ou utiles justifiées (art. 292).","pts":16,"speech":"La préemption, selon l'article 292, oblige le préempteur à payer le prix de vente, les frais du contrat et, le cas échéant, les dépenses nécessaires et utiles. Ma cliente ne refuse pas de rembourser les dépenses réellement utiles, sur justificatifs : factures, autorisations de travaux. Des embellissements de convenance ne sont pas des dépenses utiles.","ok":["Cite l'article 292","Exige des justificatifs","Distingue dépenses utiles et de convenance"],"ko":[]},{"label":"Refuser tout remboursement","detail":"Les travaux ont été faits à ses risques.","pts":6,"speech":"M. Naji a fait des travaux à ses risques ; ma cliente ne lui doit rien.","ok":["Ferme"],"ko":["Contraire au texte"]}],"concepts":[{"label":"Dépenses nécessaires et utiles","re":"utiles?|necessaires?|depenses","pts":5,"key":true},{"label":"Justificatifs exigés","re":"justifi|factur","pts":4},{"label":"Prix et frais du contrat","re":"prix|frais","pts":3}],"articles":[{"code":"CDR","article":"292","label":"Art. 292 CDR (définition et prix de la préemption)","pts":4}],"faille":"La demande refuse tout remboursement : c'est inéquitable.","concede":"Les dépenses utiles seules sont dues, je l'admets."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la notification n'a pas été reçue personnellement par la préemptrice et que l'offre réelle et la consignation ont été régulièrement faites (articles 304 et 306 CDR) ; Par ces motifs : valide la préemption et dit que les dépenses utiles justifiées seront remboursées à l'acquéreur."},{"min":45,"text":"Le Tribunal, attendu la recevabilité de la demande ; Par ces motifs : valide la préemption et ordonne une expertise sur les dépenses invoquées."},{"min":0,"text":"Le Tribunal, attendu que la préemptrice n'a pas agi dans le délai légal ; Par ces motifs : la déclare déchue de son droit de préemption."}]},{"id":"expropriation","matiere":"civil","title":"Héritiers Bennis c/ Commune de Salé","court":"Tribunal administratif de Rabat","object":"Contestation de l'indemnité d'expropriation d'un terrain urbain.","you":"Avocat des propriétaires (héritiers Bennis)","adverseName":"Avocat de la commune expropriante","facts":"La commune de Salé exproprie pour cause d'utilité publique un terrain de 2 000 m² appartenant aux héritiers Bennis, pour y construire une voie. Elle offre 400 DH le m², valeur agricole. Le terrain est classé en zone d'immeubles par le plan d'aménagement ; les parcelles voisines se sont vendues 2 500 DH le m² en 2024. Une boutique y était exploitée depuis 2015 ; un garage a été construit après la publication de l'acte déclaratif d'utilité publique.","rounds":[{"name":"La valeur du terrain","adverse":"Monsieur le Président, le terrain est nu et non bâti, d'usage agricole. L'offre de 400 Dirhams le mètre carré correspond à sa valeur.","prompt":"Contestez l'évaluation.","options":[{"label":"Valeur au jour de la décision","detail":"L'indemnité se fixe d'après la valeur de l'immeuble au jour de la décision (art. 20 loi 7-81) ; zonage urbain et ventes comparables.","pts":18,"speech":"L'article 20 de la loi 7-81 fixe l'indemnité d'après la valeur de l'immeuble au jour de la décision prononçant l'expropriation. Cette valeur dépend de la situation juridique réelle du terrain : il est classé en zone d'immeubles par le plan d'aménagement. Les ventes de parcelles voisines en 2024, à 2 500 Dirhams le mètre carré, actes à l'appui, en donnent la mesure.","ok":["Cite l'article 20","Zonage du plan d'aménagement","Termes de comparaison"],"ko":[]},{"label":"Réclamer un prix symbolique fort","detail":"Demander 5 000 DH le m².","pts":5,"speech":"Les héritiers réclament 5 000 Dirhams le mètre carré.","ok":["Ambitieux"],"ko":["Aucune justification"]}],"concepts":[{"label":"Valeur au jour de la décision","re":"valeur|jour de la decision","pts":5,"key":true},{"label":"Zonage urbain","re":"zone|plan d.amenagement|constructible|urbain","pts":4},{"label":"Ventes comparables","re":"comparab|voisin|2 500|ventes?","pts":4}],"articles":[{"code":"d0453","article":"20","label":"Art. 20 loi 7-81 (fixation de l'indemnité)","pts":5}],"faille":"Les expropriés ne produisent aucun élément de comparaison.","concede":"Le zonage est urbain, je le concède. Mais toutes les constructions ne s'indemnisent pas."},{"name":"Les constructions","adverse":"Le garage a été construit après la publication de l'utilité publique, et la boutique ne vaut rien : aucune indemnité n'est due pour ces constructions.","prompt":"Répondez sur les constructions.","options":[{"label":"Distinguer avant et après la DUP","detail":"Le garage postérieur ne s'indemnise pas (art. 20) ; la boutique antérieure, oui, avec le préjudice direct.","pts":17,"speech":"Nous ne réclamons rien pour le garage : l'article 20 exclut les constructions faites sans l'accord de l'expropriant après la publication de l'acte déclaratif d'utilité publique. La boutique, elle, existait depuis 2015, autorisation et patente à l'appui : sa valeur et la perte de son exploitation constituent un dommage actuel, certain et directement causé par l'expropriation.","ok":["Concède le garage (crédibilité)","Date la boutique","Dommage direct et certain"],"ko":[]},{"label":"Tout réclamer","detail":"Exiger l'indemnisation du garage et de la boutique.","pts":6,"speech":"Toutes les constructions doivent être indemnisées.","ok":["Ferme"],"ko":["Contraire au texte pour le garage"]}],"concepts":[{"label":"Constructions postérieures à la DUP exclues","re":"apres la publication|posterieur|utilite publique|garage","pts":5,"key":true},{"label":"Boutique antérieure indemnisable","re":"boutique|2015|anterieur|patente","pts":4},{"label":"Dommage actuel, certain et direct","re":"actuel|certain|direct","pts":4}],"articles":[{"code":"d0453","article":"20","label":"Art. 20 loi 7-81 (constructions postérieures)","pts":4}],"faille":"Les expropriés ne distinguent rien : la demande est excessive.","concede":"La boutique est antérieure, soit."},{"name":"Le préjudice futur","adverse":"Les héritiers réclament aussi la perte d'un projet immobilier qu'ils envisageaient : c'est un préjudice purement éventuel.","prompt":"Plaidez sur l'étendue du préjudice indemnisable.","options":[{"label":"Écarter l'éventuel, garder le certain","detail":"Renoncer au projet incertain ; maintenir la valeur, la boutique et le fonds exploité.","pts":15,"speech":"L'article 20 limite l'indemnité au dommage actuel et certain, à l'exclusion du dommage éventuel. Les héritiers s'en tiennent donc à la valeur du terrain et à la perte de la boutique exploitée, dont les bénéfices des trois dernières années sont justifiés. Le projet immobilier, sans permis ni financement, n'est pas réclamé.","ok":["Applique la distinction certain/éventuel","Recentre sur le justifié"],"ko":[]},{"label":"Maintenir le projet","detail":"Réclamer 1 million pour le projet perdu.","pts":5,"speech":"Le projet perdu justifie un million de Dirhams.","ok":["Ambitieux"],"ko":["Préjudice éventuel exclu par la loi"]}],"concepts":[{"label":"Préjudice éventuel exclu","re":"eventuel|incertain|indirect","pts":5,"key":true},{"label":"Préjudice certain justifié","re":"certain|justifi|benefices?","pts":4}],"articles":[{"code":"d0453","article":"20","label":"Art. 20 loi 7-81 (dommage actuel et certain)","pts":3}],"faille":"Les expropriés réclament des préjudices hypothétiques.","concede":"La demande est désormais mesurée."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la valeur du terrain s'apprécie au jour de la décision au regard de son classement en zone d'immeubles et des ventes comparables, et que seul le dommage actuel et certain est indemnisable (article 20) ; Par ces motifs : fixe l'indemnité à 2 300 Dirhams le mètre carré, outre l'indemnisation de la boutique."},{"min":45,"text":"Le Tribunal, attendu le caractère urbain du terrain ; Par ces motifs : fixe l'indemnité à 1 500 Dirhams le mètre carré."},{"min":0,"text":"Le Tribunal, attendu l'absence d'éléments de comparaison probants ; Par ces motifs : fixe l'indemnité à 600 Dirhams le mètre carré."}]},{"id":"recel","matiere":"penal","title":"Ministère public c/ Amine L.","court":"Tribunal de première instance de Tanger — chambre correctionnelle","object":"Poursuites pour recel de téléphones volés.","you":"Avocat de la défense (Amine L.)","adverseName":"Le Procureur du Roi","facts":"Amine L., gérant d'une petite boutique de téléphonie, a acheté à un client de passage cinq smartphones d'occasion pour 9 000 DH, soit environ la moitié de leur valeur. Il a noté l'identité du vendeur et conservé une copie de sa carte d'identité. Les téléphones s'avèrent volés. Le vendeur est introuvable.","rounds":[{"name":"L'élément intentionnel","adverse":"Monsieur le Président, le prévenu a acheté cinq téléphones à moitié prix : il ne pouvait ignorer leur origine. Le recel est constitué.","prompt":"Contestez l'élément intentionnel.","options":[{"label":"« Sciemment » : la connaissance à prouver","detail":"Le recel exige la connaissance de l'origine frauduleuse (art. 571) ; identité relevée, copie de la CIN : comportement d'un acheteur de bonne foi.","pts":18,"speech":"L'article 571 du Code pénal ne punit que celui qui, sciemment, recèle des choses obtenues à l'aide d'un délit. La connaissance de l'origine frauduleuse doit être prouvée par l'accusation. Mon client a relevé l'identité du vendeur et conservé la copie de sa carte nationale : ce n'est pas le comportement d'un receleur, qui fuit toute trace, mais celui d'un commerçant qui croyait à une vente régulière.","ok":["Cite l'article 571 (sciemment)","Charge de la preuve sur l'accusation","Exploite la copie de la CIN"],"ko":[]},{"label":"Plaider l'erreur","detail":"Reconnaître une imprudence commerciale.","pts":8,"speech":"Mon client a été imprudent, il le regrette.","ok":["Sincère"],"ko":["L'aveu d'imprudence peut nourrir la thèse de la connaissance"]}],"concepts":[{"label":"Connaissance de l'origine frauduleuse","re":"sciemment|connaiss|savait|ignor","pts":6,"key":true},{"label":"Charge de la preuve sur l'accusation","re":"preuve|prouver|accusation|ministere public","pts":4},{"label":"Identité du vendeur relevée","re":"identite|carte|cin|copie","pts":4}],"articles":[{"code":"CP","article":"571","label":"Art. 571 CP (recel)","pts":5}],"faille":"La défense ne dit rien de l'élément intentionnel.","concede":"L'identité a été relevée, soit. Le prix reste anormalement bas."},{"name":"Le prix anormal","adverse":"Le prix payé, la moitié de la valeur, suffit à établir que le prévenu savait.","prompt":"Répondez sur le prix.","options":[{"label":"Prix du marché de l'occasion","detail":"Téléphones d'occasion, sans boîte ni facture : décote habituelle ; factures de rachats comparables.","pts":16,"speech":"Il s'agit de téléphones d'occasion, sans boîte ni chargeur. Sur le marché de la revente, une décote de 40 à 50 % est courante, comme le montrent les registres de rachat de mon client depuis deux ans, qui comportent des dizaines d'achats à des prix comparables. Le prix n'est donc pas un indice de connaissance.","ok":["Contexte du marché","Pièces : registres de rachat"],"ko":["Le registre ne mentionne pas toujours l'origine"]},{"label":"Nier le prix","detail":"Soutenir que le prix était normal sans pièces.","pts":6,"speech":"Le prix était tout à fait normal.","ok":["Constant"],"ko":["Simple affirmation"]}],"concepts":[{"label":"Décote normale de l'occasion","re":"occasion|decote|marche|sans boite","pts":5,"key":true},{"label":"Pièces : registre ou factures comparables","re":"registre|factur|comparab","pts":4},{"label":"Le prix n'est pas une preuve","re":"indice|pas une preuve|ne prouve","pts":3}],"articles":[{"code":"CP","article":"571","label":"Art. 571 CP","pts":2}],"faille":"La défense ne justifie pas le prix.","concede":"Le registre existe, je l'admets."},{"name":"La peine","adverse":"Si le tribunal retient la culpabilité, une peine d'emprisonnement ferme s'impose pour dissuader ce commerce.","prompt":"Plaidez subsidiairement sur la peine.","options":[{"label":"Circonstances atténuantes et sursis","detail":"Casier vierge, collaboration avec l'enquête : circonstances atténuantes (art. 146) et sursis (art. 55).","pts":16,"speech":"À titre subsidiaire, mon client n'a jamais été condamné, il a collaboré avec l'enquête et restitué les appareils. L'article 146 du Code pénal permet d'accorder les circonstances atténuantes lorsque la peine prévue est excessive au regard de la culpabilité, et l'article 55 autorise le sursis pour un prévenu sans condamnation antérieure.","ok":["Cite les articles 146 et 55","Personnalité du prévenu","Restitution"],"ko":[]},{"label":"Ne rien demander","detail":"Maintenir la relaxe uniquement.","pts":7,"speech":"La défense ne plaide que la relaxe.","ok":["Cohérent"],"ko":["Aucune position de repli"]}],"concepts":[{"label":"Circonstances atténuantes / sursis","re":"attenuant|sursis","pts":6,"key":true},{"label":"Casier vierge","re":"casier|jamais (ete )?condamn|premiere fois","pts":4},{"label":"Collaboration / restitution","re":"collabor|restitu","pts":3}],"articles":[{"code":"CP","article":"146","label":"Art. 146 CP (circonstances atténuantes)","pts":2},{"code":"CP","article":"55","label":"Art. 55 CP (sursis)","pts":2}],"faille":"La défense n'a aucune position de repli.","concede":"Le casier est vierge, c'est exact."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la connaissance de l'origine frauduleuse n'est pas établie, le prévenu ayant relevé l'identité du vendeur et le prix correspondant aux usages de l'occasion (article 571) ; Par ces motifs : relaxe Amine L."},{"min":45,"text":"Le Tribunal, attendu un doute sérieux sur l'élément intentionnel mais une imprudence certaine ; Par ces motifs : relaxe le prévenu au bénéfice du doute."},{"min":0,"text":"Le Tribunal, attendu que le prix anormal et les circonstances de l'achat établissent la connaissance ; Par ces motifs : condamne Amine L. à six mois d'emprisonnement avec sursis."}]},{"id":"homicide-route","matiere":"penal","title":"Ministère public c/ Driss M.","court":"Tribunal de première instance d'El Jadida — chambre correctionnelle","object":"Homicide involontaire à la suite d'un accident de la circulation.","you":"Avocat de la défense (Driss M.)","adverseName":"Le Procureur du Roi","facts":"De nuit, sur une route nationale hors agglomération, Driss M. a heurté un piéton qui traversait loin de tout passage, vêtu de sombre. Le piéton est décédé. Le constat relève une vitesse estimée à 85 km/h pour une limite de 100 km/h ; l'alcootest du conducteur est négatif. Un témoin affirme que le piéton a surgi entre deux camions stationnés.","rounds":[{"name":"La faute du conducteur","adverse":"Monsieur le Président, un homme est mort. Le conducteur devait rester maître de son véhicule : son inattention est la cause du drame.","prompt":"Contestez la faute.","options":[{"label":"Absence de faute caractérisée","detail":"L'article 432 exige maladresse, imprudence, inattention ou inobservation des règlements : vitesse réglementaire, alcootest négatif.","pts":17,"speech":"L'article 432 du Code pénal punit l'homicide causé par maladresse, imprudence, inattention, négligence ou inobservation des règlements. Encore faut-il caractériser l'une de ces fautes. Mon client roulait à 85 km/h sous une limite de 100, son alcootest était négatif, ses phares allumés. L'émotion légitime ne peut tenir lieu de faute.","ok":["Cite l'article 432","Exige la caractérisation d'une faute","Éléments objectifs favorables"],"ko":[]},{"label":"Plaider le malheur","detail":"Insister sur la détresse du prévenu.","pts":7,"speech":"Mon client est anéanti ; il ne dort plus depuis l'accident.","ok":["Humain"],"ko":["Aucune réponse sur la faute"]}],"concepts":[{"label":"Pas de faute caractérisée","re":"aucune faute|pas de faute|caracteris|faute","pts":6,"key":true},{"label":"Vitesse réglementaire","re":"vitesse|85|100|limit","pts":4},{"label":"Alcootest négatif","re":"alcool|alcootest","pts":3}],"articles":[{"code":"CP","article":"432","label":"Art. 432 CP (homicide involontaire)","pts":5}],"faille":"La défense ne conteste pas l'inattention : la faute est établie.","concede":"La vitesse était réglementaire, soit. Le conducteur devait néanmoins adapter sa conduite."},{"name":"Le comportement de la victime","adverse":"Hors agglomération, de nuit, la prudence imposait de ralentir. Le prévenu ne peut rejeter la faute sur la victime.","prompt":"Plaidez la cause du dommage.","options":[{"label":"Faute imprévisible de la victime","detail":"Traversée hors passage, de nuit, en vêtements sombres, surgissant entre deux camions : témoin.","pts":17,"speech":"Le témoin est formel : la victime a surgi entre deux camions stationnés, loin de tout passage, de nuit et vêtue de sombre. Aucun conducteur raisonnable, roulant même plus lentement, n'aurait pu l'éviter. C'est ce comportement imprévisible, et non une faute de mon client, qui est la cause directe de l'accident.","ok":["Témoignage","Imprévisibilité","Causalité"],"ko":["Ne demande pas de reconstitution"]},{"label":"Accuser la victime","detail":"Soutenir qu'elle était ivre.","pts":4,"speech":"La victime était sans doute ivre.","ok":["—"],"ko":["Allégation sans preuve, choquante pour la famille"]}],"concepts":[{"label":"Comportement imprévisible de la victime","re":"surgi|imprevisib|hors passage|camions?","pts":6,"key":true},{"label":"Témoignage","re":"temoin|temoign","pts":4},{"label":"Causalité","re":"cause|causal","pts":3}],"articles":[{"code":"CP","article":"432","label":"Art. 432 CP (lien de causalité)","pts":3}],"faille":"La défense n'explique pas comment l'accident est arrivé.","concede":"Le témoin confirme la traversée brutale, je l'admets."},{"name":"La peine","adverse":"Le parquet requiert un an d'emprisonnement ferme.","prompt":"Plaidez subsidiairement sur la peine.","options":[{"label":"Sursis et circonstances atténuantes","detail":"Casier vierge, assistance immédiate à la victime, indemnisation par l'assurance : art. 146 et 55.","pts":16,"speech":"Subsidiairement, mon client a immédiatement appelé les secours et est resté sur place. Il n'a aucun antécédent, et son assureur indemnise la famille. L'article 146 permet les circonstances atténuantes et l'article 55 le sursis au profit d'un prévenu jamais condamné. Une peine ferme n'aurait aucun sens pour un homme qui n'a commis aucune faute volontaire.","ok":["Cite les articles 146 et 55","Comportement après l'accident"],"ko":[]},{"label":"Accepter la peine","detail":"S'en remettre au tribunal.","pts":5,"speech":"La défense s'en remet à la sagesse du tribunal.","ok":["Prudent"],"ko":["Aucun argument"]}],"concepts":[{"label":"Sursis / circonstances atténuantes","re":"sursis|attenuant","pts":6,"key":true},{"label":"Secours et comportement","re":"secours|reste sur place|assist","pts":4},{"label":"Casier vierge","re":"casier|antecedent|jamais","pts":3}],"articles":[{"code":"CP","article":"55","label":"Art. 55 CP (sursis)","pts":2},{"code":"CP","article":"146","label":"Art. 146 CP","pts":2}],"faille":"La défense ne propose rien.","concede":"Le comportement après l'accident est exemplaire."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu qu'aucune maladresse, imprudence ni inobservation des règlements n'est caractérisée et que la victime a surgi de manière imprévisible (article 432) ; Par ces motifs : relaxe Driss M."},{"min":45,"text":"Le Tribunal, attendu une faute légère du conducteur, atténuée par le comportement de la victime ; Par ces motifs : condamne Driss M. à trois mois d'emprisonnement avec sursis."},{"min":0,"text":"Le Tribunal, attendu que le conducteur n'a pas adapté sa conduite ; Par ces motifs : condamne Driss M. à un an d'emprisonnement dont six mois ferme."}]},{"id":"perquisition-nuit","matiere":"penal","title":"Ministère public c/ Rachid E.","court":"Tribunal de première instance de Casablanca — chambre correctionnelle","object":"Nullité d'une perquisition nocturne dans une affaire de vol.","you":"Avocat de la défense (Rachid E.)","adverseName":"Le Procureur du Roi","facts":"Rachid E. est poursuivi pour vol de matériel informatique dans un entrepôt. Les policiers ont perquisitionné son domicile à 23 h 30, sans demande de sa part ni appel au secours, et y ont saisi deux ordinateurs portables. Le procès-verbal mentionne qu'il « ne s'est pas opposé ». Aucune autre preuve ne le relie à l'entrepôt, hormis un témoin qui dit l'avoir vu « dans le quartier ».","rounds":[{"name":"L'heure de la perquisition","adverse":"Monsieur le Président, les objets volés ont été retrouvés chez le prévenu. La perquisition a été menée avec son accord, sans contestation.","prompt":"Soulevez la nullité.","options":[{"label":"Heures légales et nullité","detail":"Pas de perquisition avant 6 h ni après 21 h sauf exceptions (art. 62 CPP), sous peine de nullité (art. 63).","pts":18,"speech":"L'article 62 du Code de procédure pénale interdit de commencer une perquisition domiciliaire avant six heures et après vingt et une heures, sauf demande du chef de maison, appel venant de l'intérieur ou cas légalement prévus. Aucune de ces exceptions n'existe : la perquisition a commencé à 23 h 30. L'article 63 sanctionne ces règles par la nullité de l'acte et des actes qui en découlent.","ok":["Cite les articles 62 et 63 CPP","Écarte les exceptions"],"ko":[]},{"label":"Contester la propriété des ordinateurs","detail":"Soutenir que les ordinateurs lui appartiennent.","pts":8,"speech":"Ces ordinateurs appartiennent à mon client, il les a achetés.","ok":["Moyen de fond"],"ko":["Aucune facture","Ignore la nullité, moyen décisif"]}],"concepts":[{"label":"Heures légales de perquisition","re":"21 ?h|vingt et une|six heures|6 ?h|nuit|23 ?h","pts":6,"key":true},{"label":"Nullité de l'acte","re":"nullit|nul","pts":5},{"label":"Absence d'exception","re":"exception|demande du chef|appel|secours","pts":3}],"articles":[{"code":"CPP","article":"62","label":"Art. 62 CPP (heures de perquisition)","pts":4},{"code":"CPP","article":"63","label":"Art. 63 CPP (nullité)","pts":3}],"faille":"La défense ne conteste pas la régularité de la perquisition.","concede":"L'heure est tardive, soit. Mais le prévenu a consenti."},{"name":"Le prétendu consentement","adverse":"Le procès-verbal indique que le prévenu ne s'est pas opposé : il a donc consenti à la perquisition.","prompt":"Répondez sur le consentement.","options":[{"label":"Ne pas s'opposer n'est pas demander","detail":"L'exception exige une demande du chef de maison ; une absence d'opposition ne vaut pas demande.","pts":16,"speech":"L'exception de l'article 62 vise le cas où le chef de maison demande lui-même la perquisition. Le procès-verbal ne relate aucune demande, seulement l'absence d'opposition d'un homme réveillé en pleine nuit par des policiers. Ne pas s'opposer n'est pas demander : interpréter le silence comme une demande viderait la règle de toute portée.","ok":["Distingue demande et absence d'opposition","Portée de la règle"],"ko":[]},{"label":"Invoquer la pression policière","detail":"Soutenir qu'il a été intimidé.","pts":9,"speech":"Mon client était terrorisé et n'a pas osé s'opposer.","ok":["Plausible"],"ko":["Aucune preuve de pression"]}],"concepts":[{"label":"Absence d'opposition ≠ demande","re":"pas (une )?demande|absence d.opposition|ne pas s.opposer|silence","pts":6,"key":true},{"label":"Exigence d'une demande du chef de maison","re":"chef de maison|demande","pts":4}],"articles":[{"code":"CPP","article":"62","label":"Art. 62 CPP (exception de la demande)","pts":3}],"faille":"La défense ne réfute pas le consentement constaté.","concede":"La demande n'est pas mentionnée, je l'admets."},{"name":"Ce qui reste du dossier","adverse":"Même sans les ordinateurs, le témoin a vu le prévenu sur les lieux.","prompt":"Plaidez sur les preuves restantes.","options":[{"label":"Insuffisance des preuves","detail":"Le vol (art. 505) suppose une soustraction prouvée ; « dans le quartier » ne place pas le prévenu dans l'entrepôt.","pts":16,"speech":"Les saisies annulées, il reste un témoin qui a vu mon client « dans le quartier », où il habite. Le vol, selon l'article 505 du Code pénal, est la soustraction frauduleuse de la chose d'autrui : rien ne prouve que mon client soit entré dans l'entrepôt. Le doute doit lui profiter.","ok":["Cite l'article 505","Analyse le témoignage","Doute profitant au prévenu"],"ko":[]},{"label":"Plaider la clémence","detail":"Demander une peine légère.","pts":5,"speech":"Si le tribunal condamne, que ce soit avec indulgence.","ok":["Repli"],"ko":["Abandonne la relaxe possible"]}],"concepts":[{"label":"Doute / insuffisance des preuves","re":"doute|insuffis|aucune preuve|rien ne prouve","pts":6,"key":true},{"label":"Témoignage imprécis","re":"quartier|temoin|habite","pts":4},{"label":"Éléments du vol","re":"soustraction|vol","pts":3}],"articles":[{"code":"CP","article":"505","label":"Art. 505 CP (vol)","pts":3}],"faille":"La défense ne discute pas le témoignage.","concede":"Le témoignage est vague, c'est exact."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la perquisition a débuté à 23 h 30 hors des cas prévus par l'article 62 CPP, ce qui entraîne sa nullité et celle des saisies (article 63), et que les autres éléments ne suffisent pas à établir le vol ; Par ces motifs : relaxe Rachid E."},{"min":45,"text":"Le Tribunal, attendu la nullité de la perquisition ; Par ces motifs : écarte les saisies et relaxe le prévenu au bénéfice du doute."},{"min":0,"text":"Le Tribunal, attendu que le prévenu a consenti à la perquisition ; Par ces motifs : rejette l'exception et condamne Rachid E. à un an d'emprisonnement."}]},{"id":"violences-conjugales","matiere":"penal","title":"Ministère public et Mme Rhazi c/ Mehdi R.","court":"Tribunal de première instance de Rabat — chambre correctionnelle","object":"Violences volontaires sur conjointe. Constitution de partie civile.","you":"Avocat de la partie civile (Mme Rhazi)","adverseName":"Avocat de Mehdi R.","facts":"Mme Rhazi a été frappée par son époux lors d'une dispute ; le certificat médical fait état d'hématomes au visage et aux bras et de 18 jours d'incapacité. Une voisine a entendu les cris et vu Mme Rhazi sortir en pleurs. M. Rhazi parle d'une « chute » pendant une bousculade réciproque.","rounds":[{"name":"La qualification","adverse":"Monsieur le Président, il s'agit d'une dispute conjugale qui a dégénéré, avec des torts partagés. Il n'y a là qu'une affaire privée.","prompt":"Défendez la qualification de violences aggravées.","options":[{"label":"Violences sur conjoint : circonstance aggravante","detail":"L'article 404 CP aggrave les coups et blessures volontaires commis sur un conjoint.","pts":18,"speech":"Les violences au sein du couple ne sont pas une affaire privée : l'article 404 du Code pénal fait de la qualité de conjoint de la victime une circonstance aggravante des coups et blessures volontaires. Le certificat médical constate des hématomes au visage et aux bras et dix-huit jours d'incapacité. La qualification de violences volontaires aggravées s'impose.","ok":["Cite l'article 404","Rejette la thèse de l'affaire privée","S'appuie sur le certificat médical"],"ko":[]},{"label":"Insister sur la souffrance","detail":"Décrire la peur de la victime.","pts":8,"speech":"Ma cliente vit dans la peur depuis des mois.","ok":["Humain"],"ko":["Aucune qualification juridique"]}],"concepts":[{"label":"Circonstance aggravante du conjoint","re":"conjoint|epoux|aggrav","pts":6,"key":true},{"label":"Certificat médical / incapacité","re":"certificat|incapacit|18 jours|hematome","pts":4},{"label":"Pas une affaire privée","re":"pas une affaire privee|ordre public|societe","pts":3}],"articles":[{"code":"CP","article":"404","label":"Art. 404 CP (violences aggravées)","pts":5}],"faille":"La partie civile ne qualifie pas les faits.","concede":"La qualité de conjoint aggrave, je l'admets ; encore faut-il que les coups soient prouvés."},{"name":"La thèse de la chute","adverse":"Mme Rhazi est tombée pendant une bousculade réciproque. Personne n'a vu de coups.","prompt":"Démontrez les coups volontaires.","options":[{"label":"Incompatibilité avec une chute","detail":"Localisation des lésions (visage et deux bras), témoignage de la voisine, constance de la victime.","pts":16,"speech":"Une chute ne produit pas d'hématomes à la fois au visage et sur les deux bras, typiques de coups et de gestes de protection, comme le relève le certificat. La voisine a entendu des cris et vu ma cliente sortir en pleurs. La victime a décrit les mêmes faits à la police, au médecin et au juge. La thèse de la chute ne résiste pas à l'examen.","ok":["Analyse médicale des lésions","Témoignage","Constance des déclarations"],"ko":["Ne demande pas d'expertise médico-légale"]},{"label":"Accuser le mari d'antécédents","detail":"Évoquer des violences antérieures non déclarées.","pts":7,"speech":"Ce n'est pas la première fois, ma cliente a déjà été frappée.","ok":["Contexte"],"ko":["Faits non poursuivis ni prouvés"]}],"concepts":[{"label":"Lésions incompatibles avec une chute","re":"incompatib|chute|localisation|visage|bras","pts":6,"key":true},{"label":"Témoignage de la voisine","re":"voisine|temoin|cris","pts":4},{"label":"Constance de la victime","re":"constan|memes faits|declarations","pts":3}],"articles":[{"code":"CP","article":"404","label":"Art. 404 CP","pts":2}],"faille":"Rien ne contredit la chute.","concede":"Les lésions sont nombreuses, soit."},{"name":"La réparation","adverse":"La partie civile réclame 80 000 Dirhams : c'est une tentative d'obtenir de l'argent dans le cadre du divorce.","prompt":"Plaidez sur les dommages-intérêts.","options":[{"label":"Réparation du dommage causé volontairement","detail":"Celui qui cause volontairement un dommage le répare (art. 77 DOC) : frais, incapacité, préjudice moral.","pts":16,"speech":"L'article 77 du DOC oblige celui qui, sciemment et volontairement, cause un dommage matériel ou moral à le réparer. Ma cliente justifie 3 200 Dirhams de frais médicaux et dix-huit jours d'incapacité ; le préjudice moral d'une femme frappée chez elle par son époux est considérable. Nous ramenons la demande à 40 000 Dirhams, chaque poste étant justifié.","ok":["Cite l'article 77 DOC","Décompose le préjudice","Montant mesuré"],"ko":[]},{"label":"Maintenir 80 000 DH","detail":"Insister sans détail.","pts":6,"speech":"Ma cliente maintient sa demande de 80 000 Dirhams.","ok":["Ferme"],"ko":["Pas de justification"]}],"concepts":[{"label":"Réparation du dommage volontaire","re":"repar|dommage|indemnis","pts":5,"key":true},{"label":"Préjudice moral","re":"moral|souffran","pts":4},{"label":"Frais justifiés","re":"frais|justifi","pts":3}],"articles":[{"code":"DOC","article":"77","label":"Art. 77 DOC (dommage volontaire)","pts":4}],"faille":"La demande n'est pas justifiée.","concede":"Le préjudice est réel."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que les lésions constatées, incompatibles avec une chute, et le témoignage recueilli établissent des coups volontaires sur la conjointe (article 404) ; Par ces motifs : condamne Mehdi R. à huit mois d'emprisonnement avec sursis et à 40 000 Dirhams de dommages-intérêts."},{"min":45,"text":"Le Tribunal, attendu la culpabilité du prévenu ; Par ces motifs : le condamne à quatre mois avec sursis et 15 000 Dirhams de dommages-intérêts."},{"min":0,"text":"Le Tribunal, attendu un doute sur le caractère volontaire des blessures ; Par ces motifs : relaxe le prévenu."}]},{"id":"diffamation","matiere":"penal","title":"M. Lahlou c/ Kamal S.","court":"Tribunal de première instance de Fès — chambre correctionnelle","object":"Diffamation sur un réseau social. Constitution de partie civile.","you":"Avocat de la partie civile (M. Lahlou)","adverseName":"Avocat de Kamal S.","facts":"Kamal S. a publié sur un groupe Facebook de 40 000 membres que « le garagiste Lahlou vole ses clients en facturant des pièces qu'il ne change jamais ». La publication a été partagée 600 fois. Le garage a perdu plusieurs clients réguliers. Kamal S. ne produit qu'une facture contestée de 2023, que le garagiste avait remboursée.","rounds":[{"name":"La qualification","adverse":"Monsieur le Président, mon client a simplement exprimé son mécontentement de client. C'est au plus une injure, une opinion.","prompt":"Qualifiez les propos.","options":[{"label":"Imputation d'un fait précis : diffamation","detail":"Imputation d'un fait précis portant atteinte à l'honneur (art. 442), et non simple invective (art. 443).","pts":18,"speech":"L'article 442 du Code pénal définit la diffamation comme l'allégation d'un fait portant atteinte à l'honneur ou à la considération d'une personne. L'injure, selon l'article 443, est une invective qui ne renferme l'imputation d'aucun fait. Or Kamal S. impute un fait précis : facturer des pièces jamais changées, c'est-à-dire une escroquerie. Il s'agit bien d'une diffamation, rendue publique sur un groupe de 40 000 membres.","ok":["Distingue les articles 442 et 443","Identifie le fait précis imputé","Caractère public"],"ko":[]},{"label":"Plaider l'insulte","detail":"Se contenter de dire que les propos sont insultants.","pts":7,"speech":"Ces propos sont insultants et blessants pour mon client.","ok":["Constat réel"],"ko":["Ne qualifie pas juridiquement"]}],"concepts":[{"label":"Imputation d'un fait précis","re":"fait precis|imputation|imput|allegation","pts":6,"key":true},{"label":"Distinction avec l'injure","re":"injure|invective|443","pts":4},{"label":"Publicité / réseau social","re":"public|facebook|40 000|partag","pts":3}],"articles":[{"code":"CP","article":"442","label":"Art. 442 CP (diffamation)","pts":4},{"code":"CP","article":"443","label":"Art. 443 CP (injure)","pts":2}],"faille":"La partie civile ne qualifie pas les faits.","concede":"Un fait est imputé, soit ; mais il est vrai."},{"name":"La vérité des faits","adverse":"Mon client dit la vérité : il produit une facture de 2023 qui prouve la pratique du garage.","prompt":"Répondez sur la preuve invoquée.","options":[{"label":"Une facture remboursée ne prouve pas une pratique","detail":"Facture unique, contestée et remboursée ; généralisation sans preuve ; publicité soumise au code de la presse (art. 444).","pts":16,"speech":"Une facture unique, contestée en 2023 et remboursée par mon client, ne prouve pas qu'il « vole ses clients ». La généralisation est de la seule invention du prévenu. La diffamation publique relève, par renvoi de l'article 444, du code de la presse, qui n'admet la preuve des faits que dans des conditions strictes, ici absentes.","ok":["Discute la valeur de la pièce","Relève la généralisation","Cite le renvoi de l'article 444"],"ko":["Ne détaille pas la procédure de l'offre de preuve"]},{"label":"Contester l'authenticité","detail":"Affirmer que la facture est fausse.","pts":6,"speech":"Cette facture est un faux.","ok":["Ferme"],"ko":["Faux non démontré, contredit par le remboursement"]}],"concepts":[{"label":"Facture unique et remboursée","re":"rembours|une seule|unique|isole","pts":5,"key":true},{"label":"Généralisation sans preuve","re":"generalis|pratique|aucune preuve","pts":4},{"label":"Renvoi au code de la presse","re":"code de la presse|444","pts":3}],"articles":[{"code":"CP","article":"444","label":"Art. 444 CP (diffamation publique)","pts":3}],"faille":"La partie civile ne discute pas la facture.","concede":"La facture a été remboursée, je l'admets."},{"name":"Le préjudice","adverse":"Le garage n'a perdu aucun client à cause de cette publication. Le préjudice est imaginaire.","prompt":"Plaidez sur la réparation.","options":[{"label":"Faute et préjudice prouvés","detail":"Faute de la publication (art. 78 DOC), attestations de clients, baisse du chiffre d'affaires, retrait de la publication.","pts":16,"speech":"La publication est une faute au sens de l'article 78 du DOC, cause directe du dommage. Trois clients réguliers attestent avoir quitté le garage après l'avoir lue ; le chiffre d'affaires a baissé de 18 % le trimestre suivant. Nous demandons 30 000 Dirhams et le retrait de la publication ainsi que la publication du jugement dans le même groupe.","ok":["Cite l'article 78 DOC","Attestations et chiffres","Mesures de réparation en nature"],"ko":[]},{"label":"Demander un franc symbolique","detail":"Réclamer un dirham symbolique.","pts":8,"speech":"Mon client ne demande qu'un dirham symbolique pour son honneur.","ok":["Digne"],"ko":["Ignore le préjudice économique réel"]}],"concepts":[{"label":"Préjudice économique prouvé","re":"chiffre d.affaires|clients?|attest|baisse","pts":5,"key":true},{"label":"Faute et causalité","re":"faute|cause","pts":3},{"label":"Retrait / publication du jugement","re":"retrait|supprim|publication du jugement","pts":4}],"articles":[{"code":"DOC","article":"78","label":"Art. 78 DOC (faute)","pts":3}],"faille":"Aucun préjudice n'est démontré.","concede":"Les attestations existent."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la publication impute un fait précis portant atteinte à l'honneur du garagiste (article 442) et que la vérité des faits n'est pas établie ; Par ces motifs : déclare Kamal S. coupable de diffamation, le condamne à une amende et à 30 000 Dirhams de dommages-intérêts, et ordonne le retrait de la publication."},{"min":45,"text":"Le Tribunal, attendu la diffamation ; Par ces motifs : condamne le prévenu à une amende et à 10 000 Dirhams de dommages-intérêts."},{"min":0,"text":"Le Tribunal, attendu un doute sur le caractère diffamatoire des propos ; Par ces motifs : relaxe le prévenu."}]},{"id":"corruption","matiere":"penal","title":"Ministère public c/ Hassan T.","court":"Chambre criminelle — section des crimes financiers","object":"Poursuites pour corruption d'un agent communal.","you":"Avocat de la défense (Hassan T.)","adverseName":"Le Procureur général du Roi","facts":"Hassan T., agent du service de l'urbanisme d'une commune, est poursuivi pour avoir reçu 5 000 DH de M. Fadil, qui attendait une autorisation de travaux. L'argent lui a été remis dans un café. Hassan T. soutient qu'il s'agissait du remboursement d'un prêt consenti à M. Fadil, son ancien voisin, six mois plus tôt ; un relevé bancaire montre un retrait de 5 000 DH à cette date. L'autorisation avait été signée trois jours avant la remise, après avis favorable de la commission.","rounds":[{"name":"Les éléments de la corruption","adverse":"Monsieur le Président, un fonctionnaire de l'urbanisme a reçu de l'argent d'un usager qui attendait une autorisation. La corruption est constituée.","prompt":"Contestez les éléments de l'infraction.","options":[{"label":"Contrepartie d'un acte de la fonction","detail":"L'article 248 exige un avantage reçu pour accomplir ou s'abstenir d'un acte de la fonction : l'autorisation était déjà signée.","pts":17,"speech":"L'article 248 du Code pénal punit le fonctionnaire qui sollicite ou reçoit un avantage pour accomplir ou s'abstenir d'accomplir un acte de sa fonction. Le lien entre l'avantage et l'acte est l'essence même de l'infraction. Or l'autorisation avait été signée trois jours avant la remise, sur avis favorable de la commission : mon client n'avait plus aucun acte à accomplir.","ok":["Cite l'article 248","Lien avantage / acte de la fonction","Chronologie"],"ko":[]},{"label":"Contester les témoins","detail":"Discréditer M. Fadil.","pts":7,"speech":"M. Fadil est un homme rancunier qui cherche à nuire à mon client.","ok":["Pose la question de la crédibilité"],"ko":["Aucune preuve de rancune","Ne traite pas les éléments de l'infraction"]}],"concepts":[{"label":"Lien entre l'avantage et l'acte de la fonction","re":"acte de (sa|la) fonction|contrepartie|pour accomplir|lien","pts":6,"key":true},{"label":"Autorisation déjà signée","re":"deja signe|avant la remise|trois jours|commission","pts":4}],"articles":[{"code":"CP","article":"248","label":"Art. 248 CP (corruption)","pts":5}],"faille":"La défense ne conteste pas la remise d'argent.","concede":"L'autorisation était signée, soit. Mais pourquoi accepter de l'argent dans un café ?"},{"name":"L'origine des fonds","adverse":"Un remboursement de prêt ? Aucune reconnaissance de dette, aucun écrit. Cette explication est inventée.","prompt":"Justifiez la remise.","options":[{"label":"Preuve du prêt","detail":"Relevé bancaire du retrait, témoin du prêt, relation de voisinage ancienne.","pts":16,"speech":"Le relevé bancaire de mon client montre un retrait de 5 000 Dirhams six mois plus tôt, exactement le montant remis. Son épouse et un voisin attestent du prêt. Entre anciens voisins, un prêt sans écrit n'a rien d'exceptionnel. L'accusation, à qui incombe la preuve, ne démontre pas que cette somme serait le prix d'un acte de la fonction.","ok":["Relevé bancaire","Attestations","Charge de la preuve sur l'accusation"],"ko":["Les attestations émanent de proches"]},{"label":"Garder le silence","detail":"Refuser de s'expliquer.","pts":5,"speech":"Mon client n'a pas à se justifier.","ok":["Droit au silence"],"ko":["Laisse l'accusation sans contradiction"]}],"concepts":[{"label":"Relevé bancaire / montant identique","re":"releve|retrait|banc|5 000","pts":5,"key":true},{"label":"Témoins du prêt","re":"attest|temoin|voisin|epouse","pts":4},{"label":"Charge de la preuve sur l'accusation","re":"charge de la preuve|accusation|ministere public|prouver","pts":3}],"articles":[{"code":"CP","article":"248","label":"Art. 248 CP","pts":2}],"faille":"La défense n'apporte aucune justification.","concede":"Le relevé est troublant, je l'admets."},{"name":"La peine","adverse":"Le parquet requiert trois ans d'emprisonnement et l'amende maximale.","prompt":"Plaidez subsidiairement.","options":[{"label":"Circonstances atténuantes","detail":"Carrière sans reproche, montant modeste, doute sur la contrepartie : art. 146.","pts":15,"speech":"Subsidiairement, mon client compte vingt ans de service sans la moindre sanction. Le montant est modeste et l'acte administratif a été pris régulièrement, sur avis collégial. L'article 146 permet au tribunal d'accorder les circonstances atténuantes lorsque la peine prévue paraît excessive au regard de la culpabilité.","ok":["Cite l'article 146","Dossier administratif","Régularité de l'acte"],"ko":[]},{"label":"Demander la clémence","detail":"Invoquer la famille du prévenu.","pts":6,"speech":"Mon client a quatre enfants à charge.","ok":["Humain"],"ko":["Aucun fondement juridique"]}],"concepts":[{"label":"Circonstances atténuantes","re":"attenuant|146","pts":6,"key":true},{"label":"Carrière sans reproche","re":"carriere|sans (reproche|sanction)|vingt ans","pts":4},{"label":"Acte régulier","re":"regulier|commission|collegial","pts":3}],"articles":[{"code":"CP","article":"146","label":"Art. 146 CP","pts":3}],"faille":"La défense n'a rien à faire valoir sur la peine.","concede":"Le dossier administratif est irréprochable."}],"verdicts":[{"min":75,"text":"La Chambre, attendu que l'autorisation avait été accordée avant la remise des fonds sur avis de la commission et que le lien entre l'avantage reçu et un acte de la fonction n'est pas établi (article 248) ; Par ces motifs : acquitte Hassan T."},{"min":45,"text":"La Chambre, attendu un doute sérieux sur la cause de la remise ; Par ces motifs : acquitte l'accusé au bénéfice du doute."},{"min":0,"text":"La Chambre, attendu que la remise d'argent dans ces circonstances caractérise la corruption ; Par ces motifs : condamne Hassan T. à deux ans d'emprisonnement et 10 000 Dirhams d'amende."}]},{"id":"abandon-famille","matiere":"penal","title":"Mme Kabbaj c/ Omar B.","court":"Tribunal de première instance de Meknès — chambre correctionnelle","object":"Abandon de famille : non-paiement d'une pension alimentaire fixée par jugement.","you":"Avocat de la partie civile (Mme Kabbaj)","adverseName":"Avocat d'Omar B.","facts":"Par jugement exécutoire notifié en janvier 2025, Omar B. a été condamné à verser 2 500 DH par mois pour l'entretien de ses deux enfants. Il n'a rien payé depuis février. Il invoque la perte de son emploi en mars, mais a acheté une voiture d'occasion en avril et publie régulièrement des photos de voyages.","rounds":[{"name":"Les éléments du délit","adverse":"Monsieur le Président, mon client n'a jamais refusé de payer : il ne le peut plus. Ce n'est pas un délit, c'est une difficulté.","prompt":"Établissez les éléments du délit.","options":[{"label":"Décision exécutoire et omission volontaire","detail":"Omission volontaire de verser la pension fixée par décision exécutoire (art. 480 CP), applicable à l'entretien des enfants (art. 202 CF).","pts":18,"speech":"L'article 480 du Code pénal punit quiconque, au mépris d'une décision de justice exécutoire, omet volontairement de verser la pension fixée à ses descendants. L'article 202 du Code de la famille rend ces dispositions applicables à celui qui cesse d'entretenir ses enfants sans motif valable. Le jugement est exécutoire et notifié en janvier ; aucun paiement depuis février. Tous les éléments sont réunis.","ok":["Cite les articles 480 CP et 202 CF","Décision exécutoire notifiée","Durée du non-paiement"],"ko":[]},{"label":"Insister sur les enfants","detail":"Décrire la situation des enfants.","pts":7,"speech":"Les enfants manquent de tout depuis des mois.","ok":["Touchant"],"ko":["Ne démontre pas le délit"]}],"concepts":[{"label":"Décision exécutoire notifiée","re":"executoire|jugement|notifi|decision","pts":5,"key":true},{"label":"Omission volontaire","re":"volontaire|omission|refus","pts":4},{"label":"Entretien des enfants","re":"enfants?|entretien|pension","pts":3}],"articles":[{"code":"CP","article":"480","label":"Art. 480 CP (abandon de famille)","pts":4},{"code":"CF","article":"202","label":"Art. 202 CF (renvoi)","pts":2}],"faille":"La partie civile ne caractérise pas l'intention.","concede":"Le jugement est exécutoire, soit ; mais le non-paiement n'est pas volontaire."},{"name":"L'impossibilité de payer","adverse":"Mon client a perdu son emploi en mars. Il n'a pas les moyens de payer : l'omission n'est pas volontaire.","prompt":"Répondez sur l'insolvabilité alléguée.","options":[{"label":"Insolvabilité démentie par les faits","detail":"Non-paiement dès février, avant la perte d'emploi ; voiture achetée en avril ; voyages.","pts":17,"speech":"Le non-paiement a commencé en février, un mois avant la perte d'emploi invoquée. En avril, M. B. a acheté une voiture ; ses publications montrent des voyages. Celui qui trouve de quoi acheter une voiture trouve de quoi nourrir ses enfants : l'omission est volontaire. S'il était réellement sans ressources, il lui appartenait de demander la révision de la pension, ce qu'il n'a jamais fait.","ok":["Chronologie","Dépenses incompatibles","Absence de demande de révision"],"ko":[]},{"label":"Contester le licenciement","detail":"Demander la preuve du licenciement.","pts":9,"speech":"Nous demandons la lettre de licenciement.","ok":["Exige une preuve"],"ko":["N'utilise pas les dépenses du prévenu"]}],"concepts":[{"label":"Dépenses incompatibles","re":"voiture|voyage|achat|depens","pts":5,"key":true},{"label":"Chronologie défavorable","re":"fevrier|avant|chronolog","pts":4},{"label":"Pas de demande de révision","re":"revision|reviser","pts":3}],"articles":[{"code":"CP","article":"480","label":"Art. 480 CP (omission volontaire)","pts":3}],"faille":"La partie civile ne conteste pas la perte d'emploi.","concede":"La voiture est un fait gênant, je l'admets."},{"name":"Les demandes de la partie civile","adverse":"La partie civile réclame des dommages-intérêts en plus des arriérés : c'est excessif.","prompt":"Plaidez sur la réparation.","options":[{"label":"Arriérés et préjudice","detail":"Arriérés de pension et dommages pour le préjudice des enfants (art. 77 DOC) ; demande d'exécution.","pts":15,"speech":"Ma cliente demande le paiement des arriérés, soit neuf mois de pension, et 10 000 Dirhams de dommages-intérêts en réparation du préjudice causé volontairement, au sens de l'article 77 du DOC : frais d'emprunt, scolarité interrompue d'activités, angoisse des enfants.","ok":["Arriérés chiffrés","Cite l'article 77 DOC","Préjudice décrit"],"ko":[]},{"label":"Ne demander que les arriérés","detail":"Limiter à la pension due.","pts":9,"speech":"Ma cliente ne demande que les arriérés.","ok":["Modéré"],"ko":["Renonce au préjudice"]}],"concepts":[{"label":"Arriérés de pension","re":"arriere|neuf mois|pension due","pts":5,"key":true},{"label":"Préjudice causé","re":"prejudice|dommage","pts":4}],"articles":[{"code":"DOC","article":"77","label":"Art. 77 DOC","pts":3}],"faille":"Les demandes ne sont pas justifiées.","concede":"Les arriérés sont dus."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le prévenu a omis volontairement de verser la pension fixée par un jugement exécutoire, ses dépenses démentant l'insolvabilité alléguée (article 480 CP) ; Par ces motifs : le condamne à quatre mois d'emprisonnement avec sursis, au paiement des arriérés et à 10 000 Dirhams de dommages-intérêts."},{"min":45,"text":"Le Tribunal, attendu l'omission volontaire ; Par ces motifs : condamne le prévenu à une amende et au paiement des arriérés."},{"min":0,"text":"Le Tribunal, attendu un doute sur le caractère volontaire du défaut de paiement ; Par ces motifs : relaxe le prévenu."}]},{"id":"licenciement-economique","matiere":"travail","title":"Salariés de Confection Atlas c/ Confection Atlas SARL","court":"Tribunal de première instance de Tanger — chambre sociale","object":"Licenciement collectif pour motif économique sans autorisation du gouverneur.","you":"Avocat des salariés","adverseName":"Avocat de Confection Atlas","facts":"Confection Atlas, qui emploie 45 salariés, a licencié 12 ouvrières en invoquant la perte d'un client européen. Elle n'a ni consulté les délégués du personnel ni demandé l'autorisation du gouverneur. Les salariées, de 4 à 11 ans d'ancienneté, réclament leurs indemnités et des dommages-intérêts.","rounds":[{"name":"La procédure de licenciement économique","adverse":"Monsieur le Président, la perte du principal client est réelle. L'entreprise n'avait pas d'autre choix que de réduire ses effectifs.","prompt":"Contestez la régularité du licenciement.","options":[{"label":"Consultation et autorisation obligatoires","detail":"Plus de 10 salariés : information et consultation des délégués (art. 66) et autorisation du gouverneur (art. 67).","pts":18,"speech":"Le motif économique ne dispense pas de la procédure. L'article 66 du Code du travail impose à l'entreprise de dix salariés ou plus d'informer et de consulter les délégués du personnel avant tout licenciement économique ; l'article 67 subordonne ce licenciement à l'autorisation du gouverneur de la province. Confection Atlas, avec 45 salariés, n'a fait ni l'un ni l'autre.","ok":["Cite les articles 66 et 67","Seuil de dix salariés","Double manquement"],"ko":[]},{"label":"Contester le motif","detail":"Soutenir que le client n'a pas été perdu.","pts":8,"speech":"Le client n'a pas été perdu ; l'entreprise a seulement réduit ses commandes.","ok":["Vérifie le motif"],"ko":["Sans preuve","Néglige le vice de procédure"]}],"concepts":[{"label":"Autorisation du gouverneur","re":"gouverneur|autorisation","pts":6,"key":true},{"label":"Consultation des délégués","re":"delegues?|consult|inform","pts":4},{"label":"Seuil de dix salariés","re":"dix salaries|10 salaries|45","pts":3}],"articles":[{"code":"CT","article":"66","label":"Art. 66 CT (consultation)","pts":3},{"code":"CT","article":"67","label":"Art. 67 CT (autorisation)","pts":4}],"faille":"Les salariées ne contestent pas le motif économique.","concede":"La procédure n'a pas été suivie, soit. Le motif reste réel."},{"name":"Les conséquences","adverse":"Même irrégulier, le licenciement repose sur un motif réel : les salariées n'ont droit qu'aux indemnités légales, pas à des dommages-intérêts.","prompt":"Plaidez sur les droits des salariées.","options":[{"label":"Indemnités et dommages-intérêts","detail":"Indemnités de préavis et de licenciement dans tous les cas (art. 70) ; sans autorisation, dommages-intérêts de l'article 41 sur décision judiciaire.","pts":17,"speech":"L'article 70 du Code du travail est clair : les salariés ont droit aux indemnités de préavis et de licenciement, avec ou sans autorisation. Mais lorsque le licenciement intervient sans l'autorisation requise, ils peuvent en outre obtenir, sur décision judiciaire, les dommages-intérêts de l'article 41. C'est précisément notre cas.","ok":["Cite les articles 70 et 41","Cumul indemnités / dommages"],"ko":[]},{"label":"Demander la réintégration","detail":"Exiger le retour des salariées.","pts":9,"speech":"Les salariées demandent leur réintégration immédiate.","ok":["Ambitieux"],"ko":["Peu réaliste après la perte du client"]}],"concepts":[{"label":"Dommages-intérêts en l'absence d'autorisation","re":"dommages|sans (l.)?autorisation","pts":6,"key":true},{"label":"Indemnités de préavis et de licenciement","re":"preavis|indemnit","pts":4}],"articles":[{"code":"CT","article":"70","label":"Art. 70 CT","pts":4},{"code":"CT","article":"41","label":"Art. 41 CT","pts":2}],"faille":"Les salariées ne distinguent pas les indemnités.","concede":"Le texte prévoit bien les dommages-intérêts."},{"name":"Le calcul","adverse":"Les salariées réclament des montants fantaisistes.","prompt":"Chiffrez les indemnités.","options":[{"label":"Calcul selon l'ancienneté","detail":"96 heures par an jusqu'à 5 ans, 144 heures de 6 à 10 ans (art. 53) ; tableau par salariée.","pts":16,"speech":"L'indemnité de licenciement se calcule selon l'article 53 : 96 heures de salaire par année pour les cinq premières années, 144 heures de la sixième à la dixième. Nous produisons un tableau individuel pour chacune des douze salariées, avec salaire et ancienneté, auquel s'ajoutent le préavis et les dommages-intérêts.","ok":["Cite l'article 53","Tableau individuel"],"ko":[]},{"label":"Montant forfaitaire","detail":"Demander 100 000 DH par salariée.","pts":5,"speech":"Chaque salariée réclame 100 000 Dirhams.","ok":["Simple"],"ko":["Sans calcul"]}],"concepts":[{"label":"Calcul selon l'ancienneté","re":"96 heures|144 heures|anciennet|par annee","pts":5,"key":true},{"label":"Tableau individuel","re":"tableau|chacune|individuel","pts":4}],"articles":[{"code":"CT","article":"53","label":"Art. 53 CT (indemnité de licenciement)","pts":4}],"faille":"Aucun calcul n'est présenté.","concede":"Le calcul est conforme au texte."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le licenciement économique est intervenu sans consultation des délégués ni autorisation du gouverneur (articles 66 et 67) ; Par ces motifs : condamne Confection Atlas à verser à chaque salariée les indemnités de préavis et de licenciement et des dommages-intérêts (articles 70 et 41)."},{"min":45,"text":"Le Tribunal, attendu l'irrégularité de la procédure ; Par ces motifs : alloue les indemnités légales et des dommages-intérêts réduits."},{"min":0,"text":"Le Tribunal, attendu la réalité du motif économique ; Par ces motifs : alloue les seules indemnités légales."}]},{"id":"maternite","matiere":"travail","title":"Mme Sabri c/ Cabinet Comptable Amine","court":"Tribunal de première instance de Rabat — chambre sociale","object":"Licenciement d'une salariée enceinte pour absences répétées.","you":"Avocat de la salariée (Mme Sabri)","adverseName":"Avocat du cabinet","facts":"Mme Sabri, comptable depuis trois ans, a informé son employeur de sa grossesse par certificat médical en février. En avril, elle a été licenciée pour « absences répétées perturbant le service ». Ses quatre absences étaient couvertes par des certificats médicaux liés à sa grossesse.","rounds":[{"name":"La protection de la salariée enceinte","adverse":"Monsieur le Président, mon client a licencié une salariée absente, pour la bonne marche du cabinet. La grossesse n'est pas en cause.","prompt":"Invoquez la protection légale.","options":[{"label":"Interdiction de rompre","detail":"L'employeur ne peut rompre le contrat d'une salariée enceinte, grossesse attestée par certificat (art. 159).","pts":18,"speech":"L'article 159 du Code du travail interdit à l'employeur de rompre le contrat de travail d'une salariée dont la grossesse est attestée par certificat médical, pendant la grossesse et les quatorze semaines suivant l'accouchement. Mme Sabri avait remis son certificat en février ; le licenciement d'avril intervient en pleine période de protection.","ok":["Cite l'article 159","Grossesse attestée et connue","Licenciement pendant la protection"],"ko":[]},{"label":"Plaider la discrimination","detail":"Soutenir que le cabinet ne veut pas de mères.","pts":8,"speech":"Le cabinet ne voulait pas d'une jeune mère dans son équipe.","ok":["Intuition plausible"],"ko":["Intention difficile à prouver","Le texte est plus simple"]}],"concepts":[{"label":"Interdiction de rompre pendant la grossesse","re":"grossesse|enceinte|interdi|protection","pts":6,"key":true},{"label":"Certificat médical remis","re":"certificat","pts":4},{"label":"Période de quatorze semaines","re":"quatorze semaines|14 semaines","pts":3}],"articles":[{"code":"CT","article":"159","label":"Art. 159 CT (protection de la grossesse)","pts":5}],"faille":"La salariée ne conteste pas ses absences.","concede":"La protection existe, soit. Mais elle ne couvre pas une faute."},{"name":"Les absences","adverse":"Les absences répétées constituent une faute qui justifie le licenciement, même pendant la grossesse.","prompt":"Répondez sur les absences.","options":[{"label":"Absences justifiées","detail":"Chaque absence couverte par un certificat lié à la grossesse : aucune faute ; protection renforcée en cas d'état pathologique.","pts":16,"speech":"Chacune des quatre absences est couverte par un certificat médical lié à la grossesse, transmis dans les délais. Une absence justifiée n'est pas une faute. L'article 159 protège d'ailleurs aussi la salariée pendant la suspension due à un état pathologique lié à la grossesse : invoquer ces absences, c'est licencier en raison de la grossesse elle-même.","ok":["Absences justifiées par certificats","Lien avec la grossesse"],"ko":["Ne produit pas les accusés de réception des certificats"]},{"label":"Minimiser","detail":"Dire que quatre absences, c'est peu.","pts":7,"speech":"Quatre absences en deux mois, ce n'est pas grand-chose.","ok":["—"],"ko":["Ne démontre pas la justification"]}],"concepts":[{"label":"Absences justifiées médicalement","re":"justifi|certificats?","pts":6,"key":true},{"label":"Lien avec la grossesse","re":"lie(es)? a la grossesse|pathologi|grossesse","pts":4}],"articles":[{"code":"CT","article":"159","label":"Art. 159 CT (état pathologique)","pts":3}],"faille":"Rien ne justifie les absences.","concede":"Les certificats existent, je l'admets."},{"name":"Les droits de la salariée","adverse":"Subsidiairement, la salariée ne peut prétendre qu'aux indemnités minimales.","prompt":"Chiffrez vos demandes.","options":[{"label":"Licenciement abusif et congé de maternité","detail":"Dommages-intérêts (art. 41), indemnités, et rappel des droits liés au congé de 14 semaines (art. 152).","pts":16,"speech":"Le licenciement étant interdit, il est abusif : Mme Sabri a droit aux dommages-intérêts de l'article 41, à l'indemnité de licenciement et au préavis. Elle a en outre été privée du congé de maternité de quatorze semaines prévu par l'article 152, dont elle aurait bénéficié en restant dans l'entreprise. Nous chiffrons l'ensemble à 96 000 Dirhams.","ok":["Cite les articles 41 et 152","Chiffrage global"],"ko":[]},{"label":"Demander la réintégration seule","detail":"Exiger le retour au poste.","pts":9,"speech":"Mme Sabri demande sa réintégration.","ok":["Option légale"],"ko":["Ne chiffre rien en cas de refus"]}],"concepts":[{"label":"Dommages-intérêts pour licenciement abusif","re":"abusi|dommages","pts":5,"key":true},{"label":"Congé de maternité","re":"conge de maternite|quatorze semaines|14 semaines","pts":4},{"label":"Chiffrage","re":"dirhams|dh|chiffr","pts":3}],"articles":[{"code":"CT","article":"41","label":"Art. 41 CT","pts":3},{"code":"CT","article":"152","label":"Art. 152 CT (congé de maternité)","pts":2}],"faille":"Les demandes ne sont pas chiffrées.","concede":"Le chiffrage est cohérent."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la salariée, dont la grossesse était attestée par certificat médical, a été licenciée pendant la période de protection pour des absences justifiées (article 159) ; Par ces motifs : déclare le licenciement abusif et condamne le cabinet à 96 000 Dirhams."},{"min":45,"text":"Le Tribunal, attendu le caractère abusif du licenciement ; Par ces motifs : alloue 60 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu que les absences n'étaient pas toutes justifiées ; Par ces motifs : alloue les seules indemnités légales."}]},{"id":"harcelement","matiere":"travail","title":"Mme Ouazzani c/ Société Média Plus","court":"Tribunal de première instance de Casablanca — chambre sociale","object":"Départ d'une salariée victime de harcèlement sexuel : requalification en licenciement abusif.","you":"Avocat de la salariée (Mme Ouazzani)","adverseName":"Avocat de Média Plus","facts":"Mme Ouazzani, chargée de communication depuis cinq ans, a quitté son poste après des mois de messages et de propositions insistantes de son directeur. Elle a adressé une lettre expliquant qu'elle partait pour ce motif. L'employeur soutient qu'il s'agit d'une démission. Deux collègues ont reçu ses confidences et elle a conservé des messages.","rounds":[{"name":"Démission ou licenciement ?","adverse":"Monsieur le Président, la salariée est partie d'elle-même : c'est une démission. Elle n'a droit à rien.","prompt":"Requalifiez la rupture.","options":[{"label":"Départ assimilé à un licenciement abusif","detail":"Le harcèlement sexuel est une faute grave de l'employeur ; le départ du salarié pour ce motif est assimilé à un licenciement abusif (art. 40).","pts":18,"speech":"L'article 40 du Code du travail range le harcèlement sexuel parmi les fautes graves de l'employeur et dispose que le fait, pour le salarié, de quitter son travail en raison de l'une de ces fautes est assimilé à un licenciement abusif, dès lors que la faute est établie. La lettre de Mme Ouazzani indique précisément ce motif. Il n'y a pas démission, mais licenciement abusif.","ok":["Cite l'article 40","Lettre motivée de départ"],"ko":[]},{"label":"Invoquer la démission forcée","detail":"Soutenir que la démission était contrainte.","pts":9,"speech":"Ma cliente a été contrainte de démissionner.","ok":["Idée juste"],"ko":["Sans fondement textuel précis"]}],"concepts":[{"label":"Faute grave de l'employeur : harcèlement sexuel","re":"harcelement|faute grave de l.employeur","pts":6,"key":true},{"label":"Départ assimilé à un licenciement abusif","re":"assimil|licenciement abusif","pts":5},{"label":"Pas une démission","re":"pas (une )?demission|demission","pts":2}],"articles":[{"code":"CT","article":"40","label":"Art. 40 CT (fautes graves de l'employeur)","pts":5}],"faille":"La salariée ne conteste pas être partie volontairement.","concede":"Le texte assimile ce départ à un licenciement, soit ; encore faut-il prouver le harcèlement."},{"name":"La preuve du harcèlement","adverse":"Aucune preuve : des messages ambigus et des collègues qui rapportent des ouï-dire.","prompt":"Prouvez le harcèlement.","options":[{"label":"Faisceau de preuves","detail":"Messages datés et explicites, témoignages concordants, alerte des RH restée sans suite.","pts":17,"speech":"Nous produisons quarante-deux messages datés sur six mois, dont plusieurs explicites ; deux collègues attestent des confidences de Mme Ouazzani et de son état de détresse ; un courriel d'alerte aux ressources humaines, resté sans réponse, date de trois mois avant son départ. Ces éléments concordants établissent la faute, exigée par l'article 40.","ok":["Messages datés","Témoignages","Alerte RH ignorée"],"ko":[]},{"label":"Demander une enquête","detail":"Solliciter une enquête du tribunal.","pts":9,"speech":"Nous demandons au tribunal d'ordonner une enquête.","ok":["Prudent"],"ko":["Ne produit pas ses propres preuves"]}],"concepts":[{"label":"Messages conservés","re":"messages?|sms|whatsapp|courriels?","pts":5,"key":true},{"label":"Témoignages","re":"temoign|attest|collegues","pts":4},{"label":"Alerte de l'employeur","re":"alerte|ressources humaines|rh|signal","pts":3}],"articles":[{"code":"CT","article":"40","label":"Art. 40 CT (faute établie)","pts":3}],"faille":"Les preuves sont insuffisantes.","concede":"Les messages sont nombreux, je l'admets."},{"name":"La réparation","adverse":"La salariée réclame des sommes déraisonnables.","prompt":"Plaidez sur la réparation.","options":[{"label":"Dommages-intérêts et indemnités","detail":"Dommages-intérêts pour licenciement abusif (art. 41), indemnités de licenciement et de préavis, préjudice moral.","pts":16,"speech":"Le départ valant licenciement abusif, Mme Ouazzani a droit aux dommages-intérêts de l'article 41, à l'indemnité de licenciement pour ses cinq ans d'ancienneté et au préavis. Le préjudice moral, attesté par un suivi psychologique, doit également être réparé.","ok":["Cite l'article 41","Préjudice moral documenté"],"ko":[]},{"label":"Un montant global","detail":"Demander 300 000 DH sans détail.","pts":6,"speech":"Ma cliente réclame 300 000 Dirhams.","ok":["—"],"ko":["Sans détail"]}],"concepts":[{"label":"Dommages-intérêts pour licenciement abusif","re":"dommages|abusi","pts":5,"key":true},{"label":"Préjudice moral","re":"moral|psycholog","pts":4}],"articles":[{"code":"CT","article":"41","label":"Art. 41 CT","pts":4}],"faille":"Rien n'est justifié.","concede":"La réparation demandée est mesurée."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le harcèlement sexuel est établi par les messages et témoignages et que le départ de la salariée pour ce motif est assimilé à un licenciement abusif (article 40) ; Par ces motifs : condamne Média Plus aux indemnités légales et à 120 000 Dirhams de dommages-intérêts."},{"min":45,"text":"Le Tribunal, attendu la faute grave de l'employeur ; Par ces motifs : alloue les indemnités et 60 000 Dirhams de dommages-intérêts."},{"min":0,"text":"Le Tribunal, attendu que le harcèlement n'est pas suffisamment établi ; Par ces motifs : qualifie la rupture de démission et rejette la demande."}]},{"id":"cdd-requalification","matiere":"travail","title":"M. Bakkali c/ Hôtel Riad Palace","court":"Tribunal de première instance de Marrakech — chambre sociale","object":"Requalification de CDD successifs en CDI et rupture abusive.","you":"Avocat du salarié (M. Bakkali)","adverseName":"Avocat de l'hôtel","facts":"M. Bakkali est réceptionniste à l'hôtel Riad Palace depuis 2021, sous sept contrats à durée déterminée successifs de six mois, sans interruption. Le poste existe toute l'année. En décembre 2024, l'hôtel ne renouvelle pas son contrat, « arrivé à terme ».","rounds":[{"name":"La nature du contrat","adverse":"Monsieur le Président, le dernier contrat est arrivé à son terme. Il n'y a ni licenciement ni indemnité.","prompt":"Demandez la requalification.","options":[{"label":"CDD hors des cas légaux","detail":"Le CDD n'est permis que lorsque la relation ne peut être durable et dans des cas limités (art. 16) ; poste permanent, contrats successifs.","pts":17,"speech":"L'article 16 du Code du travail ne permet le contrat à durée déterminée que dans les cas où la relation de travail ne peut avoir une durée indéterminée, et dans des hypothèses limitées : remplacement, accroissement temporaire, travail saisonnier. Un poste de réceptionniste occupé toute l'année, pendant plus de trois ans et sept contrats successifs, n'entre dans aucune. La relation doit être requalifiée en contrat à durée indéterminée.","ok":["Cite l'article 16","Poste permanent","Durée de trois ans"],"ko":[]},{"label":"Plaider l'injustice","detail":"Insister sur la précarité.","pts":6,"speech":"Mon client a vécu trois ans dans la précarité.","ok":["Humain"],"ko":["Pas d'argument de droit"]}],"concepts":[{"label":"Poste permanent / pas un cas légal de CDD","re":"permanent|toute l.annee|duree indeterminee|cas (limites|prevus)","pts":6,"key":true},{"label":"Contrats successifs","re":"successi|sept contrats|renouvel","pts":4},{"label":"Requalification en CDI","re":"requalif|cdi","pts":3}],"articles":[{"code":"CT","article":"16","label":"Art. 16 CT (cas du CDD)","pts":5}],"faille":"Le salarié ne conteste pas la validité des contrats signés.","concede":"Le poste est permanent, soit ; mais l'hôtel a lancé une nouvelle activité."},{"name":"La nouvelle activité","adverse":"L'hôtel avait ouvert un nouvel établissement en 2021 : la loi autorise un CDD dans ce cas.","prompt":"Répondez sur l'exception invoquée.","options":[{"label":"Limite d'un an renouvelable une fois","detail":"L'article 17 limite le CDD lié à une ouverture à un an, renouvelable une fois ; au-delà, CDI.","pts":17,"speech":"L'article 17 permet, lors de l'ouverture d'un établissement, un CDD d'une durée maximale d'un an renouvelable une seule fois. Passé ce délai, le contrat devient à durée indéterminée. M. Bakkali a travaillé plus de trois ans : même dans l'hypothèse la plus favorable à l'hôtel, le contrat était devenu à durée indéterminée dès 2023.","ok":["Cite l'article 17","Calcule la durée maximale"],"ko":[]},{"label":"Nier l'ouverture","detail":"Contester que l'établissement fût nouveau.","pts":8,"speech":"L'hôtel existait déjà avant 2021.","ok":["Possible"],"ko":["Inutile si la durée maximale est dépassée"]}],"concepts":[{"label":"Durée maximale dépassée","re":"un an|une seule fois|deux ans|maximum|depasse","pts":6,"key":true},{"label":"Devient un CDI","re":"duree indeterminee|cdi|devient","pts":4}],"articles":[{"code":"CT","article":"17","label":"Art. 17 CT (CDD d'ouverture)","pts":5}],"faille":"Le salarié ne répond pas sur l'ouverture de l'établissement.","concede":"La durée est dépassée, je l'admets."},{"name":"Les conséquences de la rupture","adverse":"Même requalifié, le contrat a pris fin régulièrement : aucun dommage.","prompt":"Plaidez sur les conséquences.","options":[{"label":"Rupture abusive d'un CDI","detail":"Non-renouvellement = licenciement sans motif ni procédure : dommages-intérêts (art. 41) et indemnité (art. 52).","pts":16,"speech":"Le contrat étant à durée indéterminée, le non-renouvellement est un licenciement sans motif ni procédure : il est abusif. M. Bakkali a droit aux dommages-intérêts de l'article 41 et à l'indemnité de licenciement de l'article 52, due après six mois de travail.","ok":["Cite les articles 41 et 52","Qualification de licenciement"],"ko":[]},{"label":"Demander un nouveau contrat","detail":"Exiger un CDD de plus.","pts":4,"speech":"Mon client demande la signature d'un nouveau contrat.","ok":["—"],"ko":["Renonce à la requalification"]}],"concepts":[{"label":"Licenciement abusif","re":"abusi|licenciement","pts":5,"key":true},{"label":"Indemnités et dommages","re":"indemnit|dommages","pts":4}],"articles":[{"code":"CT","article":"41","label":"Art. 41 CT","pts":3},{"code":"CT","article":"52","label":"Art. 52 CT","pts":2}],"faille":"Aucune conséquence n'est tirée.","concede":"La rupture est abusive."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le poste est permanent et que la durée maximale du CDD est largement dépassée (articles 16 et 17) ; Par ces motifs : requalifie la relation en contrat à durée indéterminée et condamne l'hôtel aux indemnités et à des dommages-intérêts pour licenciement abusif."},{"min":45,"text":"Le Tribunal, attendu la requalification en CDI ; Par ces motifs : alloue l'indemnité de licenciement et des dommages-intérêts réduits."},{"min":0,"text":"Le Tribunal, attendu que les contrats étaient justifiés par l'ouverture de l'établissement ; Par ces motifs : rejette la demande."}]},{"id":"contrefacon","matiere":"affaires","title":"Argania Cosmétiques SA c/ Bazar Al Baraka","court":"Tribunal de commerce d'Agadir","object":"Contrefaçon de marque : vente de produits imitant une marque enregistrée.","you":"Avocat du titulaire de la marque (Argania Cosmétiques)","adverseName":"Avocat de Bazar Al Baraka","facts":"Argania Cosmétiques est titulaire de la marque enregistrée « ARGANIA » pour des huiles et crèmes. Le Bazar Al Baraka vend des huiles sous la marque « ARGANIYA », avec un flacon et une étiquette presque identiques. En janvier, Argania lui a adressé une lettre recommandée de mise en demeure ; un constat d'huissier de mars montre que la vente continue.","rounds":[{"name":"L'atteinte à la marque","adverse":"Monsieur le Président, « Arganiya » n'est pas « Argania ». Les noms sont différents ; il n'y a aucune contrefaçon.","prompt":"Caractérisez la contrefaçon.","options":[{"label":"Usage d'un signe similaire pour des produits identiques","detail":"Interdiction de reproduire ou d'imiter la marque pour des produits identiques sans autorisation (art. 154 et 201 loi 17-97).","pts":17,"speech":"L'article 154 de la loi 17-97 interdit, sans l'autorisation du titulaire, la reproduction, l'usage ou l'apposition d'une marque, même avec l'ajout de mots, ainsi que l'usage d'une marque reproduite, pour des produits identiques. L'article 201 qualifie de contrefaçon toute atteinte à ces droits. Une lettre ajoutée à « Argania », sur le même produit, avec le même flacon, ne crée aucune différence pour le consommateur.","ok":["Cite les articles 154 et 201","Produits identiques","Imitation du conditionnement"],"ko":[]},{"label":"Comparer les chiffres d'affaires","detail":"Montrer que le bazar profite de la notoriété.","pts":8,"speech":"Le bazar profite de la notoriété de notre marque.","ok":["Idée de parasitisme"],"ko":["Ne caractérise pas l'atteinte à la marque"]}],"concepts":[{"label":"Imitation de la marque enregistrée","re":"imitation|reprodu|similaire|ajout|une lettre","pts":6,"key":true},{"label":"Produits identiques","re":"produits? identiques?|meme produit|huiles?","pts":4},{"label":"Confusion du consommateur / conditionnement","re":"confusion|consommateur|flacon|etiquette","pts":4}],"articles":[{"code":"L17-97","article":"154","label":"Art. 154 loi 17-97 (droits sur la marque)","pts":4},{"code":"L17-97","article":"201","label":"Art. 201 loi 17-97 (contrefaçon)","pts":2}],"faille":"La demande ne démontre aucune similitude.","concede":"Les signes sont proches, soit. Mais mon client n'est qu'un revendeur."},{"name":"La bonne foi du revendeur","adverse":"Mon client n'a pas fabriqué ces produits : il les a achetés à un grossiste. Le revendeur n'est pas responsable.","prompt":"Répondez sur la responsabilité du revendeur.","options":[{"label":"Revendeur informé","detail":"Le revendeur répond s'il connaissait ou avait des raisons de connaître la contrefaçon (art. 201) : mise en demeure de janvier, constat de mars.","pts":17,"speech":"L'article 201 exonère le vendeur qui n'a pas fabriqué le produit, sauf s'il agissait en connaissance de cause ou avait des raisons sérieuses de connaître la contrefaçon. Or la mise en demeure de janvier l'a informé ; le constat d'huissier de mars montre qu'il a continué à vendre. Sa responsabilité est donc pleinement engagée.","ok":["Cite l'article 201 (connaissance)","Mise en demeure","Constat postérieur"],"ko":[]},{"label":"Viser le grossiste","detail":"Demander la mise en cause du grossiste.","pts":9,"speech":"Nous demandons la mise en cause du grossiste.","ok":["Remonte la filière"],"ko":["N'écarte pas la responsabilité du bazar"]}],"concepts":[{"label":"Connaissance après mise en demeure","re":"mise en demeure|informe|connaiss|savait","pts":6,"key":true},{"label":"Constat d'huissier postérieur","re":"constat|huissier|continue|mars","pts":4}],"articles":[{"code":"L17-97","article":"201","label":"Art. 201 loi 17-97 (vendeur de bonne foi)","pts":4}],"faille":"La demande ne prouve pas que mon client savait.","concede":"La mise en demeure existe, je l'admets."},{"name":"Les mesures et la réparation","adverse":"La demande réclame 500 000 Dirhams et la destruction du stock : c'est disproportionné pour un petit bazar.","prompt":"Plaidez sur les mesures.","options":[{"label":"Cessation, destruction et dommages justifiés","detail":"Interdiction sous astreinte, destruction du stock, dommages : perte effective et gains manqués (art. 98 DOC).","pts":15,"speech":"Nous demandons l'interdiction de vente sous astreinte et la destruction du stock saisi. Les dommages-intérêts se calculent selon l'article 98 du DOC : pertes effectives et gains manqués, que nous évaluons sur la base des quantités vendues relevées par l'huissier, soit 80 000 Dirhams, outre l'atteinte à l'image de la marque.","ok":["Mesures de cessation","Cite l'article 98 DOC","Chiffrage à partir du constat"],"ko":[]},{"label":"Maintenir 500 000 DH","detail":"Insister sur la valeur de la marque.","pts":6,"speech":"La marque vaut des millions ; 500 000 Dirhams est raisonnable.","ok":["—"],"ko":["Non justifié"]}],"concepts":[{"label":"Cessation / interdiction / astreinte","re":"interdi|cessation|astreinte","pts":5,"key":true},{"label":"Destruction du stock","re":"destruction|detruire|stock","pts":3},{"label":"Dommages chiffrés","re":"gains? manques?|perte|chiffr|quantites","pts":4}],"articles":[{"code":"DOC","article":"98","label":"Art. 98 DOC","pts":3}],"faille":"Les mesures sont excessives.","concede":"Les mesures demandées sont proportionnées."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le signe « Arganiya » imite la marque enregistrée pour des produits identiques et que le revendeur, mis en demeure, a poursuivi la vente (articles 154 et 201 de la loi 17-97) ; Par ces motifs : interdit la vente sous astreinte, ordonne la destruction du stock et condamne le défendeur à 80 000 Dirhams."},{"min":45,"text":"Le Tribunal, attendu la contrefaçon ; Par ces motifs : interdit la vente et alloue 30 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu la bonne foi du revendeur ; Par ces motifs : ordonne la cessation de la vente sans dommages-intérêts."}]},{"id":"abus-biens-sociaux","matiere":"affaires","title":"M. Alaoui (actionnaire) c/ M. Kettani, PDG d'Immo Prestige SA","court":"Tribunal de première instance de Casablanca — chambre correctionnelle","object":"Abus de biens sociaux par le président d'une société anonyme.","you":"Avocat de la partie civile (M. Alaoui, actionnaire à 30 %)","adverseName":"Avocat de M. Kettani","facts":"M. Kettani, président du conseil d'Immo Prestige SA, a fait payer par la société 1,1 million de DH de travaux dans sa villa personnelle, comptabilisés comme « travaux de chantier ». Le commissaire aux comptes a relevé l'anomalie. M. Kettani a remboursé 400 000 DH après le dépôt de la plainte.","rounds":[{"name":"Les éléments de l'infraction","adverse":"Monsieur le Président, il s'agit d'une erreur d'imputation comptable, aujourd'hui en cours de régularisation.","prompt":"Caractérisez l'abus de biens sociaux.","options":[{"label":"Usage des biens sociaux à des fins personnelles","detail":"Dirigeant de SA faisant, de mauvaise foi, des biens de la société un usage contraire à ses intérêts à des fins personnelles (art. 384-3° loi 17-95).","pts":18,"speech":"L'article 384 de la loi 17-95 punit les dirigeants de société anonyme qui, de mauvaise foi, font des biens ou du crédit de la société un usage qu'ils savent contraire à ses intérêts, à des fins personnelles. Payer 1,1 million de Dirhams de travaux dans sa villa avec les fonds sociaux, c'est exactement cela. Et l'enregistrement sous le libellé « travaux de chantier » révèle la volonté de dissimuler : la mauvaise foi est établie.","ok":["Cite l'article 384","Usage personnel","Dissimulation comptable = mauvaise foi"],"ko":[]},{"label":"Insister sur le montant","detail":"Souligner l'importance de la somme.","pts":8,"speech":"1,1 million de Dirhams, ce n'est pas une erreur.","ok":["Bon sens"],"ko":["Ne caractérise pas juridiquement"]}],"concepts":[{"label":"Usage contraire à l'intérêt social à des fins personnelles","re":"fins personnelles|interet (social|de la societe)|villa|usage","pts":6,"key":true},{"label":"Mauvaise foi / dissimulation","re":"mauvaise foi|dissimul|libelle|travaux de chantier","pts":5},{"label":"Qualité de dirigeant","re":"dirigeant|president|pdg","pts":2}],"articles":[{"code":"L17-95","article":"384","label":"Art. 384 loi 17-95 (abus de biens sociaux)","pts":5}],"faille":"La partie civile ne démontre pas la mauvaise foi.","concede":"Les fonds ont bien servi à la villa, soit. Mais ils sont remboursés."},{"name":"Le remboursement partiel","adverse":"Mon client a remboursé 400 000 Dirhams et s'engage à rembourser le reste. Le préjudice est réparé, l'infraction n'a plus d'objet.","prompt":"Répondez sur l'effet du remboursement.","options":[{"label":"Le délit est consommé","detail":"Le remboursement postérieur n'efface pas l'infraction ; il est partiel et tardif, après la plainte.","pts":17,"speech":"Le délit est consommé au moment de l'usage abusif des fonds. Un remboursement postérieur, intervenu seulement après la plainte, ne fait pas disparaître l'infraction : tout au plus peut-il être pris en compte pour la peine. Il est d'ailleurs partiel : 700 000 Dirhams restent dus à la société.","ok":["Infraction consommée","Remboursement tardif et partiel"],"ko":[]},{"label":"Accepter un accord","detail":"Proposer un échéancier pour le reste.","pts":8,"speech":"Mon client accepterait un échéancier pour le solde.","ok":["Pragmatique"],"ko":["Confond action pénale et transaction civile"]}],"concepts":[{"label":"Infraction consommée","re":"consomm|ne fait pas disparaitre|n.efface pas","pts":6,"key":true},{"label":"Remboursement tardif / partiel","re":"tardi|apres la plainte|partiel|700 000","pts":4}],"articles":[{"code":"L17-95","article":"384","label":"Art. 384 loi 17-95","pts":3}],"faille":"Le remboursement montre la bonne foi.","concede":"Le remboursement est tardif, je l'admets."},{"name":"La réparation","adverse":"La partie civile, simple actionnaire, ne subit aucun préjudice personnel : seule la société est lésée.","prompt":"Plaidez sur la réparation.","options":[{"label":"Restitution à la société et préjudice de l'actionnaire","detail":"Restitution du solde à la société ; dommage propre de l'actionnaire (dévalorisation, dividendes perdus) au sens de l'article 77 DOC.","pts":15,"speech":"Nous demandons que M. Kettani soit condamné à restituer à la société les 700 000 Dirhams restants. M. Alaoui subit en outre un préjudice propre : la valeur de ses actions et ses dividendes ont été amputés par ce détournement, qui constitue un dommage causé volontairement au sens de l'article 77 du DOC.","ok":["Restitution à la société","Préjudice personnel de l'actionnaire","Cite l'article 77 DOC"],"ko":["Le préjudice propre devra être chiffré"]},{"label":"Tout demander pour l'actionnaire","detail":"Réclamer 1,1 million pour M. Alaoui.","pts":5,"speech":"M. Alaoui réclame 1,1 million de Dirhams.","ok":["—"],"ko":["Confond le préjudice de la société et celui de l'actionnaire"]}],"concepts":[{"label":"Restitution à la société","re":"restitu|a la societe|700 000","pts":5,"key":true},{"label":"Préjudice propre de l'actionnaire","re":"propre|personnel|dividende|valeur des actions","pts":4}],"articles":[{"code":"DOC","article":"77","label":"Art. 77 DOC","pts":3}],"faille":"L'actionnaire n'a pas de préjudice personnel.","concede":"La distinction est juste."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le président a, de mauvaise foi, fait des biens de la société un usage contraire à ses intérêts à des fins personnelles (article 384-3° de la loi 17-95) ; Par ces motifs : le condamne à quatre mois d'emprisonnement avec sursis et 200 000 Dirhams d'amende, ordonne la restitution du solde à la société et alloue 50 000 Dirhams à la partie civile."},{"min":45,"text":"Le Tribunal, attendu l'abus de biens sociaux, atténué par le remboursement partiel ; Par ces motifs : condamne le prévenu à une amende et à la restitution du solde."},{"min":0,"text":"Le Tribunal, attendu un doute sur la mauvaise foi ; Par ces motifs : relaxe le prévenu et renvoie les parties à se pourvoir au civil."}]},{"id":"retractation","matiere":"affaires","title":"Mme Bennouna c/ MeubleShop.ma","court":"Tribunal de première instance de Rabat","object":"Droit de rétractation après un achat en ligne.","you":"Avocat de la consommatrice (Mme Bennouna)","adverseName":"Avocat de MeubleShop.ma","facts":"Mme Bennouna a acheté sur le site MeubleShop.ma un canapé standard du catalogue pour 14 000 DH. Livré le 3 mars, il ne convient pas. Le 8 mars, elle notifie sa rétractation par courriel et lettre recommandée. Le vendeur refuse : l'emballage a été ouvert et le canapé était « en promotion ». Rien n'est remboursé au bout de deux mois.","rounds":[{"name":"Le droit de rétractation","adverse":"Monsieur le Président, la cliente a ouvert l'emballage et utilisé le canapé. Une vente conclue est une vente conclue.","prompt":"Fondez le droit de rétractation.","options":[{"label":"Sept jours pour se rétracter","detail":"Vente à distance : 7 jours pour se rétracter sans justification ni pénalité (art. 36 loi 31-08) ; rétractation le 5e jour.","pts":18,"speech":"L'article 36 de la loi 31-08 accorde au consommateur un délai de sept jours pour exercer son droit de rétractation, sans avoir à se justifier ni à payer de pénalités. Livrée le 3 mars, Mme Bennouna s'est rétractée le 8 mars, par courriel et lettre recommandée : dans le délai. Ouvrir l'emballage est indispensable pour examiner un meuble ; ce n'est pas une renonciation.","ok":["Cite l'article 36","Calcul du délai","Ouverture de l'emballage sans effet"],"ko":[]},{"label":"Invoquer un défaut","detail":"Prétendre que le canapé était défectueux.","pts":6,"speech":"Le canapé présentait des défauts de couture.","ok":["Autre fondement"],"ko":["Inexact selon les faits","Inutile : la rétractation n'exige aucun motif"]}],"concepts":[{"label":"Délai de sept jours","re":"sept jours|7 jours","pts":6,"key":true},{"label":"Sans justification ni pénalité","re":"sans (avoir a se )?justifi|sans motif|penalit","pts":4},{"label":"Rétractation dans le délai","re":"8 mars|dans le delai|cinquieme jour|recommande","pts":3}],"articles":[{"code":"L31-08","article":"36","label":"Art. 36 loi 31-08 (rétractation)","pts":5}],"faille":"La demanderesse ne justifie d'aucun droit à annuler la vente.","concede":"Le délai est respecté, soit. Mais le produit était en promotion."},{"name":"Les exceptions invoquées","adverse":"Le canapé était en promotion : les produits soldés sont exclus de la rétractation.","prompt":"Répondez sur les exceptions.","options":[{"label":"Exceptions limitatives","detail":"L'article 38 énumère les exclusions (services commencés, produits personnalisés…) : ni la promotion ni l'emballage ouvert n'y figurent.","pts":17,"speech":"Les exceptions au droit de rétractation sont énumérées limitativement par l'article 38 : services commencés, produits dont le prix dépend des marchés financiers, biens confectionnés selon les spécifications du consommateur ou personnalisés, notamment. Un canapé standard du catalogue n'est pas personnalisé, et la promotion ne figure nulle part dans la liste.","ok":["Cite l'article 38","Caractère limitatif","Produit standard"],"ko":[]},{"label":"Contester la promotion","detail":"Soutenir que le prix n'était pas réduit.","pts":5,"speech":"Le prix n'était pas vraiment réduit.","ok":["—"],"ko":["Hors sujet"]}],"concepts":[{"label":"Liste limitative des exceptions","re":"limitati|enumer|exceptions?","pts":5,"key":true},{"label":"Produit standard, non personnalisé","re":"standard|catalogue|personnalis","pts":4},{"label":"La promotion n'est pas une exception","re":"promotion|solde","pts":3}],"articles":[{"code":"L31-08","article":"38","label":"Art. 38 loi 31-08 (exceptions)","pts":4}],"faille":"La demanderesse ne répond pas sur les exceptions.","concede":"La promotion n'est pas une exception, je l'admets."},{"name":"Le remboursement","adverse":"Le vendeur acceptera peut-être de rembourser, mais sous forme d'avoir.","prompt":"Plaidez sur le remboursement.","options":[{"label":"Remboursement intégral sous 15 jours, avec intérêts","detail":"Remboursement du montant total dans les 15 jours, puis intérêts de plein droit (art. 37).","pts":17,"speech":"L'article 37 oblige le fournisseur à rembourser sans délai le montant total payé, au plus tard dans les quinze jours suivant la rétractation. Passé ce délai, la somme produit de plein droit des intérêts au taux légal. Deux mois se sont écoulés : nous demandons 14 000 Dirhams, avec intérêts depuis le 23 mars. Un avoir n'est pas un remboursement.","ok":["Cite l'article 37","Point de départ des intérêts","Refus de l'avoir"],"ko":[]},{"label":"Accepter l'avoir","detail":"Accepter un bon d'achat.","pts":4,"speech":"Ma cliente accepterait un avoir.","ok":["Conciliant"],"ko":["Renonce à un droit au remboursement"]}],"concepts":[{"label":"Remboursement intégral sous quinze jours","re":"quinze jours|15 jours|rembours","pts":6,"key":true},{"label":"Intérêts de plein droit","re":"interets?|taux legal","pts":4},{"label":"Refus de l'avoir","re":"avoir|bon d.achat","pts":2}],"articles":[{"code":"L31-08","article":"37","label":"Art. 37 loi 31-08 (remboursement)","pts":4}],"faille":"Les modalités du remboursement ne sont pas précisées.","concede":"Le délai de quinze jours est dépassé."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la consommatrice a exercé son droit de rétractation dans le délai de sept jours et que la promotion ne figure pas parmi les exceptions légales (articles 36 et 38 de la loi 31-08) ; Par ces motifs : condamne MeubleShop.ma à rembourser 14 000 Dirhams avec intérêts au taux légal à compter du seizième jour suivant la rétractation."},{"min":45,"text":"Le Tribunal, attendu la régularité de la rétractation ; Par ces motifs : condamne le vendeur au remboursement de 14 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu l'utilisation du produit ; Par ces motifs : rejette la demande."}]},{"id":"cession-fonds","matiere":"affaires","title":"Société Lait d'Or c/ M. Saidi (acquéreur)","court":"Tribunal de commerce de Fès","object":"Opposition d'un créancier au paiement du prix de cession d'un fonds de commerce.","you":"Avocat du créancier (Société Lait d'Or)","adverseName":"Avocat de M. Saidi","facts":"M. Amrani, épicier, devait 160 000 DH de factures à son fournisseur Lait d'Or. Il a vendu son fonds à M. Saidi pour 600 000 DH. Deux jours après la seconde insertion légale, M. Saidi a payé directement l'intégralité du prix au vendeur, qui a disparu. Lait d'Or avait formé opposition au greffe le dixième jour suivant la seconde insertion.","rounds":[{"name":"L'opposition","adverse":"Monsieur le Président, mon client a payé le vendeur. Il n'a plus rien à verser : l'opposition est sans objet.","prompt":"Défendez l'opposition.","options":[{"label":"Opposition régulière dans les quinze jours","detail":"Créancier du vendeur : opposition par lettre recommandée ou dépôt au greffe dans les 15 jours de la seconde insertion (art. 84).","pts":17,"speech":"L'article 84 du Code de commerce permet aux créanciers du vendeur, que leur créance soit exigible ou non, de former opposition au paiement du prix dans les quinze jours au plus tard après la seconde insertion. Lait d'Or l'a fait le dixième jour, par dépôt au greffe contre récépissé. L'opposition est régulière et recevable.","ok":["Cite l'article 84","Délai respecté","Récépissé"],"ko":[]},{"label":"Viser le vendeur","detail":"Poursuivre M. Amrani.","pts":7,"speech":"Nous poursuivrons M. Amrani pour sa dette.","ok":["Logique"],"ko":["Le vendeur a disparu ; n'utilise pas la protection légale"]}],"concepts":[{"label":"Opposition dans les quinze jours","re":"quinze jours|15 jours|opposition","pts":6,"key":true},{"label":"Seconde insertion","re":"seconde insertion|insertion","pts":3},{"label":"Dépôt au greffe / lettre recommandée","re":"greffe|recepisse|recommande","pts":3}],"articles":[{"code":"CCOM","article":"84","label":"Art. 84 CCOM (opposition)","pts":5}],"faille":"Le créancier ne justifie pas de son opposition.","concede":"L'opposition est dans le délai, soit. Mais le prix était déjà payé."},{"name":"Le paiement prématuré","adverse":"Mon client a payé de bonne foi ; il ne pouvait savoir qu'un créancier allait se manifester.","prompt":"Répondez sur l'effet du paiement.","options":[{"label":"Paiement inopposable aux créanciers","detail":"L'acquéreur qui paie avant l'expiration du délai de quinze jours n'est pas libéré à l'égard des tiers (art. 89).","pts":18,"speech":"L'article 89 du Code de commerce est sans ambiguïté : l'acquéreur qui a payé le vendeur avant l'expiration du délai de quinze jours n'est pas libéré à l'égard des tiers. M. Saidi a payé deux jours après la seconde insertion, alors que le délai d'opposition courait encore. Sa bonne foi est indifférente : il doit payer une seconde fois le créancier opposant.","ok":["Cite l'article 89","Chronologie","Bonne foi indifférente"],"ko":[]},{"label":"Plaider l'équité","detail":"Reconnaître la bonne foi de l'acquéreur.","pts":5,"speech":"Nous comprenons la situation de M. Saidi.","ok":["Courtois"],"ko":["Affaiblit la demande"]}],"concepts":[{"label":"Acquéreur non libéré","re":"pas libere|non libere|inopposable|payer (une )?seconde fois","pts":6,"key":true},{"label":"Paiement avant l'expiration du délai","re":"avant (l.expiration|la fin)|deux jours|delai","pts":4},{"label":"Bonne foi indifférente","re":"bonne foi","pts":2}],"articles":[{"code":"CCOM","article":"89","label":"Art. 89 CCOM (paiement prématuré)","pts":5}],"faille":"Le créancier ne démontre pas que l'acquéreur reste tenu.","concede":"Le paiement était prématuré, je l'admets."},{"name":"La créance et la forme de la cession","adverse":"La créance de Lait d'Or n'est pas prouvée, et l'acte de cession était parfaitement régulier.","prompt":"Justifiez la créance et le montant.","options":[{"label":"Créance justifiée, formalités de la cession","detail":"Factures et bons de livraison signés par le vendeur ; l'acte (art. 81) et son dépôt (art. 83) ont fait courir le délai.","pts":15,"speech":"La créance est établie par les factures et les bons de livraison signés par M. Amrani sur deux ans, et par ses propres relevés de compte. Quant à la cession, sa régularité formelle, acte écrit conformément à l'article 81 et dépôt au greffe selon l'article 83, ne fait que confirmer le point de départ des délais. M. Saidi doit verser 160 000 Dirhams à Lait d'Or.","ok":["Preuves de la créance","Cite les articles 81 et 83","Montant précis"],"ko":[]},{"label":"Demander tout le prix","detail":"Réclamer les 600 000 DH.","pts":4,"speech":"Lait d'Or réclame l'intégralité du prix.","ok":["—"],"ko":["Excède la créance"]}],"concepts":[{"label":"Créance prouvée","re":"factur|bons? de livraison|releve","pts":5,"key":true},{"label":"Montant limité à la créance","re":"160 000","pts":4},{"label":"Formalités de la cession","re":"acte|depot|greffe|insertion","pts":3}],"articles":[{"code":"CCOM","article":"81","label":"Art. 81 CCOM (acte de cession)","pts":2},{"code":"CCOM","article":"83","label":"Art. 83 CCOM (dépôt)","pts":2}],"faille":"La créance n'est pas justifiée.","concede":"La créance est établie."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que l'opposition a été formée dans le délai de quinze jours suivant la seconde insertion et que l'acquéreur, ayant payé avant l'expiration de ce délai, n'est pas libéré à l'égard des tiers (articles 84 et 89) ; Par ces motifs : condamne M. Saidi à payer 160 000 Dirhams à Lait d'Or."},{"min":45,"text":"Le Tribunal, attendu la régularité de l'opposition ; Par ces motifs : condamne l'acquéreur au paiement de la créance justifiée, réduite à 140 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu que la créance n'est pas suffisamment justifiée ; Par ces motifs : ordonne une expertise comptable."}]},{"id":"caution-banque","matiere":"affaires","title":"Banque Al Moustakbal c/ M. Filali (caution)","court":"Tribunal de commerce de Casablanca","object":"Poursuite d'une caution pour le prêt impayé d'une société.","you":"Avocat de la caution (M. Filali)","adverseName":"Avocat de la banque","facts":"M. Filali, ami du gérant, s'est porté caution d'un prêt de 900 000 DH consenti à Nord Import SARL. L'acte, signé à titre personnel, mentionne « je me porte caution », sans le mot « solidaire » ni renonciation au bénéfice de discussion. La société est en activité et possède un entrepôt et un stock importants. La banque poursuit directement M. Filali. Elle a par ailleurs accordé à la société une remise de 200 000 DH dans un protocole de restructuration.","rounds":[{"name":"Le bénéfice de discussion","adverse":"Monsieur le Président, la caution s'est engagée à payer à la place du débiteur. La banque peut la poursuivre directement.","prompt":"Invoquez le bénéfice de discussion.","options":[{"label":"Discuter d'abord le débiteur","detail":"La caution peut exiger que le créancier poursuive d'abord les biens du débiteur (art. 1136) ; société solvable.","pts":17,"speech":"Le cautionnement, selon l'article 1117 du DOC, oblige la caution à payer si le débiteur n'y satisfait pas lui-même. L'article 1136 lui permet d'exiger que le créancier discute au préalable les biens du débiteur principal, en les lui indiquant. Nous indiquons l'entrepôt et le stock de Nord Import, société en pleine activité. Les poursuites contre M. Filali doivent être suspendues.","ok":["Cite les articles 1117 et 1136","Indique les biens du débiteur"],"ko":[]},{"label":"Contester la dette","detail":"Soutenir que le prêt n'a pas été débloqué.","pts":6,"speech":"Rien ne prouve que le prêt a été versé.","ok":["Vérifie la créance"],"ko":["Contredit les relevés de la banque"]}],"concepts":[{"label":"Bénéfice de discussion","re":"discut|d.abord le debiteur|poursuivre d.abord","pts":6,"key":true},{"label":"Biens du débiteur indiqués","re":"entrepot|stock|biens|solvab","pts":4},{"label":"Caractère subsidiaire du cautionnement","re":"subsidiaire|si le debiteur n.y satisfait pas|1117","pts":3}],"articles":[{"code":"DOC","article":"1136","label":"Art. 1136 DOC (bénéfice de discussion)","pts":4},{"code":"DOC","article":"1117","label":"Art. 1117 DOC (définition)","pts":2}],"faille":"La caution ne conteste pas son engagement.","concede":"Le bénéfice de discussion existe, soit ; mais cette caution est solidaire."},{"name":"La solidarité alléguée","adverse":"En matière commerciale, la solidarité se présume. La caution est donc solidaire et ne peut demander la discussion.","prompt":"Répondez sur la solidarité.","options":[{"label":"Engagement civil, pas de renonciation","detail":"La présomption de solidarité (art. 335 CCOM) vise les obligations commerciales ; M. Filali, non commerçant, s'est engagé à titre personnel, sans renonciation (art. 1137).","pts":16,"speech":"L'article 335 du Code de commerce présume la solidarité en matière d'obligations commerciales. Mais M. Filali n'est pas commerçant ; il s'est porté caution à titre personnel, par amitié, sans intérêt dans la société : son engagement est civil. L'article 1137 du DOC ne prive la caution du bénéfice de discussion que si elle y a renoncé formellement ou s'est engagée solidairement. L'acte ne contient ni l'un ni l'autre.","ok":["Cite les articles 335 CCOM et 1137 DOC","Caractère civil de l'engagement","Lecture de l'acte"],"ko":["Le caractère civil peut être discuté si la caution a un intérêt"]},{"label":"Ne pas répondre","detail":"Revenir au bénéfice de discussion.","pts":4,"speech":"Le bénéfice de discussion s'applique, voilà tout.","ok":["—"],"ko":["Laisse la présomption de solidarité sans réponse"]}],"concepts":[{"label":"Pas de solidarité ni de renonciation","re":"pas solidaire|non solidaire|renonc|sans le mot","pts":6,"key":true},{"label":"Engagement civil, caution non commerçante","re":"civil|non commercant|pas commercant|a titre personnel|amitie","pts":4},{"label":"Présomption limitée aux obligations commerciales","re":"335|presom|obligations commerciales","pts":3}],"articles":[{"code":"DOC","article":"1137","label":"Art. 1137 DOC (exclusions du bénéfice)","pts":3},{"code":"CCOM","article":"335","label":"Art. 335 CCOM (solidarité présumée)","pts":2}],"faille":"La caution ne combat pas la présomption de solidarité.","concede":"L'engagement de la caution paraît civil, je l'admets."},{"name":"La remise accordée au débiteur","adverse":"Subsidiairement, la caution doit les 900 000 Dirhams prêtés, quelles que soient les négociations entre la banque et la société.","prompt":"Plaidez sur le montant.","options":[{"label":"Extinction partielle de l'obligation principale","detail":"Les causes d'extinction de l'obligation principale éteignent le cautionnement (art. 1150) : la remise de 200 000 DH profite à la caution.","pts":16,"speech":"L'article 1150 du DOC dispose que toutes les causes d'extinction de l'obligation principale éteignent le cautionnement. La banque a remis 200 000 Dirhams à la société par le protocole de restructuration : la dette principale est réduite d'autant, et la caution ne peut être tenue au-delà de ce que doit le débiteur. Au plus, et après discussion, M. Filali ne pourrait devoir que le solde.","ok":["Cite l'article 1150","Accessoire du cautionnement","Montant maximal"],"ko":[]},{"label":"Demander des délais","detail":"Solliciter des délais de paiement.","pts":7,"speech":"M. Filali demande des délais de grâce.","ok":["Pragmatique"],"ko":["Admet la dette entière"]}],"concepts":[{"label":"Remise profitant à la caution","re":"remise|200 000|reduit|protocole","pts":6,"key":true},{"label":"Caractère accessoire du cautionnement","re":"accessoire|ne peut (etre tenue|devoir) (plus|au-dela)|extinction","pts":4}],"articles":[{"code":"DOC","article":"1150","label":"Art. 1150 DOC (extinction)","pts":4}],"faille":"La caution ne discute pas le montant.","concede":"La remise profite à la caution, je l'admets."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la caution, engagée à titre civil sans solidarité ni renonciation, peut opposer le bénéfice de discussion (articles 1136 et 1137 DOC) et que la remise consentie au débiteur réduit son engagement (article 1150) ; Par ces motifs : sursoit aux poursuites contre M. Filali jusqu'à la discussion des biens de Nord Import et limite son engagement à 700 000 Dirhams."},{"min":45,"text":"Le Tribunal, attendu que la remise consentie réduit la dette principale ; Par ces motifs : condamne la caution à 700 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu la présomption de solidarité en matière commerciale ; Par ces motifs : condamne M. Filali à payer 900 000 Dirhams."}]},{"complexe":true,"id":"cx-divorce-entreprise","matiere":"famille","title":"Mme Sefrioui c/ M. Sefrioui — divorce, entreprise et chèque","court":"Tribunal de première instance de Casablanca (section de la famille et chambre correctionnelle)","object":"Trois problèmes : partage des biens acquis pendant le mariage, chèque sans provision remis pour le don de consolation, évaluation des droits de l'épouse.","you":"Avocat de l'épouse (Mme Sefrioui)","adverseName":"Avocat de M. Sefrioui","facts":"Mariés en 2008 sans contrat sur les biens, les époux ont créé ensemble une société de traiteur, enregistrée au seul nom du mari. Mme Sefrioui y a travaillé quinze ans sans salaire : recettes, clientèle, gestion des employés. Le divorce pour discorde a été prononcé. Pour régler le don de consolation, M. Sefrioui a remis un chèque de 150 000 DH, revenu impayé faute de provision. Il soutient que la société n'appartient qu'à lui et que la consolation doit être minime, l'épouse ayant « voulu » le divorce.","rounds":[{"name":"Problème 1 — Famille : les biens acquis pendant le mariage","adverse":"Monsieur le Président, les époux ont des patrimoines séparés. La société est au nom de mon client : elle lui appartient, et l'épouse n'a aucun droit dessus.","prompt":"Revendiquez la part de l'épouse dans la société.","options":[{"label":"Travail et efforts de l'épouse","detail":"À défaut d'accord, le juge tient compte du travail, des efforts et des charges de chaque conjoint pour fructifier les biens (art. 49 CF).","pts":18,"speech":"La séparation des patrimoines n'est que le point de départ. L'article 49 du Code de la famille prévoit qu'à défaut d'accord sur les biens acquis pendant le mariage, on recourt aux règles générales de preuve en tenant compte du travail de chacun des conjoints, des efforts fournis et des charges assumées pour fructifier les biens de la famille. Mme Sefrioui a travaillé quinze ans sans salaire dans la société : témoignages des employés, carnets de recettes à son écriture, relations avec les clients. Elle a droit à une part correspondant à cet apport.","ok":["Cite l'article 49","Preuves concrètes du travail","Distingue titre de propriété et contribution"],"ko":[]},{"label":"Demander la moitié automatiquement","detail":"Réclamer 50 % au nom de la communauté.","pts":7,"speech":"Ma cliente a droit à la moitié de tout ce qui a été acquis pendant le mariage.","ok":["Ambitieux"],"ko":["Il n'existe pas de communauté légale automatique","Aucune preuve"]}],"concepts":[{"label":"Travail et efforts de l'épouse","re":"travail|efforts?|contribu|sans salaire|charges assumees","pts":6,"key":true},{"label":"Absence d'accord sur les biens","re":"a defaut d.accord|pas de contrat|aucun accord|regles generales","pts":4},{"label":"Preuves de la contribution","re":"temoign|employes|carnets?|clients?|preuves?","pts":4}],"articles":[{"code":"CF","article":"49","label":"Art. 49 CF (biens acquis pendant le mariage)","pts":5}],"faille":"L'épouse ne prouve aucune contribution : la société reste au mari.","concede":"Le travail de l'épouse est établi, soit. Encore faut-il l'évaluer."},{"name":"Problème 2 — Pénal / effets de commerce : le chèque impayé","adverse":"Le chèque a été remis dans un contexte familial, sous le coup de l'émotion. C'est une affaire civile, pas pénale ; mon client paiera quand il pourra.","prompt":"Caractérisez l'infraction liée au chèque.","options":[{"label":"Délit d'émission sans provision","detail":"Le tireur qui omet de maintenir ou constituer la provision est puni (art. 316 CCOM), quel que soit le contexte.","pts":17,"speech":"L'article 316 du Code de commerce punit le tireur d'un chèque qui omet de maintenir ou de constituer la provision en vue de son paiement à la présentation. Le contexte familial est indifférent : un chèque est un instrument de paiement, pas une promesse. Ma cliente se constitue partie civile ; l'amende ne peut être inférieure à vingt-cinq pour cent du montant du chèque.","ok":["Cite l'article 316 CCOM","Contexte indifférent","Constitution de partie civile"],"ko":[]},{"label":"Demander seulement le paiement","detail":"Réclamer les 150 000 DH devant le juge de la famille.","pts":9,"speech":"Ma cliente demande simplement le paiement des 150 000 Dirhams.","ok":["Objectif clair"],"ko":["Renonce au levier pénal"]}],"concepts":[{"label":"Défaut de provision","re":"provision|sans provision|impaye","pts":6,"key":true},{"label":"Contexte indifférent","re":"indifferent|instrument de paiement|peu importe|quel que soit","pts":4},{"label":"Partie civile / sanction","re":"partie civile|amende|emprisonnement|25","pts":3}],"articles":[{"code":"CCOM","article":"316","label":"Art. 316 CCOM (chèque sans provision)","pts":5}],"faille":"L'épouse ne qualifie pas l'infraction.","concede":"Le chèque est bien sans provision, je l'admets."},{"name":"Problème 3 — Famille : le montant du don de consolation","adverse":"La consolation doit être symbolique : c'est l'épouse qui a demandé le divorce pour discorde.","prompt":"Plaidez sur les droits de l'épouse divorcée.","options":[{"label":"Critères légaux de la Mout'â","detail":"Évaluée selon la durée du mariage, la situation financière de l'époux, les motifs et l'abus (art. 84 CF) ; responsabilités dans la discorde (art. 97).","pts":17,"speech":"L'article 84 du Code de la famille évalue le don de consolation en fonction de la durée du mariage, de la situation financière de l'époux, des motifs du divorce et du degré d'abus. Dix-sept ans de mariage, un mari propriétaire d'une société prospère, une discorde née de son comportement : tout plaide pour une consolation substantielle. L'article 97 impose d'ailleurs de tenir compte de la responsabilité de chacun dans la discorde ; avoir saisi le juge n'est pas une faute.","ok":["Cite les articles 84 et 97","Applique chaque critère","Demander n'est pas fauter"],"ko":[]},{"label":"Accepter le chèque comme plafond","detail":"Limiter la demande à 150 000 DH.","pts":8,"speech":"Ma cliente se contentera des 150 000 Dirhams promis.","ok":["Cohérent avec le chèque"],"ko":["N'utilise pas les critères légaux"]}],"concepts":[{"label":"Critères de la consolation","re":"duree du mariage|situation financiere|motifs|abus|mout","pts":6,"key":true},{"label":"Responsabilité dans la discorde","re":"responsabilit|discorde|comportement","pts":4},{"label":"Demander le divorce n'est pas une faute","re":"pas une faute|droit de|saisi","pts":3}],"articles":[{"code":"CF","article":"84","label":"Art. 84 CF (droits de l'épouse)","pts":4},{"code":"CF","article":"97","label":"Art. 97 CF (discorde)","pts":2}],"faille":"Rien n'est dit des critères : la consolation sera minime.","concede":"Les critères sont favorables à l'épouse, je le reconnais."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu le travail de l'épouse pendant quinze ans dans la société (article 49), le défaut de provision du chèque remis (article 316 du Code de commerce) et les critères de l'article 84 ; Par ces motifs : attribue à l'épouse 35 % de la valeur de la société, fixe le don de consolation à 200 000 Dirhams et, sur l'action pénale, condamne l'époux à une amende de 40 000 Dirhams."},{"min":45,"text":"Le Tribunal, attendu la contribution partielle de l'épouse ; Par ces motifs : lui attribue 15 % de la valeur de la société et fixe la consolation à 150 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu que la contribution de l'épouse n'est pas établie ; Par ces motifs : fixe la consolation à 60 000 Dirhams et rejette la demande relative à la société."}]},{"complexe":true,"id":"cx-chauffeur-livreur","matiere":"travail","title":"M. Tazi c/ Société Rapid Livraison — accident, licenciement et responsabilité","court":"Tribunal de première instance de Rabat (chambres correctionnelle, sociale et civile)","object":"Trois problèmes : blessures involontaires, licenciement pour « faute grave », responsabilité de l'employeur envers la victime.","you":"Avocat du chauffeur-livreur (M. Tazi)","adverseName":"Avocat de Rapid Livraison","facts":"M. Tazi, livreur salarié depuis six ans, a renversé un cycliste pendant une tournée, en grillant un feu orange sous la pression de délais imposés par l'employeur (40 livraisons par jour). Le cycliste a 30 jours d'incapacité. Le lendemain, avant tout jugement, Rapid Livraison licencie M. Tazi pour faute grave. La victime réclame 120 000 DH de dommages-intérêts directement à M. Tazi.","rounds":[{"name":"Problème 1 — Pénal : les blessures involontaires","adverse":"Monsieur le Président, le prévenu a franchi un feu orange et blessé un cycliste : l'inobservation des règlements est caractérisée.","prompt":"Plaidez sur la responsabilité pénale et la peine.","options":[{"label":"Qualification exacte et circonstances","detail":"Blessures involontaires avec ITT > 6 jours (art. 433) ; feu orange, pression de l'employeur, casier vierge : circonstances atténuantes (art. 146).","pts":15,"speech":"La qualification est celle de l'article 433 du Code pénal : blessures involontaires entraînant une incapacité de plus de six jours, punies d'un mois à deux ans ou de l'amende seule. Le feu était orange, non rouge ; mon client roulait sous la pression d'un objectif de quarante livraisons par jour imposé par l'employeur. Sans antécédent, il mérite les circonstances atténuantes de l'article 146 et une simple amende.","ok":["Cite l'article 433 (pas l'homicide)","Contexte de pression","Cite l'article 146"],"ko":["Ne conteste pas la faute elle-même"]},{"label":"Nier toute faute","detail":"Soutenir que le cycliste est seul responsable.","pts":6,"speech":"C'est le cycliste qui a surgi sans regarder.","ok":["Défense classique"],"ko":["Contredit le constat","Perd en crédibilité"]}],"concepts":[{"label":"Blessures involontaires (ITT > 6 jours)","re":"blessures? involontaires?|433|incapacit|six jours","pts":5,"key":true},{"label":"Pression de l'employeur","re":"pression|40 livraisons|objectif|delais","pts":4},{"label":"Circonstances atténuantes / amende","re":"attenuant|amende|146|casier","pts":4}],"articles":[{"code":"CP","article":"433","label":"Art. 433 CP (blessures involontaires)","pts":4},{"code":"CP","article":"146","label":"Art. 146 CP","pts":2}],"faille":"La défense ne discute ni la qualification ni la peine.","concede":"La pression de l'employeur est un fait, je l'admets."},{"name":"Problème 2 — Travail : le licenciement pour faute grave","adverse":"Un chauffeur qui provoque un accident commet une faute grave : le licenciement immédiat est justifié, sans indemnité.","prompt":"Contestez le licenciement.","options":[{"label":"Faute grave non caractérisée","detail":"Le délit ne constitue une faute grave qu'après un jugement définitif privatif de liberté (art. 39) ; licenciement immédiat abusif (art. 41).","pts":18,"speech":"L'article 39 du Code du travail ne fait du délit une faute grave que s'il a donné lieu à un jugement définitif privatif de liberté et s'il porte atteinte à l'honneur, à la confiance ou aux bonnes mœurs. Mon client a été licencié le lendemain de l'accident, sans aucun jugement, pour une infraction involontaire commise en exécutant les ordres de l'entreprise. Le licenciement est abusif : il a droit aux dommages-intérêts de l'article 41.","ok":["Cite l'article 39 (jugement définitif)","Infraction involontaire","Cite l'article 41"],"ko":[]},{"label":"Invoquer l'ancienneté","detail":"Insister sur six ans de bons services.","pts":8,"speech":"Six ans sans le moindre reproche : on ne licencie pas un tel salarié.","ok":["Contexte favorable"],"ko":["Ne démontre pas l'absence de faute grave"]}],"concepts":[{"label":"Pas de jugement définitif","re":"jugement definitif|aucun jugement|avant tout jugement|privatif","pts":6,"key":true},{"label":"Infraction involontaire, pas d'atteinte à l'honneur","re":"involontaire|honneur|confiance","pts":4},{"label":"Licenciement abusif","re":"abusi|dommages","pts":3}],"articles":[{"code":"CT","article":"39","label":"Art. 39 CT (fautes graves du salarié)","pts":5},{"code":"CT","article":"41","label":"Art. 41 CT","pts":2}],"faille":"Le salarié ne conteste pas sérieusement la faute.","concede":"Aucun jugement n'avait été rendu, c'est exact."},{"name":"Problème 3 — Civil : qui indemnise la victime ?","adverse":"La victime réclame 120 000 Dirhams au chauffeur : c'est lui qui conduisait.","prompt":"Plaidez sur la responsabilité de l'employeur.","options":[{"label":"Responsabilité du commettant","detail":"Les commettants répondent du dommage causé par leurs préposés dans leurs fonctions (art. 85 DOC) : l'employeur doit être mis en cause.","pts":17,"speech":"L'article 85 du DOC rend les maîtres et commettants responsables du dommage causé par leurs préposés dans les fonctions auxquelles ils les ont employés. L'accident est survenu en pleine tournée, avec le véhicule de l'entreprise, sous des cadences fixées par elle. Nous demandons la mise en cause de Rapid Livraison et de son assureur, qui doivent indemniser la victime.","ok":["Cite l'article 85 DOC","Accident dans les fonctions","Mise en cause de l'assureur"],"ko":[]},{"label":"Contester le montant","detail":"Discuter les 120 000 DH.","pts":9,"speech":"Le montant réclamé est excessif.","ok":["Utile en subsidiaire"],"ko":["Laisse le chauffeur seul débiteur"]}],"concepts":[{"label":"Responsabilité du commettant pour son préposé","re":"commettant|prepose|employeur.*(respons|repond)","pts":6,"key":true},{"label":"Dans l'exercice des fonctions","re":"fonctions|tournee|vehicule de l.entreprise|pendant le travail","pts":4},{"label":"Mise en cause / assureur","re":"mise en cause|assur","pts":3}],"articles":[{"code":"DOC","article":"85","label":"Art. 85 DOC (responsabilité du fait d'autrui)","pts":5}],"faille":"Le chauffeur ne désigne personne d'autre : il paiera.","concede":"L'accident est survenu pendant la tournée, je l'admets."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu les blessures involontaires commises sous la pression des cadences imposées (articles 433 et 146 CP), l'absence de jugement définitif rendant la faute grave inopérante (article 39 CT) et la responsabilité du commettant (article 85 DOC) ; Par ces motifs : condamne M. Tazi à 1 000 Dirhams d'amende, déclare le licenciement abusif et condamne Rapid Livraison, garantie par son assureur, à indemniser la victime."},{"min":45,"text":"Le Tribunal, attendu le caractère abusif du licenciement ; Par ces motifs : condamne M. Tazi à deux mois avec sursis et l'employeur aux indemnités de licenciement."},{"min":0,"text":"Le Tribunal, attendu la faute du conducteur ; Par ces motifs : condamne M. Tazi à quatre mois avec sursis et à indemniser lui-même la victime."}]},{"complexe":true,"id":"cx-bail-cheques","matiere":"affaires","title":"M. Benjelloun c/ Café Le Zénith — loyers, chèques et éviction","court":"Tribunal de commerce de Marrakech et chambre correctionnelle","object":"Trois problèmes : congé pour loyers impayés, chèques sans provision remis en paiement, indemnité d'éviction réclamée par le locataire.","you":"Avocat du bailleur (M. Benjelloun)","adverseName":"Avocat du Café Le Zénith","facts":"Le Café Le Zénith loue un local commercial depuis 2016 (12 000 DH par mois). Il n'a rien payé depuis cinq mois. Le bailleur lui a adressé une mise en demeure avec congé motivé par le défaut de paiement ; vingt jours plus tard, rien n'était réglé. Pour « calmer » le bailleur, le gérant a remis trois chèques de 12 000 DH, tous rejetés faute de provision, présentés dans les délais. Le café réclame une indemnité d'éviction de 900 000 DH, soit la valeur de son fonds.","rounds":[{"name":"Problème 1 — Bail commercial : le congé","adverse":"Monsieur le Président, mon client exploite ce café depuis neuf ans. Un simple retard de loyers ne justifie pas de le priver de son fonds.","prompt":"Justifiez l'éviction.","options":[{"label":"Congé motivé et délai de quinze jours","detail":"Pour défaut de paiement, le délai d'éviction est de quinze jours à compter de la réception du congé motivé (art. 26 loi 49-16).","pts":17,"speech":"L'article 26 de la loi 49-16 permet au bailleur de mettre fin au bail par un congé exposant son motif ; lorsque le motif est le défaut de paiement des loyers, le délai d'éviction est de quinze jours à compter de la réception. Le congé, motivé, a été reçu ; vingt jours plus tard, rien n'était payé. Cinq mois d'impayés, soit 60 000 Dirhams, ne sont pas un « simple retard ».","ok":["Cite l'article 26","Délai de quinze jours","Chiffre l'arriéré"],"ko":[]},{"label":"Invoquer le contrat","detail":"Se référer à la clause résolutoire du bail.","pts":9,"speech":"Le bail contient une clause résolutoire en cas d'impayé.","ok":["Piste contractuelle"],"ko":["La loi 49-16 encadre la procédure"]}],"concepts":[{"label":"Congé motivé pour défaut de paiement","re":"conge|defaut de paiement|motive","pts":5,"key":true},{"label":"Délai de quinze jours","re":"quinze jours|15 jours","pts":5},{"label":"Arriéré important","re":"cinq mois|60 000|impayes?","pts":3}],"articles":[{"code":"L49-16","article":"26","label":"Art. 26 loi 49-16 (congé et délai)","pts":5}],"faille":"Le bailleur ne justifie pas de la régularité du congé.","concede":"Le délai de quinze jours a expiré, soit."},{"name":"Problème 2 — Effets de commerce et pénal : les chèques rejetés","adverse":"Les chèques ont été remis de bonne foi ; mon client attendait un virement. Le bailleur n'avait qu'à patienter.","prompt":"Plaidez sur les chèques sans provision.","options":[{"label":"Délit et recours préservé","detail":"Défaut de provision puni (art. 316 CCOM) ; chèques présentés dans les délais, recours du porteur non prescrit (art. 295).","pts":16,"speech":"Le tireur qui omet de constituer la provision d'un chèque à sa présentation commet le délit de l'article 316 du Code de commerce ; l'attente d'un virement n'y change rien. Le bailleur se constitue partie civile. Les chèques ayant été présentés dans les délais, ses recours cambiaires, qui se prescrivent par six mois selon l'article 295, sont intacts : il peut en obtenir le paiement.","ok":["Cite les articles 316 et 295","Bonne foi indifférente","Recours non prescrit"],"ko":["N'évoque pas l'avis de non-paiement"]},{"label":"Ne viser que les loyers","detail":"Ignorer les chèques, réclamer les loyers.","pts":7,"speech":"Les chèques importent peu : nous réclamons les loyers.","ok":["Simple"],"ko":["Renonce à une arme efficace"]}],"concepts":[{"label":"Défaut de provision : délit","re":"provision|316|delit","pts":6,"key":true},{"label":"Recours cambiaire / six mois","re":"six mois|6 mois|recours|prescri","pts":4},{"label":"Bonne foi indifférente","re":"bonne foi|virement|indifferent","pts":3}],"articles":[{"code":"CCOM","article":"316","label":"Art. 316 CCOM","pts":4},{"code":"CCOM","article":"295","label":"Art. 295 CCOM (prescription des recours)","pts":2}],"faille":"Le bailleur ne dit rien de ses droits sur les chèques.","concede":"Les chèques étaient sans provision, c'est exact."},{"name":"Problème 3 — Bail commercial : l'indemnité d'éviction","adverse":"En tout état de cause, mon client a droit à une indemnité d'éviction égale à la valeur de son fonds, soit 900 000 Dirhams.","prompt":"Répondez sur l'indemnité d'éviction.","options":[{"label":"Exclusion de l'indemnité","detail":"Pas d'indemnité si le locataire n'a pas payé dans les 15 jours de la mise en demeure et que l'arriéré atteint 3 mois (art. 8 loi 49-16).","pts":18,"speech":"Le principe de l'indemnité, posé à l'article 7, connaît des exceptions. L'article 8 de la loi 49-16 dispense le bailleur de toute indemnité lorsque le locataire n'a pas payé dans les quinze jours suivant la mise en demeure et que l'arriéré équivaut au moins à trois mois de loyer. L'arriéré est de cinq mois, la mise en demeure est restée sans effet : aucune indemnité n'est due.","ok":["Cite l'article 8 (exception)","Deux conditions vérifiées"],"ko":[]},{"label":"Contester le montant","detail":"Soutenir que le fonds vaut moins.","pts":8,"speech":"Le fonds ne vaut pas 900 000 Dirhams ; ses déclarations fiscales le montrent.","ok":["Utile en subsidiaire (art. 7)"],"ko":["Admet implicitement le principe de l'indemnité"]}],"concepts":[{"label":"Exception à l'indemnité pour impayés","re":"aucune indemnite|exception|exclu|pas d.indemnite|dispense","pts":6,"key":true},{"label":"Trois mois d'arriéré et quinze jours","re":"trois mois|3 mois|quinze jours|15 jours","pts":4},{"label":"Principe de l'indemnité (art. 7)","re":"valeur du fonds|principe","pts":2}],"articles":[{"code":"L49-16","article":"8","label":"Art. 8 loi 49-16 (exclusion de l'indemnité)","pts":5},{"code":"L49-16","article":"7","label":"Art. 7 loi 49-16","pts":1}],"faille":"Le bailleur ne conteste pas l'indemnité : elle est due.","concede":"Les conditions de l'exclusion sont réunies, je l'admets."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le congé motivé par le défaut de paiement est resté sans effet au-delà de quinze jours (article 26) et que l'arriéré excède trois mois (article 8) ; Par ces motifs : valide le congé, ordonne l'éviction sans indemnité, condamne le locataire aux loyers ; sur l'action pénale, condamne le gérant pour émission de chèques sans provision."},{"min":45,"text":"Le Tribunal, attendu la validité du congé ; Par ces motifs : ordonne l'éviction et réduit l'indemnité à 150 000 Dirhams."},{"min":0,"text":"Le Tribunal, attendu l'ancienneté du bail ; Par ces motifs : accorde des délais de paiement et réserve la question de l'éviction."}]},{"complexe":true,"id":"cx-gerant-fraude","matiere":"affaires","title":"Mme Rami (associée) c/ M. Hilali, gérant de Batinord SARL — abus, faux et redressement fiscal","court":"Tribunal de commerce de Tanger et chambre correctionnelle","object":"Trois problèmes : abus de biens sociaux du gérant de SARL, fausses factures, prise en charge du redressement fiscal.","you":"Avocat de l'associée minoritaire (Mme Rami, 40 %)","adverseName":"Avocat de M. Hilali","facts":"M. Hilali, gérant et associé à 60 % de Batinord SARL, a fait payer par la société 600 000 DH de factures d'une entreprise appartenant à son frère, pour des travaux jamais réalisés. L'administration fiscale a rejeté la déduction de ces charges et de la TVA, et notifié un redressement de 280 000 DH avec pénalités. Mme Rami découvre les faits à la lecture du rapport fiscal.","rounds":[{"name":"Problème 1 — Droit pénal des sociétés : l'abus de biens sociaux","adverse":"Monsieur le Président, mon client a géré au mieux ; ces travaux étaient prévus et ont été payés à un sous-traitant de confiance.","prompt":"Caractérisez l'infraction du gérant.","options":[{"label":"Abus de biens sociaux en SARL","detail":"Gérant faisant, de mauvaise foi, des biens de la société un usage contraire à son intérêt pour favoriser une entreprise où il est intéressé (art. 107 loi 5-96).","pts":17,"speech":"L'article 107 de la loi 5-96 punit les gérants qui, de mauvaise foi, font des biens ou du crédit de la société un usage qu'ils savent contraire à ses intérêts, à des fins personnelles ou pour favoriser une autre entreprise dans laquelle ils sont intéressés. 600 000 Dirhams versés à l'entreprise du frère du gérant pour des travaux jamais réalisés : l'usage contraire à l'intérêt social et l'intérêt indirect du gérant sont établis.","ok":["Cite l'article 107","Intérêt indirect (frère)","Travaux inexistants"],"ko":[]},{"label":"Demander la révocation","detail":"Réclamer seulement la révocation du gérant.","pts":8,"speech":"Mme Rami demande la révocation de M. Hilali.","ok":["Mesure utile"],"ko":["Ne qualifie pas l'infraction"]}],"concepts":[{"label":"Usage contraire à l'intérêt social","re":"contraire a l.interet|interet social|abus de biens","pts":6,"key":true},{"label":"Entreprise où le gérant est intéressé","re":"frere|interesse|favoriser","pts":4},{"label":"Travaux fictifs / mauvaise foi","re":"jamais realises|fictif|mauvaise foi","pts":3}],"articles":[{"code":"L5-96","article":"107","label":"Art. 107 loi 5-96 (abus de biens sociaux en SARL)","pts":5}],"faille":"L'associée ne prouve pas que les travaux sont fictifs.","concede":"Les travaux n'ont pas été réalisés, je l'admets."},{"name":"Problème 2 — Pénal / fiscal : les factures fictives","adverse":"Les factures sont en règle : elles comportent toutes les mentions légales. L'administration fiscale s'est trompée.","prompt":"Plaidez sur la nature des factures.","options":[{"label":"Factures sans opération réelle","detail":"Une facture doit correspondre à un achat réellement réalisé (art. 146 CGI) ; une facture de travaux inexistants est une altération frauduleuse de la vérité (art. 351 CP).","pts":16,"speech":"La régularité formelle ne suffit pas : l'article 146 du Code général des impôts exige que l'achat soit réellement réalisé. Or le constat d'huissier montre que les travaux facturés n'existent pas. Une facture qui décrit des travaux imaginaires est une altération frauduleuse de la vérité dans un écrit, de nature à causer un préjudice : c'est la définition du faux en écritures de l'article 351 du Code pénal.","ok":["Cite les articles 146 CGI et 351 CP","Constat d'huissier","Forme ≠ réalité"],"ko":["Le faux en écriture de commerce relève d'une qualification précise à détailler"]},{"label":"Accepter le redressement","detail":"Ne pas discuter les factures.","pts":6,"speech":"Le redressement fiscal parle de lui-même.","ok":["Simple"],"ko":["N'établit pas le caractère fictif"]}],"concepts":[{"label":"Opération non réelle","re":"reellement|realite|inexistant|imaginaire|fictiv","pts":6,"key":true},{"label":"Faux en écritures","re":"faux|alteration","pts":4},{"label":"Constat / preuve","re":"constat|huissier|preuve","pts":3}],"articles":[{"code":"CGI","article":"146","label":"Art. 146 CGI (achats réellement réalisés)","pts":3},{"code":"CP","article":"351","label":"Art. 351 CP (faux en écritures)","pts":3}],"faille":"Les factures sont régulières en la forme.","concede":"Le constat est accablant, je l'admets."},{"name":"Problème 3 — Droit des sociétés : qui paie le redressement ?","adverse":"Le redressement est une dette de la société : les associés le supportent ensemble, à proportion de leurs parts.","prompt":"Plaidez sur la responsabilité civile du gérant.","options":[{"label":"Responsabilité du gérant envers la société","detail":"Le gérant répond envers la société des fautes de gestion et infractions (art. 67 loi 5-96) : remboursement des 600 000 DH et du redressement.","pts":17,"speech":"L'article 67 de la loi 5-96 rend les gérants responsables envers la société des infractions aux dispositions légales et des fautes commises dans leur gestion. Le redressement de 280 000 Dirhams et ses pénalités sont la conséquence directe des fausses factures du gérant. Mme Rami exerce l'action sociale : M. Hilali doit rembourser à la société les 600 000 Dirhams détournés et le montant du redressement.","ok":["Cite l'article 67","Lien de causalité","Action sociale"],"ko":[]},{"label":"Partager le redressement","detail":"Accepter de payer 40 % du redressement.","pts":4,"speech":"Mme Rami accepte de supporter sa part de 40 %.","ok":["—"],"ko":["Fait payer l'associée innocente"]}],"concepts":[{"label":"Responsabilité du gérant pour faute de gestion","re":"gerant.*respons|respons.*gerant|faute de gestion|67","pts":6,"key":true},{"label":"Remboursement à la société","re":"rembours|a la societe|action sociale","pts":4},{"label":"Lien avec le redressement","re":"redressement|280 000|consequence","pts":3}],"articles":[{"code":"L5-96","article":"67","label":"Art. 67 loi 5-96 (responsabilité des gérants)","pts":5}],"faille":"L'associée ne démontre pas la faute de gestion.","concede":"Le lien entre les factures et le redressement est direct."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu l'usage des fonds sociaux au profit de l'entreprise du frère du gérant pour des travaux inexistants (article 107 de la loi 5-96), le caractère fictif des factures (article 351 CP) et la responsabilité du gérant envers la société (article 67) ; Par ces motifs : condamne M. Hilali pénalement et à rembourser à la société 600 000 Dirhams et le montant du redressement fiscal."},{"min":45,"text":"Le Tribunal, attendu l'abus de biens sociaux ; Par ces motifs : condamne le gérant à rembourser 600 000 Dirhams, le redressement restant à la charge de la société."},{"min":0,"text":"Le Tribunal, attendu un doute sur la réalité des travaux ; Par ces motifs : ordonne une expertise avant dire droit."}]},{"complexe":true,"id":"cx-delegue-facebook","matiere":"travail","title":"M. Chafik c/ Société Textiles du Sud — délégué, liberté d'expression et licenciement","court":"Tribunal de première instance d'Agadir (chambres sociale et correctionnelle)","object":"Trois problèmes : licenciement d'un délégué syndical, plainte en diffamation de l'employeur, calcul des indemnités.","you":"Avocat du salarié (M. Chafik)","adverseName":"Avocat de Textiles du Sud","facts":"M. Chafik, délégué syndical, ouvrier depuis 12 ans, a publié sur Facebook : « À Textiles du Sud, on travaille dans la chaleur, sans pause, pour un salaire de misère. Ça suffit ! » et appelé à un rassemblement. Il est licencié pour « dénigrement de l'entreprise » et l'employeur dépose une plainte en diffamation. Son salaire horaire est de 18 DH.","rounds":[{"name":"Problème 1 — Travail : le motif du licenciement","adverse":"Monsieur le Président, le salarié a dénigré publiquement son employeur. C'est un manquement grave au devoir de loyauté.","prompt":"Contestez le motif du licenciement.","options":[{"label":"Activité syndicale protégée","detail":"L'exercice d'un mandat syndical et la participation à des activités syndicales ne sont pas des motifs valables (art. 36 CT) ; atteinte aux libertés syndicales interdite (art. 9).","pts":18,"speech":"L'article 36 du Code du travail exclut, comme motif valable de licenciement, l'affiliation syndicale, l'exercice d'un mandat de représentant syndical et la participation à des activités syndicales. L'article 9 interdit toute atteinte aux libertés syndicales. Dénoncer les conditions de travail et appeler à un rassemblement, c'est exactement le rôle d'un délégué syndical. Le licenciement est abusif.","ok":["Cite les articles 36 et 9","Qualifie la publication d'activité syndicale"],"ko":[]},{"label":"Plaider la liberté d'expression générale","detail":"Invoquer le droit de chacun de s'exprimer.","pts":9,"speech":"Chacun a le droit de s'exprimer sur Facebook.","ok":["Principe réel"],"ko":["N'utilise pas la protection syndicale spécifique"]}],"concepts":[{"label":"Activité / mandat syndical protégé","re":"syndica|delegue|mandat","pts":6,"key":true},{"label":"Motif non valable","re":"pas (un )?motif valable|motif non valable|36","pts":4},{"label":"Liberté syndicale","re":"liberte syndicale|libertes syndicales|9","pts":3}],"articles":[{"code":"CT","article":"36","label":"Art. 36 CT (motifs non valables)","pts":5},{"code":"CT","article":"9","label":"Art. 9 CT (libertés syndicales)","pts":2}],"faille":"Le salarié ne justifie pas le caractère syndical de la publication.","concede":"Le mandat syndical est établi, soit ; mais les propos sont diffamatoires."},{"name":"Problème 2 — Pénal : la plainte en diffamation","adverse":"Écrire que l'entreprise paie des « salaires de misère » sans pause, c'est porter atteinte à sa considération : c'est une diffamation.","prompt":"Défendez le salarié contre la plainte.","options":[{"label":"Critique et non imputation diffamatoire","detail":"La diffamation suppose l'imputation d'un fait portant atteinte à l'honneur (art. 442) ; ici, une appréciation de conditions de travail, vérifiable et d'intérêt collectif.","pts":15,"speech":"L'article 442 du Code pénal définit la diffamation comme l'imputation d'un fait portant atteinte à l'honneur ou à la considération. « Salaire de misère » est un jugement de valeur, pas un fait précis ; quant à la chaleur et à l'absence de pause, ce sont des faits exacts, constatés par l'inspection du travail l'an dernier. Une critique syndicale des conditions de travail, fondée sur des faits établis, n'est pas une diffamation, et pas davantage une injure au sens de l'article 443.","ok":["Distingue jugement de valeur et fait","Exactitude prouvée par l'inspection","Écarte aussi l'injure"],"ko":["La publicité relève du code de la presse (art. 444)"]},{"label":"Supprimer la publication","detail":"Proposer des excuses publiques.","pts":7,"speech":"M. Chafik est prêt à retirer sa publication et à s'excuser.","ok":["Apaisement"],"ko":["Reconnaissance implicite"]}],"concepts":[{"label":"Jugement de valeur / critique","re":"jugement de valeur|critique|opinion|appreciation","pts":5,"key":true},{"label":"Faits exacts / inspection du travail","re":"exact|inspection|constat|vrai","pts":4},{"label":"Ni diffamation ni injure","re":"pas (une )?diffamation|injure|442|443","pts":3}],"articles":[{"code":"CP","article":"442","label":"Art. 442 CP (diffamation)","pts":3},{"code":"CP","article":"443","label":"Art. 443 CP (injure)","pts":2}],"faille":"Le salarié ne discute pas la qualification pénale.","concede":"Les faits ont été constatés par l'inspection, je l'admets."},{"name":"Problème 3 — Travail : les indemnités","adverse":"Subsidiairement, l'indemnité doit être minimale : le salarié a provoqué la rupture.","prompt":"Chiffrez les indemnités.","options":[{"label":"Calcul légal par tranches","detail":"Indemnité de licenciement : 96 h/an (5 premières années), 144 h (6-10), 192 h (11-15) (art. 53) ; dommages-intérêts (art. 41).","pts":16,"speech":"Avec douze ans d'ancienneté et un salaire horaire de 18 Dirhams, l'article 53 donne : 5 × 96 heures, plus 5 × 144 heures, plus 2 × 192 heures, soit 1 584 heures, c'est-à-dire 28 512 Dirhams d'indemnité de licenciement. S'y ajoutent les dommages-intérêts pour licenciement abusif de l'article 41, aggravés par l'atteinte à l'exercice syndical, et le préavis.","ok":["Calcul exact par tranches","Cite les articles 53 et 41"],"ko":[]},{"label":"Montant forfaitaire","detail":"Demander 200 000 DH.","pts":5,"speech":"M. Chafik réclame 200 000 Dirhams.","ok":["—"],"ko":["Sans calcul"]}],"concepts":[{"label":"Calcul par tranches d'ancienneté","re":"96|144|192|tranches?|anciennet","pts":6,"key":true},{"label":"Dommages-intérêts pour licenciement abusif","re":"dommages|abusi|41","pts":4},{"label":"Montant chiffré","re":"28 512|1 584|dirhams","pts":3}],"articles":[{"code":"CT","article":"53","label":"Art. 53 CT (indemnité de licenciement)","pts":4},{"code":"CT","article":"41","label":"Art. 41 CT","pts":2}],"faille":"Le calcul n'est pas présenté.","concede":"Le calcul est exact."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que la publication relève de l'activité syndicale du délégué (articles 9 et 36 CT) et ne contient ni imputation diffamatoire ni injure (articles 442 et 443 CP) ; Par ces motifs : relaxe M. Chafik, déclare le licenciement abusif et condamne l'employeur à 28 512 Dirhams d'indemnité de licenciement, au préavis et à 80 000 Dirhams de dommages-intérêts."},{"min":45,"text":"Le Tribunal, attendu le caractère abusif du licenciement ; Par ces motifs : alloue les indemnités légales et 30 000 Dirhams de dommages-intérêts ; relaxe le salarié."},{"min":0,"text":"Le Tribunal, attendu le caractère excessif des propos ; Par ces motifs : retient une faute du salarié et alloue les seules indemnités légales."}]},{"complexe":true,"id":"cx-riad-heritage","matiere":"famille","title":"Mme Lahlou et sa fille c/ M. Karim Lahlou et M. Dupuis — succession, testament et préemption","court":"Tribunal de première instance de Fès","object":"Trois problèmes : parts successorales et testament au profit d'un héritier, vente d'une part indivise à un étranger à la famille, exercice de la préemption.","you":"Avocat de la veuve et de sa fille (Mme Lahlou et Nadia)","adverseName":"Avocat de M. Karim Lahlou et de l'acquéreur","facts":"M. Lahlou est décédé en laissant sa veuve, un fils (Karim) et une fille (Nadia). Sa succession comprend un riad. Un testament manuscrit lègue le riad entier à Karim. Celui-ci, se disant propriétaire, a vendu « sa part » indivise à un acquéreur étranger, M. Dupuis, qui a fait signifier une copie de l'acte par lettre déposée à la loge du gardien de l'immeuble où vit Nadia.","rounds":[{"name":"Problème 1 — Successions : le testament et les parts","adverse":"Monsieur le Président, le défunt a légué le riad à son fils par un testament écrit de sa main. Karim en est seul propriétaire.","prompt":"Établissez les droits de la veuve et de la fille.","options":[{"label":"Legs à héritier sans effet, parts légales","detail":"Pas de legs à un héritier sans l'accord des autres (art. 280 CF) ; la veuve reçoit le huitième en présence d'enfants (art. 344).","pts":18,"speech":"L'article 280 du Code de la famille interdit le legs au profit d'un héritier, sauf permission des autres héritiers. Karim est héritier ; sa mère et sa sœur n'ont rien autorisé : le legs est sans effet. Le riad revient à la succession : la veuve en reçoit le huitième, en présence de descendants, selon l'article 344, le reste étant partagé entre les enfants selon les règles légales.","ok":["Cite les articles 280 et 344","Retour du riad à la masse"],"ko":[]},{"label":"Contester l'écriture","detail":"Demander une expertise graphologique.","pts":7,"speech":"Nous doutons que ce testament soit de la main du défunt.","ok":["Possible"],"ko":["Inutile : le legs à héritier est sans effet de toute façon"]}],"concepts":[{"label":"Legs à héritier sans effet","re":"heritier.*(interdit|sans effet|nul|ne peut)|(interdit|sans effet|nul).*heritier|280","pts":6,"key":true},{"label":"Huitième de la veuve","re":"huitieme|1/8|344","pts":4},{"label":"Riad dans la masse successorale","re":"masse|succession|partage","pts":3}],"articles":[{"code":"CF","article":"280","label":"Art. 280 CF (legs à héritier)","pts":4},{"code":"CF","article":"344","label":"Art. 344 CF (huitième de l'épouse)","pts":2}],"faille":"Les demanderesses ne contestent pas le testament.","concede":"Le legs à héritier est sans effet, je l'admets ; Karim reste copropriétaire."},{"name":"Problème 2 — Droits réels : la vente à un étranger et le délai","adverse":"Karim a vendu sa part indivise. L'acquéreur a notifié l'acte ; les co-indivisaires disposaient de trente jours pour préempter. Le délai est expiré.","prompt":"Défendez le droit de préemption.","options":[{"label":"Notification non reçue personnellement","detail":"La préemption appartient au copropriétaire indivis (art. 292 CDR) ; la notification n'est valable que reçue personnellement (art. 304).","pts":17,"speech":"Nadia et sa mère sont copropriétaires indivises du riad : l'article 292 du Code des droits réels leur ouvre la préemption sur la portion vendue. Le délai de trente jours de l'article 304 ne court qu'à compter d'une notification reçue personnellement par l'ayant droit. Une lettre déposée à la loge du gardien n'est pas une réception personnelle : le délai n'a jamais couru.","ok":["Cite les articles 292 et 304","Réception personnelle"],"ko":[]},{"label":"Contester la vente","detail":"Soutenir que Karim n'avait rien à vendre.","pts":8,"speech":"Karim n'avait rien à vendre puisque le testament est nul.","ok":["Partiellement juste"],"ko":["Karim reste héritier d'une part : la préemption est la bonne voie"]}],"concepts":[{"label":"Réception personnelle exigée","re":"personnellement|personnelle|gardien|loge","pts":6,"key":true},{"label":"Copropriétaire indivis / préemption","re":"indivis|preemption|chefaa|292","pts":4},{"label":"Délai non couru","re":"trente jours|30 jours|n.a (jamais )?pas couru|jamais couru","pts":3}],"articles":[{"code":"CDR","article":"304","label":"Art. 304 CDR (notification)","pts":4},{"code":"CDR","article":"292","label":"Art. 292 CDR (préemption)","pts":2}],"faille":"Les demanderesses ne contestent pas la notification.","concede":"La lettre a été laissée au gardien, c'est exact."},{"name":"Problème 3 — Droits réels : la procédure de préemption","adverse":"Encore faut-il que les préemptrices paient le prix. Elles n'ont rien offert.","prompt":"Plaidez sur la mise en œuvre de la préemption.","options":[{"label":"Requête, offre réelle, consignation","detail":"Demande au président, offre réelle du prix et des frais, consignation en cas de refus (art. 306 CDR).","pts":16,"speech":"Mes clientes ont présenté requête au président du tribunal, conformément à l'article 306, pour être autorisées à faire une offre réelle du prix et des frais apparents de l'acte. M. Dupuis l'ayant refusée, elles ont consigné les sommes à la caisse du tribunal dans le délai légal : le récépissé est versé aux débats.","ok":["Cite l'article 306","Étapes respectées","Récépissé"],"ko":[]},{"label":"Demander des délais","detail":"Solliciter un délai pour réunir les fonds.","pts":5,"speech":"Mes clientes demandent un délai pour réunir le prix.","ok":["Franchise"],"ko":["Risque de déchéance"]}],"concepts":[{"label":"Offre réelle et consignation","re":"offre reelle|consign|caisse","pts":6,"key":true},{"label":"Requête au président","re":"requete|president","pts":3},{"label":"Prix et frais","re":"prix|frais","pts":3}],"articles":[{"code":"CDR","article":"306","label":"Art. 306 CDR (offre réelle et consignation)","pts":5}],"faille":"Aucune consignation n'est justifiée.","concede":"La consignation est faite, je l'admets."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que le legs au profit d'un héritier est sans effet (article 280 CF), que la notification n'a pas été reçue personnellement (article 304 CDR) et que l'offre réelle et la consignation ont été faites (article 306) ; Par ces motifs : dit que le riad dépend de la succession, valide la préemption exercée par la veuve et sa fille sur la portion vendue."},{"min":45,"text":"Le Tribunal, attendu la nullité du legs ; Par ces motifs : ordonne le partage du riad selon les parts légales et réserve la préemption."},{"min":0,"text":"Le Tribunal, attendu que les demanderesses n'ont pas agi dans le délai ; Par ces motifs : valide la vente à M. Dupuis."}]},{"complexe":true,"id":"cx-parfums-contrefaits","matiere":"affaires","title":"M. Idrissi c/ Luxe-Parfums.ma — vente en ligne, contrefaçon et escroquerie","court":"Tribunal de première instance de Casablanca (chambres civile et correctionnelle)","object":"Trois problèmes : droit de rétractation, escroquerie par vente de faux produits de marque, réparation du préjudice.","you":"Avocat de l'acheteur (M. Idrissi)","adverseName":"Avocat de Luxe-Parfums.ma","facts":"M. Idrissi a acheté sur Luxe-Parfums.ma cinq parfums présentés comme « 100 % originaux, importés de Paris » pour 6 500 DH. Reçus le 10 juin, ils sentent l'alcool ; le fabricant confirme par écrit qu'il s'agit de contrefaçons (numéros de lot inexistants). M. Idrissi notifie sa rétractation le 14 juin. Le site refuse de rembourser, puis disparaît ; son gérant est identifié.","rounds":[{"name":"Problème 1 — Consommation : la rétractation","adverse":"Monsieur le Président, les flacons ont été ouverts : un parfum ouvert ne se reprend pas. La vente est définitive.","prompt":"Exigez le remboursement.","options":[{"label":"Rétractation dans les sept jours, remboursement sous 15 jours","detail":"Sept jours pour se rétracter sans motif (art. 36 loi 31-08) ; remboursement intégral sous 15 jours, puis intérêts (art. 37).","pts":17,"speech":"L'article 36 de la loi 31-08 accorde au consommateur sept jours pour se rétracter, sans justification ni pénalité. Reçus le 10 juin, les parfums ont fait l'objet d'une rétractation le 14 juin. L'article 37 oblige alors le fournisseur à rembourser le montant total au plus tard dans les quinze jours, faute de quoi la somme produit des intérêts au taux légal. Ouvrir un flacon pour vérifier un produit n'est pas une renonciation.","ok":["Cite les articles 36 et 37","Dates","Intérêts de plein droit"],"ko":[]},{"label":"Invoquer la non-conformité","detail":"Plaider seulement le défaut de conformité.","pts":9,"speech":"Les produits ne sont pas conformes : le vendeur doit les reprendre.","ok":["Fondement possible"],"ko":["Moins simple que la rétractation sans motif"]}],"concepts":[{"label":"Rétractation dans les sept jours","re":"sept jours|7 jours|retractation","pts":6,"key":true},{"label":"Remboursement sous quinze jours","re":"quinze jours|15 jours|rembours","pts":4},{"label":"Intérêts","re":"interets?|taux legal","pts":3}],"articles":[{"code":"L31-08","article":"36","label":"Art. 36 loi 31-08","pts":3},{"code":"L31-08","article":"37","label":"Art. 37 loi 31-08","pts":3}],"faille":"L'acheteur ne justifie pas d'un droit au remboursement.","concede":"La rétractation est dans le délai, soit."},{"name":"Problème 2 — Pénal : l'escroquerie","adverse":"Le site ignorait le caractère contrefait des produits : il les achetait à un grossiste. Aucune intention frauduleuse.","prompt":"Caractérisez l'escroquerie.","options":[{"label":"Affirmations fallacieuses pour un profit illégitime","detail":"Induire en erreur par des affirmations fallacieuses pour se procurer un profit (art. 540 CP) : « 100 % originaux », lots inexistants, disparition du site.","pts":17,"speech":"L'article 540 du Code pénal punit celui qui, pour se procurer un profit pécuniaire illégitime, induit astucieusement en erreur une personne par des affirmations fallacieuses. Le site affirmait « 100 % originaux, importés de Paris » ; le fabricant atteste que les numéros de lot n'existent pas. Le refus de rembourser puis la disparition du site démentent toute bonne foi. M. Idrissi se constitue partie civile.","ok":["Cite l'article 540","Affirmations fallacieuses","Disparition = mauvaise foi"],"ko":[]},{"label":"Viser la contrefaçon","detail":"Dénoncer une atteinte à la marque.","pts":8,"speech":"Ces parfums contrefont des marques célèbres.","ok":["Exact"],"ko":["L'action en contrefaçon appartient au titulaire de la marque, pas à l'acheteur"]}],"concepts":[{"label":"Affirmations fallacieuses / tromperie","re":"fallacieu|tromp|induit en erreur|originaux","pts":6,"key":true},{"label":"Profit illégitime","re":"profit|illegitime","pts":3},{"label":"Mauvaise foi (disparition, lots)","re":"dispar|lot|mauvaise foi|fabricant","pts":4}],"articles":[{"code":"CP","article":"540","label":"Art. 540 CP (escroquerie)","pts":5}],"faille":"La partie civile ne démontre pas l'intention.","concede":"Les affirmations étaient fausses, je l'admets."},{"name":"Problème 3 — Civil : la réparation","adverse":"L'acheteur réclame 30 000 Dirhams pour des parfums à 6 500 Dirhams : c'est un enrichissement.","prompt":"Chiffrez la réparation.","options":[{"label":"Préjudice causé volontairement","detail":"Remboursement, frais engagés et préjudice moral de la tromperie (art. 77 DOC).","pts":15,"speech":"L'article 77 du DOC oblige celui qui cause sciemment un dommage à le réparer. M. Idrissi demande le remboursement des 6 500 Dirhams, les frais d'expertise et de constat (2 400 Dirhams) et 5 000 Dirhams pour le préjudice moral : les parfums étaient des cadeaux de mariage, offerts avant qu'il ne découvre la fraude. Total : 13 900 Dirhams.","ok":["Cite l'article 77 DOC","Postes justifiés","Montant mesuré"],"ko":[]},{"label":"Maintenir 30 000 DH","detail":"Insister sur l'humiliation.","pts":6,"speech":"L'humiliation justifie 30 000 Dirhams.","ok":["—"],"ko":["Sans détail"]}],"concepts":[{"label":"Réparation du dommage volontaire","re":"repar|dommage|77","pts":5,"key":true},{"label":"Postes justifiés","re":"frais|constat|expertise|6 500","pts":4},{"label":"Préjudice moral","re":"moral|cadeau|humili","pts":3}],"articles":[{"code":"DOC","article":"77","label":"Art. 77 DOC","pts":4}],"faille":"La demande est excessive.","concede":"La demande est désormais mesurée."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu la rétractation exercée dans le délai (articles 36 et 37 de la loi 31-08) et les affirmations fallacieuses du vendeur (article 540 CP) ; Par ces motifs : déclare le gérant coupable d'escroquerie, le condamne à six mois avec sursis et à verser 13 900 Dirhams à M. Idrissi, avec intérêts."},{"min":45,"text":"Le Tribunal, attendu la rétractation régulière ; Par ces motifs : condamne le vendeur au remboursement de 6 500 Dirhams avec intérêts ; relaxe le gérant au bénéfice du doute."},{"min":0,"text":"Le Tribunal, attendu l'ouverture des flacons ; Par ces motifs : rejette la demande civile et relaxe le prévenu."}]},{"complexe":true,"id":"cx-voisins","matiere":"civil","title":"M. Amrani c/ M. Fikri — passage, agression et mur effondré","court":"Tribunal de première instance de Settat (chambres civile et correctionnelle)","object":"Trois problèmes : servitude de passage refusée, violences entre voisins, dommage causé par l'effondrement d'un mur.","you":"Avocat de M. Amrani","adverseName":"Avocat de M. Fikri","facts":"M. Amrani possède une ferme enclavée ; il passe depuis toujours par le chemin longeant la propriété de M. Fikri, seule issue praticable. M. Fikri a fermé le chemin. Lors d'une dispute, il a frappé M. Amrani avec un bâton : 25 jours d'incapacité. Une semaine plus tard, le vieux mur de clôture de M. Fikri, fissuré depuis des années, s'est effondré sur le tracteur de M. Amrani (réparation : 38 000 DH).","rounds":[{"name":"Problème 1 — Droits réels : le passage","adverse":"Monsieur le Président, mon client est chez lui : il ferme son chemin comme il l'entend. Le passage était une simple tolérance.","prompt":"Revendiquez le passage.","options":[{"label":"Servitude légale du fonds enclavé","detail":"Le propriétaire d'un fonds enclavé obtient un passage sur le fonds voisin, moyennant indemnité, au lieu le moins dommageable (art. 64 CDR).","pts":17,"speech":"Il ne s'agit pas d'une tolérance mais d'un droit : l'article 64 du Code des droits réels permet au propriétaire d'un fonds sans issue suffisante sur la voie publique d'obtenir un passage sur les fonds voisins, moyennant une indemnité adéquate, à l'endroit qui cause le moindre préjudice. Le chemin existant, en bordure, est ce tracé de moindre préjudice. Nous offrons l'indemnité.","ok":["Cite l'article 64","Tracé existant de moindre préjudice","Offre d'indemnité"],"ko":[]},{"label":"Invoquer l'usage immémorial","detail":"Soutenir que le passage est acquis par l'usage.","pts":8,"speech":"Ma famille passe par là depuis cinquante ans.","ok":["Contexte"],"ko":["Fondement incertain sans l'enclave"]}],"concepts":[{"label":"Fonds enclavé","re":"enclav|sans issue|issue (insuffisante|praticable)","pts":6,"key":true},{"label":"Passage au lieu le moins dommageable","re":"moindre prejudice|bordure|chemin existant","pts":4},{"label":"Indemnité","re":"indemnit","pts":3}],"articles":[{"code":"CDR","article":"64","label":"Art. 64 CDR (fonds enclavé)","pts":5}],"faille":"Le demandeur ne prouve pas l'enclave.","concede":"L'enclave est réelle, soit."},{"name":"Problème 2 — Pénal : les coups de bâton","adverse":"Une simple bousculade entre voisins énervés. Il n'y a là qu'une contravention.","prompt":"Qualifiez les violences.","options":[{"label":"Violences avec arme et ITT > 20 jours","detail":"Incapacité supérieure à 20 jours, et emploi d'une arme : peine aggravée (art. 401 CP).","pts":17,"speech":"Les violences volontaires de l'article 400 sont aggravées par l'article 401 lorsque l'incapacité dépasse vingt jours, ce qui est le cas avec vingt-cinq jours constatés par certificat médical. Le même article aggrave encore la peine en cas d'emploi d'une arme : un bâton utilisé pour frapper en est une. Ce n'est pas une bousculade, c'est un délit grave.","ok":["Cite l'article 401","ITT de 25 jours","Bâton = arme"],"ko":[]},{"label":"Rester sur l'article 400","detail":"Qualifier en violences simples.","pts":8,"speech":"Ce sont des violences volontaires au sens de l'article 400.","ok":["Qualification de base"],"ko":["Oublie l'aggravation"]}],"concepts":[{"label":"Incapacité supérieure à vingt jours","re":"vingt jours|20 jours|25 jours|incapacit","pts":5,"key":true},{"label":"Emploi d'une arme","re":"arme|baton","pts":4},{"label":"Violences volontaires","re":"volontaire|coups","pts":3}],"articles":[{"code":"CP","article":"401","label":"Art. 401 CP (violences aggravées)","pts":4},{"code":"CP","article":"400","label":"Art. 400 CP","pts":1}],"faille":"La partie civile ne qualifie pas précisément les violences.","concede":"Le certificat mentionne bien 25 jours."},{"name":"Problème 3 — Civil : le mur effondré","adverse":"L'effondrement du mur est un accident : la pluie de la veille en est la cause. Mon client n'y est pour rien.","prompt":"Engagez la responsabilité du propriétaire du mur.","options":[{"label":"Responsabilité du propriétaire de l'édifice","detail":"Le propriétaire répond de l'écroulement dû à la vétusté ou au défaut d'entretien (art. 89 DOC) : fissures connues depuis des années.","pts":17,"speech":"L'article 89 du DOC rend le propriétaire d'un édifice ou d'une construction responsable du dommage causé par son écroulement lorsqu'il est dû à la vétusté ou au défaut d'entretien. Les photographies de 2021 montrent les fissures ; deux voisins avaient alerté M. Fikri. Une pluie ordinaire ne fait pas tomber un mur entretenu. Il doit les 38 000 Dirhams de réparation du tracteur.","ok":["Cite l'article 89","Preuve de la vétusté","Écarte la force majeure"],"ko":[]},{"label":"Invoquer la faute","detail":"Plaider la négligence (art. 78).","pts":10,"speech":"M. Fikri a été négligent en n'entretenant pas son mur.","ok":["Raisonnement juste"],"ko":["L'article 89 est plus direct"]}],"concepts":[{"label":"Écroulement dû à la vétusté / défaut d'entretien","re":"vetuste|defaut d.entretien|fissur|ecroul","pts":6,"key":true},{"label":"Pluie ordinaire, pas de force majeure","re":"pluie|force majeure|ordinaire","pts":4},{"label":"Montant du dommage","re":"38 000|tracteur|reparation","pts":3}],"articles":[{"code":"DOC","article":"89","label":"Art. 89 DOC (ruine d'un bâtiment)","pts":5}],"faille":"Rien ne prouve l'état du mur.","concede":"Les fissures étaient anciennes, je l'admets."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu l'état d'enclave du fonds (article 64 CDR), les violences avec arme ayant causé plus de vingt jours d'incapacité (article 401 CP) et l'écroulement du mur par défaut d'entretien (article 89 DOC) ; Par ces motifs : rétablit le passage moyennant indemnité, condamne M. Fikri à un an d'emprisonnement dont quatre mois ferme et à 38 000 Dirhams pour le tracteur, outre 20 000 Dirhams pour les blessures."},{"min":45,"text":"Le Tribunal, attendu les violences et la responsabilité du propriétaire du mur ; Par ces motifs : condamne M. Fikri à six mois avec sursis et aux réparations, la question du passage étant renvoyée à expertise."},{"min":0,"text":"Le Tribunal, attendu des torts partagés ; Par ces motifs : condamne M. Fikri à une amende et rejette les autres demandes."}]},{"complexe":true,"id":"cx-garde-pension","matiere":"famille","title":"Mme Naciri c/ M. Bouzid — enfant retenu, garde et pension","court":"Tribunal de première instance d'Oujda (section de la famille et chambre correctionnelle)","object":"Trois problèmes : non-représentation d'enfant, demande de transfert de garde pour déménagement, non-paiement de la pension.","you":"Avocat de la mère (Mme Naciri)","adverseName":"Avocat de M. Bouzid","facts":"Par jugement exécutoire, la garde de Yanis (8 ans) a été confiée à sa mère, le père ayant un droit de visite. Mme Naciri a déménagé d'Oujda à Fès pour un emploi d'infirmière, en informant le père. Après un week-end de visite, M. Bouzid refuse de rendre l'enfant depuis trois semaines et demande le transfert de la garde. Il ne paie plus la pension de 1 500 DH fixée par le jugement depuis quatre mois.","rounds":[{"name":"Problème 1 — Pénal : l'enfant non rendu","adverse":"Monsieur le Président, mon client protège son fils d'un déménagement brutal. Il ne l'a pas enlevé : l'enfant est chez son père.","prompt":"Caractérisez l'infraction.","options":[{"label":"Non-représentation d'enfant","detail":"Le parent qui ne représente pas l'enfant à celui qui en a la garde, en vertu d'une décision exécutoire, est puni (art. 477 CP).","pts":18,"speech":"L'article 477 du Code pénal punit le père ou la mère qui, alors que la garde a été réglée par une décision exécutoire, ne représente pas le mineur à ceux qui ont le droit de le réclamer, même sans fraude ni violence. Le jugement confie la garde à la mère ; le père retient l'enfant depuis trois semaines après une visite. Ses motifs, même sincères, ne l'autorisent pas à se faire justice.","ok":["Cite l'article 477","Décision exécutoire","Même sans violence"],"ko":[]},{"label":"Demander le retour en urgence","detail":"Saisir le juge des référés seulement.","pts":9,"speech":"Nous demandons le retour immédiat de l'enfant en référé.","ok":["Utile"],"ko":["Ne qualifie pas l'infraction"]}],"concepts":[{"label":"Non-représentation d'enfant","re":"represent|ne (rend|restitue) pas|retient|477","pts":6,"key":true},{"label":"Décision de garde exécutoire","re":"executoire|jugement|decision","pts":4},{"label":"Même sans violence ni fraude","re":"sans (fraude|violence)|se faire justice","pts":3}],"articles":[{"code":"CP","article":"477","label":"Art. 477 CP (non-représentation d'enfant)","pts":5}],"faille":"La mère ne caractérise pas l'infraction.","concede":"Le jugement est exécutoire, soit ; mais le déménagement change tout."},{"name":"Problème 2 — Famille : le déménagement de la mère","adverse":"La mère a emmené l'enfant à 350 kilomètres : elle perd la garde. L'intérêt de l'enfant commande qu'il reste à Oujda avec son père.","prompt":"Défendez le maintien de la garde.","options":[{"label":"Le déménagement n'entraîne pas la déchéance","detail":"Changement de résidence à l'intérieur du Maroc sans effet, sauf motifs avérés (art. 178 CF) ; intérêt de l'enfant (art. 186).","pts":17,"speech":"L'article 178 du Code de la famille dispose que le changement de résidence, à l'intérieur du Maroc, de la mère gardienne n'entraîne pas la déchéance de la garde, sauf motifs avérés appréciés au regard de l'intérêt de l'enfant, que l'article 186 place au premier rang, et de la distance. Mme Naciri a déménagé pour un emploi stable, a inscrit Yanis dans une bonne école et a informé le père. Nous proposons d'adapter le droit de visite aux vacances et à un week-end sur deux, frais de transport partagés.","ok":["Cite l'article 178","Motif légitime du déménagement","Adaptation de la visite"],"ko":[]},{"label":"Accuser le père","detail":"Reprocher au père sa violence passée.","pts":6,"speech":"Le père a toujours été violent.","ok":["—"],"ko":["Aucune preuve","Ne répond pas sur le déménagement"]}],"concepts":[{"label":"Déménagement sans déchéance","re":"changement de residence|demenag|pas (la )?decheance|178","pts":6,"key":true},{"label":"Intérêt de l'enfant","re":"interet de l.enfant|ecole|stabilit","pts":4},{"label":"Adaptation du droit de visite","re":"visite|vacances|transport","pts":3}],"articles":[{"code":"CF","article":"178","label":"Art. 178 CF (changement de résidence)","pts":4},{"code":"CF","article":"186","label":"Art. 186 CF (intérêt de l'enfant)","pts":2}],"faille":"La mère ne justifie pas son déménagement.","concede":"Le déménagement est motivé, je l'admets."},{"name":"Problème 3 — Pénal / famille : la pension impayée","adverse":"Mon client a cessé de payer parce qu'il garde lui-même l'enfant depuis trois semaines.","prompt":"Plaidez sur le non-paiement de la pension.","options":[{"label":"Abandon de famille","detail":"Omission volontaire de verser la pension fixée par décision exécutoire (art. 480 CP), applicable à l'entretien des enfants (art. 202 CF) : quatre mois d'impayés, bien avant la rétention.","pts":16,"speech":"L'article 480 du Code pénal punit quiconque omet volontairement de verser la pension fixée par une décision exécutoire, et l'article 202 du Code de la famille applique ces dispositions à l'entretien des enfants. Le non-paiement dure depuis quatre mois, bien avant les trois semaines de rétention, qui sont elles-mêmes illégales : on ne peut invoquer sa propre infraction pour justifier une autre.","ok":["Cite les articles 480 CP et 202 CF","Chronologie","Nul ne peut se prévaloir de sa faute"],"ko":[]},{"label":"Réclamer les arriérés seulement","detail":"Demander 6 000 DH.","pts":9,"speech":"Nous demandons les 6 000 Dirhams d'arriérés.","ok":["Concret"],"ko":["Ne qualifie pas l'abandon de famille"]}],"concepts":[{"label":"Omission volontaire de payer la pension","re":"pension|omission|abandon de famille|480","pts":6,"key":true},{"label":"Chronologie : impayés antérieurs","re":"quatre mois|avant|anterieur","pts":4},{"label":"Pas de justification par la rétention","re":"propre (faute|infraction)|retention|illegal","pts":3}],"articles":[{"code":"CP","article":"480","label":"Art. 480 CP","pts":3},{"code":"CF","article":"202","label":"Art. 202 CF","pts":2}],"faille":"La mère ne répond pas à l'argument du père.","concede":"Les impayés précèdent la rétention, c'est exact."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu la non-représentation de l'enfant malgré un jugement exécutoire (article 477 CP), l'absence de déchéance de la garde pour un déménagement motivé à l'intérieur du Maroc (article 178 CF) et l'omission volontaire de payer la pension (article 480 CP) ; Par ces motifs : ordonne le retour immédiat de l'enfant, maintient la garde à la mère avec un droit de visite adapté, et condamne le père à quatre mois avec sursis et aux arriérés."},{"min":45,"text":"Le Tribunal, attendu la non-représentation de l'enfant ; Par ces motifs : ordonne le retour de l'enfant et maintient la garde, le père étant condamné à une amende."},{"min":0,"text":"Le Tribunal, attendu l'éloignement de l'enfant ; Par ces motifs : ordonne une enquête sociale et confie provisoirement l'enfant au père."}]},{"complexe":true,"id":"cx-faillite-salaries","matiere":"travail","title":"Salariés de Métal Atlas c/ Métal Atlas SA et son syndic — licenciements et procédure collective","court":"Tribunal de commerce de Casablanca et tribunal de première instance (chambre sociale)","object":"Trois problèmes : licenciement collectif sans autorisation, déclaration des créances salariales dans le redressement judiciaire, calcul des indemnités.","you":"Avocat des salariés","adverseName":"Avocat du syndic de Métal Atlas","facts":"Métal Atlas SA (120 salariés) a licencié 35 ouvriers en mars sans consulter les délégués ni demander l'autorisation du gouverneur. En juin, le tribunal de commerce ouvre une procédure de redressement judiciaire. Le syndic refuse de payer les indemnités, au motif que les salariés n'ont pas déclaré leurs créances dans le délai de deux mois. L'ancienneté moyenne est de 9 ans, au salaire horaire moyen de 16 DH.","rounds":[{"name":"Problème 1 — Travail : les licenciements","adverse":"Monsieur le Président, l'entreprise était au bord de la faillite, comme le prouve le redressement judiciaire. Les licenciements étaient inévitables.","prompt":"Contestez la régularité des licenciements.","options":[{"label":"Procédure obligatoire ignorée","detail":"Consultation des délégués (art. 66) et autorisation du gouverneur (art. 67) obligatoires au-delà de 10 salariés ; à défaut, dommages-intérêts (art. 70).","pts":17,"speech":"Les difficultés économiques ne dispensent pas de la loi. L'article 66 du Code du travail impose l'information et la consultation des délégués, l'article 67 l'autorisation du gouverneur. Aucune de ces formalités n'a été accomplie. L'article 70 prévoit alors, en plus des indemnités de préavis et de licenciement, les dommages-intérêts de l'article 41 sur décision judiciaire.","ok":["Cite les articles 66, 67 et 70","Difficultés ≠ dispense"],"ko":[]},{"label":"Contester le motif économique","detail":"Soutenir que l'entreprise était rentable.","pts":6,"speech":"Métal Atlas était rentable ; le motif est faux.","ok":["—"],"ko":["Contredit par le redressement judiciaire"]}],"concepts":[{"label":"Autorisation du gouverneur / consultation","re":"gouverneur|autorisation|delegues|consult","pts":6,"key":true},{"label":"Difficultés ne dispensent pas","re":"ne dispense|meme en cas|difficultes","pts":3},{"label":"Dommages-intérêts","re":"dommages|70|41","pts":4}],"articles":[{"code":"CT","article":"67","label":"Art. 67 CT (autorisation)","pts":3},{"code":"CT","article":"70","label":"Art. 70 CT (indemnités et dommages)","pts":3}],"faille":"Les salariés ne contestent pas le motif économique.","concede":"Les formalités n'ont pas été accomplies, je l'admets."},{"name":"Problème 2 — Procédures collectives : la déclaration des créances","adverse":"Toute créance antérieure au jugement d'ouverture doit être déclarée au syndic dans les deux mois. Les salariés ne l'ont pas fait : leurs créances sont éteintes.","prompt":"Répondez sur l'obligation de déclarer.","options":[{"label":"Les salariés sont dispensés","detail":"L'article 719 CCOM impose la déclaration à tous les créanciers antérieurs, à l'exception des salariés ; le délai de l'art. 720 ne leur est pas opposable.","pts":18,"speech":"L'article 719 du Code de commerce est explicite : tous les créanciers dont la créance est antérieure au jugement d'ouverture adressent la déclaration de leurs créances au syndic, à l'exception des salariés. Le délai de deux mois de l'article 720 ne s'applique donc pas à nos clients. Leurs créances d'indemnités subsistent intégralement et doivent être payées.","ok":["Cite l'article 719 (exception des salariés)","Délai de l'article 720 inopposable"],"ko":[]},{"label":"Demander un relevé de forclusion","detail":"Solliciter une prorogation du délai.","pts":8,"speech":"Les salariés demandent à être relevés de la forclusion.","ok":["Démarche possible"],"ko":["Admet à tort une obligation qui n'existe pas"]}],"concepts":[{"label":"Exception des salariés","re":"exception des salaries|a l.exception|salaries (sont )?dispenses|dispens","pts":6,"key":true},{"label":"Délai de deux mois inopposable","re":"deux mois|720|inopposable|ne s.applique pas","pts":4}],"articles":[{"code":"CCOM","article":"719","label":"Art. 719 CCOM (déclaration des créances)","pts":5},{"code":"CCOM","article":"720","label":"Art. 720 CCOM (délai)","pts":2}],"faille":"Les salariés ne justifient d'aucune déclaration.","concede":"Le texte excepte bien les salariés."},{"name":"Problème 3 — Travail : le calcul des indemnités","adverse":"Les sommes réclamées sont fantaisistes et mettraient en péril le plan de redressement.","prompt":"Chiffrez les indemnités.","options":[{"label":"Calcul légal par tranches","detail":"Pour 9 ans : 5 × 96 h + 4 × 144 h = 1 056 h (art. 53), soit 16 896 DH par salarié en moyenne, outre préavis et dommages.","pts":16,"speech":"Selon l'article 53, l'indemnité de licenciement est de 96 heures par année pour les cinq premières années et de 144 heures de la sixième à la dixième. Pour neuf ans d'ancienneté : 5 × 96 plus 4 × 144, soit 1 056 heures ; au salaire horaire de 16 Dirhams, 16 896 Dirhams en moyenne par salarié. Nous produisons un tableau individuel ; s'y ajoutent le préavis et les dommages-intérêts.","ok":["Calcul exact","Cite l'article 53","Tableau individuel"],"ko":[]},{"label":"Accepter une réduction","detail":"Proposer 50 % pour sauver l'entreprise.","pts":6,"speech":"Les salariés accepteraient la moitié pour sauver l'entreprise.","ok":["Solidaire"],"ko":["Renonce à des droits d'ordre public"]}],"concepts":[{"label":"Calcul par tranches","re":"96|144|1 056|tranches?|anciennet","pts":6,"key":true},{"label":"Montant chiffré","re":"16 896|dirhams","pts":3},{"label":"Tableau individuel","re":"tableau|individuel|chaque salarie","pts":3}],"articles":[{"code":"CT","article":"53","label":"Art. 53 CT (indemnité de licenciement)","pts":4}],"faille":"Le calcul n'est pas présenté.","concede":"Le calcul est conforme au texte."}],"verdicts":[{"min":75,"text":"Le Tribunal, attendu que les licenciements sont intervenus sans consultation ni autorisation (articles 66, 67 et 70 CT) et que les salariés sont dispensés de déclarer leurs créances (article 719 CCOM) ; Par ces motifs : fixe les créances de chaque salarié aux indemnités légales (article 53) et à des dommages-intérêts, à inscrire au passif sans forclusion."},{"min":45,"text":"Le Tribunal, attendu la dispense de déclaration des salariés ; Par ces motifs : admet les indemnités légales, sans dommages-intérêts."},{"min":0,"text":"Le Tribunal, attendu le défaut de déclaration dans le délai ; Par ces motifs : déclare les créances forcloses."}]}];
